/**
  Sean Connery (Dr. No, From Russia With Love, Goldfinger, Thunderball, You Only Live Twice, Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('168088f0-e705-446b-96f4-cf1fdb035856'),
       'Sean Connery',
       'James Bond',
       'Thomas Sean Connery was born on August 25, 1930, in the Fountainbridge district of Edinburgh, Scotland. Raised in a working-class family, he took on odd jobs at a young age to support his household, including working as a milkman, lorry driver, coffin polisher, and bricklayer. After a brief three-year stint in the Royal Navy ended due to medical reasons, he pursued bodybuilding and artistic modeling in Edinburgh. His imposing physique led to a third-place finish in a London bodybuilding competition, which opened the door to his first theatrical role in a touring production of the musical South Pacific in the early 1950s. Connery subsequently refined his craft through television broadcasts and minor film roles, eventually securing early credited screen appearances in features like No Road Back and Disney''s Darby O''Gill and the Little People. Connery’s defining career breakthrough came in 1962 when producers Albert R. "Cubby" Broccoli and Harry Saltzman cast him as Ian Fleming’s suave British secret agent, James Bond, in Dr. No. His magnetic charisma, physical grace, and wry humor defined the template for 007, launching a massive global cinematic phenomenon. He went on to star as Bond across six official Eon Productions films, including From Russia with Love, Goldfinger, Thunderball, You Only Live Twice, and Diamonds Are Forever, as well as the unofficial 1983 release Never Say Never Again. Eager to prevent being typecast, Connery established a diverse and celebrated body of dramatic work outside the 007 series. He delivered iconic performances in notable films such as Alfred Hitchcock''s Marnie, Sidney Lumet''s The Hill, John Huston''s The Man Who Would Be King, and Jean-Jacques Annaud''s The Name of the Rose. His performance as tough veteran police officer Jim Malone in Brian De Palma''s 1987 film The Untouchables earned him the Academy Award for Best Supporting Actor. In his later career, he led major blockbusters such as Indiana Jones and the Last Crusade, The Hunt for Red October, and The Rock. Knighted by Queen Elizabeth II in 2000 for services to film drama, Connery retired from acting in the mid-2000s and passed away at age ninety on October 31, 2020, leaving behind a monumental cinematic legacy as one of the defining screen icons of the twentieth century.',
       'Scottish',
        '1930-08-25',
       '2020-10-31',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Ursula Andress (Dr. No)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d56e4a3b-c398-4d83-923d-1b792fa00bf4'),
       'Ursula Andress',
       'Honey Rider',
       'Ursula Andress was born on March 19, 1936, in Ostermundigen, Switzerland. Raised in a strict Protestant household alongside five siblings, she spent her youth cultivating an adventurous spirit, running away to Rome at sixteen to work as an art restorer before breaking into European cinema. After securing minor roles in Italian films during the mid-1950s, she moved to Hollywood under contract with Paramount Pictures, where she spent time learning English and adapting to the studio system while marrying actor and director John Derek in 1957. Andress achieved immediate worldwide fame in 1962 when she was cast as Honey Ryder in the debut Eon Productions James Bond film, Dr. No. Her famous entrance, stepping out of the Caribbean Sea onto an island shore in a white bikini with a hunting knife strapped to her hip, became one of the most celebrated and iconic images in motion picture history. Though her line dialogue was famously dubbed by voice actress Monica van der Zyl due to Andress’s heavy Swiss-German accent, her performance set the standard for the modern "Bond Girl" dynamic and earned her a Golden Globe Award for New Star of the Year. Following her breakthrough as Honey Ryder, Andress built an international career across American and European film productions throughout the 1960s and 1970s. She starred opposite major Hollywood icons, playing opposite Elvis Presley in Fun in Acapulco, Frank Sinatra and Dean Martin in 4 for Texas, and Peter Sellers in What''s New Pussycat?. She also returned to the spy spoof genre by appearing as Vesper Lynd in the unofficial 1967 James Bond satire Casino Royale. Through the 1970s and 1980s, she transitioned primarily into European cult cinema, action-adventures, and television series, cementing her status as a legendary international screen siren and beauty icon of mid-century world cinema.',
       'Swiss',
       '1936-03-19',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Joseph Wiseman (Dr. No)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('e4637616-5b01-4c90-bb19-7b4b1a895377'),
       'Joseph Wiseman',
       'Dr. No',
       'Joseph Wiseman was born on May 15, 1918, in Montreal, Quebec, Canada. Raised in New York City from a young age, he began acting in his late teens and made his Broadway debut in 1938 in Abe Lincoln in Illinois. He established himself as a distinguished stage actor, earning acclaim for his intense theatrical presence in productions such as Detective Story, The Lark, and Incident at Vichy, as well as winning a Drama Desk Award for starring as J. Robert Oppenheimer in In the Matter of J. Robert Oppenheimer.  He transitioned to feature films in the early 1950s, bringing a brooding, sinister energy to character roles. After recreating his Broadway role in the 1951 film adaptation of Detective Story, he appeared alongside Marlon Brando in Elia Kazan''s Viva Zapata! and starred in John Huston''s Western The Unforgiven. Wiseman achieved immortal pop-culture fame in 1962 when producer Harry Saltzman cast him as the title character in the first Eon Productions James Bond film, Dr. No. Playing Dr. Julius No—a reclusive, megalomaniacal nuclear scientist with prosthetic metal hands working for SPECTRE—Wiseman delivered a coldly detached, cerebral performance that created the definitive template for all subsequent James Bond villains. Though he initially took the job thinking it was a minor B-movie project and later preferred to be recognized for his extensive body of theatrical work, his portrayal of Bond''s first screen adversary remained his most globally famous role. Following Dr. No, Wiseman remained dedicated to the stage while maintaining an active career in American and international film and television. His notable later screen credits included The Night They Raided Minsky''s, The Apprenticeship of Duddy Kravitz, and a recurring role as crime boss Manny Weisbord on the 1980s television series Crime Story. He continued performing into his eighties, remaining active on Broadway and in Yiddish theater readings. Wiseman passed away on October 19, 2009, at age ninety-one, leaving behind a seven-decade acting legacy spanning theater, television, and cinematic history. An iconic glimpse of Wiseman in his defining screen role can be seen in Joseph Wiseman as Dr. No, which highlights his memorable performance alongside Sean Connery in the climax of the 1962 film.',
       'Canadian-American',
       '1918-05-15',
       '2009-10-19',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Bernard Lee (Dr. No, From Russia With Love, Goldfinger, Thunderball, You only live twice, On her majestys Secret service, Live and let die, The man with the golden gun, the spy who loved me, moonraker)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d1c41998-74ea-4737-82d8-46b59c83acc2'),
       'Bernard Lee',
       'M.',
       'John Bernard Lee was born on January 10, 1908, in County Londonderry, Ireland. The son of an actor, he spent much of his childhood traveling with theatrical tours before training formally at the Royal Academy of Dramatic Art in London. He established himself as a versatile stage performer throughout the late 1920s and 1930s, debuting on the West End and appearing in early British film productions. His acting career was temporarily paused during World War II, during which he served in the British Army''s Royal Artillery. Following the war, Lee built a prolific reputation in post-war British cinema, specializing in authoritative, gruff, yet dependable figures such as police detectives, military commanders, and civil servants. He appeared in acclaimed film classics such as Carol Reed''s The Third Man, The Fallen Idol, The Small Back Room, and The Purple Plain. His stoic, no-nonsense screen presence made him one of the most recognizable and trusted character actors in British film and television throughout the 1950s. Lee achieved worldwide cinematic immortality in 1962 when he was cast as M, the head of the British Secret Intelligence Service (MI6), in the inaugural Eon Productions James Bond film, Dr. No. His stern, paternal authority and sharp verbal exchanges with Sean Connery''s 007 established the core dynamic of the MI6 briefing scenes, creating the definitive blueprint for the character. Lee went on to portray M across eleven consecutive official Bond films, remaining a constant presence as the franchise transitioned across three different lead actors—Sean Connery, George Lazenby, and Roger Moore. He continued working steadily in television and film alongside his Bond duties throughout the 1960s and 1970s, making guest appearances on popular British series such as The Avengers, Danger Man, and The Persuaders!. Lee was preparing to reprise his role as M for a twelfth time in For Your Eyes Only when he fell ill, passing away from stomach cancer on January 16, 1981, at age seventy-three. Out of respect for his legacy, producer Albert R. Broccoli chose not to recast the role for the 1981 film, leaving M''s script lines assigned to Minister of Defence Sir Frederick Gray and Chief of Staff Bill Tanner as a quiet tribute to Lee''s irreplaceable contribution to the 007 legacy.',
       'British',
       '1908-01-10',
       '1981-01-16',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Lois Maxwell (Dr. No, From Russia With Love, Goldfinger, You only live twice, On her majestys secret service, Diamonds are forever, Live and let die, The man with the golden gun, The spy who loved me, moonraker, for your eyes only, octopussy, a view to a kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('f6d0b2bb-c596-430a-bb86-019fccd3ca6b'),
       'Lois Maxwell',
       'Miss Moneypenny',
       'Lois Maxwell was born Lois Ruth Hooker on May 19, 1927, in Kitchener, Ontario, Canada. She ran away from home at age fifteen during World War II to join the Canadian Army''s Entertainment Unit, performing across Europe before her real age was discovered in England. She subsequently trained at the Royal Academy of Dramatic Art in London, where she befriended classmate Roger Moore. Moving to Hollywood in the late 1940s, she won a Golden Globe Award for Most Promising Newcomer for her performance in That Hagen Girl in 1947, appearing alongside Shirley Temple and Ronald Reagan. Seeking more diverse roles, Maxwell moved to Italy in the early 1950s, starring in classical film adaptations including Aida alongside Sophia Loren. After marrying television producer Peter Marriott in 1957, she resettled in the United Kingdom and continued working steadily in British television and film, making guest appearances on popular series such as The Saint, Department S, and UFO. Maxwell secured her place in cinematic history in 1962 when director Terence Young cast her as Miss Moneypenny, secretary to M, in the first Eon Productions James Bond film, Dr. No. Her affectionate, quick-witted banter with Sean Connery''s 007 defined the playful romantic tension of the MI6 office scenes, establishing a beloved franchise staple. Maxwell played Moneypenny across fourteen consecutive official Bond films over twenty-three years, spanning the eras of Sean Connery, George Lazenby, and her former drama classmate Roger Moore, making her one of the most enduring presences in the history of the film series. In addition to her Bond performances, Maxwell worked as a columnist for the Toronto Sun for over a decade, writing under the pen name Miss Moneypenny, and ran a textile business. She retired from the Bond franchise following A View to a Kill in 1985, after which she moved to Canada and later to Australia. Maxwell passed away from vascular disease on September 29, 2007, at age eighty in Fremantle, Western Australia, leaving behind a legacy as the original and definitive screen portrayal of Miss Moneypenny.',
       'Canadian',
       '1927-02-14',
       '2007-09-29',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jack Lord (Dr. No)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b642143a-32dc-4406-8d73-437add9e16c8'),
       'Jack Lord',
       'Felix Leiter',
       'Jack Lord was born John Joseph Patrick Ryan on December 30, 1920, in Brooklyn, New York. Raised in a maritime family, he attended the United States Merchant Marine Academy and served in the Merchant Marine during World War II, where he began making educational maritime films. Recognizing his passion for the craft, he studied fine art at New York University on a football scholarship while simultaneously honing his acting at the Neighborhood Playhouse and the Actors Studio alongside peers like Marlon Brando and Paul Newman. He made his Broadway debut in 1954 in The Traveling Lady, earning a Theatre World Award, and subsequently appeared in the original Broadway production of Cat on a Hot Tin Roof. Throughout the 1950s, Lord built a reputation as a versatile and intense character actor in live television anthologies and feature films. He gained prominent screen credits in films such as The Court-Martial of Billy Mitchell, God''s Little Acre, Man of the West, and Walk Like a Dragon. His commanding physical presence, sharp jawline, and authoritative delivery made him a natural fit for tough, law-enforcement and Western roles across popular television series of the era, including Untouchables, Bonanza, and Have Gun – Will Travel. Lord made James Bond cinematic history in 1962 when director Terence Young cast him as CIA agent Felix Leiter in the first Eon Productions 007 film, Dr. No. Playing Bond''s resourceful American ally in Jamaica, Lord brought a cool, suave confidence to Leiter that matched Sean Connery''s James Bond step-for-step, establishing the precedent for the iconic recurring character. Although producer Albert R. Broccoli intended to bring Lord back for Goldfinger, Lord demanded a higher salary, co-star billing, and a larger role, leading the producers to recast the character instead. Following his brief Bond tenure, Lord starred in the short-lived Western series Stoney Burke before landing the role that defined his career in 1968 as Detective Steve McGarrett in Hawaii Five-O. As the leader of Hawaii''s elite state police unit, Lord became a global television icon, famous for his razor-sharp delivery of the catchphrase "Book ''em, Danno." He starred in and executive-produced the hit series for twelve seasons until its conclusion in 1980. After retiring from acting, Lord devoted his later years to painting, photography, and philanthropy in Hawaii. He passed away from congestive heart failure on January 21, 1998, at age seventy-seven at his home in Honolulu.',
       'American',
       '1920-12-30',
       '1998-01-21',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Anthony Dawson (Dr. No)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('fd195e53-fddf-47c1-927f-6959437d3af1'),
       'Anthony Dawson',
       'Professor Dent',
       'Anthony Douglas Gillon Dawson was born on October 18, 1916, in Edinburgh, Scotland. He trained as an actor at the Royal Academy of Dramatic Art in London and served in the British Army during World War II. Dawson made his film debut in 1943''s They Met in the Dark and built a strong early career appearing in notable British cinema classics such as The Way to the Stars and The Wooden Horse. Moving to America in the 1950s, Dawson gained international acclaim on Broadway and in film. Director Alfred Hitchcock cast him in his memorable role as the sinister blackmail victim turned hired killer Captain Lesgate in Dial M for Murder in 1954. His lean frame, sharp features, and calm, calculating presence quickly made him a sought-after character actor for villains, schemers, and suspenseful roles in thrillers such as Midnight Lace and Hammer''s The Curse of the Werewolf. In 1962, director Terence Young—a frequent collaborator—cast Dawson as Professor R. J. Dent in Dr. No, the inaugural James Bond film. As a treacherous geologist secretly working for SPECTRE, Dawson delivered a famously cold performance that led to one of early cinema’s most defining moments when James Bond shoots Dent in cold blood after the professor exhausts his ammunition. Although Professor Dent was killed off in Dr. No, Young brought Dawson back for the next two Bond entries, From Russia with Love in 1963 and Thunderball in 1965, to provide the physical body, lap-petting hands, and physical presence of SPECTRE mastermind Ernst Stavro Blofeld, whose face remained unseen and whose voice was dubbed by Eric Pohlmann. Additionally, Dawson appeared alongside several Bond alumni in the 1967 Italian spy spoof Operation Kid Brother. Throughout the late 1960s and 1970s, Dawson relocated to Rome, becoming a staple of European genre cinema, including numerous Spaghetti Westerns and crime dramas. He continued to act across European film and television into his seventies. Dawson passed away from cancer on January 8, 1992, in Lewes, Sussex, England, at the age of seventy-five.',
       'Scottish',
       '1916-10-18',
       '1992-01-08',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Anthony Dawson (From Russia With Love, Thunderball)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('91027fc5-7388-4f21-92da-d2ad3e24c339'),
       'Anthony Dawson',
       'Ernst Stavro Blofeld',
       'Anthony Douglas Gillon Dawson was born on October 18, 1916, in Edinburgh, Scotland. He trained as an actor at the Royal Academy of Dramatic Art in London and served in the British Army during World War II. Dawson made his film debut in 1943''s They Met in the Dark and built a strong early career appearing in notable British cinema classics such as The Way to the Stars and The Wooden Horse. Moving to America in the 1950s, Dawson gained international acclaim on Broadway and in film. Director Alfred Hitchcock cast him in his memorable role as the sinister blackmail victim turned hired killer Captain Lesgate in Dial M for Murder in 1954. His lean frame, sharp features, and calm, calculating presence quickly made him a sought-after character actor for villains, schemers, and suspenseful roles in thrillers such as Midnight Lace and Hammer''s The Curse of the Werewolf. In 1962, director Terence Young—a frequent collaborator—cast Dawson as Professor R. J. Dent in Dr. No, the inaugural James Bond film. As a treacherous geologist secretly working for SPECTRE, Dawson delivered a famously cold performance that led to one of early cinema’s most defining moments when James Bond shoots Dent in cold blood after the professor exhausts his ammunition. Although Professor Dent was killed off in Dr. No, Young brought Dawson back for the next two Bond entries, From Russia with Love in 1963 and Thunderball in 1965, to provide the physical body, lap-petting hands, and physical presence of SPECTRE mastermind Ernst Stavro Blofeld, whose face remained unseen and whose voice was dubbed by Eric Pohlmann. Additionally, Dawson appeared alongside several Bond alumni in the 1967 Italian spy spoof Operation Kid Brother. Throughout the late 1960s and 1970s, Dawson relocated to Rome, becoming a staple of European genre cinema, including numerous Spaghetti Westerns and crime dramas. He continued to act across European film and television into his seventies. Dawson passed away from cancer on January 8, 1992, in Lewes, Sussex, England, at the age of seventy-five.',
       'Scottish',
       '1916-10-18',
       '1992-01-08',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Zena Marshall (Dr. No)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('8544e961-7884-4e08-99bf-f4057561727c'),
           'Zena Marshall',
           'Miss Taro',
           'Zena Marshall was born Zena Moyra Marshall on January 1, 1925, in Nairobi, British Kenya. Raised in Kenya and Leicestershire, England, she cultivated a passion for performance from a young age and went on to train at the prestigious Royal Academy of Dramatic Art in London. She began her acting career in theatrical productions before making her film debut in the 1945 British epic Caesar and Cleopatra alongside Vivien Leigh. Throughout the 1940s and 1950s, Marshall established herself as a versatile character actress across British cinema and television, appearing in films such as Snowbound, Miranda, So Long at the Fair, and The Red Boomerang, often playing glamorous, exotic, or intriguing figures. Marshall earned her most famous role in 1962 when director Terence Young cast her as Miss Taro in Dr. No, the inaugural Eon Productions James Bond film. Portraying a treacherous double agent working for Dr. Julius No and SPECTRE under the guise of a secretary at Government House in Kingston, Marshall shared memorable onscreen chemistry with Sean Connery''s James Bond. Her character is famously seduced by Bond, who anticipates her betrayal and arranges for the Jamaican police to arrest her as she leaves her home, cementing Miss Taro as the franchise''s very first villainous Bond girl or femme fatale. Following her notable performance in Dr. No, Marshall continued to act in international film and television projects during the 1960s, including appearances in the comedy classic Those Magnificent Men in Their Flying Machines, the spy series Danger Man, and the sci-fi horror film The Terrornauts. She retired from acting in the late 1960s and spent her remaining decades enjoying a quiet life in England while occasionally celebrating her enduring legacy as a pioneer of the James Bond series. Marshall passed away from cancer on July 10, 2009, in London, England, at the age of eighty-four.',
           'British',
           '1926-01-01',
           '2009-07-10',
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Eunice Gayson (Dr. No, From Russia With Love)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('cdae3d6e-adf8-4f68-8187-0a1c7fbbec95'),
       'Eunice Gayson',
       'Sylvia Trench',
       'Eunice Gayson was born Eunice Sarganson on March 17, 1928, in Croydon, Surrey, England. She trained in dance and opera before transitioning to screen acting in the late 1940s, quickly establishing herself as a talented and glamorous leading lady in British cinema, television, and theater. Throughout the 1950s, she appeared in numerous film and TV productions, notably starring alongside Peter Cushing in Hammer Film Productions'' classic gothic horror film The Revenge of Frankenstein in 1958, as well as making regular appearances in popular television series such as The Saint and The Avengers. Gayson secured her place in cinematic history in 1962 when director Terence Young cast her as Sylvia Trench in Dr. No, the inaugural Eon Productions James Bond film. As the elegant gambler at the baccarat table who first encounters Sean Connery, she earned the distinction of being the very first Bond girl on screen and famously prompted Connery''s iconic line delivery by introducing herself as "Trench, Sylvia Trench," leading to Bond''s legendary reply. Although her dialogue was dubbed by voice actress Nikki van der Zyl, Gayson returned to reprise her role as Sylvia Trench in From Russia with Love in 1963, making her the only actress to play the same romantic Bond girl across multiple official films. Following her historic Bond tenure, Gayson continued to enjoy a versatile career on stage and television, appearing in hit West End musical productions such as The Sound of Music and Into the Woods. In her later years, she embraced her legacy as a beloved pioneer of the Bond franchise, making frequent fan convention appearances and publishing an autobiography titled For The Sight Of Your Eyes in 2012. She passed away on June 8, 2018, at the age of ninety.',
       'British',
       '1928-03-17',
       '2018-06-08',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Kitzmiller (Dr. No)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('e20bc307-cf22-4e5d-b0e3-c8d9a0609995'),
       'John Kitzmiller',
       'Quarrel',
       'John Kitzmiller was an American actor born on December 4, 1913, in Battle Creek, Michigan. Before entering the entertainment industry, he earned a degree in chemical engineering from the University of Michigan and served as a captain in the United States Army Corps of Engineers during World War II. Deployed to Italy during the war, he opted to remain in the country following his military service, where he was discovered by Italian film producers while playing poker at an officers'' club. He quickly built a prolific screen career in post-war European cinema, becoming a prominent figure in Italian neorealism films and starring in over forty European productions, including prominent roles in Without Pity and Valley of Peace, the latter of which earned him the Best Actor award at the 1957 Cannes Film Festival.  Kitzmiller achieved international fame in 1962 when director Terence Young cast him as Quarrel in Dr. No, the inaugural Eon Productions James Bond film. As the skilled Caymanian fisherman and ally to Sean Connery''s James Bond and Jack Lord''s Felix Leiter, Kitzmiller provided essential local knowledge, navigation, and field support during the investigation of Crab Key, establishing Quarrel as the very first major recurring ally character in the cinematic franchise.  Following his landmark appearance in the Bond series, Kitzmiller continued to act in European film projects, concluding his career with the title role in the 1965 German drama film Uncle Tom''s Cabin. He passed away in Rome, Italy, on February 23, 1965, at the age of fifty-one. ',
       'American',
       '1913-12-04',
       '1965-02-23',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Peter Burton (Dr. No)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1e4433e7-de52-4ccc-a90c-9f1eebd522c3'),
       'Peter Burton',
       'Major Boothroyd (Q.)',
       'Peter Burton was a versatile English film and television actor, best remembered by film historians as the original actor to portray Major Boothroyd, the MI6 armorer, in the 1962 James Bond film Dr. No. Born on April 4, 1921, in Bromley, Kent, Burton served in the Royal Air Force during World War II before pursuing his passion for the dramatic arts. He built a steady and reliable career as a character actor throughout the 1950s, appearing in numerous British theatrical productions, television series, and feature films. When director Terence Young began casting the very first James Bond movie, Dr. No, Burton was chosen to play the armorer who famously forces Bond to trade in his Beretta for the iconic Walther PPK. Though his scene was brief, Burton established the foundation for the quartermaster character who would soon become universally known as Q. When the producers asked Burton to reprise his role for the 1963 sequel, From Russia with Love, scheduling conflicts with another acting assignment prevented him from taking the part. The role was then recast with Desmond Llewelyn, who went on to play the character for decades. Burton continued to work steadily in British television and cinema for several decades, appearing in popular shows like The Avengers, Saint, and The Professionals. He passed away from a heart attack on November 21, 1989, at the age of 68, leaving behind a memorable legacy as the man who first handed James Bond his signature firearm.',
       'British',
       '1921-04-04',
       '1989-11-21',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Robert Shaw (From Russia With Love)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b54ff1ba-e86e-423d-9f0f-630eb9cc80a5'),
       'Robert Shaw',
       'Grant',
       'Robert Archibald Shaw was an acclaimed English actor, novelist, and playwright, born on August 9, 1927, in Westhoughton, Lancashire. After honing his craft at the Royal Academy of Dramatic Art and performing with the Shakespeare Memorial Theatre, Shaw transitioned into film and television during the 1950s. He earned major international recognition in 1963 for his role as Donald "Red" Grant, the ruthless SPECTRE assassin who went head-to-head with Sean Connery''s James Bond in From Russia with Love. His chilling performance created one of the most memorable villain roles in the entire Bond franchise. Throughout the 1960s and 1970s, Shaw established himself as a powerful leading and character actor in Hollywood. He earned an Academy Award nomination for Best Supporting Actor for his depiction of King Henry VIII in A Man for All Seasons (1966). He continued to deliver iconic performances, notably playing the mob boss Doyle Lonnegan in The Sting (1973) and the hardened shark hunter Quint in Steven Spielberg''s 1975 blockbuster Jaws. Off the screen, Shaw was a accomplished writer, authoring several successful novels and stage plays, including The Man in the Glass Booth. Shaw’s life and career were cut tragically short when he suffered a fatal heart attack on August 28, 1978, at the age of 51, near his home in County Mayo, Ireland. Though his career spanned just over two decades, his intense screen presence and distinct talent leave an enduring legacy in cinema history.',
       'British',
       '1927-08-09',
       '1978-08-28',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Lotte Lenya (From Russia With Love)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('43c98c14-15da-4dc1-9f85-a444ac94edac'),
       'Lotte Lenya',
       'Rosa Klebb',
       'Lotte Lenya was an Austrian-American actress and singer whose career spanned over six decades across European theater, Broadway, and international cinema. Born Karoline Wilhelmine Charlotte Blamauer on October 18, 1898, in Vienna, she left home in her teens to study dance and drama in Zürich before moving to Berlin in the early 1920s to pursue acting. In Berlin, she met the composer Kurt Weill, whom she married in 1926. Lenya became a sensation of the Weimar-era theater scene, achieving major success when she created the role of Jenny in the 1928 premiere of Bertolt Brecht and Kurt Weill''s groundbreaking The Threepenny Opera (Die Dreigroschenoper). With the rise of the Nazi regime in Germany, Lenya and Weill fled Europe, eventually immigrating to the United States in 1935. In America, Lenya continued her stage work while devoting much of her energy to championing and preserving her late husband''s musical legacy after Weill passed away in 1950. She achieved renewed acclaim on Broadway during the 1950s and 1960s, winning a Tony Award for an off-Broadway revival of The Threepenny Opera and originating the role of Fräulein Schneider in the original 1966 Broadway production of Cabaret. Film audiences around the world recognized Lenya for her striking dramatic talent in major Hollywood and international productions. She earned an Academy Award nomination for Best Supporting Actress for her portrayal of a manipulative aristocrat in The Roman Spring of Mrs. Stone (1961). In 1963, she delivered one of the most famous performances in espionage cinema as Rosa Klebb, the ruthless, shoe-blade-wielding SPECTRE operative in the James Bond classic From Russia with Love. Lenya remained active in performing and overseeing the Kurt Weill Foundation until her death from cancer on November 27, 1981, in New York City at the age of 83.',
       'Austrian-American',
       '1898-10-18',
       '1981-11-27',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Daniela Bianchi (From Russia With Love)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9792842b-f8e4-43e3-8ffc-294ccac95e77'),
       'Daniela Bianchi',
       'Tatiana Romanova',
       'Daniela Bianchi is an Italian former actress and model, best known internationally for her leading role as the Bond girl Tatiana Romanova in the second James Bond film, From Russia with Love (1963). Born on January 31, 1942, in Rome, Italy, she studied ballet for eight years before establishing a successful career as a fashion model. Bianchi gained widespread attention in 1960 when she was crowned Miss Rome and subsequently named the first runner-up in the Miss Universe pageant, where she was also voted Miss Photogenic. Her success in pageantry brought her to the attention of the James Bond film producers, who cast her at the age of twenty-one to play Tatiana Romanova, a Soviet clerk used as an unwitting pawn by SPECTRE. Because of her limited English, her spoken dialogue in the film was dubbed by British actress Barbara Jefford, but Bianchi’s screen presence and charm made her an immediate international symbol of 1960s cinema. Following her breakout role in the Bond franchise, Bianchi appeared in a handful of European films throughout the mid-to-late 1960s, mostly in Italian and French spy thrillers and comedies. Notably, she starred in the 1967 Bond parody Operation Kid Brother alongside Sean Connery''s real-life brother, Neil Connery, as well as several other Bond film veterans. In 1970, Bianchi chose to retire from acting after marrying Genoese shipping magnate Alberto Cameli, stepping away from the public eye to focus on her private family life in Italy.',
       'Italian',
       '1942-01-31',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Pedro Armendáriz (From Russia With Love)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('c3a4a81d-42b8-4101-82a6-aa0e0f95e633'),
       'Pedro Armendáriz',
       'Kerim Bay',
       'Pedro Armendáriz was a legendary Mexican actor and one of the defining leading men of Latin American cinema''s Golden Age. Born Pedro Gregorio Armendáriz Hastings on May 9, 1912, in Mexico City, he spent much of his youth in Texas and later studied mechanics and engineering at California Polytechnic State University. Upon returning to Mexico, he was discovered by director Miguel Zacarías in 1935 while reciting a Shakespearean soliloquy to a tourist in a cafe. That chance encounter launched an acting career that established him as a premier talent in international film. Throughout the 1940s and 1950s, Armendáriz built a massive profile in Mexican, European, and Hollywood cinema. He frequently collaborated with director Emilio Fernández in acclaimed classics such as María Candelaria (1943), which won the Grand Prix at the Cannes Film Festival. His commanding, charismatic screen presence caught the eye of Hollywood giant John Ford, who featured him in prominent American films including The Fugitive (1947), Fort Apache (1948), and 3 Godfathers (1948). In 1963, Armendáriz brought his immense charm to the role of Ali Kerim Bey, the vibrant head of Station T in Istanbul, in the second James Bond feature, From Russia with Love. Unknown to most of the public, Armendáriz was suffering from terminal cancer during production. Despite severe pain, he pushed through filming to ensure financial security for his family, though director Terence Young ultimately had to step in as a double for a few remaining pick-up shots. Realizing his illness was terminal, Armendáriz ended his life on June 18, 1963, at the age of 51 at UCLA Medical Center, four months before From Russia with Love premiered. His portrayal of Kerim Bey remains celebrated as one of the finest allies in the entire Bond series.',
       'Mexican',
       '1912-05-09',
       '1963-06-18',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Vladek Shyebal (From Russia With Love)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('c654cb13-faf7-4deb-b5b1-694112598cd6'),
       'Vladek Shyebal',
       'Kronsteen',
       'Vladek Sheybal was a Polish character actor, director, and singer who built a prolific career in British and international film, television, and theatre. Born Władysław Rudolf Zbigniew Sheybal on March 12, 1923, in Zgierz, Poland, he survived imprisonment during World War II before beginning his acting career on the Polish stage and screen. He gained acclaim for his role in Andrzej Wajda''s classic film Kanał (1957). Seeking creative freedom, he left Poland in 1958 and eventually settled in the United Kingdom, where he initially worked as a drama teacher and theatre director. In 1963, recommended by his friend Sean Connery, Sheybal was cast as Kronsteen, the cold, calculating SPECTRE grandmaster and chief planner, in the James Bond hit From Russia with Love. His chilling performance as Kronsteen launched a long and successful career in Western cinema, where his distinctive voice, sharp features, and intense presence made him a sought-after actor for memorable character roles and sinister figures. Over the following three decades, Sheybal appeared in a wide array of notable films, including Billion Dollar Brain (1967), Ken Russell''s Women in Love (1969), The Wind and the Lion (1975), and the American action feature Red Dawn (1984). He was equally active on television, earning prominent roles in cult series such as Gerry Anderson''s UFO, as well as major miniseries including Shōgun (1980) and Smiley''s People (1982). In addition to his screen work, Sheybal continued to direct stage and television productions, expanding his artistic presence across Europe late in his career. He died unexpectedly in London on October 16, 1992, at the age of 69. Today, he is remembered as one of the most versatile character actors of his generation and a key contributor to classic European and British espionage cinema.',
       'Polish',
       '1923-03-12',
       '1992-10-16',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Walter Gotell (From Russia With Love)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6a6da807-3476-4aa6-970e-3de36e2631e3'),
       'Walter Gotell',
       'Morzeny',
       'Walter Gotell was a prolific German-British character actor who enjoyed a distinguished international screen career spanning six decades. Born Walter Karl Gotell on March 15, 1924, in Bonn, Germany, he fled to the United Kingdom with his family during the rise of the Nazi regime in the 1930s. He made his professional acting debut in British cinema during the early 1940s, frequently cast in military and authority roles throughout the post-war period due to his imposing stature, stern gaze, and natural authority. His early feature work included performances in major productions such as The African Queen (1951) and The Guns of Navarone (1961). In 1963, Gotell landed his first role in the James Bond series as Morzeny, the ruthless SPECTRE training camp instructor in From Russia with Love. While Morzeny was a memorable villain, Gotell gained far greater fame within the Bond franchise over a decade later when he returned in a completely different, recurring role. Starting with The Spy Who Loved Me (1977), he portrayed General Anatol Gogol, the charismatic and pragmatic head of the KGB. Gotell went on to play General Gogol across six consecutive Bond films spanning the Roger Moore and Timothy Dalton eras, making him one of the most recognizable and recurring supporting actors in the history of the 007 series. Beyond his legendary association with James Bond, Gotell built an extensive body of work in television and film on both sides of the Atlantic. He guest-starred in scores of popular American and British series, including The Saint, Star Trek: The Next Generation, The X-Files, Knight Rider, and MacGyver. Later in life, he settled in the United States, where he continued acting until the late 1990s. Gotell passed away from cancer on December 5, 1997, in London, England, at the age of 73, leaving behind an enduring legacy as one of the quintessential character actors of 20th-century entertainment.',
       'German-British',
       '1924-03-15',
       '1997-05-05',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Walter Gotell (The spy who loved me, moonraker, for your eyes only, octopussy, a view to a kill, the living daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('cdd278bb-6e17-4b6d-8587-c5f3436bdf40'),
       'Walter Gotell',
       'General Anatol Gogol',
       'Walter Gotell was a prolific German-British character actor who enjoyed a distinguished international screen career spanning six decades. Born Walter Karl Gotell on March 15, 1924, in Bonn, Germany, he fled to the United Kingdom with his family during the rise of the Nazi regime in the 1930s. He made his professional acting debut in British cinema during the early 1940s, frequently cast in military and authority roles throughout the post-war period due to his imposing stature, stern gaze, and natural authority. His early feature work included performances in major productions such as The African Queen (1951) and The Guns of Navarone (1961). In 1963, Gotell landed his first role in the James Bond series as Morzeny, the ruthless SPECTRE training camp instructor in From Russia with Love. While Morzeny was a memorable villain, Gotell gained far greater fame within the Bond franchise over a decade later when he returned in a completely different, recurring role. Starting with The Spy Who Loved Me (1977), he portrayed General Anatol Gogol, the charismatic and pragmatic head of the KGB. Gotell went on to play General Gogol across six consecutive Bond films spanning the Roger Moore and Timothy Dalton eras, making him one of the most recognizable and recurring supporting actors in the history of the 007 series. Beyond his legendary association with James Bond, Gotell built an extensive body of work in television and film on both sides of the Atlantic. He guest-starred in scores of popular American and British series, including The Saint, Star Trek: The Next Generation, The X-Files, Knight Rider, and MacGyver. Later in life, he settled in the United States, where he continued acting until the late 1990s. Gotell passed away from cancer on December 5, 1997, in London, England, at the age of 73, leaving behind an enduring legacy as one of the quintessential character actors of 20th-century entertainment.',
       'German-British',
       '1924-03-15',
       '1997-05-05',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Francis De Wolff (From Russia With Love)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7e86e8f3-1c43-40c2-aabf-e03d300b163d'),
       'Francis De Wolff',
       'Vavra',
       'Francis De Wolff was a prolific English character actor whose commanding physical presence, deep voice, and distinctive features made him a staple of mid-20th-century British cinema, theatre, and television. Born on January 7, 1913, in Essex, England, he began his professional acting career in the late 1930s, developing a reputation as a dependable and versatile performer. Throughout his four-decade career, his imposing frame and natural authority frequently saw him cast as formidable villains, rough-and-ready authority figures, pirates, and memorable historical characters. His film career includes appearances in several high-profile Hollywood and British epics, such as Moby Dick (1956), where he played Captain Gardiner, as well as Treasure Island (1950), Ivanhoe (1952), and From the Earth to the Moon (1958). In 1963, De Wolff was featured in the second James Bond film, From Russia with Love, portraying Vavra, the wise and formidable chief of the Romani camp in Turkey who hosts James Bond and Kerim Bey during their escape through Istanbul. His scene hosted the iconic and chaotic Romani camp battle sequence when rival forces launch a surprise raid. In addition to his cinematic work, De Wolff was an exceptionally active television actor throughout the 1960s and 1970s. He made guest appearances on classic British shows such as The Saint, The Avengers, Maigret, and the science-fiction series Doctor Who, where he famously played the Agamemnon character in the 1965 storyline The Myth Makers. He remained active in the British acting community until his retirement in the late 1970s. Francis De Wolff passed away on April 18, 1984, at the age of 71, leaving behind a rich filmography of classic British cinema and television roles.',
       'British',
       '1913-01-07',
       '1984-04-18',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Desmond Llewelyn (From Russia With Love, Goldfinger, Thunderball, you only live twice, on her majesty's secret service, diamonds are forever, the man with the golden gun, the spy who loved me, moonraker, for your eyes only, octopussy, a view to a kill, the living daylights, license to kill, goldeneye, tomorrow never dies, the world is not enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('ce7a54b2-aeb2-4603-94a7-83923c19c197'),
       'Desmond Llewelyn',
       'Q.',
       'Desmond Llewelyn was a Welsh actor best remembered around the world for his legendary portrayal of Q, the eccentric, gadget-crafting quartermaster of MI6 in the James Bond film series. Born on September 12, 1914, in Newport, Wales, Llewelyn originally considered a career in the clergy before realizing his true passion lay in acting, which led him to train at the Royal Academy of Dramatic Art in London. His acting career was abruptly interrupted by the outbreak of World War II, during which he served as a second lieutenant in the Royal Welch Fusiliers. In 1940, he was captured by German forces in France and spent five grueling years as a prisoner of war, standardizing a sense of patience and resilience that would later define his iconic screen persona. After the war, Llewelyn resumed working in British theater, television, and film. His big breakthrough came in 1963 when director Terence Young cast him as Major Boothroyd (Q) in From Russia with Love. Though he only appeared briefly to hand Sean Connery''s Bond a specially outfitted briefcase, his exasperated chemistry with 007 was an immediate hit with audiences. Llewelyn went on to play Q in 17 Bond films across five decades and alongside five different James Bond actors, making his final franchise appearance in 1999''s The World Is Not Enough. Tragically, Llewelyn passed away shortly after the premiere of The World Is Not Enough on December 19, 1999, following a car crash in East Sussex at the age of 85. Today, he remains one of the most beloved figures in cinematic history, praised for turning a minor supporting role into one of the most enduring, essential fixtures of modern cinema.',
       'Welsh',
       '1914-09-12',
       '1999-12-19',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Gert Fröbe (Goldfinger)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('bd0e5683-5691-43b2-8d26-9882af45826a'),
       'Gert Fröbe',
       'Auric Goldfinger',
       'Gert Fröbe was an acclaimed German character actor best known internationally for portraying the titular villain, Auric Goldfinger, in the 1964 James Bond classic Goldfinger. Born Karl Gerhart Fröbe on February 25, 1913, in Oberplanitz, Germany, he initially trained as a violinist before discovering a passion for cabaret, set decoration, and stage acting during the 1930s.  His life took a complex path during the interwar and World War II years. Joined to the Nazi Party as a teenager in 1929 due to economic promises, Fröbe grew disillusioned and resigned his membership in 1937. During the war, he worked as an actor in Vienna and used his situation to secretly hide a Jewish mother and her son from the Gestapo. Later, when German theaters were shuttered in late 1944, he was drafted into the German army, where he served until the end of the conflict. After the war, Fröbe established himself as one of post-war European cinema''s premier talents. He achieved breakout fame as "Otto Normalverbraucher" in the 1948 hit Berliner Ballade and went on to deliver a chilling performance as a child murderer in the 1958 film Es geschah am hellichten Tag (It Happened in Broad Daylight). That sinister performance caught the eye of James Bond producers Harry Saltzman and Albert R. Broccoli, who cast him as the gold-obsessed Auric Goldfinger. Although his iconic performance made him a global household name, Fröbe''s dialogue was largely dubbed by English actor Michael Collins due to his heavy German accent. The film was briefly banned in Israel following misquoted interview reports regarding his pre-war political ties, but the ban was quickly lifted when the Jewish survivor he had sheltered came forward to publicly clear his name. Following Goldfinger, Fröbe capitalized on his international stardom with major roles in big-budget productions, playing the villainous Baron Bomburst in Chitty Chitty Bang Bang (1968) and appearing in all-star ensemble films like The Longest Day (1962), Those Magnificent Men in Their Flying Machines (1965), and Is Paris Burning? (1966). He continued acting across stage, film, and television until his death from a heart attack on September 5, 1988, at the age of 75 in Munich. Today, Fröbe is remembered as one of the most larger-than-life villains in cinematic history.',
       'German',
       '1913-02-25',
       '1988-09-05',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Honor Blackman (Goldfinger)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('e0000e8d-601c-4412-8bde-8477c46c5518'),
       'Honor Blackman',
       'Pussy Galore',
       'Honor Blackman was an English actress whose charismatic screen presence and martial arts prowess made her an icon of 1960s British popular culture, best remembered internationally as the formidable pilot Pussy Galore in the 1964 James Bond classic Goldfinger. Born on December 22, 1925, in Plaistow, Essex, Blackman studied acting at the Guildhall School of Music and Drama in London, beginning her professional career on stage and in film during the late 1940s with notable roles in films like A Night to Remember (1958). Her major breakthrough arrived in 1962 when she was cast as Dr. Cathy Gale in the hit television series The Avengers. As one of television''s first strong, self-reliant female action heroes, Blackman underwent rigorous judo training and famously wore leather suits, setting a new precedent for female roles on television. Her success on The Avengers directly caught the attention of Bond producers, leading to her iconic casting in Goldfinger. At 38, she was noticeably older than Sean Connery, bringing a distinctive maturity, wit, and genuine physicality to the role of Pussy Galore, famously flipping Bond over her shoulder in a barn during one of the film''s most famous scenes. After leaving the Bond franchise, Blackman enjoyed a vast and varied career spanning six decades across theater, film, and television. She starred in films such as Jason and the Argonauts (1963) and Shalako (1968), and gained a new generation of fans playing Laura West in the popular 1990s British sitcom The Upper Hand. A lifelong political advocate and supporter of the Liberal Democrats, she turned down a CBE (Commander of the Order of the British Empire) in 2002. Blackman passed away peacefully of natural causes at her home in Lewes, Sussex, on April 5, 2020, at the age of 94, remembered as a pioneer for strong female characters in cinema.',
       'British',
       '1925-08-22',
       '2020-04-05',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Shirley Eaton (Goldfinger)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('00360161-535b-4e6e-938e-fdb31a5594ef'),
       'Shirley Eaton',
       'Jill Masterson',
       'Shirley Eaton is an English former actress and model who became an indelible cultural icon of 1960s cinema as Jill Masterson in the 1964 James Bond blockbuster Goldfinger. Born on January 12, 1937, in Edgware, Middlesex, Eaton displayed a natural talent for singing and performing at an early age. She trained at the Aida Foster Theatre School in London and made her professional stage debut at just twelve years old before transitioning into film and television during the early 1950s. Throughout the 1950s and early 1960s, Eaton established herself as a popular leading lady in British cinema, particularly in light comedies and musicals. She became a familiar face to audiences through her appearances in several early entries of the famed Carry On film franchise, including Carry On Sergeant (1958) and Carry On Nurse (1959). Her rising profile and glamorous screen appeal caught the attention of Bond producers Harry Saltzman and Albert R. Broccoli, leading to her casting in Goldfinger. Although Eaton only appears on screen for about five minutes in Goldfinger, her performance created one of the most famous visual images in cinematic history. As Jill Masterson, the doomed associate who betrays Auric Goldfinger for Sean Connery''s James Bond, she meets a grim fate by being painted head-to-toe in gold paint and suffocated. Her image covered in gold gilding served as the film''s iconic promotional artwork, gracing magazine covers worldwide—including Life magazine—and sealing her status as an enduring sex symbol of the era. Following her sensational role in Goldfinger, Eaton starred in several international films, including the underwater adventure Around the World Under the Sea (1966), the mystery Ten Little Indians (1965), and the fantasy flick The Girl from Rio (1969). However, at the peak of her career in 1969, Eaton chose to retire from acting at age thirty-two to dedicate herself fully to raising her family with her husband, Colin Rowe. Decades later, she published an autobiography titled Golden Girl and has enjoyed a quiet life pursuing painting and sculpting while remaining a beloved guest at film conventions around the world.',
       'British',
       '1937-01-12',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Tania Mallet (Goldfinger)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('fd1511fb-962c-483e-820c-59cf81daa48a'),
       'Tania Mallet',
       'Tilly Masterson',
       'Tania Mallet was an English model and actress best known internationally for playing Tilly Masterson in the 1964 James Bond film Goldfinger. Born on May 19, 1941, in Blackpool, England, to Henry Mallet and Olga Mironoff, she was educated in both England and France and was a cousin of actress Helen Mirren. She began modeling at age sixteen after attending Lucy Clayton''s modelling school, quickly becoming one of the top British fashion models of the late 1950s and early 1960s and gracing the cover of Vogue multiple times. Her entry into cinema began when she auditioned for the role of Soviet agent Tatiana Romanova in the second James Bond feature, From Russia with Love. Though she did not land that role, producer Albert R. Broccoli remembered her and subsequently cast her in Goldfinger. As Tilly Masterson, she played a woman seeking vengeance against Auric Goldfinger for the murder of her sister, Jill, before meeting a tragic fate at the hands of the henchman Oddjob and his steel-rimmed hat. Despite the global success of Goldfinger, the film served as Mallet''s only major screen appearance. She chose to walk away from acting and return to her lucrative modeling career due to the strict contractual restrictions on her personal life during filming, as well as the low weekly pay compared to what she earned as a model. She married Simon Radcliffe in 1976 and lived a quiet life outside the spotlight, though she occasionally attended James Bond conventions to meet fans. Mallet passed away on March 30, 2019, at the age of 77.',
       'British',
       '1941-05-19',
       '2019-03-30',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Harold Sakata (Goldfinger)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('8c575fc0-39e0-4e95-9c17-5b7922c81b40'),
       'Harold Sakata',
       'Oddjob',
       'Harold Sakata was an American professional wrestler, actor, and Olympic weightlifter who gained international fame for his portrayal of the silent, deadly henchman Oddjob in the 1964 James Bond film Goldfinger. Born Toshiyuki Sakata on July 1, 1920, in Holualoa, Hawaii, he was raised in a working-class Japanese-American family. During his youth, Sakata pursued weightlifting to build his strength, ultimately earning a spot on the United States Olympic team for the 1948 Summer Games in London, where he won a silver medal in the light-heavyweight division. Following his Olympic success, Sakata transitioned into professional wrestling, adopting the ring name Tosh Togo. Throughout the 1950s and early 1960s, he built a successful career in North America and Japan, often playing a formidable heel character due to his imposing physical stature and athletic background. His distinct build and intimidating presence caught the attention of Bond producers Harry Saltzman and Albert R. Broccoli, who were searching for an actor to bring Ian Fleming''s formidable killer to life on screen. Sakata''s performance as Oddjob became one of the most memorable elements of Goldfinger and established a template for cinematic henchmen. Despite having no spoken dialogue in the film, he conveyed immense presence through physical performance, utilizing his character''s iconic steel-rimmed bowler hat as a lethal weapon. Sakata famously demonstrated his extreme professional dedication during the filming of Oddjob''s death scene, sustaining heavy burns on his hands while holding onto the metal bars of a vault gate during a electrocution stunt to avoid ruining the take before director Guy Hamilton called cut. The massive success of Goldfinger redefined Sakata''s career, leading to numerous roles in feature films, television shows, and commercials worldwide, often playing formidable enforcers or tongue-in-cheek parodies of his famous Bond persona. He remained an affectionate and active figure within the entertainment industry and fan community until his death from cancer on July 29, 1982, in Honolulu, Hawaii, at the age of 62.',
       'American',
       '1920-07-01',
       '1982-07-29',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Martin Benson (Goldfinger)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1e82c200-e556-4b08-ac08-21bbee477d32'),
       'Martin Benson',
       'Mr. Solo',
       'Martin Benson was an English character actor who enjoyed a prolific career spanning six decades in theater, film, and television, best remembered internationally for playing the ill-fated mobster Mr. Solo in the 1964 James Bond classic Goldfinger. Born on August 10, 1918, in London, England, Benson developed an interest in drama early in life. During World War II, he served in the Royal Artillery and spent time in North Africa, where he helped entertain troops by co-founding the Mercury Theatre Company to lift morale. Upon returning to civilian life, Benson quickly established himself as a versatile and reliable character actor in British cinema and television. Possessing a distinctive, angular face and commanding voice, he was frequently cast in foreign, sinister, or authoritative roles. One of his early high-profile roles came in the 1956 musical film The King and I, where he portrayed the Kralahome, the stern Prime Minister of Siam, acting opposite Yul Brynner and Deborah Kerr. His casting in Goldfinger provided him with one of the most memorable scenes in early Bond history. As Mr. Solo, the lone gangster who refuses to join Auric Goldfinger''s scheme to raid Fort Knox, Benson played a crucial narrative foil to the villain. His character meets a famously gruesome end when he is driven away by Oddjob, shot, and subsequently crushed inside a Lincoln Continental at a scrapyard, creating one of the franchise''s most famous set pieces. Throughout the rest of his career, Benson remained a tireless worker in the entertainment industry. He appeared in dozens of acclaimed films, including Cleopatra (1963), The Pink Panther Strikes Again (1976), and the classic horror film The Omen (1976), in which he played Father Spiletto. In addition to acting, Benson was a talented amateur painter. He continued working in television and film well into his eighties before passing away in his sleep on February 28, 2010, at his home in Buckinghamshire, England, at the age of 91.',
       'British',
       '1918-08-10',
       '2010-02-28',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Cec Linder (Goldfinger)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('873a7cf6-4169-4a26-8875-21c478819609'),
       'Cec Linder',
       'Felix Leiter',
       'Cec Linder was a Polish-born Canadian film, television, and stage actor who built a prolific career across North America and Europe, best remembered globally for portraying CIA agent Felix Leiter in the 1964 James Bond classic Goldfinger. Born Cecilius Linder on March 10, 1921, in Galanta, Poland (now Slovakia), he immigrated with his family to Canada as an infant and grew up in Timmins, Ontario. Linder developed an early passion for performance, honing his craft in Canadian radio and theater before making the transition to screen acting in the 1950s. Throughout the 1950s and 1960s, Linder established himself as a versatile character actor, dividing his time between Canada, the United States, and Great Britain. His rugged features and calm, authoritative presence made him a natural fit for roles as mature professionals, detectives, military officers, and politicians. In 1959, he delivered a praised performance as Dr. Jean Morelle in the British sci-fi horror film Quatermass and the Pit, which elevated his profile within the UK film industry and eventually led to his casting in Goldfinger. Linder joined the Goldfinger production on short notice, stepping into the role of James Bond''s American ally Felix Leiter after the character was recast. Playing opposite Sean Connery, Linder portrayed a somewhat older, more world-weary version of Leiter compared to Jack Lord''s slicker rendition in Dr. No. His relaxed chemistry with Connery grounded the CIA-MI6 dynamic, helping Bond track Auric Goldfinger across Kentucky and providing vital intelligence during the dramatic climax at Fort Knox. Following his iconic turn as Leiter, Linder enjoyed a long and active career across both side of the Atlantic. He became a staple of Canadian television and film, appearing in popular series such as The Edge of Night, Little House on the Prairie, and Bionic Woman, as well as films like Lolita (1962), A Christmas Story (1983), and Running Brave (1983). Over four decades in the industry, he earned widespread respect among peers for his quiet professionalism and reliability. Linder passed away from complications of emphysema on April 10, 1992, in Toronto, Ontario, at the age of 71.',
       'Polish-Canadian',
       '1921-03-10',
       '1992-04-10',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Richard Vernon (Goldfinger)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b4e24df3-d3b8-481c-bcbe-e3dd42c8796f'),
       'Richard Vernon',
       'Colonel Smithers',
       'Richard Vernon was an English character actor renowned for his dignified bearing, dry wit, and distinctive, prematurely aged appearance that made him a staple of British film, television, and radio for decades. Born Richard Evelyn Vernon on March 7, 1925, in Naivasha, Kenya Colony, he returned to England for his education and trained at the Royal Central School of Speech and Drama. With his receding hairline, aristocratic posture, and polished, authoritative voice, Vernon quickly carved out a niche playing stuffy establishment figures, bank executives, politicians, and high-ranking military officers while still in his thirties. Vernon gained cinematic prominence in 1964 when he appeared in two defining British films of the era: as the grumpy railway passenger sharing a compartment with the Fab Four in A Hard Day''s Night, and as Colonel Smithers of the Bank of England in the James Bond classic Goldfinger. Appearing opposite Sean Connery and Bernard Lee, Vernon delivered a memorable performance over dinner at the Bank of England, briefing 007 on Auric Goldfinger''s gold-smuggling operation and introducing the bar of Nazi bullion used to bait Goldfinger into a high-stakes game of golf. Goldfinger stands as Vernon''s sole appearance in the James Bond film franchise. Following his turn in Goldfinger, Vernon enjoyed a long and distinguished career across multiple genres. Sci-fi fans came to know him as the fjord-building planetary designer Slartibartfast in both the original radio and 1981 television adaptations of The Hitchhiker''s Guide to the Galaxy. His screen resume also included prominent roles in The Pink Panther Strikes Again (1976), The Human Factor (1979), Evil Under the Sun (1982), and political satirical series such as The Sandbaggers, Yes Minister, and Yes, Prime Minister, where he played the dim-witted bank governor Sir Desmond Glazebrook. Vernon continued working consistently until his death from Parkinson''s disease on December 4, 1997, in London, at the age of 72.',
       'British',
       '1925-03-07',
       '1997-12-04',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Austin Willis (Goldfinger)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d9605726-4654-4b4f-8f31-a40bd97f6625'),
       'Austin Willis',
       'Mr. Simmons',
       'Austin Willis was a Canadian actor, television host, and broadcasting pioneer whose suave screen presence and smooth baritone voice made him a fixture of North American and British entertainment for over half a century. Born Alexander Austin Willis on September 30, 1917, in Halifax, Nova Scotia, he initially pursued a career in broadcasting, becoming a prominent radio announcer in Canada during the late 1930s before serving as a lieutenant in the Royal Canadian Navy during World War II. After the war, Willis transitioned seamlessly into acting, finding success on stage, screen, and as one of the earliest television presenters for the Canadian Broadcasting Corporation. In the early 1960s, Willis moved to England to expand his acting opportunities, which landed him his famous role in the 1964 James Bond classic Goldfinger. Willis played Mr. Simmons, the wealthy American card player who falls victim to Auric Goldfinger''s cheating during a high-stakes gin rummy game at the Fontainebleau Hotel in Miami. In the scene, Sean Connery''s James Bond intercepts Goldfinger''s earpiece and blackmails the villain into losing $15,000 to a delighted Simmons. Goldfinger marks Willis''s single appearance in the 007 franchise, though he originally read for the role of Felix Leiter before swapping parts with fellow Canadian actor Cec Linder just before filming. Returning to Canada in the mid-1960s, Willis solidified his legacy as a versatile performer and major television personality. He hosted popular Canadian game shows and variety programs, including This Is Law and Cross-Canada Hit Parade, while continuing to land roles in feature films such as Eight Men Out (1988). Later in life, he retired to Nova Scotia, where he remained active in local arts and community work, eventually receiving the Order of Canada in 2002 for his lifelong contributions to the nation''s broadcasting and performing arts. Willis passed away from natural causes on April 4, 2004, in Dartmouth, Nova Scotia, at the age of 86.',
       'Canadian',
       '1917-09-30',
       '2004-04-04',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Claudine Auger (Thunderball)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9e50aa52-4905-4ce0-a50d-045d651c1f97'),
       'Claudine Auger',
       'Dominique "Domino" Derval',
       'Claudine Auger was a French actress, model, and former beauty queen who gained worldwide fame as the leading lady in the fourth James Bond installment, Thunderball (1965). Born Claudine Oger on April 26, 1941, in Paris, she excelled in the arts from an early age, attending the Conservatoire de Paris while launching a highly successful modeling career. She brought national attention to her home country after winning the Miss France Monde title and finishing as the first runner-up in the 1958 Miss World competition. This success seamlessly opened doors in French theater and cinema, where she secured early supporting roles in films such as Jean Cocteau’s Testament of Orpheus (1960). Auger achieved international stardom when director Terence Young cast her as Dominique "Domino" Derval in Thunderball. Originally envisioned as an Italian woman named Domino Vitali in Ian Fleming''s novel and early script drafts, the character was specially rewritten into a French woman to suit Auger after her impressive screen test. As the mistress of SPECTRE villain Emilio Largo and sister to a murdered NATO pilot, Auger delivered a strong, physical performance opposite Sean Connery, performing her own underwater swimming stunts in the Bahamas. Though her voice was ultimately dubbed in post-production by voice artist Monica van der Zyl due to accent considerations, Auger became the very first French actress to play a primary Bond girl, setting a prominent precedent for the franchise. Following her landmark turn in Thunderball, Auger returned to Europe, where she built a diverse and prolific screen career across mainstream cinema and arthouse projects. She reteamed with Terence Young and Sean Connery''s former co-stars in the World War II thriller Triple Cross (1966), and went on to become a popular figure in Italian giallo thrillers, including A Bay of Blood (1971) and Black Belly of the Tarantula (1971). Over nearly four decades in entertainment, she accumulated over eighty film and television credits throughout France, Italy, and the UK before retiring from acting in the late 1990s. Auger passed away on December 18, 2019, in Paris at the age of 78.',
       'French',
       '1941-04-26',
       '2019-12-18',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Adolfo Celi (Thunderball)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('5945d8f8-fe87-4854-a578-ca8999db5366'),
       'Adolfo Celi',
       'Emilio Largo',
       'Adolfo Celi was a celebrated Italian actor and director who earned international acclaim for his powerful presence, gravelly voice, and commanding portrayals of suave on-screen villains, most famously playing the eyepatch-wearing SPECTRE operative Emilio Largo in the 1964 James Bond classic Thunderball. Born on July 27, 1919, in Messina, Sicily, Celi studied acting at the prestigious Academy of Dramatic Art in Rome. Following World War II, he emigrated to Brazil, where he spent over a decade working as a respected theater director and filmmaker, helping to pioneer modern Brazilian theater and co-founding the Vera Cruz Film Company in São Paulo. Returning to Europe in the early 1960s, Celi transitioned smoothly into international film roles, quickly catching the attention of global audiences after starring alongside Jean-Paul Belmondo in the hit French adventure-comedy That Man from Rio (1964). His international star power spiked when director Terence Young cast him in Thunderball as Emilio Largo, SPECTRE''s ruthless Number Two who orchestrates the theft of two atomic bombs. Playing opposite Sean Connery and Claudine Auger, Celi crafted one of the Bond franchise''s most iconic villains, complete with a distinctive eye patch, a pool full of man-eating sharks, and a tense skeet-shooting showdown at his Nassau estate. Although his voice was dubbed in post-production by actor Robert Rietty due to Celi''s heavy Sicilian accent, his physical performance established Largo as a definitive benchmark for Bond antagonists. Thunderball stands as Celi''s sole official appearance in the James Bond film series. Following Thunderball, Celi enjoyed a remarkably busy career across European cinema, becoming a sought-after lead and supporting actor in dozens of films each year. He showcased his versatility by moving effortlessly between serious dramas, historical epics, and popular comedies. Notable credits include the World War II drama Grand Prix (1966), the cult caper movie Danger: Diabolik (1968), and the wildly successful Italian comedy series Amici miei (1975). He also portrayed Pope Alexander VI in the acclaimed BBC television production The Borgias (1981). Throughout his life, Celi remained deeply committed to both the stage and screen until he passed away from a heart attack on February 19, 1986, in Siena, Italy, at the age of 66.',
       'Italian',
       '1922-07-27',
       '1986-02-19',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Luciana Paluzzi (Thunderball)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('ff4249e4-3b9f-47ba-902f-23438baf10f3'),
       'Luciana Paluzzi',
       'Fiona Volpe',
       'Luciana Paluzzi is an Italian-American actress who earned international acclaim and cemented her place in pop culture history as the ruthless, redheaded SPECTRE assassin Fiona Volpe in the fourth James Bond film, Thunderball (1965). Born on June 10, 1937, in Rome, Italy, she originally pursued an education in naval architecture before pivoting toward dramatic arts. She made her uncredited screen debut in the American romantic comedy Three Coins in the Fountain (1954), which quickly led to a steady stream of roles across Italian, French, and British cinema throughout the late 1950s, as well as a starring role in the spy thriller television series Five Fingers (1959). Paluzzi achieved global stardom in Thunderball, delivering a magnetic performance as one of the most celebrated and lethal "femme fatale" figures in cinema history. She originally auditioned for the role of the primary Bond girl, Dominique "Domino" Derval, but director Terence Young and the producers felt her dynamic energy and fierce screen presence were far better suited for the film''s main female antagonist. As Fiona Volpe, Paluzzi commanded the screen opposite Sean Connery, performing high-speed motorcycle stunts, executing SPECTRE operatives, and famously delivering sharp, mocking dialogues about Bond''s legendary charm before meeting her end on a crowded Bahamas dance floor. Unlike many foreign Bond actresses of that era, Paluzzi voiced her own lines in the English release, earning praise for her distinct voice and striking performance. Following Thunderball, Paluzzi enjoyed a prolific career spanning both sides of the Atlantic, continuously working across feature films, television, and international co-productions. She starred in a wide array of genre cinema throughout the 1960s and 1970s, including popular Italian giallo thrillers, sci-fi pictures like The Green Slime (1968), and westerns such as Chuka (1967). She also made frequent guest appearances on prominent American television series, including Hawaii Five-O, The Six Million Dollar Man, and Search for Tomorrow. Paluzzi retired from screen acting in the late 1970s, leaving behind a rich filmography of over eighty credits, with her fiery turn in Thunderball remaining a high-water mark for villainous performances in the action-spy genre.',
       'Italian-American',
       '1937-06-10',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Rik Van Nutter (Thunderball)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b2a65f16-c009-48c0-8beb-6b44de662420'),
       'Rik Van Nutter',
       'Felix Leiter',
       'Rik Van Nutter was an American actor and screenwriter best remembered by film audiences for his charismatic turn as CIA agent Felix Leiter in the fourth James Bond adventure, Thunderball (1965). Born Allen Reynolds Van Nutter on May 1, 1929, in Los Angeles, California, he spent much of his early life pursuing a variety of creative passions before finding his footing in the entertainment industry. Blessed with tall, athletic good looks and classic Hollywood appeal, Van Nutter initially broke into film and television during the late 1950s, building up steady work on both sides of the Atlantic. Van Nutter achieved his most enduring screen fame when he was selected to play James Bond''s close American ally, Felix Leiter, opposite Sean Connery in Thunderball. He was the third actor to take on the recurring role, following Jack Lord in Dr. No and Cec Linder in Goldfinger. Bringing a relaxed, effortlessly cool swagger to the Nassau-set spy thriller, Van Nutter shared great on-screen chemistry with Connery as they investigated SPECTRE''s stolen atomic weapons. His connection to the franchise went beyond his audition, as he was married at the time to Swedish actress Anita Ekberg, who was a close acquaintance of Bond producer Albert R. Broccoli. Van Nutter''s laid-back performance helped establish the easygoing, collaborative friendship between 007 and Leiter that became a staple of the long-running series. Following his notable appearance in Thunderball, Van Nutter worked primarily in European cinema throughout the late 1960s and 1970s. He starred in several Italian spaghetti westerns under the pseudonym Clyde Rogers, including lead roles in Seven Hours of Gunfire (1965) and Dynamite Joe (1967). In addition to acting, he expanded into screenwriting and film production, contributing to several European action and adventure projects. After stepping away from the film industry, he led a quiet life away from the Hollywood spotlight, maintaining his passion for travel, writing, and ocean sailing. Van Nutter passed away on October 15, 2005, in West Palm Beach, Florida, at the age of 76.',
       'American',
       '1929-05-01',
       '2005-10-15',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Guy Doleman (Thunderball)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('a4433ce2-760e-429f-bc40-4c00729c53e5'),
       'Guy Doleman',
       'Count Lippe',
       'Guy Doleman was a distinguished New Zealand-born character actor who earned international recognition across movie and television roles, including his memorable turn as the sinister SPECTRE operative Count Lippe in the James Bond blockbuster Thunderball (1965). Born Guy Hamilton Doleman on November 22, 1923, in Hamilton, Waikato, New Zealand, he was raised in Australia, where he initially embarked on his acting career. After serving in the Royal Australian Air Force during World War II, Doleman rapidly established himself as one of Australia’s premier radio and stage performers before making a smooth transition to feature films in the late 1940s, appearing in early classic Australian productions like The Overlanders (1946) and Smiley (1956). Seeking broader opportunities, Doleman relocated to the United Kingdom in the early 1960s, where his imposing height, sharp features, and authoritative screen presence made him an in-demand character actor. His career reached a major peak in 1965 when he secured two prominent spy film roles. First, he starred as the austere, no-nonsense intelligence officer Colonel Ross opposite Michael Caine in The Ipcress File (1965), a role he would reprise in two sequels. That same year, Terence Young cast him in Thunderball as Count Lippe, the SPECTRE operative stationed at the Shrublands health clinic where James Bond is recuperating. Doleman delivered a tense, menacing performance opposite Sean Connery, engaging in a memorable sequence of sabotage in a traction machine before meeting a dramatic demise on a country road at the hands of Fiona Volpe''s rocket-firing motorcycle. Following his standout performance in Thunderball, Doleman enjoyed a prolific and globe-spanning career in cinema and television for over three decades. He maintained a steady presence in British screen productions throughout the 1960s and 1970s, appearing in classic series like The Prisoner, The Avengers, and The Saint, before returning to Australia to continue working in local film and television. In addition to his reprise of Colonel Ross in the 1990s Harry Palmer television movies Bullet to Beijing and Midnight in Saint Petersburg, Doleman compiled over one hundred screen credits across his long career. He spent his final years living in Australia until he passed away from lung cancer on January 30, 1996, in Los Angeles, California, at the age of 72.',
       'New Zealand',
       '1923-11-22',
       '1996-01-30',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Molly Peters (Thunderball)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('51615a0a-93e1-4b23-a947-f9f975e70c8c'),
       'Molly Peters',
       'Patricia "Pat" Fearing',
       'Molly Peters was an English actress and model who earned a distinct place in cinema history as a classic Bond girl, best remembered for her role as nurse Patricia Fearing in the fourth James Bond film, Thunderball (1965). Born Vivien Mollie Rudderham in Walsham-le-Willows, Suffolk, she began her career working as a model in her late teens, appearing on the covers of various men''s magazines. Her striking looks quickly caught the eye of director Terence Young, who chose to cast her in the high-profile 007 production. In Thunderball, Peters portrayed Patricia "Pat" Fearing, a nurse at the Shrublands health clinic who treats James Bond (Sean Connery) while he is recuperating. Her performance proved notable in franchise lore as she became the first Bond girl to undress on screen in the series, generating considerable media attention and adding a provocative edge to the film''s promotional campaign. Despite the widespread fame generated by her appearance in Thunderball, Peters had a relatively brief screen career due to contractual complications with her management following the film''s massive success. She went on to appear in a few screen projects during the late 1960s, including the comedy Don''t Raise the Bridge, Lower the River (1968) alongside Jerry Lewis, before stepping away from acting altogether. After leaving show business, she lived a quiet life in England with her family. Peters passed away on May 30, 2017, at the age of 75.',
       'British',
       '1942-03-15',
       '2017-05-30',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Martine Beswick (Thunderball)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('18f4a452-ac99-4f36-a53b-e5cc3093ed73'),
       'Martine Beswick',
       'Paula Caplan',
       'Martine Beswick is a British-Jamaican actress and former model who holds a unique distinction in 007 lore as one of the few actresses to play prominent, unrelated Bond girls across multiple films in the series. Born Mary Rose Penso Beswick on September 26, 1941, in Port Antonio, Jamaica, she grew up on the island before moving to London with her family in the mid-1950s. Determined to pursue a career in entertainment, she worked as a model and entered beauty pageants, placing as runner-up in Miss Jamaica, before setting her sights on acting. Beswick launched her feature film career in the James Bond franchise after director Terence Young spotted her potential. Although an initial audition for the series debut Dr. No (1962) did not pan out, she was cast in the second entry, From Russia with Love (1963), portraying the fiery gypsy girl Zora. Her performance was highlighted by a famous, intense catfight scene opposite Aliza Gur''s character Vida. Impressed by her screen presence, Young recruited Beswick two years later for Thunderball (1965). In her second Bond appearance, she took on a larger role as Paula Caplan, a CIA operative based in Nassau who assists James Bond (Sean Connery) before heroically taking her own life to avoid revealing secrets under interrogation. She also briefly appeared as one of the dancing silhouettes in the opening title credits of Dr. No, cementing a three-film connection to the early Bond era. Following her success in the Bond films, Beswick established herself as a prominent cult film actress and Hammer Horror icon throughout the late 1960s and 1970s. She starred opposite Raquel Welch in One Million Years B.C. (1966), headlined Prehistoric Women (1967), and played the lead role of Sister Hyde in Hammer''s Dr. Jekyll and Sister Hyde (1971). She later relocated to Hollywood, expanding her career into American television with appearances in series such as Mannix, The Six Million Dollar Man, Falcon Crest, and Fantasy Island. Beswick retired from full-time acting in the 1990s and remains a beloved figure among cinema fans, frequently appearing as a guest at international film retrospectives and Bond conventions.',
       'Jamaican-British',
       '1941-09-26',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Philip Locke (Thunderball)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2aee5fcc-cbf1-4b62-930c-bb2e54118af0'),
       'Philip Locke',
       'Vargas',
       'Philip Locke was a highly respected English character actor of stage, television, and film, best known to international cinema audiences for his performance as the stern, cold-blooded henchman Vargas in the fourth James Bond film, Thunderball (1965). Born on March 29, 1928, in St Marylebone, London, Locke developed a passion for performance at an early age and went on to train as an actor, building a reputation for his precise, menacing screen presence and remarkable physical discipline. Locke earned his place in James Bond history with his turn as Vargas, the silent, tea-drinking right-hand man to SPECTRE villain Emilio Largo (Adolfo Celi) in Thunderball. Characterized by his dark sunglasses, stoic demeanor, and absolute lack of vice—famously noted by Largo, who tells Sean Connery’s 007 that Vargas does not drink, smoke, or make love—Locke created a memorable, imposing henchman without relying on dialogue. His character ultimately meets a dramatic end when Bond impales him with a speargun on a Bahamian beach, delivering the classic line, "I think he got the point." Beyond his iconic role in the Bond franchise, Locke enjoyed a long and distinguished career that spanned five decades, with a heavy emphasis on classical theater and British television. He was a long-standing member of the Royal Shakespeare Company, where he performed in numerous productions, including playing the character of Professor Moriarty in the RSC''s acclaimed theatrical run of Sherlock Holmes on Broadway and the West End. On television, he appeared in dozens of iconic British shows, including Doctor Who, The Avengers, Inspector Morse, The Saint, and Casualty. Locke continued working across stage and screen throughout the late 20th century before he passed away on April 19, 2004, at the age of 76.',
       'British',
       '1928-03-29',
       '2004-04-19',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Akiko Wakabayashi (You Only Live Twice)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('e3bb1524-e053-4c27-88d0-8dcb524b5931'),
       'Akiko Wakabayashi',
       'Aki',
       'Born on December 13, 1939, in Tokyo, Japan, Akiko Wakabayashi is a retired actress best known to international audiences as the clever Japanese Secret Service agent Aki in the 1967 James Bond classic You Only Live Twice. She began her acting career in the late 1950s and quickly established herself as a popular star during the golden era of Toho Studios. Throughout the 1960s, she starred in major Japanese monster and science-fiction films, including King Kong vs. Godzilla, Dogora, the Space Monster, and Ghidorah, the Three-Headed Monster. Her work also gained international traction when footage from her 1965 spy movie was re-dubbed by Woody Allen for his famous directorial debut, What''s Up, Tiger Lily?. Her definitive international role arrived when she was cast alongside Sean Connery in You Only Live Twice. Originally chosen for a smaller role, Wakabayashi was reassigned to play Bond''s primary local ally when her co-star struggled with the English script. She personally suggested changing her character''s name to Aki, and her vibrant portrayal made her one of the most proactive Bond companions of the era. Shortly after her success in the Bond franchise, Wakabayashi retired from acting in the early 1970s following a few final television appearances, later noting that injuries sustained while filming contributed to her decision to step away from the spotlight.',
       'Japanese',
       '1939-12-13',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Mie Hama (You only live twice)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('cf38626f-fdf1-42dd-9443-6673b20916e6'),
       'Mie Hama',
       'Kissy',
       'Born on November 20, 1943, in Tokyo, Japan, Mie Hama is a Japanese former actress, author, and television presenter best known internationally for playing the Ama diver Kissy Suzuki in the 1967 James Bond film You Only Live Twice. Hama was discovered by film producer Tomoyuki Tanaka while working as a bus conductor as a teenager. She joined Toho Studios and rapidly became one of Japan''s most sought-after stars during the golden age of Japanese cinema. By the time she was cast in a James Bond film, she had already accumulated over 60 movie credits. She gained prominent fame through Toho’s major fantasy and kaiju monster films, starring as Fumiko Sakurai in King Kong vs. Godzilla (1962), as well as appearing in The Lost World of Sinbad (1963) and King Kong Escapes (1967). Like her co-star Akiko Wakabayashi, she also featured in the 1965 Japanese spy flick that was later re-dubbed into Woody Allen''s What''s Up, Tiger Lily?. When cast in You Only Live Twice, Hama was initially chosen to play the primary agent character Aki, while Akiko Wakabayashi was set to play Kissy Suzuki. However, when Hama struggled to learn English under a tight shooting schedule, the producers decided to swap their roles, giving Hama the role of Kissy, which had significantly less English dialogue. Hama stepped away from feature film acting shortly after her international success to pursue a normal life. She went on to enjoy a multifaceted career as an author of over a dozen books, a radio and television host, a advocate for environmental preservation, and an expert in traditional Japanese folk arts and farming practices.',
       'Japanese',
       '1943-11-20',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Tetsurô Tanba (You Only Live Twice)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9cd4010c-66d4-476b-9af8-7b149dda8d12'),
       'Tetsurô Tanba',
       'Tiger Tanaka',
       'Born Shozaburo Tanba on July 17, 1922, in Tokyo, Japan, Tetsurō Tanba was one of Japan''s most prolific and respected actors, with a career spanning over five decades and nearly 300 film and television credits. Western audiences know him best as Tiger Tanaka, the charismatic head of the Japanese Secret Service who partnered with Sean Connery in the 1967 James Bond film You Only Live Twice. Tanba began his screen acting career in the early 1950s and quickly became a prominent leading man during the golden age of Japanese cinema. Over his long career, he collaborated with many of Japan''s acclaimed directors, including Masaki Kobayashi, Kinji Fukasaku, Shōhei Imamura, and Takashi Miike, earning critical acclaim and a Japan Academy Film Prize for Best Supporting Actor in 1981. His entrance into Western cinema was aided by director Lewis Gilbert, who had previously worked with Tanba on the 1964 drama The 7th Dawn and brought him on for You Only Live Twice. Tanba also played a pivotal off-screen role in casting the film, as he recommended both Akiko Wakabayashi and Mie Hama to the Bond producers. His international career included other notable roles, such as starring in the 1969 spaghetti Western The Five Man Army. In the latter part of his life, Tanba expanded his pursuits beyond acting to become a published author on spiritual topics and psychic phenomena. He remained active in the entertainment industry up until his death from pneumonia on September 24, 2006, at the age of 84.',
       'Japanese',
       '1922-07-17',
       '2006-09-24',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Teru Shimada (You Only Live Twice)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6880782a-9a10-4320-bc78-d123010f5794'),
       'Teru Shimada',
       'Mr. Osato',
       'Born Akira Shimada on November 17, 1905, in Mito, Ibaraki, Japan, Teru Shimada was a Japanese-born American actor best known internationally for playing the villainous SPECTRE industrialist Mr. Osato in the 1967 James Bond film You Only Live Twice. Shimada emigrated to the United States in the 1920s to pursue an acting career, initially training in theater before transitioning into Hollywood film and television. Over the decades, he established himself as a reliable character actor in American productions, often cast in supporting roles across movies and popular TV series such as Perry Mason, Hawaii Five-O, Voyage to the Bottom of the Sea, and The Six Million Dollar Man. One of his notable early film successes included starring alongside Humphrey Bogart in the 1949 drama Tokyo Joe. His most iconic role came when he was cast in You Only Live Twice as Mr. Osato, the head of Osato Chemicals who secretly collaborates with SPECTRE. In the film, he shares memorable scenes with Sean Connery, including the famous moment where he coldly orders his secretary, Helga Brandt, to execute Bond. Shimada retired from acting in the mid-1970s and lived quietly in California until his death on June 19, 1988, at the age of 82.',
       'Japanese-American',
       '1905-11-17',
       '1988-06-19',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Karin Dor (You Only Live Twice)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('74266ff6-a095-411c-85a3-12fc49989ac5'),
       'Karin Dor',
       'Helga Brandt',
       'Born Kätherose Derr on February 22, 1938, in Wiesbaden, Germany, Karin Dor was a celebrated German actress best remembered internationally for her role as the lethal SPECTRE assassin Helga Brandt in the 1967 James Bond film You Only Live Twice. Dor began her acting career in her teens during the mid-1950s and quickly rose to stardom in German cinema, frequently starring as the fragile heroine in popular Karl May Western adaptations and Edgar Wallace crime mysteries. Many of these successful films were directed by her first husband, Harald Reinl. Her strikingly elegant looks and dramatic range earned her the nickname "Miss Crime" in her homeland due to her frequent appearances in thriller films. Her international profile expanded significantly when she was cast as Helga Brandt, the dangerous secretary and operative working alongside Mr. Osato in You Only Live Twice. Her character famously seduces Sean Connery''s James Bond before trying to kill him in a plane crash, ultimately meeting an iconic demise when Blofeld drops her into a piranha-filled pool for failing her mission. Following her Bond success, Dor went on to achieve another major Hollywood milestone when Alfred Hitchcock cast her as Juanita de Cordoba in his 1969 Cold War thriller Topaz. Dor enjoyed an exceptionally long and varied career, remaining active across international cinema, German television, and stage theater for over six decades. She continued performing into her seventies, receiving critical acclaim for her late-career theater work and her role in the 2006 drama I Am the Other Woman. Dor passed away on November 6, 2017, in a Munich hospital at the age of 79.',
       'German',
       '1938-02-22',
       '2017-11-06',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Donald Pleasence (You Only Live Twice)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d2618e5a-6828-4f98-886f-fe5e39184f24'),
       'Donald Pleasence',
       'Ernst Stavro Blofeld',
       'Born Donald Henry Pleasence on October 5, 1919, in Worksop, Nottinghamshire, England, Donald Pleasence was a legendary English actor who became globally iconic for portraying James Bond’s ultimate nemesis, Ernst Stavro Blofeld, in the 1967 film You Only Live Twice. Before establishing his prolific acting career, Pleasence served in the Royal Air Force during World War II, surviving a period as a prisoner of war after his bomber was shot down over France in 1944. After the war, he built an extensive stage and screen career defined by his intense, distinctive voice and remarkable capability for playing eccentric, complex, and menacing characters. He earned early acclaim on Broadway and in classic films such as The Great Escape (1963) before achieving cinematic immortality as the head of SPECTRE in You Only Live Twice. His performance—featuring his scarred face, white Persian cat, and volcano lair—set the definitive visual and performance archetype for master villains for decades to come, directly inspiring parodies like Dr. Evil in Austin Powers. Beyond the Bond franchise, Pleasence was extraordinarily prolific, appearing in over two hundred film and television roles. He achieved another massive pop-culture milestone in 1978 when director John Carpenter cast him as Dr. Sam Loomis in Halloween, a iconic role he reprised across five sequels in the horror franchise. He was knighted into the Order of the British Empire (OBE) in 1994 for his contributions to the arts. Pleasence continued working consistently until his passing on February 2, 1995, at the age of 75.',
       'British',
       '1919-10-05',
       '1995-02-02',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Charles Gray (You Only Live Twice)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9001bc38-41a3-4d30-bcc6-982d129c8996'),
       'Charles Gray',
       'Dikko Henderson',
       'Born Donald Marshall Gray on August 29, 1928, in Bournemouth, Hampshire, England, Charles Gray was a distinguished English actor celebrated for his theatrical presence, suave demeanor, and distinctive, velvety voice. In the 1967 James Bond film You Only Live Twice, he played Dikko Henderson, the Australian British Intelligence contact stationed in Tokyo who provides James Bond with key local contacts before being abruptly assassinated. He would later return to the franchise in a major villainous role, portraying Bond''s arch-nemesis Ernst Stavro Blofeld in the 1971 film Diamonds Are Forever. Gray began his career in classical theater, joining the Regent’s Park Open Air Theatre and later the Old Vic, where he established himself in Shakespearean productions. Transitioning into film and television during the late 1950s, his refined delivery and formidable screen authority quickly made him a sought-after character actor for roles playing aristocrats, suave villains, and eccentric intellectuals. Outside of his major contributions to the James Bond franchise, Gray earned international cult fame as The Criminologist—the dry, pompous narrator who instructs the audience on how to dance the "Time Warp"—in the 1975 classic The Rocky Horror Picture Show. Over a career spanning four decades, he compiled over one hundred screen credits, including notable roles in The Night of the Generals, The Beast Must Die, and recurring appearances as Mycroft Holmes in the acclaimed 1980s television adaptations of Sherlock Holmes. Gray passed away on March 7, 2000, in London at the age of 71.',
       'british',
       '1928-08-29',
       '2000-03-07',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  George Lazenby (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0b26a229-5751-4dd7-8d00-eed2f095899a'),
       'George Lazenby',
       'James Bond',
       'Born George Robert Lazenby on September 5, 1939, in Goulburn, New South Wales, Australia, George Lazenby is an Australian actor and former model who achieved instant cinema fame by becoming the second actor to portray James Bond in the official EON Productions film series, starring in the 1969 film On Her Majesty''s Secret Service. Lazenby served in the Australian Army and worked as a car salesman and ski instructor before moving to London in the 1960s, where he quickly became one of Europe''s top male commercial models. Despite having virtually no professional acting experience, he famously landed the role of 007 after bluffing his way into an audition with producer Albert R. Broccoli and impressing him with his physical swagger and athletic fighting style. At age 29, he became the youngest actor ever cast as James Bond. His performance brought a ground-level vulnerability, athletic intensity, and emotional depth to the character, culminating in the tragic marriage storyline with Diana Rigg''s Tracy Bond. Despite being offered a multi-picture contract, Lazenby famously chose to step away from the franchise after just one film, advised by his agent that the Bond series would become outdated in the counterculture movement of the 1970s. Following his exit, he worked steadily in international cinema, television, and martial arts films—notably training with and almost starring alongside Bruce Lee in Hong Kong—and later appeared in popular television series such as General Hospital and the Emmanuelle television film series. Over time, On Her Majesty''s Secret Service gained widespread critical reassessment as one of the very best films in the entire Bond series, elevating Lazenby''s singular performance to iconic status.',
       'Australian',
       '1939-09-05',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Diana Rigg (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d5ae11bf-85a9-4fe7-9075-99554c126032'),
       'Diana Rigg',
       'Contessa Teresa "Tracy" di Vicenzo',
       'Born Enid Diana Elizabeth Rigg on July 20, 1938, in Doncaster, Yorkshire, England, Dame Diana Rigg was a revered English actress whose commanding presence, sharp intelligence, and effortless elegance made her an icon of stage and screen for over six decades. In the 1969 James Bond film On Her Majesty''s Secret Service, she starred as Contessa Teresa "Tracy" di Vicenzo, who becomes the first and only woman to legally marry James Bond before her tragic assassination in the film''s closing moments. Her performance is widely regarded as one of the finest in the franchise, bringing unprecedented depth, strength, and emotional gravity to the role. Rigg spent her early childhood in India, where her father worked as a railway engineer, before returning to England to attend the Royal Academy of Dramatic Art. She joined the prestigious Royal Shakespeare Company in 1959, establishing her formidable theatrical foundation. She catapulted to international stardom in the mid-1960s as secret agent Emma Peel in the British spy series The Avengers, becoming a global sex symbol and an enduring feminist icon for her character''s martial arts prowess and sharp wit. Throughout her remarkable career, Rigg seamlessly transitioned between classical theater, major motion pictures, and television. She won a Tony Award in 1994 for her title role in Medea on Broadway, an Emmy Award for her role in the 1997 television adaptation of Rebecca, and earned multiple BAFTA honors. In the 2010s, she introduced herself to a new generation of fans with her acclaimed, Emmy-nominated portrayal of the sharp-tongued Olenna Tyrell in HBO''s Game of Thrones. Rigg was made a Dame Commander of the Order of the British Empire in 1994 for her services to drama. She passed away on September 10, 2020, in London at the age of 82.',
       'British',
       '1938-07-20',
       '2020-09-10',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Telly Savalas (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('23f449bc-c565-4970-af51-435a6c391a1b'),
       'Telly Savalas',
       'Ernst Stavro Blofeld',
       'Born Aristotelis Savalas on January 21, 1922, in Garden City, New York, Telly Savalas was an acclaimed American actor and singer renowned for his distinctively smooth voice, magnetic charisma, and iconic bald head. In the 1969 James Bond film On Her Majesty''s Secret Service, he took over the role of Bond''s arch-nemesis, Ernst Stavro Blofeld, delivering a physical, menacing, and aristocratic portrayal that stood out as one of the most formidable interpretations of the famous villain in the franchise. Prior to his acting career, Savalas served in the United States Army during World War II, earning a Purple Heart, and later worked as a executive director of news events at ABC, not taking up professional acting until his late thirties. His raw intensity quickly made him a sought-after character actor, earning an Academy Award nomination for Best Supporting Actor for his role in the 1962 film Birdman of Alcatraz. Throughout the 1960s, he built a strong Hollywood presence with memorable roles in classic films such as The Greatest Story Ever Told, The Dirty Dozen, and Kelly''s Heroes. Savalas achieved ultimate television immortality in 1973 when he landed the lead role of Detective Theo Kojak in the gritty crime drama Kojak. His portrayal of the lollipop-sucking, sharp-dressed New York detective earned him an Emmy Award, a Golden Globe, and global pop-culture fame. Beyond acting, he enjoyed success as a recording artist, topping the UK Singles Chart in 1975 with his spoken-word cover of the song "If." Savalas remained an active performer and a beloved figure in entertainment until his death on January 22, 1994, at the age of 72.',
       'American',
       '1922-01-21',
       '1994-01-22',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Gabriele Ferzetti (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('f6634c8d-95f3-4f5c-bc81-1905bfc3fa2c'),
       'Gabriele Ferzetti',
       'Marc-Ange Draco',
       'Born Pasquale Gabriele Ferzetti on March 17, 1925, in Rome, Italy, Gabriele Ferzetti was a distinguished Italian actor whose refined charm, aristocratic elegance, and intense screen presence made him one of the most prominent figures in European cinema for over half a century. In the 1969 James Bond film On Her Majesty''s Secret Service, he played Marc-Ange Draco, the charismatic head of the powerful Union Corse crime syndicate and the protective father of Tracy di Vicenzo, who forms a crucial alliance with James Bond and ultimately becomes his father-in-law. Ferzetti studied at the prestigious Silvio D''Amico Academy of Dramatic Arts in Rome before embarking on an extensive stage and screen career during the post-war era. He achieved international critical acclaim through his collaborations with legendary director Michelangelo Antonioni, notably starring in L''Avventura in 1960 and Le Amiche in 1955. His remarkable versatility allowed him to move effortlessly between high-art auteur cinema, sweeping historical epics, and popular genre films across Europe, including Sergio Leone''s seminal Western Once Upon a Time in the West in 1968. Throughout his prolific career, Ferzetti amassed over one hundred and fifty film and television credits, remaining a deeply respected character actor well into his eighties with roles in films like Luca Guadagnino''s 2009 drama I Am Love. His contribution to Italian culture earned him widespread acclaim, including a Nastro d''Argento award for Best Supporting Actor. Ferzetti passed away on December 2, 2015, in Rome at the age of 90.',
       'Italian',
       '1925-03-17',
       '2015-12-02',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Ilse Steppat (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('fa1998b9-03f2-450b-8710-6731e0ce1b96'),
       'Ilse Steppat',
       'Irma Bunt',
       'Born Ilse Paula Steppat on November 11, 1917, in Wuppertal, Germany, Ilse Steppat was a highly accomplished German stage and screen actress renowned for her commanding authority, intense dramatic range, and sharp presence. In the 1969 James Bond film On Her Majesty''s Secret Service, she played Irma Bunt, the sinister, iron-fisted henchwoman and right-hand associate to Ernst Stavro Blofeld. Steppat delivered an unforgettable performance as the menacing overseer of Blofeld’s clinic atop Piz Gloria, culminating in her character firing the fatal gunshots that kill James Bond''s new bride, Tracy, in the film''s tragic climax. Steppat began her career on the German theatrical stage during the 1930s, developing a formidable reputation as a classical dramatic actress. Following World War II, she quickly transitioned into feature films, starring as the female lead in early post-war German cinema milestones such as the 1947 drama Ehe im Schatten (Marriage in the Shadows). Over the next two decades, she became a staple of German cinema and television, frequently cast as stern matrons, authoritative matriarchs, and aristocratic women in popular crime thrillers and adaptations of Edgar Wallace novels. Her performance as Irma Bunt in On Her Majesty''s Secret Service marked her international English-language debut and was intended to launch a broader international film career, with producers planning to make her a recurring villain in future Bond installments. Tragically, just three days after the film premiered in London, Steppat suffered a sudden, fatal heart attack on December 21, 1969, in West Berlin at the age of 52.',
       'German',
       '1917-11-30',
       '1969-12-21',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  George Baker (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('36593d65-2413-46d7-a771-4bf11ed8ebfd'),
       'George Baker',
       'Sir Hillary bray',
       'Born George Morris Baker on April 1, 1931, in Varna, Bulgaria, George Baker was a distinguished English actor and writer whose suave demeanor, vocal versatility, and steady authority made him a beloved fixture of British theater, film, and television for over six decades. In the 1969 James Bond film On Her Majesty''s Secret Service, he played Sir Hilary Bray, the aristocratic London genealogist at the College of Arms whom James Bond impersonates to infiltrate Blofeld’s lair atop Piz Gloria. In addition to his on-screen role as Bray, Baker provided the voice dubbing for George Lazenby during the extensive sequences where Bond is in disguise as the heraldic expert. Baker was educated in England before beginning his theatrical career in repertory theater and joining the prestigious Old Vic Company in the 1950s. His classic good looks and commanding presence rapidly earned him leading film roles, notably as the heroic Flight Lieutenant David Maltby in the 1955 war epic The Dam Busters. Beyond his cinematic work, Baker established a remarkably prolific television career, making iconic guest appearances in series such as I, Claudius and Doctor Who. Modern audiences know him best for his definitive portrayal of Chief Inspector Reginald Wexford in the long-running mystery series The Ruth Rendell Mysteries, a role he played for over thirteen years and for which he also wrote several teleplays. Throughout his celebrated lifetime, Baker appeared in dozens of feature films and hundreds of television episodes, remaining an active figure in the artistic community until his later years. He was awarded an MBE (Member of the Order of the British Empire) in the 1989 New Year Honours list for his charitable services to the theatrical profession. Baker passed away from pneumonia following a stroke on October 7, 2011, in West Lavington, Wiltshire, at the age of 80.',
       'british',
       '1931-04-01',
       '2011-10-07',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Bernard Horsfall (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7fd9fbea-e467-4fb2-9999-418b7f9063b9'),
       'Bernard Horsfall',
       'Shaun Campbell (MI6 Operative)',
       'Born Bernard Arthur Gordon Horsfall on November 20, 1930, in Bishop''s Stortford, Hertfordshire, England, Bernard Horsfall was a prolific English actor whose tall, imposing frame and classic stage presence made him a ubiquitous character actor across British theater, film, and television. In the 1969 James Bond film On Her Majesty''s Secret Service, he played Shaun Campbell, the covert MI6 operative stationed in Switzerland who attempts to assist James Bond from afar, only to be captured, tortured, and ultimately killed by Blofeld''s henchmen. Horsfall trained at the Royal Academy of Dramatic Art (RADA) before establishing a firm foundation on the theatrical stage with the Royal Shakespeare Company and the Old Vic. His refined delivery and versatility earned him continuous screen work from the 1950s onward. Outside of the Bond universe, he became particularly beloved by sci-fi audiences for his multiple appearances in Doctor Who, spanning four distinct roles across three decades, including Lemuel Gulliver in The Mind Robber (1968) and the Time Lord Chancellor Goth in The Deadly Assassin (1976). His extensive cinematic and television portfolio also included notable performances in classic period dramas, war films, and adventure series, such as Guns at Batasi (1964), Braveheart (1995), and popular TV shows like The Avengers, Blake''s 7, and Poirot. Horsfall remained active in the performing arts well into his later years, passing away on January 28, 2013, in the Isle of Skye, Scotland, at the age of 82.',
       'British',
       '1930-11-20',
       '2013-01-28',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Yuri Borienko (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('e9419aa9-48cd-4104-bab3-716cc8a9796e'),
       'Yuri Borienko',
       'Grunther',
       'Born Jan Bolesław Kadlubowski on October 27, 1930, in Malawa, Poland, Yuri Borienko was a professional wrestler and character actor whose intimidating physique and rough-hewn features led to a career playing tough guys, henchmen, and formidable enforcers. In the 1969 James Bond film On Her Majesty''s Secret Service, he played Grunther, the brutish head of security and chief henchman at Ernst Stavro Blofeld’s Piz Gloria clinic. Borienko originally established himself as a heavy-hitting professional wrestler in the United Kingdom during the 1960s, adopting his ring moniker by pairing the name of Russian cosmonaut Yuri Gagarin with the surname of an earlier wrestler. His transition into screen acting included guest appearances on popular British television series like Z-Cars, Department S, and The Persuaders!. Famously, during the casting process for On Her Majesty''s Secret Service, Borienko participated in a fight screen test with a then-unknown George Lazenby. Lazenby accidentally punched Borienko for real, breaking his nose; the incident so impressed producer Harry Saltzman that Lazenby landed the role of 007, and Borienko was cast as Grunther. Following his Bond appearance, Borienko continued to work as a character actor in film and television projects, culminating in his final movie role as a Russian general in 1987’s Superman IV: The Quest for Peace. After stepping away from acting, he relocated to Canada, where he spent his later years running a motel business. Borienko passed away on February 10, 1999, in Vancouver, British Columbia, at the age of 68.',
       'Polish',
       '1930-10-27',
       '1999-02-10',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Virginia North (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('fc3d35bd-1bea-4fe4-9738-1fde96813e68'),
       'Virginia North',
       'Olympe',
       'Born Virginia Anne Northrop on April 24, 1946, in London, England, Virginia North was a British-American model and actress who gained international glamour and cult cinema recognition during the late 1960s and early 1970s. The daughter of a U.S. Army officer, she spent much of her youth traveling across Europe and the United States before returning to London in the mid-1960s to launch a successful career as a fashion and swimwear model, eventually joining the prominent agency Models 1. In the 1969 James Bond film On Her Majesty''s Secret Service, she played Olympe, the chic, trusted associate of Unione Corse leader Marc-Ange Draco who plays chess with her boss and attends the wedding of James Bond and Tracy di Vicenzo. Her screen acting debut arrived in 1967 with minor roles in the Bulldog Drummond adventure film Deadlier Than the Male and the historical drama The Long Duel. She followed these with another appearance in the Drummond series, 1969''s Some Girls Do, and a guest role in the television series Department S. Beyond her brief turn in the 007 franchise, North achieved her most iconic screen role as Vulnavia, the stylishly silent, musical assistant to Vincent Price''s vengeful mad scientist in the cult classic horror-comedy The Abominable Dr. Phibes (1971). Following her performance in Dr. Phibes, North retired from screen acting. In 1974, she married British industrialist Gordon White, Baron White of Hull, becoming Lady White until their divorce in 1991. She spent her post-acting years raising her son and living quietly out of the public eye until her passing from cancer on June 5, 2004, in East Sussex, England, at the age of 58.',
       'British',
       '1946-04-24',
       '2004-06-05',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Irvin Allen (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('34869841-c69e-4e19-a1d7-26cbed9862ad'),
       'Irvin Allen',
       'Che-Che',
       'Irvin Allen was a British character actor and performer active throughout the 1960s and 1970s. Often cast in physical roles due to his tough, athletic presence, he worked as a versatile background actor and stunt performer across several classic British film and television productions. In the 1969 James Bond film On Her Majesty''s Secret Service, he played Che-Che, a knife-wielding enforcer for Unione Corse leader Marc-Ange Draco. His role featured a memorable physical hotel-room brawl against George Lazenby’s 007 early in the film, and he later participated in the assault on Blofeld''s Piz Gloria stronghold as part of Draco''s mercenary team. Beyond his work on On Her Majesty''s Secret Service, Allen made multiple uncredited appearances as an actor and stunt crew member across the James Bond franchise, as well as in other prominent film productions. His filmography includes appearances in Stanley Kubrick''s Lolita (1962), The Road to Hong Kong (1962), and the Peter Sellers comedy Revenge of the Pink Panther (1978). On television, he appeared in popular classic series such as Z-Cars, The Saint, and ITV Play of the Week.',
       'American',
       '1916-06-12',
       '1991-11-02',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Terence Mountain (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6b4492f7-9558-4cf3-aaae-167f23f88ea3'),
       'Terence Mountain',
       'Raphael',
       'Terence Mountain is an English actor and former stunt performer known for his commanding physique and memorable appearances in British action cinema and television throughout the late 1960s and 1970s. Before embarking on his screen career, he worked as a lifeguard before joining the Film Artists Association to break into acting. In the 1969 James Bond film On Her Majesty''s Secret Service, he secured the high-profile role of Raphael, the gunman who ambushes James Bond on the beach in Portugal during the movie''s iconic pre-credits fight sequence in the crashing surf. His work on the film led to a close friendship with star George Lazenby, and his talent for physical, action-oriented performances led to steady employment in the genre. Outside of the Bond universe, Mountain worked alongside notable Hollywood stars such as Clint Eastwood and Richard Burton in the classic 1968 war film Where Eagles Dare. On television, he appeared in popular British adventure series of the era, including seven episodes of The Saint opposite future James Bond actor Roger Moore.',
       'British',
       '1936-10-25',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  James Bree (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('473a8a45-66b0-4821-8b40-7723ff3efc2a'),
       'James Bree',
       'Gebrüder Gumbold',
       'Born James Braid on July 20, 1923, in East Dereham, Norfolk, England, James Bree was a versatile character actor known for his sharp, expressive features and refined theatrical technique. After serving in the Royal Air Force during World War II, he trained at the Central School of Speech and Drama and launched a prolific career across British theater, film, and television. In the 1969 James Bond film On Her Majesty''s Secret Service, he played Gebrüder Gumbold, the precise and uncooperative Swiss lawyer whose Bern office James Bond breaks into to safecrack his safe and copy vital documents regarding Blofeld''s claim to the title Count Balthazar de Bleuchamp. Bree enjoyed a distinguished career with the Royal Shakespeare Company and the Royal National Theatre, appearing in numerous classic plays. On screen, he became a familiar face in classic television series, earning a dedicated cult following for his multiple appearances in Doctor Who, where he portrayed three distinct characters: Security Chief in The War Games (1969), Nefred in Full Circle (1980), and Keeper of the Matrix in The Trial of a Time Lord (1986). His extensive film and television credits also included roles in On the Buses, The Jewel in the Crown, Sherlock Holmes, and The Avengers. Bree retired from acting in the late 1990s and passed away on December 1, 2008, in London, England, at the age of 85.',
       'British',
       '1923-07-20',
       '2008-12-01',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Angela Scoular (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('58e6438a-9147-4e49-ba9e-f7b8cb760e4a'),
       'Angela Scoular',
       'Ruby Bartlett',
       'Angela Scoular was an English actress known for her elegance, comedic timing, and prominent roles in 1960s British film and television. Born on November 8, 1945, in London, she trained at the Royal Academy of Dramatic Art before making her screen debut in the mid-1960s. In On Her Majesty''s Secret Service (1969), she played Ruby Bartlett, one of Blofeld''s "Angels of Death" at the Piz Gloria allergy clinic, a quirky English patient who famously writes her room number in butter on James Bond''s thigh. Beyond her work in the official Bond series, Scoular holds a unique place in 007 history for also appearing as Buttercup in the 1967 spoof Casino Royale, making her one of the few actors to cross over between the unofficial and official franchises. She enjoyed a prolific career in British comedy and drama, appearing in classic television shows such as The Avengers, Doctor in the House, and Keeping Up Appearances. She was married to fellow actor Leslie Phillips from 1982 until her death on April 11, 2011, at the age of 65.',
       'British',
       '1945-11-08',
       '2011-04-11',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Catherine Von Schell (On her majesty's secret service)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9df943e8-424a-45d9-bf9a-ad6afe12da65'),
       'Catherine Von Schell',
       'Nancy',
       'Catherine Von Schell, born Baroness Katherina Freiin Von Schell-Bauschlott on July 17, 1944, in Budapest, Hungary, is a retired actress known for her elegance and prominent roles in international film and television. Her family fled Hungary during World War II, eventually settling in Munich and later North London, where she developed her passion for acting and ballet. In the 1969 James Bond film On Her Majesty''s Secret Service, she portrayed Nancy, a charming Hungarian patient among Blofeld''s "Angels of Death" at the Piz Gloria clinic, who becomes one of James Bond''s romantic conquests during his undercover infiltration. Beyond her role in the 007 franchise, Von Schell built a distinguished career across sci-fi, comedy, and drama. She achieved cult icon status for her starring role as Maya, a shape-shifting alien, in the second season of the classic British science-fiction television series Space: 1999. She also gained widespread recognition opposite Peter Sellers in The Return of the Pink Panther (1975), playing Lady Claudine Lytton, as well as starring in the Hammer Horror film Moon Zero Two (1969). After retiring from acting in the mid-1990s, she managed a cozy bed-and-breakfast in France and published her autobiography, A Charmed Life, in 2013.',
       'Hungarian-British',
       '1944-07-17',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jill St. John (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9d6b9396-da9b-4ee0-a93b-c87c6cd38d1f'),
       'Jill St. John',
       'Tiffany Case',
       'Jill St. John, born Jill Arlyn Oppenheim on August 19, 1940, in Los Angeles, California, is an American actress who achieved international fame as one of Hollywood''s leading ladies in the 1960s and 1970s. A child performer who began acting on radio and television at age six, she was signed to a major studio contract by Universal Pictures as a teenager. Known for her striking red hair, quick-witted charm, and high IQ, she quickly established herself in Hollywood comedies and adventure films, including The Lost World (1960), Come Blow Your Horn (1963) alongside Frank Sinatra, and Tony Rome (1967). In 1971, St. John secured a landmark place in cinematic history when she was cast as diamond smuggler Tiffany Case in Diamonds Are Forever. Her portrayal made her the very first American actress to play a major Bond girl in the official EON Productions franchise. Following her iconic turn opposite Sean Connery, she continued to work steadily in television and film throughout the 1970s and 1980s, appearing in series like Fantasy Island, Love Boat, and Magnum, P.I. Later in life, she pursued her passion for culinary arts, becoming a successful cookbook author and culinary personality. St. John has been married to fellow actor Robert Wagner since 1990.',
       'American',
       '1940-08-19',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Charles Gray (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7e6259d6-a505-4e4f-82ab-1972a738238b'),
       'Charles Gray',
       'Ernst Stavro Blofeld',
       'Born Donald Marshall Gray on August 29, 1928, in Bournemouth, Hampshire, England, Charles Gray was a distinguished English actor celebrated for his theatrical presence, suave demeanor, and distinctive, velvety voice. In the 1967 James Bond film You Only Live Twice, he played Dikko Henderson, the Australian British Intelligence contact stationed in Tokyo who provides James Bond with key local contacts before being abruptly assassinated. He would later return to the franchise in a major villainous role, portraying Bond''s arch-nemesis Ernst Stavro Blofeld in the 1971 film Diamonds Are Forever. Gray began his career in classical theater, joining the Regent’s Park Open Air Theatre and later the Old Vic, where he established himself in Shakespearean productions. Transitioning into film and television during the late 1950s, his refined delivery and formidable screen authority quickly made him a sought-after character actor for roles playing aristocrats, suave villains, and eccentric intellectuals. Outside of his major contributions to the James Bond franchise, Gray earned international cult fame as The Criminologist—the dry, pompous narrator who instructs the audience on how to dance the "Time Warp"—in the 1975 classic The Rocky Horror Picture Show. Over a career spanning four decades, he compiled over one hundred screen credits, including notable roles in The Night of the Generals, The Beast Must Die, and recurring appearances as Mycroft Holmes in the acclaimed 1980s television adaptations of Sherlock Holmes. Gray passed away on March 7, 2000, in London at the age of 71.',
       'british',
       '1928-08-29',
       '2000-03-07',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Lana Wood (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('eec759ae-0292-4193-a036-76f0c2daaede'),
       'Lana Wood',
       'Plenty O''Toole',
       'Lana Wood, born Svetlana Gurdin on March 1, 1946, in Santa Monica, California, is an American actress and producer who built a prolific career in film and television starting as a child. The younger sister of film icon Natalie Wood, she began her acting journey at an early age, making her screen debut in John Ford''s classic western The Searchers (1956). She went on to gain widespread recognition on television during the 1960s, most notably as Sandy Webber in the hit soap opera Peyton Place, which established her as a popular and familiar screen presence. In 1971, Wood achieved lasting pop culture fame when she played Plenty O''Toole in the James Bond film Diamonds Are Forever. Her memorable role as a opportunistic Las Vegas casino guest opposite Sean Connery created one of the franchise''s most famous character introductions and cemented her status as a classic Bond girl. Throughout the 1970s and 1980s, she continued to guest star in numerous popular television shows, including The Fugitive, Starsky & Hutch, and Fantasy Island. In addition to her acting work, Wood has written memoirs reflecting on her Hollywood upbringing and family legacy, including her relationship with her famous sister.',
       'American',
       '1946-03-01',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jimmy Dean (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('176de9df-a4ed-48a2-ac52-1541799bc3c9'),
       'Jimmy Dean',
       'Willard Whyte',
       'Jimmy Dean, born Seth Ward on August 10, 1928, in Olton, Texas, was a multifaceted American entertainer, country music star, television host, and businessman. Raised in poverty during the Great Depression, he learned to play piano and accordion as a child before joining the U.S. Air Force in the late 1940s. He launched his music career in the 1950s and achieved massive crossover success in 1961 with his self-penned hit song "Big Bad John," which topped both the country and pop charts and earned him a Grammy Award. His charismatic personality led to a successful broadcasting career, including hosting his own popular variety program, The Jimmy Dean Show, which famously gave Muppets creator Jim Henson his first regular national television exposure. In 1971, Dean brought his natural Southern charm to the big screen when he played reclusive billionaire Willard Whyte in the James Bond film Diamonds Are Forever. His character, a colorful homage to Howard Hughes, provided key comedic and dramatic moments as Bond worked to rescue him from Blofeld''s captivity. Parallel to his entertainment career, Dean founded the Jimmy Dean Sausage Company in 1969 alongside his brother, building it into a household brand and a massive commercial success. After retiring from public life, Dean was inducted into the Country Music Hall of Fame shortly before his death in June 2010 at the age of 81.',
       'American',
       '1928-08-10',
       '2010-06-13',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Bruce Cabot (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1b913291-ae63-45bf-83c3-1160ec4cd724'),
       'Bruce Cabot',
       'Bert Saxby',
       'Bruce Cabot, born Etienne de Pelissier Bujac Jr. on April 20, 1904, in Carlsbad, New Mexico, was a prominent American actor whose Hollywood career spanned more than four decades. After attending the Sewanee Military Academy and working various odd jobs, including as a sailor and oil worker, Cabot relocated to Hollywood in the early 1930s. He secured his ultimate place in cinema history in 1933 when he starred as Jack Driscoll, the hero who rescues Ann Darrow from the giant ape, in the original monster classic King Kong. His rugged good looks and strong presence quickly established him as a reliable leading man and character actor in action, crime, and western films throughout the Golden Age of Hollywood. During World War II, Cabot served as an officer in the U.S. Army Air Forces before returning to a prolific screen career, during which he became a core member of John Wayne''s inner circle, appearing alongside the western icon in over a dozen films such as Angel and the Badman (1947), The Comancheros (1961), and The Green Berets (1968). In 1971, Cabot delivered one of his final film performances as Bert Saxby, the corrupt casino manager aligned with Blofeld, in the James Bond movie Diamonds Are Forever. This marked the end of an extensive filmography before he passed away from lung cancer on May 3, 1972, at the age of 68.',
       'American',
       '1904-04-20',
       '1972-05-03',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Putter Smith (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('5c98b718-374d-4b87-9508-855440eec172'),
       'Putter Smith',
       'Mr. Kidd',
       'Putter Smith, born Patrick Putter Smith on January 19, 1941, in Los Angeles, California, is an American jazz double bassist and actor who achieved cinematic fame through an unusual path. Growing up in a musical family, he began playing the bass at a young age and quickly developed into a respected and versatile musician within the Los Angeles jazz scene. Over the decades, he has performed and recorded alongside jazz luminaries such as Thelonious Monk, Art Blakey, Chet Baker, and Warne Marsh, while also teaching music theory and bass performance at prestigious institutions like the Pasadena Conservatory of Music. Smith made an unexpected leap into film when director Guy Hamilton spotted him performing at a jazz club and offered him a role in the 1971 James Bond movie Diamonds Are Forever. Despite having no prior professional acting experience, Smith delivered an iconic performance as Mr. Kidd, one half of a chillingly polite yet ruthless pair of assassin henchmen alongside Bruce Glover''s Mr. Wint. His deadpan delivery and eerie chemistry with Glover created one of the franchise''s most memorable villain duos. Although he made a few subsequent screen appearances on television shows such as The Wonder Years, Smith dedicated the vast majority of his career to his true passion for jazz music as a performer, recording artist, and educator.',
       'American',
       '1941-01-19',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Bruce Glover (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('154dd0f0-bdc8-422a-b054-1bd702f1ac2b'),
       'Bruce Glover',
       'Mr. Wint',
       'Bruce Herbert Glover, born May 2, 1932, in Chicago, Illinois, is an American character actor whose screen career spans over six decades in film and television. Before committing to acting, Glover served in the United States Army and pursued studies in English literature. He began his professional career on the stage before transitioning to screen roles in the mid-1960s, quickly becoming a recognizable presence in television series such as Hawk, Perry Mason, My Favorite Martian, and Adam-12. His distinct voice, tall frame, and intense delivery often saw him cast in memorable supporting parts, eccentric character roles, and menacing antagonists. Glover achieved widespread international recognition in 1971 when he starred as Mr. Wint in the James Bond feature Diamonds Are Forever. Teaming up with Putter Smith''s Mr. Kidd, Glover played one of the franchise''s most distinct assassin duos, delivering a performance marked by dark humor and chilling politeness. Beyond the Bond franchise, Glover amassed a prolific filmography, including notable roles as Deputy Grady Coker in the cult classic action-drama Walking Tall (1973) and its two sequels, as well as appearances in Roman Polanski''s Chinatown (1974) and Hard Times (1975) alongside Charles Bronson. He is also the father of acclaimed actor and filmmaker Crispin Glover, with whom he has collaborated on independent film projects such as What Is It? (2005). Over the course of his long career, Glover also dedicated significant time to teaching acting technique in the Los Angeles area.',
       'American',
       '1932-05-02',
       '2025-03-12',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Norman Burton (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0fbec4f6-4c38-4fc8-9c83-a47a6372132f'),
       'Norman Burton',
       'Felix Leiter',
       'Norman Burton, born Norman Burton Weinberg on December 5, 1923, in New York City, was a versatile American character actor who enjoyed a prolific four-decade career in film, television, and theater. Burton developed an early passion for performance and studied acting at the renowned Actors Studio in New York under the guidance of Lee Strasberg. His deep training in the Method technique made him a reliable and adaptable presence, allowing him to transition seamlessly between dramatic, comedic, and action-oriented roles across various media starting in the 1950s. Throughout the 1960s and 1970s, Burton became a ubiquitous face on American television, guest-starring in popular series such as The Wild Wild West, Get Smart, Ironside, and later taking on recurring roles such as Joe Atkinson in Wonder Woman. In 1971, Burton stepped into the James Bond universe in Diamonds Are Forever, portraying CIA agent Felix Leiter. His depiction of Leiter as a pragmatic, slightly cynical bureaucrat provided a distinct contrast to other portrayals of the character in the series. Outside of the Bond franchise, Burton appeared in several notable feature films, including Planet of the Apes (1968), where he played the ape leader Hunt Leader, as well as The Towering Inferno (1974) and Bloodsport (1988). Later in life, he continued to act in film and television until retiring in the late 1990s, before passing away following a car accident on November 29, 2003, at the age of 79.',
       'American',
       '1923-12-05',
       '2003-11-29',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Joseph Fürst (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('42e556f9-d0c6-460b-8ca0-be8ec5f5f4a1'),
       'Joseph Fürst',
       'Dr. Metz',
       'Joseph Fürst, born on February 13, 1916, in Vienna, Austria-Hungary, was an international character actor whose career spanned theater, film, and television across multiple continents. Raised in Austria, Fürst studied law before fleeing Europe in the late 1930s due to the rise of Nazism. He resettled in the United Kingdom, where he developed a passion for the dramatic arts and established himself as a talented stage actor. His distinctive accent and commanding screen presence made him a natural fit for roles portraying intellectuals, foreign dignitaries, authority figures, and villains in mid-century British television and cinema. Throughout the 1960s and 1970s, Fürst became a recognizable guest star on popular British television series, including Doctor Who, The Avengers, The Saint, and The Champions. In 1971, he landed his most widely viewed cinematic role as Dr. Metz, the gullible laser expert and idealist exploited by Blofeld, in the James Bond film Diamonds Are Forever. Later in his career, Fürst relocated to Australia, where he continued to act in prominent television productions such as Number 96, Prisoner, and A Town Like Alice. He eventually retired from performing and spent his final years in Sydney, Australia, until his death on April 24, 2005, at the age of 89.',
       'Austrian',
       '1916-02-13',
       '2005-11-29',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Leonard Barr (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1246d9f0-7876-4bd7-83b1-fc67db74af3e'),
       'Leonard Barr',
       'Sahdy Tree',
       'Leonard Barr, born Leonard Barra on September 27, 1903, in West Virginia, was an American stand-up comedian and character actor whose late-in-life film success stemmed from a long career in vaudeville and nightspots. Barr, who was the real-life uncle of legendary entertainer Dean Martin, spent decades performing as a song-and-dance man and comic, honing his dry delivery and sharp comedic timing across the American club circuit. Despite his deep roots in live entertainment, he did not transition into mainstream film and television until he was well into his sixties, bringing a seasoned, cynical charm to his screen roles. Barr achieved wider public recognition in 1971 when he appeared as the weary, gambling-resort comedian Shady Tree in the James Bond film Diamonds Are Forever. His brief but memorable performance as a smuggling middleman who meets an untimely end at the hands of Mr. Wint and Mr. Kidd showcased his natural comedic background. Following his Bond role, Barr became a popular character actor throughout the 1970s, making guest appearances on hit television series such as The Odd Couple, All in the Family, and Laverne & Shirley, while also featuring in films like The Sting (1973). He continued working periodically until his death on November 22, 1980, at the age of 77.',
       'American',
       '1903-09-27',
       '1980-11-22',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Margaret Lacey (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0fcea797-fdf2-49bd-bf3d-8ae7a71b68fd'),
       'Margaret Lacey',
       'Mrs. Whistler',
       'Margaret Lacey, born Margaret Edith Mary Lacey on November 10, 1911, in Denbighshire, Wales, was a Welsh actress and ballet dancer whose acting career flourished later in her life. Before taking on film and television roles, Lacey dedicated much of her early career to dance, performing in stage productions and working as a respected ballet mistress and teacher. Her deep background in movement and stagecraft gave her a distinct poise and presence that she seamlessly brought to screen acting when she transitioned to film and television roles during the 1960s. Lacey became best known to international audiences for her memorable character work in high-profile British and American films. In 1971, she played the gentle, unsuspecting schoolteacher and diamond smuggler Mrs. Whistler in the James Bond film Diamonds Are Forever, meeting an early demise in Amsterdam at the hands of assassins Mr. Wint and Mr. Kidd. She also made a notable appearance as the eccentric teacher Miss Stevenson in The Prime of Miss Jean Brodie (1969) alongside Maggie Smith, and appeared in films such as Raging Moon (1971) and Dr. Jekyll and Sister Hyde (1971), alongside guest roles on popular television shows like Z-Cars. Lacey retired from acting in the late 1970s and spent her remaining years in Wales until her death on September 1, 1988, at the age of 76.',
       'Welsh',
       '1911-10-26',
       '1988-10-04',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Joe Robinson (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('efacade7-999e-417c-b3d2-3cf43bbb8da7'),
       'Joe Robinson',
       'Peter Franks',
       'Joe Robinson, born Joseph Robinson on May 31, 1927, in Newcastle upon Tyne, England, was a British actor, stuntman, and martial artist celebrated for his impressive physical build and athleticism. Raised in a family of champion wrestlers, Robinson naturally gravitated toward combat sports and physical culture, winning the European Junior Heavyweight Wrestling Championship in 1952. His exceptional physique and natural charisma soon opened doors in the entertainment industry, leading him to study at the Royal Academy of Dramatic Art (RADA) while simultaneously working as a professional wrestler and stunt arranger. Throughout the 1950s and 1960s, Robinson built a successful international acting career, frequently cast in muscular, action-heavy roles. He starred in several Italian "peplum" or sword-and-sandals epics, including Taur the Mighty (1963) and Ursus in the Land of Fire (1963), while also working as a stunt coordinator and personal fitness trainer for top film stars like Honor Blackman and Diana Rigg. In 1971, Robinson secured his most famous cinematic appearance as the diamond smuggler Peter Franks in Diamonds Are Forever. His brutal, close-quarters elevator fight sequence with Sean Connery remains one of the most iconic hand-to-hand combat scenes in the entire James Bond series. Following his screen career, Robinson established a successful martial arts academy in Brighton, where he taught judo and karate for decades until his death on July 3, 2017, at the age of 90.',
       'British',
       '1927-05-31',
       '2017-07-03',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Laurence Naismith (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('35f0eeee-eeff-40a5-9242-1ef94dda87fe'),
       'Laurence Naismith',
       'Sir Donald Munger',
       'Laurence Naismith, born Lawrence Johnson on December 14, 1908, in Thames Ditton, Surrey, England, was a highly distinguished British actor whose prolific career spanned over four decades across stage, film, and television. After starting out as a chorus dancer and repertory theater actor in the late 1920s, Naismith served in the Royal Artillery during World War II before returning to acting full-time. Blessed with a commandingly warm voice, expressive features, and natural gravitas, he effortlessly moved between Shakespearean stage productions, Hollywood blockbusters, and beloved British cinema classics. Naismith became a staple of international cinema, specializing in authoritative, kindly, or delightfully eccentric figures. He delivered memorable performances in major films such as Mogambo (1953), A Night to Remember (1958), Jason and the Argonauts (1963), Camelot (1967), and Scrooge (1970). In 1971, he brought his signature authority to Diamonds Are Forever as Sir Donald Munger, the refined British diamond merchant who recruits James Bond and M to investigate the large-scale smuggling of South African diamonds. Beyond film, Naismith was a familiar face on television, notably starring as Judge Fulton alongside Roger Moore and Tony Curtis in The Persuaders!. He retired to Australia in the late 1970s and lived in Southport, Queensland, until his death on June 5, 1992, at the age of 83.',
       'British',
       '1908-12-14',
       '1992-06-05',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Marc Lawrence (Diamonds Are Forever)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2734a744-c52e-4d99-bcfa-77101f51b093'),
       'Marc Lawrence',
       'Slumber Inc. Attendant',
       'Marc Lawrence, born Max Goldsmith on February 17, 1910, in New York City, was a legendary American character actor whose remarkably long screen career spanned over seven decades. Recognized instantly by his distinctive, rugged pockmarked visage and intense brooding glare, Lawrence became one of Hollywood’s most iconic and enduring cinema mobsters, heavies, and underworld figures, accumulating well over two hundred film and television credits throughout his lifetime. After studying drama at the City College of New York and performing with Eva Le Gallienne''s Civic Repertory Theatre, Lawrence entered feature films in the early 1930s. He quickly carved out a niche playing tough guys in classic film noir and crime dramas, earning prominent roles in masterpieces such as John Huston''s Key Largo (1948) and The Asphalt Jungle (1950). Blacklisted during the McCarthy era after testifying before the House Un-American Activities Committee, he spent several years living and working in Europe, starring in numerous Italian productions before making a triumphant return to American cinema and television in the 1960s. Lawrence earned a special place in 007 lore by appearing as two distinct underworld figures in back-to-back James Bond films. In Diamonds Are Forever (1971), he played a shady Slumber Incorporated attendant who receives a envelope of money from James Bond at a Las Vegas mortuary. He returned to the franchise three years later in The Man with the Golden Gun (1974) as Rodney, a hitman hired to challenge Francisco Scaramanga in his deadly island funhouse during the film''s opening pre-credits sequence, where Scaramanga ultimately guns him down. Beyond his Bond appearances, Lawrence remained active into his nineties, featuring in high-profile modern films like Marathon Man (1976), Newsies (1992), and Looney Tunes: Back in Action (2003), while also writing and directing independent films such as Nightmare Circus (1974). He passed away from heart failure on November 27, 2005, at the age of 95 in Palm Springs, California.',
       'American',
       '1910-02-17',
       '2005-11-28',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Roger Moore (live and let die, The man with the golden gun, The spy who loved me, moonraker, for your eyes only, octopussy, A view to a kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0a589426-6f07-46dc-9b13-0bf7657e8a2b'),
       'Roger Moore',
       'James Bond',
       'Sir Roger Moore, born Roger George Moore on October 14, 1927, in Stockwell, London, was an acclaimed English actor best known for bringing a suave, lighthearted charm and refined wit to the role of James Bond. The son of a policeman, Moore worked briefly as an animation apprentice and extra before studying at the Royal Academy of Dramatic Art. After serving in the British Army''s Royal Army Service Corps following World War II, he pursued acting in theater, television, and film, steadily gaining traction as a Hollywood contract actor during the 1950s. Moore achieved widespread international television stardom during the 1960s as the dashing thief Simon Templar in the hit British series The Saint, followed by his starring role as Lord Brett Sinclair alongside Tony Curtis in The Persuaders!. In 1973, he made his debut as 007 in Live and Let Die, stepping into the shoes of Sean Connery and redefining the iconic secret agent with his trademark raised eyebrow, dry humor, and effortless sophistication. He went on to portray James Bond in seven consecutive films across twelve years—the longest tenure of any actor in the official EON Productions franchise—before handing off the role after A View to a Kill (1985). Off-screen, Moore''s personal life was colorful and tempestuous, marked by four marriages. In 1946, at age eighteen, he married his first wife, fellow RADA student and ice skater Doorn van Steyn, though the volatile union ended in divorce in 1953. That same year, he wed famed Welsh singer Dorothy Squires, who was twelve years his senior and helped elevate his profile in North America; their dramatic relationship ended when he left her for Italian actress Luisa Mattioli, whom he eventually married in 1969. Moore and Mattioli had three children together—Deborah, Geoffrey, and Christian—before separating in the 1990s. In 2002, Moore married Danish-Swedish socialite Kristina "Kiki" Tholstrup, describing her as his lifeline and enjoying a quiet, devoted partnership with her for the rest of his life. In his later years, Moore dedicated much of his life to humanitarian work, serving as a UNICEF Goodwill Ambassador from 1991 until his death. His philanthropic efforts earned him a knighthood from Queen Elizabeth II in 2003. Sir Roger Moore passed away on May 23, 2017, in Switzerland at the age of 89, leaving behind an enduring legacy as one of cinema''s most beloved screen legends.',
       'British',
       '1927-10-14',
       '2017-05-23',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Yaphet Kotto (live and let die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d3b8fc33-c1fa-45da-98e8-f3e163f58030'),
       'Yaphet Kotto',
       'Dr. Kananga',
       'Yaphet Kotto, born Yaphet Frederick Kotto on November 15, 1939, in New York City, was a formidable American actor known for his commanding screen presence, deep voice, and intense performances. Raised in Harlem, Kotto discovered a passion for performing at an early age and began studying acting at sixteen at the Actors Mobile Theater Studio. He launched his professional career on the stage, making his theatrical debut at nineteen in a production of Othello before joining the prestigious Actors Studio and appearing on Broadway in hit plays such as The Great White Hope. Kotto made a seamless transition to film in the 1960s, quickly establishing himself as a versatile character actor capable of embodying both terrifying antagonists and heroic figures. In 1973, he achieved global fame starring opposite Roger Moore in Live and Let Die, playing the dual roles of Caribbean dictator Dr. Kananga and his crime-boss alter-ego Mr. Big—making history as the first Black actor to play a main James Bond villain. Following his Bond performance, Kotto delivered standout roles in cinematic classics, including space technician Dennis Parker in Ridley Scott''s Alien (1979), a rebellious factory worker in Blue Collar (1978), a resistance fighter in The Running Man (1987), and an exasperated FBI agent in the action-comedy Midnight Run (1988). In the 1990s, Kotto found a new generation of fans on television, starring for seven seasons as the authoritative yet deeply compassionate Lieutenant Al Giardello on the acclaimed police drama Homicide: Life on the Street. Renowned throughout his five-decade career for his refusal to take stereotypical roles, Kotto brought undeniable dignity and gravitas to every project he touched. He passed away on March 15, 2021, in Manila, Philippines, at the age of 81, leaving behind a lasting legacy as a powerhouse talent of American cinema and television.',
       'American',
       '1939-11-15',
       '2021-03-15',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jane Seymour (live and let die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2eaae906-60a0-4a5d-86cb-31597bc42c91'),
       'Jane Seymour',
       'Solitaire',
       'Jane Seymour, born Joyce Penelope Wilhelmina Frankenberg on February 15, 1951, in Uxbridge, Middlesex, England, is an acclaimed English-American actress renowned for her timeless elegance, classical beauty, and versatile performances across film, television, and theater. Raised by an English doctor father and a Dutch nurse mother, Seymour initially trained as a ballet dancer at the Arts Educational School in Tring, Hertfordshire. However, after a knee injury derailed her dance career, she redirected her passion toward acting, adopting her famous stage name after the sixteenth-century queen of England. After early television roles and a brief appearance in Richard Attenborough''s Oh! What a Lovely War, Seymour landed her major international breakthrough in 1973 at the age of twenty-two when she starred as the enigmatic tarot-reading bond girl Solitaire opposite Roger Moore in Live and Let Die. Her striking performance as the innocent yet captivating fortune teller elevated her profile in Hollywood, leading to a long and distinguished career in both British and American entertainment. She went on to earn critical acclaim for her roles in period dramas and miniseries, winning a Golden Globe Award for her performance in East of Eden (1981) and an Emmy Award for portraying Marie Antoinette in Onassis: The Richest Man in the World (1988). In the 1990s, Seymour achieved widespread worldwide popularity on television starring as Dr. Michaela "Mike" Quinn in the beloved western drama series Dr. Quinn, Medicine Woman, a role that earned her a second Golden Globe Award and cemented her status as a household name. Throughout her expansive career, she has demonstrated remarkable range, seamlessly transitioning between romantic leads, theatrical period pieces, and comedy, including a memorable turn in the hit film Wedding Crashers (2005). Beyond acting, Seymour is an accomplished author, painter, jewelry designer, and dedicated philanthropist who actively supports numerous charitable causes, maintaining an active and celebrated presence in the arts for over five decades.',
       'British-American',
       '1951-02-15',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Clifton James (live and let die, The man with the golden gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6eac7a5f-212c-47b1-9560-59981cc48713'),
       'Clifton James',
       'Sheriff J.W. Pepper',
       'Clifton James, born George Clifton James on May 29, 1920, in Spokane, Washington, was a distinguished American character actor celebrated for his robust screen presence and remarkable talent for portraying colorful, booming lawmen. Raised during the Great Depression, James served with honor in the United States Army during World War II as a soldier in the 163rd Infantry Regiment, spending nearly five years in the South Pacific and earning two Purple Hearts, a Silver Star, and a Bronze Star for his bravery. Upon returning home, he utilized the G.I. Bill to study theater at the University of Oregon, eventually moving to New York City to launch a long and successful acting career in stage, television, and film. James honed his craft in the theater, appearing on Broadway in productions such as The Cave Dwellers and J.B., before transitioning into film and television roles during the 1960s and 1970s. He gained widespread international recognition in 1973 when he was cast as the loudmouthed, tobacco-chewing Louisiana Sheriff J.W. Pepper in Live and Let Die opposite Roger Moore. His humorous portrayal of the blustery southern lawman became an instant fan favorite, prompting the filmmakers to write him directly into the next James Bond adventure, The Man with the Golden Gun (1974), as a vacationing tourist caught in another high-speed chase. Beyond his memorable Bond appearances, James was a highly respected character actor who brought authenticity to dozens of memorable films, including Cool Hand Luke (1967), The Last Detail (1973), Silver Streak (1976), Superman II (1980), and Eight Men Out (1988). He also made frequent guest appearances on popular television shows such as The Dukes of Hazzard, Dallas, and Lewis & Clark. Beloved by colleagues and audiences alike for his warm demeanor off-screen and his unmistakable comedic timing on camera, James enjoyed a marriage of nearly sixty-six years to his wife, Laurie Harper, with whom he had five children. Clifton James passed away on April 15, 2017, at the age of 96 in Gladstone, Oregon, leaving behind a rich legacy as one of cinema''s most endearing character performers.',
       'American',
       '1920-05-29',
       '2017-04-15',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Julius Harris (live and let die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6fc8dbb5-4d3b-434c-aae1-2d3a26447c39'),
       'Julius Harris',
       'Tee Hee',
       'Julius W. Harris, born on August 17, 1923, in Philadelphia, Pennsylvania, was a talented American character actor known for his imposing physical presence, deep voice, and remarkable versatility on stage, film, and television. Before pursuing a career in performance, Harris worked as a nurse and spent over a decade as a bartender in Greenwich Village, New York, where his interactions with local artists and theatrical figures eventually inspired him to try acting in his late thirties. He made his motion picture debut in the groundbreaking independent drama Nothing But a Man (1964), earning praise for his nuanced performance as the alcoholic father of the lead character. Throughout the 1970s, Harris became a prominent and recognizable figure during the Blaxploitation film era, starring in seminal pictures such as Super Fly (1972), Black Caesar (1973), and Hell Up in Harlem (1973). In 1973, he achieved enduring global fame when he played Tee Hee Johnson, the menacing, steel-clawed henchman working for Dr. Kananga in Live and Let Die. Facing off against Roger Moore''s James Bond, Harris created one of the franchise''s most iconic and memorable physical antagonists, balancing intimidating menace with a cold, chuckling charm. Following his Bond role, Harris maintained a prolific and steady acting career for over three decades across both movies and television. His notable film credits included the disaster thriller King Kong (1976), the cult classic Looking for Mr. Goodbar (1977), and the comedy Darkman (1990). On television, he made memorable guest appearances on scores of popular series, including Sanford and Son, The Incredible Hulk, Cagney & Lacey, Golden Girls, and Murder, She Wrote. Off-screen, Harris was also a founding member of the Negro Ensemble Company, actively supporting Black theatrical talent and representation in the arts. Julius Harris passed away on October 17, 2004, at the age of 81 in Woodland Hills, California, leaving behind a rich legacy of captivating character work.',
       'American',
       '1923-08-18',
       '2004-10-17',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Geoffrey Holder (live and let die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('273e8c30-ef96-4ad7-89d2-b3289dc17717'),
       'Geoffrey Holder',
       'Baron Samedi',
       'Geoffrey Lamont Holder, born on August 1, 1930, in Port of Spain, Trinidad and Tobago, was a towering multi-talented artist who captivated international audiences as a dancer, choreographer, actor, singer, director, painter, and costume designer. Blessed with an extraordinary six-foot-six frame, a booming bass voice, and incredible physical grace, Holder was introduced to the arts at an early age through his older brother Boscoe, joining his dance troupe before moving to New York City in 1954. He quickly established himself as a force on Broadway and became a principal dancer with the Metropolitan Opera Ballet, winning widespread acclaim for his vibrant charisma and command of movement. In 1973, Holder gained global cinematic fame for his iconic performance as Baron Samedi, the cackling, top-hatted, voodoo-practicing henchman in Live and Let Die opposite Roger Moore. Beyond creating one of the most memorable and visually striking villains in the James Bond series, Holder also choreographed the film''s elaborate West Indian dance sequences. Outside of Bond, his film credits included Doctor Dolittle (1967), Annie (1982), and Boomerang (1992), alongside serving as the booming, unmistakable narrator for Tim Burton''s Charlie and the Chocolate Factory (2005) and becoming a household figure through his popular "Uncola" television commercials for 7 Up. Holder achieved historic success on Broadway in 1975 when he directed and designed costumes for the groundbreaking musical The Wiz, winning Tony Awards for both Best Direction of a Musical and Best Costume Design—becoming the first Black man to win in either category. Throughout his lifelong marriage to fellow renowned dancer Carmen de Lavallade, with whom he had one son, Holder remained a passionate polymath, celebrated as a pioneer for Black artists in theater, dance, and fine arts. Geoffrey Holder passed away from complications of pneumonia on October 5, 2014, in Manhattan at the age of 84.',
       'Trinidadian-American',
       '1930-08-01',
       '2014-10-05',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Gloria Hendry (live and let die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('a1297808-786b-4a0a-b40f-841c4b24b875'),
       'Gloria Hendry',
       'Rosie Carver',
       'Gloria Hendry, born on March 3, 1949, in Winter Haven, Florida, is an American actress, singer, and model who carved out a distinctive path in 1970s cinema. Raised in Newark, New Jersey, Hendry initially worked as a secretary for the NAACP and later became a receptionist and bunny at the famous Playboy Club in New York City. Her striking beauty and natural presence soon opened doors into modeling and acting, leading to her big-screen debut in Hal Ashby''s acclaimed comedy-drama The Landlord (1970). Hendry made cinematic history in 1973 when she was cast as double-agent Rosie Carver in Live and Let Die. Playing opposite Roger Moore in his debut film as 007, she became the first African American woman to portray a romantic interest for James Bond in the official EON Productions franchise. Her performance as the nervous CIA operative secretly working for Dr. Kananga added crucial tension to the story and cemented her status as a pop-culture trailblazer. That same year, Hendry emerged as a leading star of the Blaxploitation genre, demonstrating remarkable versatility and physical dynamicism. She delivered standout performances alongside Fred Williamson in Black Caesar (1973) and its sequel Hell Up in Harlem (1973), and she famously showcased her martial arts talents in the action hit Black Belt Jones (1974) opposite Jim Kelly. Beyond her prominent 1970s film roles, Hendry appeared on television series such as Hunter and Dragnet, while also pursuing a successful secondary career as a jazz vocalist and working as a legal assistant. In 2021, she published her autobiography, detailing her pioneering artistic journey and enduring impact on cinema.',
       'American',
       '1949-03-03',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Tommy Lane (live and let die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('5e0e2389-085c-4a12-8b90-15c58068c530'),
       'Tommy Lane',
       'Adam',
       'Tommy Lane, born on December 17, 1937, in Liberty City, Miami, Florida, was a rugged American actor and stunt performer whose imposing presence made him a memorable fixture in 1970s action cinema. He began his acting career in the mid-1960s with appearances on the television series Flipper before transitioning to feature films, where he often showcased his physical capabilities by performing stunt work alongside his acting roles. Lane first gained widespread recognition in the iconic 1971 film Shaft, playing the hitman Leroy, who memorably battles the title character before being thrown through a window. In 1973, he joined the James Bond franchise in Live and Let Die, portraying the ruthless henchman Adam. As an enforcer reporting to Dr. Kananga''s criminal alias Mr. Big, Lane created an intimidating physical antagonist opposite Roger Moore. Beyond the Bond franchise, Lane appeared in notable films such as Cotton Comes to Harlem (1970), Shamus (1973), and the classic Ganja & Hess (1973). Outside of his acting and stunt career, he was a talented jazz musician in the 1980s who played the trumpet and flugelhorn, performing at renowned venues like New York City''s Blue Note. Lane was married to Raquel Bastias-Lane, with whom he shared a large blended family consisting of seven children and a stepson. He passed away on November 29, 2021, at a medical center in Fort Lauderdale, Florida, at the age of 83, following a long battle with chronic obstructive pulmonary disease (COPD).',
       'American',
       '1937-12-17',
       '2021-11-29',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Roy Stewart (live and let die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('ec66f160-4a11-486a-86da-8910d11cf4a1'),
       'Roy Stewart',
       'Quarrel Jr.',
       'Atwell Roy Stewart, born on May 15, 1925, in Jamaica, was a pioneering British-Jamaican actor, stuntman, and businessman who became one of the most prolific Black performers in postwar British cinema and television. Immigrating to Britain in the late 1940s with initial ambitions to study medicine, he was soon drawn to the performing arts, starting out in theater before transitioning into film work as a stuntman. Driven in part by the widespread practice of white stuntmen wearing blackface, Stewart offered genuine representation and quickly established himself as a physically imposing and dependable presence on screen. In 1973, Stewart gained international fame in the James Bond franchise when he played Quarrel Junior in Live and Let Die. Serving as the loyal ally and son of Quarrel from Dr. No, his character provided vital local assistance to Roger Moore''s 007 in the Caribbean. The filming brought Stewart back to his native Jamaica for the first time in decades. Throughout his acting career, Stewart amassed a vast array of screen credits across genres. He appeared in notable films such as Hammer Horror''s The Mummy (1959) and Twins of Evil (1971), Jean-Luc Godard''s Sympathy for the Devil (1968), and the comedy classic Carry On Up the Jungle (1970). On British television, he secured roles in high-profile series including Doctor Who, The Avengers, Space: 1999, and I, Claudius. Beyond performance, Stewart was a major entrepreneur and cultural figure in London. In 1954, he opened Roy Stewart''s Gym in West London, an inclusive training space frequented by prominent figures, including bodybuilders and fellow actors like Sean Connery, Dave Prowse, and Arnold Schwarzenegger. He also established The Globe, a popular Caribbean restaurant and nightclub that became a landmark venue host to legendary musicians. Stewart retired from acting in the early 1980s and continued running his business until his passing on October 27, 2008, at the age of 83.',
       'Jamaican',
       '1925-05-15',
       '2008-10-12',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Earl Jolly Brown (live and let die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('bef9533b-5535-4319-88d0-236af62049fc'),
       'Earl Jolly Brown',
       'Whisper',
       'Earl Jolly Brown, born on October 18, 1939, in Houston, Texas, was a character actor whose distinctive, imposing physical stature and expressive comedic timing made him a recognizable presence in American film and television throughout the 1970s and 1980s. Standing well over six feet tall and weighing over three hundred pounds, Brown used his imposing screen presence to craft memorable, larger-than-life supporting characters. In 1973, Brown achieved international cinema fame when he was cast in Live and Let Die, Roger Moore''s debut outing as James Bond. He portrayed Whisper, the quiet, soft-spoken henchman working for the villainous Dr. Kananga. The humorous contrast between Brown''s massive frame and his character''s barely audible, hushed voice provided iconic comic relief, culminating in the memorable climax where Bond traps him inside a metal champagne bucket. Throughout his career, Brown appeared in a variety of classic film and television productions. He notably played Harry in the classic sports comedy The Bad News Bears (1976) and made memorable guest appearances on hit television series such as Laverne & Shirley, The Jeffersons, Happy Days, and Get Christie Love!. He retired from professional acting in the mid-1980s and spent his later years in Nevada until his passing on August 24, 2006, in Las Vegas at the age of 66.',
       'American',
       '1939-10-18',
       '2006-08-26',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Lon Satton (live and let die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3f2e7332-e06a-4fb4-901f-86756c7efac0'),
       'Lon Satton',
       'CIA Agent Strutter',
       'Lon Satton, born Lonnie Satton on February 11, 1927, in Jacksonville, Florida, was an accomplished American actor and singer who built an expansive international career across theater, film, and television. Initially pursuing music as a baritone vocalist, Satton gained early prominence on Broadway, featuring in notable theatrical productions such as The Heathen and Kismet during the late 1950s and 1960s. His smooth vocal talents and charismatic stage presence eventually led him to relocate to the United Kingdom, where he became a well-regarded figure in British West End theater and television. In 1973, Satton achieved wide cinematic recognition when he joined the cast of Live and Let Die, Roger Moore''s first film as James Bond. He portrayed Strutter, a sharp-dressed CIA operative stationed in New Orleans alongside David Hedison''s Felix Leiter. As an ally assisting 007 in tracking down Dr. Kananga''s criminal syndicate, Satton brought an effortless coolness to the role, memorable for his understated interactions with Bond while shadowing suspect movements in the French Quarter. Beyond his contribution to the Bond franchise, Satton maintained a remarkably diverse career. In the realm of feature films, he appeared in productions such as Major Dundee (1965) and Hell Boats (1970). He also achieved major success in musical theater, notably originating the role of Poppa in the original West End production of Andrew Lloyd Webber''s hit musical Starlight Express in 1984. Satton made numerous television appearances on both sides of the Atlantic, including roles in popular British series such as The Professionals and Doctor Who. He continued to perform and record music later in life before passing away on November 8, 2020, at the age of 93.',
       'American',
       '1927-02-11',
       '2020-10-30',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  David Hedison (live and let die, License To Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9e8cf91f-2879-46c1-898b-2ce955c2de52'),
       'David Hedison',
       'Felix Leiter',
       'Albert David Hedison Jr., born on May 20, 1927, in Providence, Rhode Island, was a handsome and charming American actor who enjoyed a prolific career spanning six decades across theater, film, and television. After deciding to pursue acting following his service in the United States Navy, Hedison studied at the Neighborhood Playhouse and trained under Sanford Meisner alongside studying at the Actors Studio. He earned early acclaim on the New York stage, winning a Theatre World Award in 1954 for his performance in A Month in the Country, which quickly led to a contract with 20th Century Fox. Hedison achieved major cinematic recognition starring as scientist André Delambre in the iconic sci-fi classic The Fly (1958) and as Lord Richard Roxton in Irwin Allen''s adaptation of The Lost World (1960). His association with Allen led to his most famous television role as Captain Lee Crane in the hit science-fiction series Voyage to the Bottom of the Sea, which ran for four seasons from 1964 to 1968. In 1973, Hedison stepped into the James Bond universe as CIA ally Felix Leiter in Live and Let Die, sharing strong on-screen chemistry with his longtime friend Roger Moore. He later made franchise history by returning to the role sixteen years later in Licence to Kill (1989) opposite Timothy Dalton, becoming the first actor to play Felix Leiter in more than one official EON Productions film. Throughout his extended career, Hedison remained a steady and popular presence on television, guest starring on dozens of beloved shows including The Love Boat, Fantasy Island, Charlie''s Angels, Knight Rider, Murder, She Wrote, and the daytime soap opera The Young and the Restless. On a personal level, he was married to production assistant Bridget Mori for nearly fifty years, from 1968 until her death in 2016, and together they had two daughters, including actress Alexandra Hedison. David Hedison passed away peacefully on July 18, 2019, in Los Angeles at the age of 92, remembered fondly by fans for his suave presence, warmth, and enduring contributions to classic television and cinema.',
       'American',
       '1927-05-20',
       '2019-07-18',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Christopher Lee (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('4c072fe9-069d-4571-822e-e303af526e1e'),
       'Christopher Lee',
       'Fransisco Scaramanga',
       'Sir Christopher Lee, born Christopher Frank Carandini Lee on May 27, 1922, in London, England, was an iconic English actor, singer, and author whose remarkable career spanned nearly seven decades. With his commanding height, deep operatic voice, and aristocratic bearing, Lee became one of the most prolific and distinctive performers in cinema history. During World War II, he served in the Royal Air Force and intelligence services, later embarking on an acting career in 1947 that would encompass over two hundred film appearances. In 1974, Lee achieved a personal and franchise milestone when he starred as Francisco Scaramanga in The Man with the Golden Gun. Interestingly, Lee was a step-cousin of James Bond creator Ian Fleming, who had originally envisioned Lee for the title role in Dr. No. When he finally joined the series opposite Roger Moore, Lee crafted one of 007''s most acclaimed adversaries. His portrayal of Scaramanga, a suave, million-dollar-a-shot assassin who viewed Bond as a dark mirror image of himself, brought exceptional gravitas and sophisticated menace to the film. Before his Bond debut, Lee gained worldwide stardom through his legendary collaboration with Hammer Film Productions, defining horror cinema with his haunting performances as Count Dracula, Frankenstein''s monster, and the Mummy. His versatility extended into modern pop-culture juggernauts in his later career, introducing him to new generations of fans as the wizard Saruman in Peter Jackson''s The Lord of the Rings and The Hobbit trilogies, and as the Sith Lord Count Dooku in the Star Wars prequel films. Knighted for services to drama and charity in 2009, Lee was also an accomplished operatic singer who released several heavy metal albums in his eighties. He passed away on June 7, 2015, in London at the age of 93, leaving behind an incomparable cinematic legacy.',
       'British',
       '1922-05-27',
       '2015-06-07',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Britt Ekland (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('23c42e0a-f78a-4fac-8e3a-8b2c0eac4ac2'),
       'Britt Ekland',
       'Mary Goodnight',
       'Britt Ekland, born Britt-Marie Eklund on October 6, 1942, in Stockholm, Sweden, is an international actress and glamour icon who became one of the most recognizable screen figures of the 1960s and 1970s. Raised in Stockholm, she began taking drama lessons in her youth and was discovered by a talent scout while studying at a theater school, leading to early film roles in Sweden and Italy. Her profile rose dramatically following her high-profile 1964 marriage to English actor Peter Sellers, with whom she co-starred in films like After the Fox (1966) and The Bobo (1967), establishing her presence in international cinema. In 1974, Ekland took on one of her most famous roles as Mary Goodnight in The Man with the Golden Gun. Originally auditioning for the role of Scaramanga''s mistress, mistress administrative assistant Mary Goodnight was rewritten specifically with Ekland in mind after director Guy Hamilton saw her. Portraying James Bond''s well-meaning but accident-prone MI6 assistant stationed in Far East operations, Ekland brought vibrant comedy and charm opposite Roger Moore, navigating close encounters with Francisco Scaramanga and accidentally triggering the destruction of his island lair. Outside of the 007 franchise, Ekland amassed a wide array of notable film and television credits. She starred alongside Michael Caine in the iconic British crime drama Get Carter (1971) and delivered a memorable performance in the classic folk horror film The Wicker Man (1973). Over subsequent decades, she appeared frequently on British stage productions, reality television programs, and talk shows, while also publishing an autobiography and beauty guides. Known for her multilingual talents and enduring cultural impact, Ekland remains a celebrated figure in international pop culture.',
       'Swedish',
       '1942-10-06',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Hervé Villechaize (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('838d5cd3-6c2d-423b-b10b-04a5cad3d05d'),
       'Hervé Villechaize',
       'Nick Nack',
       'Hervé Jean-Pierre Villechaize, born on April 23, 1943, in Paris, France, was an actor, artist, and pop culture figure who achieved worldwide fame through his distinctive screen presence and expressive performances. Born with dwarfism resulting from an endocrine condition, Villechaize initially channeled his talents into the visual arts, studying at the École des Beaux-Arts in Paris and becoming a accomplished painter and sculptor. In his early twenties, he relocated to New York City to further his artistic career, where he began pursuing acting through Off-Broadway theater productions and small film parts. In 1974, Villechaize captured international attention when he was cast as Nick Nack in The Man with the Golden Gun. Serving as the loyal yet scheming manservant, cook, and assassin''s accomplice to Christopher Lee''s Francisco Scaramanga, Villechaize brought an energetic blend of dark humor, charm, and malice to the role. His memorable performance culminated in a chaotic duel with Roger Moore aboard Bond''s yacht, cementing Nick Nack as one of the most recognizable Henchmen in the entire James Bond franchise. Following his success in the 007 series, Villechaize achieved television stardom as Tattoo, the energetic assistant to Ricardo Montalbán''s Mr. Roarke, on the hit drama series Fantasy Island from 1977 to 1983, immortalizing the famous catchphrase announcing arriving visitors. Throughout his career, he also appeared in cult films such as Forbidden Zone (1980) and made guest appearances on various television programs. Villechaize spent his later years advocating for various charitable causes before his death on September 4, 1993, at the age of 50 in Los Angeles, California.',
       'French',
       '1943-04-23',
       '1993-09-04',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Richard Loo (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('db1b6b62-2f55-4542-95b3-c432cb3101c8'),
       'Richard Loo',
       'Hai Fat',
       'Richard Loo, born on May 27, 1903, in Maui, Hawaii, was a prolific Chinese-American character actor whose career spanned over five decades in Hollywood. After graduating from the University of California, Berkeley, Loo initially pursued a career in business, working as an import-export broker before the 1929 stock market crash shifted his focus toward acting. He made his screen debut in the early 1930s and quickly established himself as one of the most recognizable Asian-American actors working in American film and television during the golden age of cinema. Throughout World War II, Loo became a ubiquitous face in Hollywood cinema, frequently cast in stern military roles in wartime dramas such as The Purple Heart (1944) and God Is My Co-Pilot (1945). Beyond feature films, he built an extensive television resume, appearing in popular series such as Perry Mason, I Spy, The Brady Bunch, and Kung Fu. Known for his dignified screen presence, sharp focus, and polished delivery, Loo consistently found work across genres despite the limited range of roles typically offered to Asian-American actors of his era. In 1974, Loo delivered his final feature film performance in The Man with the Golden Gun as the wealthy Thai industrialist Hai Fat. Operating as a covert financier for assassin Francisco Scaramanga, Hai Fat hires Scaramanga to steal the Solex Agitator solar technology. However, when Hai Fat expresses hesitation over Scaramanga''s ambitious plan and attempts to cancel their arrangement, Scaramanga abruptly executes him with his golden gun, leaving Hai Fat''s estate and martial arts academy as notable set pieces in Bond''s investigation. Loo passed away from heart failure on November 20, 1983, at the age of 80 in Los Angeles, California.',
       'American',
       '1903-10-01',
       '1983-11-20',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Soon-Tek Oh (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('da77be4b-0aa9-44b9-924f-2b71c930222a'),
       'Soon-Tek Oh',
       'Lieutenant Hip',
       'Soon-Tek Oh, born on June 29, 1932, in Gwangju, Korea, was a pioneering Korean-American actor, director, and educator who played a key role in expanding representation for Asian-American performers in Western media. Immigrating to the United States in 1959, he earned a Master of Fine Arts from UCLA and trained at the Neighborhood Playhouse in New York. A passionate champion of Asian-American theater, Oh co-founded the influential East West Players theater organization in Los Angeles in 1965 and later established the Society of Heritage Performers, helping foster generations of Asian-American creative talent. In 1974, Oh reached global movie audiences when he was cast as Lieutenant Hip in The Man with the Golden Gun. Serving as a sharp, resourceful local agent for British Intelligence in Hong Kong and Bangkok, Hip assists James Bond during his investigation of Francisco Scaramanga. Oh brought a suave efficiency and quiet humor to the role, notably assisting Bond in escaping a martial arts academy alongside his martial-artist nieces in one of the film''s memorable action sequences. Beyond his entry into the James Bond series, Oh built an extensive screen career spanning five decades in Hollywood. He originated the role of the Recruiter in Stephen Sondheim''s acclaimed 1976 Broadway musical Pacific Overtures and starred in films such as Missing in Action 2: The Beginning (1985) and Beverly Hills Ninja (1997). Disney animation fans also recognize him as the voice of Mulan''s father, Fa Zhou, in Mulan (1998). His prolific television work featured guest roles on iconic series including MASH*, Hawaii Five-O, Charlie''s Angels, MacGyver, and Dynasty. Oh passed away on April 4, 2018, at the age of 85 in Los Angeles, California.',
       'Sout Korean-American',
       '1932-06-29',
       '2018-04-04',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Marc Lawrence (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('09b53fdd-bcbd-4feb-997c-3b4454ed17d3'),
       'Marc Lawrence',
       'Rodney',
       'Marc Lawrence, born Max Goldsmith on February 17, 1910, in New York City, was a legendary American character actor whose remarkably long screen career spanned over seven decades. Recognized instantly by his distinctive, rugged pockmarked visage and intense brooding glare, Lawrence became one of Hollywood’s most iconic and enduring cinema mobsters, heavies, and underworld figures, accumulating well over two hundred film and television credits throughout his lifetime. After studying drama at the City College of New York and performing with Eva Le Gallienne''s Civic Repertory Theatre, Lawrence entered feature films in the early 1930s. He quickly carved out a niche playing tough guys in classic film noir and crime dramas, earning prominent roles in masterpieces such as John Huston''s Key Largo (1948) and The Asphalt Jungle (1950). Blacklisted during the McCarthy era after testifying before the House Un-American Activities Committee, he spent several years living and working in Europe, starring in numerous Italian productions before making a triumphant return to American cinema and television in the 1960s. Lawrence earned a special place in 007 lore by appearing as two distinct underworld figures in back-to-back James Bond films. In Diamonds Are Forever (1971), he played a shady Slumber Incorporated attendant who receives a envelope of money from James Bond at a Las Vegas mortuary. He returned to the franchise three years later in The Man with the Golden Gun (1974) as Rodney, a hitman hired to challenge Francisco Scaramanga in his deadly island funhouse during the film''s opening pre-credits sequence, where Scaramanga ultimately guns him down. Beyond his Bond appearances, Lawrence remained active into his nineties, featuring in high-profile modern films like Marathon Man (1976), Newsies (1992), and Looney Tunes: Back in Action (2003), while also writing and directing independent films such as Nightmare Circus (1974). He passed away from heart failure on November 27, 2005, at the age of 95 in Palm Springs, California.',
       'American',
       '1910-02-17',
       '2005-11-28',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Marne Maitland (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('fa852bb6-319f-4545-9406-5168a9d98950'),
       'Marne Maitland',
       'Lazar',
       'Marne Maitland, born James Marne Maitland on December 18, 1914, in Calcutta, British India, was a distinctive Anglo-Indian character actor known for his striking features, gentle voice, and remarkable versatility. After moving to England for his education at Magdalen College, Oxford, he served in the British Army during World War II before pursuing his passion for acting. His dark, expressive features and refined demeanor made him a highly sought-after actor for exotic, cunning, or dignified roles across British, American, and European cinema. Throughout a screen career that spanned more than four decades, Maitland appeared in dozens of notable film and television productions. His major feature credits included Father Brown (1954), Bhowani Junction (1956), Lord Jim (1965), and Nicholas Ray''s biblical epic King of Kings (1961). On television, he became a familiar face to British audiences through guest appearances in classic adventure series such as The Saint, Danger Man, The Avengers, and Blake''s 7. In 1974, Maitland delivered a memorable turn in The Man with the Golden Gun as Lazar, the master gunsmith residing in Macau. As the craftsman responsible for custom-manufacturing Francisco Scaramanga''s signature golden bullets, Lazar operates with meticulous professional detachment. When James Bond tracks him down to his workshop, Lazar calmly explains the intricate chemistry and craftsmanship behind the golden ammunition before Bond intercepts a delivery to trace Scaramanga''s contact, Andrea Anders. Maitland passed away on March 6, 1991, at the age of 76 in Hampshire, England.',
       'Indian',
       '1914-12-18',
       '1991-03-06',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  James Cossins (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d8c65c08-a7a8-4360-b0ba-70d992d600f0'),
       'James Cossins',
       'Colthorpe',
       'James Cossins, born on December 4, 1933, in Beckenham, Kent, England, was a highly accomplished British character actor celebrated for his imposing screen presence, pompous comic timing, and distinctive mustache. With his booming voice and flustered, authoritative demeanor, Cossins became one of British television and cinema''s most recognizable faces, specialized in portraying stuffed-shirt establishment figures, blustering military officers, and pedantic bureaucrats. After training at the Royal Academy of Dramatic Art and honing his craft in classical stage repertory, Cossins transitioned into film and television during the early 1960s. He built an extensive resume spanning over three decades, featuring in acclaimed films such as Darling (1965), How I Won the War (1967), The Anniversary (1968), and The First Great Train Robbery (1978). On television, he became a household favorite through iconic guest roles, most notably as the bewildered hotel guest Mr. Walt in the famous "Hotel Inspectors" episode of Fawlty Towers, as well as prominent appearances in The Swayford Tools, Barlow at Large, and The Pallisers. In 1974, Cossins brought his signature supercilious demeanor to The Man with the Golden Gun playing Colthorpe, the armaments expert for British Secret Service. Appearing alongside Bernard Lee''s M and Desmond Llewelyn''s Q inside the makeshift MI6 headquarters aboard the capsized wreckage of the RMS Queen Elizabeth in Hong Kong harbor, Colthorpe provides key tactical intelligence regarding Francisco Scaramanga''s custom-built golden bullet and identifies the unique ballistic signatures of master armorer Lazar. Cossins passed away on February 12, 1997, at the age of 63 in Surrey, England.',
       'British',
       '1933-12-04',
       '1997-02-12',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Yao Lin Chen (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('232ce200-9da9-4fe9-b647-d51c90fdb527'),
       'Yao Lin Chen',
       'Chula',
       'Yao Lin Chen, also credited as Chan Yiu Lam, was a Hong Kong actor, martial artist, and stunt performer. Active in the golden age of Hong Kong action cinema throughout the 1970s, he built a solid reputation as a skilled screen fighter, villainous henchman, and dependable stunt contributor across dozens of martial arts feature films. Alongside his work in local Hong Kong productions, Chen frequently collaborated with top martial arts choreographers and directors of the era. His notable genre credits include performances in martial arts classics such as Golgo 13: Assignment Kowloon (1977) and the Jackie Chan feature Snake in the Eagle''s Shadow (1978). In 1974, Chen secured his most widely recognized international role in The Man with the Golden Gun as Chula. Portrayed as the top martial artist student at the Bangkok kung fu academy controlled by industrialist Hai Fat, Chula is pitted against James Bond in a formal match. Demonstrating impressive martial skill, Chula gains the upper hand on Bond, forcing 007 to break protocol by kicking him in the face mid-bow and making a rapid escape through the window. Chen passed away in 2011.',
       'Chinese',
       null,
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  carmen du sautoy (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1bbcec7f-bb91-4095-baab-7ac458f648cb'),
       'carmen du sautoy',
       'Saida',
       'Born in London, England, Carmen Du Sautoy developed a strong classical foundation that propelled her into an extensive, multi-decade career across stage, television, and film. She built a distinguished reputation in British theatre, performing prominently with prestigious institutions such as the Royal Shakespeare Company and the Royal National Theatre. Her stage repertoire spans classical and Shakespearean productions—including A Midsummer Night''s Dream, Troilus and Cressida, and Love''s Labour''s Lost—alongside acclaimed appearances in West End productions such as Piaf. Beyond her stage work, Du Sautoy established a prolific television career featured in numerous series, miniseries, and television movies. Her key television credits include leading and featured roles in acclaimed dramas such as The Citadel, Lost Empires, Poor Little Rich Girl, A Dance to the Music of Time, and The Line of Beauty, alongside guest roles in popular series like Midsomer Murders and Absolutely Fabulous. In 1974, Du Sautoy earned wide international screen recognition in The Man with the Golden Gun as Saida, a sensual belly dancer based in Beirut. As the former mistress of fallen MI6 agent 002, Bill Fairbanks, Saida kept the golden bullet that killed him as a lucky charm lodged in her belly button. When James Bond tracks her down to retrieve the vital piece of evidence, he attempts to extract the bullet with his mouth while kissing her, only to end up accidentally swallowing it during an ambush by local thugs, leaving a distraught Saida crying over her lost charm.',
       'British',
       '1950-02-26',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Maud Adams (The Man With The Golden Gun)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('45dedb1b-a285-48a7-bc75-14de502a9906'),
       'Maud Adams',
       'Andrea Anders',
       'Maud Adams, born Maud Solveig Christina Wikström on February 12, 1945, in Luleå, Sweden, is a Swedish actress and former top fashion model who holds a unique distinction in cinematic history. Discovered by a photographer in a shop, she embarked on a highly successful international modeling career that led her to Paris and New York, where she worked with top agencies and graced the covers of major fashion magazines. Her striking elegance and fluent multilingual abilities eased her transition into acting during the early 1970s. In 1974, Adams achieved major film prominence when she was cast as Andrea Anders in The Man with the Golden Gun. Playing the doomed, mistreated mistress of assassin Francisco Scaramanga, Adams infused the character with a poignant blend of vulnerability and quiet desperation. Her character secretly mails golden bullets to British intelligence in a bid to set 007 against Scaramanga, making her essential to driving the film''s plot before meeting a tragic fate. Adams went on to earn a rare status within the James Bond franchise by making multiple appearances across different roles in the Roger Moore era. Beyond 007, she starred in cult films like Rollerball (1975) and Tattoo (1981), along with television appearances on hit shows such as Hawaii Five-O, Kojak, and Magnum, P.I. She later expanded her career into cosmetics and business ventures, remaining an enduring and elegant fan favorite at international cinema conventions.',
       'Swedish',
       '1945-02-12',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  George Baker (The Spy Who Loved Me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6671b6e6-0abb-460e-a0d0-137e268ccf99'),
       'George Baker',
       'Royal Navy Captain Benson',
       'Born George Morris Baker on April 1, 1931, in Varna, Bulgaria, George Baker was a distinguished English actor and writer whose suave demeanor, vocal versatility, and steady authority made him a beloved fixture of British theater, film, and television for over six decades. In the 1969 James Bond film On Her Majesty''s Secret Service, he played Sir Hilary Bray, the aristocratic London genealogist at the College of Arms whom James Bond impersonates to infiltrate Blofeld’s lair atop Piz Gloria. In addition to his on-screen role as Bray, Baker provided the voice dubbing for George Lazenby during the extensive sequences where Bond is in disguise as the heraldic expert. Baker was educated in England before beginning his theatrical career in repertory theater and joining the prestigious Old Vic Company in the 1950s. His classic good looks and commanding presence rapidly earned him leading film roles, notably as the heroic Flight Lieutenant David Maltby in the 1955 war epic The Dam Busters. Beyond his cinematic work, Baker established a remarkably prolific television career, making iconic guest appearances in series such as I, Claudius and Doctor Who. Modern audiences know him best for his definitive portrayal of Chief Inspector Reginald Wexford in the long-running mystery series The Ruth Rendell Mysteries, a role he played for over thirteen years and for which he also wrote several teleplays. Throughout his celebrated lifetime, Baker appeared in dozens of feature films and hundreds of television episodes, remaining an active figure in the artistic community until his later years. He was awarded an MBE (Member of the Order of the British Empire) in the 1989 New Year Honours list for his charitable services to the theatrical profession. Baker passed away from pneumonia following a stroke on October 7, 2011, in West Lavington, Wiltshire, at the age of 80.',
       'british',
       '1931-04-01',
       '2011-10-07',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Barbara Bach (The spy who loved me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('a1b2c3d4-e5f6-7a8b-9c0d-1e2f3a4b5c6d'),
       'Barbara Bach',
       'Major Anya Amasova (Agent XXX)',
       'Barbara Bach, born Barbara Goldbach in Queens, New York, began her professional career in the mid-1960s as a high-fashion model after joining the Eileen Ford Agency. She quickly became one of the most sought-after cover models of the decade, appearing on the covers of international publications such as Vogue and ELLE. In the late 1960s, Bach relocated to Italy, where she launched her acting career. She made her screen debut in the 1968 television adaptation Odissea and subsequently starred in several Italian films and giallo thrillers throughout the early 1970s, including The Black Belly of the Tarantula and Short Night of Glass Dolls. Her major international breakthrough arrived in 1977 when she was cast opposite Roger Moore as KGB operative Major Anya Amasova (Agent XXX) in the James Bond feature The Spy Who Loved Me. Her portrayal of a highly capable, top-tier secret agent standing as an equal to Bond made the role one of the most memorable Bond heroine performances in the franchise''s history. Following her success in the Bond film, she appeared in notable features such as the 1978 World War II adventure Force 10 from Navarone. While filming the slapstick comedy Caveman in 1980, Bach met former Beatles drummer Ringo Starr. The couple married in April 1981. Bach gradually stepped away from acting in the mid-1980s to focus on her personal life and education, later earning a master''s degree in psychology from UCLA in 1993. She has since devoted much of her time to charitable endeavors, co-founding the Self Help Addiction Recovery Program and establishing The Lotus Foundation alongside her husband.',
       'American',
       '1947-08-27',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Curd Jürgens (The spy who loved me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b2c3d4e5-f6a7-8b9c-0d1e-2f3a4b5c6d7e'),
       'Curd Jürgens',
       'Karl Stromberg',
       'Curd Jürgens was born in Solln, a district of Munich, Germany, in 1915. He initially pursued a career in journalism before turning to acting in the 1930s under the encouragement of his first wife, actress Louise Basler. He established himself on the German stage and screen, working extensively at the prestigious Burgtheater in Vienna. His early career faced significant political hardship, as his outspoken criticism of National Socialism eventually led to his arrest and internment in an Austrian labor camp as a politically unreliable figure toward the end of World War II. Following the war, Jürgens resumed his acting career and rose to prominent stardom across European cinema. His international breakthrough came in 1955 with the German war drama Des Teufels General (The Devil''s General), which earned him the Best Actor award at the Venice Film Festival. Soon after, he began starring in major international productions, often billed as "Curt Jurgens" in English-language markets. Notable Hollywood and European films included the Brigitte Bardot sensation And God Created Woman (1956), the naval thriller The Enemy Below (1957) alongside Robert Mitchum, and the epic war film The Longest Day (1962). In 1977, Jürgens gained widespread global recognition among blockbuster audiences when he played the villainous industrialist Karl Stromberg in the James Bond film The Spy Who Loved Me. His portrayal of the web-fingered, megalomaniacal shipping tycoon obsessed with destroying civilization to build an underwater empire became one of the franchise''s classic antagonist roles. Over the course of a career that spanned five decades, Jürgens appeared in more than 160 films and published a successful autobiography titled Sixty-One and Still Counting. He remained an active stage and screen performer until his death from a heart attack in Vienna on June 18, 1982, at the age of 66.',
       'German-Austrian',
       '1915-12-13',
       '1982-06-18',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Caroline Munro (The spy who loved me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d4e5f6a7-b89c-0d1e-2f3a-4b5c6d7e8f9a'),
       'Caroline Munro',
       'Naomi',
       'Caroline Munro was born in Windsor, Berkshire, England, in 1949. Her path to stardom began unexpectedly in the mid-1960s when her mother and a friend submitted photos of her to a newspaper''s "Face of the Year" competition. Winning the contest at age 16 launched a highly successful modeling career in London, where she appeared in Vogue magazine and became widely recognized as the face of Lamb''s Navy Rum in an advertising campaign that lasted ten years. Her modeling work caught the attention of film producers, leading to a contract with Hammer Film Productions in the early 1970s and establishing her as a beloved cult cinema icon and "Scream Queen." Throughout the decade, she starred in prominent fantasy and horror films, including Dracula A.D. 1972, The Golden Voyage of Sinbad (1973), Captain Kronos – Vampire Hunter (1974), and At the Earth''s Core (1976). In 1977, Munro achieved major international fame when she was cast as Naomi, the seductive helicopter pilot and assassin working for Karl Stromberg, in the James Bond film The Spy Who Loved Me. Her iconic scene—winking at Roger Moore''s James Bond from her helicopter before he shoots her down with a missile fired from his amphibious Lotus Esprit—holds a unique distinction in the franchise, making Naomi the first woman explicitly killed by 007 in a Bond movie. Following her appearance in the Bond series, she continued to act in cult classics like Starcrash (1978) and Maniac (1980), while remaining an enduring favorite at film conventions worldwide.',
       'British',
       '1949-01-16',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Michael Billington (The spy who loved me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('f6a7b89c-0d1e-2f3a-4b5c-6d7e8f9a0b1c'),
       'Michael Billington',
       'KGB Agent Sergei Barsov',
       'Michael Billington was born in Blackburn, Lancashire, England, in 1941. Before pursuing an acting career, he worked in a neon-sign factory and performed as a dancer and stage actor in London, eventually transitioning into dramatic roles with the Royal Shakespeare Company. He achieved wider television recognition in the early 1970s by starring as Colonel Paul Foster in Gerry Anderson''s cult science-fiction series UFO, and subsequently appeared in notable period and historical dramas like The Onedin Line, War and Peace, and Edward the Seventh. In 1977, Billington appeared in the James Bond film The Spy Who Loved Me as Sergei Barsov, the Soviet agent and romantic partner of Anya Amasova who meets his end in the movie''s pre-credits ski chase. Beyond this on-screen role, Billington is famously known within franchise history for being screen-tested for the role of James Bond more than any other actor, auditioning across multiple decades as a primary contender to take over the mantle. Later in his career, he split his time between British television and guest-starring roles in Hollywood productions before stepping away from the screen in the early 1990s. He passed away in 2005 at the age of 63.',
       'British',
       '1941-12-24',
       '2005-06-03',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Olga Bisera (The spy who loved me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('a7b89c0d-1e2f-3a4b-5c6d-7e8f9a0b1c2d'),
       'Olga Bisera',
       'Felicca',
       'Olga Bisera was born Bisera Vukotić in Mostar, Bosnia and Herzegovina, in 1944. She pursued her passion for performing by studying at the Drama Arts Academy in Belgrade before making her American film debut at age 25 in Sidney Pollack''s war drama Castle Keep (1969). Following her debut, she was signed to Columbia Pictures and trained at the Lee Strasberg Theatre and Film Institute in New York. In the early 1970s, she relocated to Italy, where she adopted her stage name, established her own film production company, Cinemondial, and established herself as a versatile figure in Italian cinema. During this period, she starred in numerous European feature films alongside prominent actors such as Marcello Mastroianni, Alain Delon, and Sylva Koscina. Bisera gained widespread international recognition in 1977 when she appeared in the James Bond film The Spy Who Loved Me as Felicca, the Egyptian secretary to black market trader Aziz Fekkesh. In her memorable scene, Felicca is assigned to entertain and distract James Bond (Roger Moore) in Cairo, but her sudden moment of panic upon spotting a sniper causes Bond to react, leading to her tragic demise as she is caught in the crossfire. Following her acting career, Bisera successfully transitioned into journalism, interviewing high-profile political and world figures for prominent Italian media outlets. In addition to her work in broadcasting and news, she has built a career as an author and executive producer, publishing several books and managing creative projects across Europe.',
       'Yugoslavian',
       '1944-05-26',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Edward de Souza (The spy who loved me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b89c0d1e-2f3a-4b5c-6d7e-8f9a0b1c2d3e'),
       'Edward de Souza',
       'Sheikh Hosein',
       'Edward de Souza was born in Hull, East Yorkshire, England, in 1932 to a Portuguese-Indian father and an English mother. He trained at the Royal Academy of Dramatic Art (RADA) in London, graduating in 1957, and quickly made a name for himself as a classical actor. He spent time with both the Royal Shakespeare Company and the Royal National Theatre, sharing the stage with prominent actors of the era such as Laurence Olivier and Vivien Leigh. In the early 1960s, de Souza became a well-known face in British cinema, starring in leading roles for Hammer Film Productions, including the horror films The Phantom of the Opera (1962) and The Kiss of the Vampire (1963). He also built a remarkably prolific television career, guest-starring in popular shows like The Avengers, Doctor Who, The Saint, and Coronation Street. In 1977, de Souza appeared in the James Bond film The Spy Who Loved Me as Sheikh Hosein, an old Cambridge University classmate and ally of James Bond. In the film, Hosein hosts Bond at his desert camp in Egypt, offering him vital intelligence on Karl Stromberg''s operations while providing him with shelter and hospitality. In addition to his extensive work in film, television, and radio, de Souza became a celebrated voice actor, performing in over a thousand radio plays for the BBC, including a long stint on the long-running radio drama The Archers. He has maintained a performing career across stage and screen for over six decades.',
       'British',
       '1932-09-04',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Vernon Dobtcheff (The spy who loved me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('c90d1e2f-3a4b-5c6d-7e8f-9a0b1c2d3e4f'),
       'Vernon Dobtcheff',
       'Max Kalba',
       'Vernon Dobtcheff was born in Nîmes, France, in 1934 to Russian parents. Educated in England at Aske''s Hatcham Boys'' School, he developed a fluency in multiple languages—including English, French, Italian, and German—which would become a defining hallmark of his international acting career. He began his professional career on the British stage with the Old Vic Theatre before transitioning into television and cinema in the mid-1960s. Known for his distinctive voice, expressive features, and commanding screen presence, Dobtcheff became one of European cinema''s most prolific and recognizable character actors. Over a career spanning more than six decades, he accumulated over 300 film and television credits across several countries. His notable film appearances include classics such as The Taming of the Shrew (1967), The Day of the Jackal (1973), Murder on the Orient Express (1974), The Name of the Rose (1986), and Before Sunset (2004), alongside guest roles in popular television series like Doctor Who, Blake''s 7, and The Borgias. In 1977, Dobtcheff appeared in the James Bond film The Spy Who Loved Me as Max Kalba, the suave Egyptian nightclub owner and black market antiquities dealer in Cairo. In the film, Kalba possesses the microfilm containing the underwater submarine tracking system that both James Bond and Anya Amasova are trying to acquire, leading to his untimely death at the hands of the assassin Jaws inside the club''s office. Throughout his long career, Dobtcheff remained a favored actor among major international directors, continuing to perform across theater, film, and television well into his eighties while maintaining a reputation as one of the hardest-working actors in the industry.',
       'British',
       '1934-08-14',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Nadim Sawalha (The spy who loved me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d01e2f3a-4b5c-6d7e-8f9a-0b1c2d3e4f5a'),
       'Nadim Sawalha',
       'Fekkesh',
       'Nadim Sawalha was born in Madaba, Jordan, in 1935. He moved to the United Kingdom in the 1950s to study drama at the Drama Centre London, eventually settling in Britain and building a distinguished career as a character actor across theater, television, and international cinema. His natural charisma and ability to project authority made him a popular choice for playing diplomats, merchants, and traditional authority figures. Over a career spanning more than five decades, Sawalha accumulated an impressive list of credits in major Hollywood and British productions. His notable film appearances include The Return of the Pink Panther (1975), Young Sherlock Holmes (1985), Syriana (2005), and West Is West (2010). On television, he appeared in widely recognized series such as The Sweeney, Doctor Who, The Bill, and House of Cards. He also established a legacy through his family, as father to prominent British actresses Julia Sawalha and Nadia Sawalha. In 1977, Sawalha appeared in the James Bond film The Spy Who Loved Me as Fekkesh, an Egyptian contact who holds key information regarding the stolen submarine tracking system microfilm. In the film, Bond tracks Fekkesh to Cairo, following him through a bustling market and onto the rooftops near the Pyramids, where Fekkesh is ultimately murdered by the imposing henchman Jaws before he can reveal the location of the microfilm. Throughout his career, Sawalha remained an influential figure for Arab actors in British television and cinema, frequently advocating for broader and more nuanced representation of Middle Eastern characters in Western media. He continued performing across film, television, and radio well into his later years.',
       'Jordanian-British',
       '1935-09-09',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Richard Kiel (The spy who loved me, moonraker)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('c3d4e5f6-a7b8-9c0d-1e2f-3a4b5c6d7e8f'),
       'Richard Kiel',
       'Jaws',
       'Richard Kiel was born in Detroit, Michigan, in 1939. Standing 7 feet 2 inches tall due to acromegaly, a condition caused by an overproduction of growth hormone, Kiel initially worked as a night club bouncer and a cemetery plot salesman before breaking into acting in the late 1950s. His towering height and commanding presence quickly made him a recognizable figure on American television, earning him early roles in classic series such as The Twilight Zone, The Man from U.N.C.L.E., and Gilligan''s Island. His major international breakthrough came in 1977 when he was cast as the steel-toothed assassin Jaws in the James Bond film The Spy Who Loved Me. Despite playing a silent, terrifying villain tasked with killing Roger Moore''s James Bond, Kiel infused the character with subtle humor and vulnerability. The character became an instant fan favorite, prompting the film''s producers to change the ending so Jaws survived, which paved the way for his return in subsequent franchise installments. Beyond the Bond series, Kiel enjoyed a prolific acting career spanning five decades across film and television. Notable roles included the giant alien Kanamit in The Twilight Zone, the intimidating convict Lethal in The Longest Yard (1974), and the hitman Arnold in Silver Streak (1976). Later in his career, he introduced himself to a new generation of fans playing Mr. Larson, the towering boss of Adam Sandler''s character in the 1996 comedy Happy Gilmore, and by voicing Vlad in the 2010 Disney animated feature Tangled. Kiel was also a devout Christian who authored an autobiography, Making It Big in the Movies, in 2002. He passed away on September 10, 2014, at the age of 74, leaving behind a legacy as one of cinema''s most iconic screen villains and beloved character actors.',
       'American',
       '1939-09-13',
       '2014-09-10',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Geoffrey Keen (The spy who loved me, moonraker, for your eyes only, octopussy, a view to a kill, the living daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('e5f6a7b8-9c0d-1e2f-3a4b-5c6d7e8f9a0b'),
       'Geoffrey Keen',
       'Sir Frederick Gray, Minister of Defence',
       'Geoffrey Keen was born in England in 1916. He was educated at Bristol Grammar School before attending the Royal Academy of Dramatic Art (RADA), where he earned the Bancroft Gold Medal upon graduating in 1936. He began his professional acting career on the stage, appearing in productions with the Old Vic Theatre. His career was temporarily interrupted by World War II, during which he served in the Royal Army Medical Corps and performed with the Stars in Battledress entertainment troupe. Following the war, Keen established himself as one of Britain''s most prolific character actors. Known for his crisp delivery and commanding presence, he was frequently cast as authority figures, including senior police officers, military commanders, politicians, and corporate executives. His extensive filmography includes appearances in acclaimed movies such as Odd Man Out (1947), The Third Man (1949), Treasure Island (1950), Doctor in the House (1954), Sink the Bismarck! (1960), and Doctor Zhivago (1965). On television, he gained widespread popularity starring as oil executive Brian Stead in the long-running BBC series The Troubleshooters. In 1977, Keen took on the recurring role of Sir Frederick Gray, the British Minister of Defence, making his franchise debut in the James Bond film The Spy Who Loved Me. His portrayal of the stern government official added a steadying presence to the series and became a recognizable fixture of the Bond films over the next decade. Keen appeared in over 100 films throughout a screen career that spanned nearly five decades before his retirement in 1991. He passed away in London in 2005 at the age of 89',
       'British',
       '1916-08-21',
       '2005-11-03',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Robert Brown (The Spy Who Loved Me)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('a1b2c3d4-e5f6-7a8b-9c0d-0e1f2a3b4c5d'),
       'Robert Brown',
       'Vice Admiral Hargreaves',
       'Robert Brown was born in Swanage, Dorset, England, in July 1921. He began his professional acting career in British theater and cinema during the late 1940s, making an early film appearance in Carol Reed’s classic noir thriller The Third Man (1949). Over the following decades, Brown built a prolific career as a dependable character actor, distinguished by his robust build, stern features, and commanding vocal delivery. His extensive screen work included supporting roles in landmark productions such as Ben-Hur (1959), Sink the Bismarck! (1960), Billy Budd (1962), and One Million Years B.C. (1966), alongside numerous guest appearances on television. In 1983, Brown officially took over the role of M, head of the Secret Intelligence Service (MI6), in the James Bond entry Octopussy. Following the passing of Bernard Lee—who had portrayed M in the previous eleven films—the production team chose Brown to step into the iconic role. Bringing a slightly more gruff, no-nonsense authority to the briefing room, Brown’s M holds Roger Moore’s 007 to strict professional standards during the investigation into the forged Fabergé egg and Soviet nuclear plot. Brown had previously debuted in the series six years earlier in The Spy Who Loved Me (1977) playing Vice Admiral Hargreaves, leading many fans and franchise scholars to speculate that Hargreaves was promoted to succeed Lee’s character as M. Following his debut as M in Octopussy, Brown remained a central figure in the franchise throughout the remainder of the 1980s. He reprised the role opposite Roger Moore in A View to a Kill (1985) and continued as M through Timothy Dalton''s tenure in The Living Daylights (1987) and Licence to Kill (1989). In Licence to Kill, Brown was given a particularly memorable narrative thread as he personally revokes Bond''s license to kill in Key West when 007 chooses personal revenge over MI6 orders. Brown retired from acting in the 1990s and passed away in November 2003 at the age of eighty-two.',
       'British',
       '1921-07-23',
       '2003-11-11',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Lois Chiles (Moonraker)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1a2b3c4d-5e6f-7a8b-9c0d-1e2f3a4b5c6d'),
       'Lois Chiles',
       'Dr. Holly Goodhead',
       'Lois Chiles was born in Houston, Texas, in 1947. Before entering the film industry, she established a successful career as a high-fashion model in New York City during the late 1960s and early 1970s. She made her feature film debut in 1972 and quickly gained prominent roles in major Hollywood productions, including The Way We Were (1973) alongside Barbra Streisand and Robert Redford, The Great Gatsby (1974) as Jordan Baker, the medical thriller Coma (1978), and the Agatha Christie adaptation Death on the Nile (1978). In 1979, Chiles starred as Dr. Holly Goodhead in the James Bond film Moonraker. As a CIA operative disguised as a NASA scientist and astronaut, her character broke the traditional Bond girl mold by serving as a highly capable, independent partner to Roger Moore''s James Bond. Together, they travel from California to Venice, Rio de Janeiro, and into outer space to stop the billionaire villain Hugo Drax from eradicating humanity. Following her signature Bond role, Chiles maintained an active career across film and television throughout the 1980s and 1990s. Her notable later credits include a recurring role as Holly Harwood on the hit prime-time soap opera Dallas, the horror anthology Creepshow 2 (1987), James L. Brooks'' acclaimed comedy-drama Broadcast News (1987), and guest roles on popular television series such as Murder, She Wrote and CSI: Crime Scene Investigation. In addition to her screen career, she also spent time teaching dramatic arts at the university level.',
       'American',
       '1947-04-15',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Michael Lonsdale (Moonraker)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2b3c4d5e-6f7a-8b9c-0d1e-2f3a4b5c6d7e'),
       'Michael Lonsdale',
       'Hugo Drax',
       'Michael Lonsdale was born in Paris, France, in 1931 to an English military officer father and a French-Irish mother. He spent much of his childhood in London and Casablanca before returning to Paris in 1947 to study painting. His focus soon shifted to the performing arts, and he made his professional stage debut in 1955. His bilingual mastery of French and English allowed him to transition seamlessly between French cinema and major international productions, where his deep voice, serene demeanor, and subtle intensity quickly made him a favored collaborator for renowned filmmakers. Throughout a prolific career spanning six decades and over two hundred roles, Lonsdale worked with legendary directors such as François Truffaut, Alain Resnais, Orson Welles, Luis Buñuel, and Steven Spielberg. He gained early international acclaim for his portrayal of the relentless French police detective Deputy Commissioner Lebel in The Day of the Jackal (1973). His other notable screen credits include The Phantom of Liberty (1974), The Name of the Rose (1986), The Remains of the Day (1993), Ronin (1998), and Munich (2005). In 1979, Lonsdale delivered one of his most iconic performances as the villainous industrialist Hugo Drax in the James Bond film Moonraker. As a megalomaniacal billionaire plotting to annihilate world human population with a lethal nerve gas and repopulate Earth from an orbital space station, Drax remains one of the most chillingly soft-spoken and sophisticated antagonists in the franchise. Lonsdale played the character with a calm, refined detachment that made his genocidal ambitions all the more striking against Roger Moore''s James Bond. Later in life, Lonsdale achieved critical triumph in France for his performance as Brother Luc in the acclaimed drama Of Gods and Men (2010), earning him the César Award for Best Supporting Actor. Beyond acting, he was an accomplished author, audiobook narrator, and stage director, as well as a devout Christian who often recorded spoken-word religious texts. He passed away peacefully in Paris in September 2020 at the age of 89, leaving behind a legacy as one of the most versatile and respected character actors in international cinema.',
       'French-British',
       '1931-05-24',
       '2020-09-21',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Corinne Cléry (Moonraker)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3c4d5e6f-7a8b-9c0d-1e2f-3a4b5c6d7e8f'),
       'Corinne Cléry',
       'Corrine Dufour',
       'Corinne Cléry was born Corinne Piccolo in Paris, France, in 1950. She began her career as a teenager working as a model and bit-part actress, initially using the stage name Corinne Piccoli. She achieved major international fame in 1975 when she starred as the title character in the controversial French erotic drama Story of O (Histoire d''O). The film''s massive success across Europe made her a household name and launched a busy career in European mainstream and genre cinema, particularly in Italy, where she would make her home and build the majority of her film and television body of work. In 1979, Cléry reached a global audience when she was cast as Corinne Dufour in the James Bond film Moonraker. Serving as the personal helicopter pilot for the main villain, billionaire Hugo Drax, her character assists Roger Moore''s James Bond by giving him access to Drax''s safe after realizing the madness of her employer''s plot. Her betrayal is discovered by Drax, leading to one of the most memorable and haunting exit scenes in the franchise, where she is hunted down and killed by Drax''s dobermans in a serene French forest. Following her memorable turn in Moonraker, Cléry focused heavily on Italian cinema, television, and theater. She starred in a wide array of Italian comedies, crime thrillers, and dramas, working with prominent directors such as Lucio Fulci, Sergio Corbucci, and Pasquale Festa Campanile. In her later career, she became a familiar and beloved personality on Italian television, starring in popular long-running soaps such as Incantesimo, appearing in numerous stage plays, and participating in hit reality programs such as Italy''s Dancing with the Stars (Ballando con le Stelle) and L''Isola dei Famosi.',
       'French',
       '1950-03-23',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Toshirô Suga (Moonraker)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('4d5e6f7a-8b9c-0d1e-2f3a-4b5c6d7e8f9a'),
       'Toshirô Suga',
       'Chang',
       'Toshirō Suga was born in Tokyo, Japan, in 1950. Guided by his father''s advice, he began practicing judo at age fifteen and started studying aikido in 1968 at the Aikikai Hombu Dojo in Tokyo. During his early training, he received instruction from prominent aikido masters, including Morihei Ueshiba, the founder of the martial art. In the summer of 1971, he moved to France to continue his martial arts journey, eventually establishing himself as a high-ranking instructor holding the rank of 7th dan Aikikai. He spent decades teaching aikido across Europe and Canada, where he also instructed military forces. His entry into the film industry came about through his aikido connections, as he taught martial arts to James Bond franchise producer Michael G. Wilson. This relationship led directly to his casting in the 1979 James Bond film Moonraker. In the movie, Suga played Chang, the personal martial-arts-trained henchman and assassin serving main villain Hugo Drax. His role featured notable action sequences opposite Roger Moore''s James Bond, including a attempt to sabotage a centrifuge trainer and a fight scene in a Venetian glass museum that ends in a clock tower struggle. While Moonraker served as his most prominent cinematic appearance, Suga maintained a brief acting career alongside his primary profession as a world-renowned martial arts teacher. He appeared in a few French film and television productions in the 1980s, including Tout dépend des filles... (1980) and Charlots connection (1984). However, he remained primarily dedicated to the practice and instruction of aikido, conducting international seminars, producing instructional martial arts media, and teaching in France.',
       'Japanese',
       '1950-08-22',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Emily Bolton (Moonraker)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('5e6f7a8b-9c0d-1e2f-3a4b-5c6d7e8f9a0b'),
       'Emily Bolton',
       'Manuela',
       'Emily Bolton was born in Aruba in 1951 and raised in both England and the Netherlands. Multilingual and originally trained with the intention of becoming a concert pianist, she chose at age eighteen to pivot to the dramatic arts and enrolled in drama school. She began her professional acting career in British television and film in the mid-1970s, occasionally performing under the name June Bolton. Her early work included appearances in popular series such as Space: 1999, Gangsters, and Survivors, as well as a role in Ken Russell''s biographical film Valentino (1977). In 1979, Bolton achieved global visibility when she was cast in the James Bond adventure Moonraker as Manuela. Stationed in Rio de Janeiro as an operative for Station VH, her character serves as Bond''s local British Intelligence liaison in Brazil. She assists Roger Moore''s 007 by researching connections to Drax Industries, welcoming him to his hotel, and standing guard during a covert night operation in an alleyway during Carnival, where she narrowly survives an attack by the steel-toothed henchman Jaws. Following her appearance in the Bond franchise, Bolton continued to build a distinguished television career throughout the 1980s and early 1990s. She gained widespread acclaim for her major recurring role as prisoner of war Christina Campbell in the critically praised BBC drama series Tenko (1981–1985). Her later credits include prominent roles in the financial drama series Capital City (1989–1990) and the American miniseries The Winds of War (1983). She eventually retired from professional acting to transition into working as a talent agent.',
       'Dutch',
       '1951-01-01',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Blanche Ravalec (Moonraker)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6f7a8b9c-0d1e-2f3a-4b5c-6d7e8f9a0b1c'),
       'Blanche Ravalec',
       'Dolly',
       'Blanche Ravalec was born in France in 1954 and began her career in French cinema and television during the late 1970s. Initially working as a dubbing artist and voice actress alongside screen acting, she gained early film roles in French productions such as La Carapate (1978) and Trocadéro bleu citron (1978). Her expressive performances and background in comedic timing helped establish her in the French entertainment industry during these formative years. In 1979, Ravalec gained worldwide attention when she was cast as Dolly in the James Bond entry Moonraker. Her character, a sweet, blonde woman with pigtails and glasses, unexpectedly falls in love with the towering, steel-toothed henchman Jaws after saving him from the wreckage of a cable car crash in Rio de Janeiro. Dolly becomes Jaws''s romantic partner, accompanying him to Hugo Drax''s space station where the pair ultimately defect to assist James Bond and Holly Goodhead once they realize Drax''s vision excludes non-physically ideal humans. Following her memorable turn in the Bond franchise, Ravalec built a prolific and enduring career in France, primarily focusing on television and voice work. She became one of France''s most active dubbing actresses, providing the French voice for major international stars such as Marcia Cross in Desperate Housewives, Patricia Heaton in Everybody Loves Raymond, and dynamic characters across various anime and animated features. She also continued her screen acting career with regular roles in popular French television dramas, including a long-running main role in the crime series Navarro.',
       'French',
       '1954-09-19',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Anne Lonnberg (Moonraker)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('83398612-b805-4aca-9dee-726eb24f32c6'),
       'Anne Lonnberg',
       'Museum Guide',
       'Anne Lonnberg was born in Berkeley, California, in 1948 to a Swedish father and an American mother. Beginning her entertainment career as a model, she transitioned into acting in the mid-1960s and gained early notice starring in European and Greek cinema, including a prominent role in the critically acclaimed film Girls in the Sun. Over the course of her career, she moved to France and cultivated a multilingual presence, appearing in various international film and television projects such as Woody Allen''s Love and Death and Lewis Gilbert''s Seven Nights in Japan. In 1979, Lonnberg gained international recognition when she appeared in the James Bond film Moonraker. In the film, she played the museum guide who interacts with James Bond during his investigation at the Drax museum in Venice, directing his attention toward vital clues concerning Hugo Drax''s operations. She also appeared later in the film as one of the selected women stationed at Drax''s secret space station compound. Following her work in the Bond franchise, Lonnberg continued acting in film and television projects throughout the 1980s, concluding her screen career with a supporting role as a Swiss photographer in Philip Kaufman''s film adaptation of The Unbearable Lightness of Being in 1988. After stepping away from acting, she shifted her creative focus toward literature, writing numerous French-language novels under the pen name Anne de Pasquale.',
       'American',
       '1948-02-17',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Carole Bouquet (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1c2b3a4d-5e6f-7a8b-9c0d-1e2f3a4b5c6d'),
       'Carole Bouquet',
       'Melina Havelock',
       'Carole Bouquet was born in Neuilly-sur-Seine, France, in 1957. She studied acting at the Conservatoire Supérieur d''Art Dramatique in Paris before making an acclaimed international debut at just nineteen years old in Luis Buñuel''s surrealist masterpiece That Obscure Object of Desire (1977). Her striking appearance and icy elegance quickly established her as a major talent in European cinema and led to high-profile modeling work, most notably becoming the face of the luxury fragrance Chanel No. 5 throughout the 1980s and 1990s. In 1981, Bouquet achieved international stardom when she played Melina Havelock in the James Bond film For Your Eyes Only. Starring opposite Roger Moore, her character is a fierce Greek-French archer seeking vengeance against the assassins who murdered her parents. Melina''s drive for revenge forms the central emotional anchor of the film, leading her to partner with 007 across action sequences in Greece and under the sea. For Your Eyes Only remains her sole appearance in the James Bond franchise, totaling one film. Following her Bond success, Bouquet built an esteemed career in French and European cinema, earning widespread critical acclaim for her dramatic versatility. She won the prestigious César Award for Best Actress for her performance in the 1989 romantic comedy-drama Too Beautiful for You (Trop belle pour toi). Over the subsequent decades, she appeared in dozens of acclaimed films and television series, worked extensively in theater, and expanded her pursuits outside acting into winemaking on the Italian island of Pantelleria.',
       'French',
       '1957-08-18',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Chaim Topol (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2d3c4b5a-6f7a-8b9c-0d1e-2f3a4b5c6d7e'),
       'Chaim Topol',
       'Milos Columbo',
       'Chaim Topol, known professionally by his surname Topol, was born in Tel Aviv, Mandate Palestine, in 1935. He discovered his passion for performance while serving in the Israel Defense Forces, where he joined an army entertainment troupe. Following his military service, he helped found the Haifa Municipal Theatre and became a celebrated figure in Israeli cinema and theater, earning early acclaim for his breakout starring role in the popular Israeli film Sallah Shabati in 1964. Topol achieved enduring international stardom through his iconic portrayal of Tevye the milkman in the musical Fiddler on the Roof. After starring in the hugely successful London stage production starting in 1967, he was cast in Norman Jewison''s 1971 film adaptation. His performance earned him a Golden Globe Award for Best Actor, an Academy Award nomination, and worldwide renown. He continued to perform as Tevye thousands of times on stage around the globe over the course of several decades, making the role inextricably linked to his career. In 1981, Topol joined the James Bond franchise in For Your Eyes Only, playing Milos Columbo, a charismatic Greek smuggler and pistachio-eating intelligence informant. Columbo initially appears as a potential antagonist before becoming one of Roger Moore''s most trusted allies, aiding 007 in defeating Aristotle Kristatos during a dramatic assault on a mountaintop monastery. For Your Eyes Only stands as Topol''s only appearance in a James Bond film. Beyond his performance in For Your Eyes Only, Topol''s film credits included sci-fi classic Flash Gordon (1980), where he played Dr. Hans Zarkov, and major television miniseries such as The Winds of War (1983) and War and Remembrance (1988). Throughout his life, he remained deeply dedicated to social work, founding Jordan River Village, a holiday camp for children with chronic illnesses. Topol was awarded the Israel Prize for lifetime achievement in 2015 and passed away in Tel Aviv in 2023 at the age of 87.',
       'Israeli',
       '1935-09-09',
       '2023-03-08',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Lynn-Holly Johnson (For your eyes only)
 */
-- Lynn-Holly Johnson
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3e4d5c6b-7a8b-9c0d-1e2f-3a4b5c6d7e8f'),
       'Lynn-Holly Johnson',
       'Bibi Dahl',
       'Lynn-Holly Johnson was born in Chicago, Illinois, in 1958. A talented competitive figure skater from a young age, she placed sixth at the 1974 United States Figure Skating Championships at the novice level before transitioning into professional ice show tours like the Capades. Her ice-skating prowess opened the door to Hollywood when director Donald Wrye cast her as the lead in the romantic drama Ice Castles (1978). Her charming performance as a blinded young skater earning a second chance at her sport earned her a Golden Globe nomination for New Star of the Year. In 1981, Johnson joined the cast of the James Bond film For Your Eyes Only as Bibi Dahl, an energetic, impetuous teenage ice skater pursuing Olympic gold under the sponsorship of wealthy villain Aristotle Kristatos. Her character becomes infatuated with Roger Moore''s James Bond, creating a lighthearted comic dynamic as 007 repeatedly rebuffs her playful advances while ensuring her safety amidst the international intrigue. For Your Eyes Only remains her sole appearance in the James Bond franchise, totaling one film. Following her turn as Bibi Dahl, Johnson continued to work steadily in film and television throughout the 1980s. She starred in cult films like the sci-fi comedy Where the Boys Are ''84 and the horror-mystery The Watcher in the Woods (1980) alongside Bette Davis. As the years progressed, she shifted her primary focus away from screen acting toward her family, theater productions, and philanthropic efforts, while remaining a fondly remembered figure among Bond enthusiasts and figure skating fans alike.',
       'American',
       '1958-12-13',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Julian Glover (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('4f5e6d7c-8b9c-0d1e-2f3a-4b5c6d7e8f9a'),
       'Julian Glover',
       'Aristotle "Aris" Kristatos',
       'Julian Glover was born in Hampstead, London, in 1935 into a family of journalists and performers. He trained at the prestigious Royal Academy of Dramatic Art before joining the Royal Shakespeare Company, where his powerful stage presence and classic diction made him a mainstay of classical British theater. Throughout the 1960s and 1970s, he built an extensive television career in the United Kingdom, appearing in landmark programs like Doctor Who, The Avengers, and Space: 1999, usually specializing in authoritative, stern, or subtly sinister figures. In 1981, Glover was cast in the James Bond series for For Your Eyes Only, taking on the role of Aristotle Kristatos, the main villain of the film. Kristatos initially presents himself to 007 as a helpful, respectable Greek businessman while framing his rival Milos Columbo, but he is eventually revealed to be a ruthless double agent attempting to sell the British ATAC missile encryption device to the KGB. Glover brought an icy, refined menace to the role, clashing directly with Roger Moore''s Bond during a climactic standoff at a mountaintop monastery. For Your Eyes Only stands as Glover''s single performance in the James Bond film series. In addition to his turn in the 007 franchise, Glover achieved rare pop-culture distinction by portraying memorable antagonists in several of cinema''s largest properties. He played Imperial General Veers in Star Wars: Episode V - The Empire Strikes Back (1980) and the power-hungry Nazi sympathizer Walter Donovan in Indiana Jones and the Last Crusade (1989). In later decades, he voiced the giant spider Aragog in Harry Potter and the Chamber of Secrets (2002) and gained a new generation of fans playing Grand Maester Pycelle across six seasons of HBO''s Game of Thrones. Appointed a Commander of the Order of the British Empire for his services to drama, Glover remains one of the most respected and recognizable character actors in British entertainment history.',
       'British',
       '1935-03-27',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Cassandra Harris (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('5a6b7c8d-9e0f-1a2b-3c4d-5e6f7a8b9c0d'),
       'Cassandra Harris',
       'Countess Lisl von Schlaf',
       'Cassandra Harris was born Sandra Colleen Waites in Sydney, Australia, in 1948. She studied acting at the National Institute of Dramatic Art before moving to London in the late 1960s to launch her acting career. She established herself on the British stage and television screen throughout the 1970s, appearing in iconic series such as Space: 1999 and The Sweeny, while also taking on film roles like the action thriller The Rough Cut (1980). In 1981, Harris secured her most famous cinematic role in the James Bond film For Your Eyes Only, playing the Countess Lisl von Schlaf. Her character is a sophisticated Austrian mistress to the smuggler Milos Columbo who shares a brief, romantic connection with Roger Moore''s James Bond before being tragically killed on a beach by the henchman Emile Leopold Locque. During the production of the film, she was accompanied on set by her husband, Pierce Brosnan, who would famously go on to portray James Bond himself fourteen years later in GoldenEye (1995). For Your Eyes Only stands as her sole appearance in the official James Bond film franchise. Following her role as Countess Lisl, Harris continued to work in television, including guest appearances alongside her husband in Remington Steele. Tragically, her career and life were cut short when she was diagnosed with ovarian cancer in the late 1980s. She passed away in Los Angeles in December 1991 at the age of forty-three, leaving behind a lasting legacy among Bond aficionados and cinema audiences alike.',
       'Australian',
       '1948-12-15',
       '1991-12-28',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jill Bennett (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6b7c8d9e-0f1a-2b3c-4d5e-6f7a8b9c0d1e'),
       'Jill Bennett',
       'Jacoba Brink',
       'Jill Bennett was born Nora Grace Bennett in Penang, British Malaya, in 1931. She spent her early years in Asia before relocating to England, where she trained at the Royal Academy of Dramatic Art. She made her professional stage debut in the late 1940s and quickly earned critical acclaim for her work with the Royal Shakespeare Company and the Royal Court Theatre. Known for her distinctive raspy voice, sharp intelligence, and emotionally intense performances, Bennett became a prominent figure in the post-war British theatrical scene, collaborating closely with groundbreaking playwrights such as Samuel Beckett and John Osborne, to whom she was married from 1968 to 1977. In 1981, Bennett took on a supporting role in the James Bond series for For Your Eyes Only, playing Jacoba Brink. Her character is the stern, fiercely protective figure skating instructor and chaperone to the young, spoiled Olympic hopeful Bibi Dahl. Throughout the film, Brink attempts to keep her wild protege focused on her training while navigating the influence of wealthy benefactor Aristotle Kristatos and dodging the charms of Roger Moore''s 007. For Your Eyes Only stands as Bennett''s single performance in the James Bond film series. Alongside her stage achievements, Bennett cultivated an extensive career in British film and television, earning a BAFTA nomination for her role in Inadmissible Evidence (1968) and appearing in films such as The Nanny (1965), Julius Caesar (1970), and The Sheltering Sky (1990). Her career spanned over four decades, during which she was widely regarded as one of the fine character actresses of her generation. She suffered from severe bouts of depression later in life and passed away in London in October 1990 at the age of fifty-nine.',
       'British',
       '1931-12-24',
       '1990-10-04',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Michael Gothard (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7c8d9e0f-1a2b-3c4d-5e6f-7a8b9c0d1e2f'),
       'Michael Gothard',
       'Emile Leopold Locque',
       'Michael Gothard was born in London in 1939 and spent his childhood moving between various homes in England and Wales. After travelling extensively across Europe as a young man, he returned to London to pursue acting and trained at the City Literary Institute and the New Arts Theatre Workshop. His striking, angular facial features and intense screen presence quickly made him a sought-after talent for dark, eccentric, or menacing character roles in late 1960s and 1970s cinema, including prominent appearances in The Devils (1971) and The Three Musketeers (1973). In 1981, Gothard featured in the James Bond series for For Your Eyes Only, taking on the role of Emile Leopold Locque. His character is an icy, silent Belgian assassin and enforcer working for Aristotle Kristatos who wears distinctive hexagonal-framed glasses and leaves a porcelain dove at the scene of his murders. Locque''s relentless pursuit of 007 culminates in one of the most famously cold-blooded moments in the franchise, where Roger Moore''s Bond kicks Locque''s teetering car off a cliff to his death. For Your Eyes Only stands as Gothard''s single performance in the James Bond film series. Throughout his career, Gothard maintained a steady presence in British film and television, featuring in classic programs like Arthur of the Britons, The Professionals, and Minder. Despite his consistent acting work, he struggled with severe lifelong depression during his adult years. Gothard died by suicide at his home in Hampstead, London, in December 1992 at the age of fifty-three, leaving behind a memorable legacy as one of cult cinema''s most striking villainous actors.',
       'British',
       '1939-06-24',
       '1992-12-02',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Wyman (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('8d9e0f1a-2b3c-4d5e-6f7a-8b9c0d1e2f3a'),
       'John Wyman',
       'Erich Kriegler',
       'John Wyman was born in London, England, and began his performance career in British theatre during the late 1960s and 1970s. Blessed with a tall, muscular physique, sharp features, and intense blue eyes, he naturally gravitated toward roles that capitalized on his formidable physical presence. He quickly established himself as a reliable character actor on British television, appearing in popular series of the era such as The Tomorrow People, Doomwatch, and Blake''s 7, often portraying imposing authority figures, military officers, or intimidating henchmen. In 1981, Wyman secured his most famous film role when he was cast in the James Bond entry For Your Eyes Only as Erich Kriegler. His character is a towering East German Olympic biathlete who operates as a ruthless henchman and secret operative for the villainous Aristotle Kristatos. Kriegler serves as a physical match for Roger Moore''s 007, engaging Bond in a tense ski chase through the Italian Alps and a brutal hand-to-hand fight at the climax of the film before being thrown off a mountain cliff. For Your Eyes Only stands as Wyman''s single performance in the James Bond film series. Following his memorable turn in the Bond franchise, Wyman continued to work in international film and television productions throughout the 1980s and 1990s. He made guest appearances in classic shows such as Hart to Hart and Tales of the Unexpected, while also featuring in action films like Tough Guys Don''t Dance (1987) and Fire, Ice and Dynamite (1990). In his later career, Wyman shifted his primary focus away from screen acting toward theatrical directing, voice acting, and managing creative performance projects in Europe.',
       'British',
       '1944-07-20',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jack Hedley (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9e0f1a2b-3c4d-5e6f-7a8b-9c0d1e2f3a4b'),
       'Jack Hedley',
       'Sir Timothy Havelock',
       'Jack Hedley was born Jack Hawkins in London, England, in 1929. After serving in the Royal Marines during World War II, he pursued a career in acting, adopting the stage name Hedley to avoid confusion with the famous British screen actor of the same original name. Throughout the 1950s and 1960s, he established a strong presence on British television and stage, becoming a familiar face to television audiences through starring roles in popular series such as The World of Tim Frazer and The Colditz Story, where his calm, authoritative demeanor made him an ideal fit for military officers, detectives, and steadfast gentlemen. In 1981, Hedley joined the James Bond series for For Your Eyes Only, taking on the role of Sir Timothy Havelock. His character is a distinguished British marine archaeologist secretly hired by the British government to locate the sunken ATAC missile communication device. Havelock''s tragic assassination alongside his wife aboard their research vessel, witnessed by their daughter Melina, sets the revenge-driven plot of the film in motion and propels 007 into his mission. For Your Eyes Only stands as Hedley''s single performance in the James Bond film series. Following his turn in the Bond franchise, Hedley continued to enjoy a prolific career across British, Italian, and international screen productions. He gained particular recognition in Italy for his starring role in Lucio Fulci''s cult horror film The New York Ripper (1982), while also making notable appearances in classic British miniseries like ''Allo ''Allo! and Dalgliesh. Hedley maintained a steady acting career well into the 1990s before retiring from the screen, eventually passing away in December 2021 at the age of ninety-two.',
       'British',
       '1929-10-28',
       '2021-12-11',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  James Villiers (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0f1a2b3c-4d5e-6f7a-8b9c-0d1e2f3a4b5c'),
       'James Villiers',
       'MI6 Chief of Staff Bill Tanner',
       'James Villiers was born in London, England, in 1933, into an aristocratic lineage connected to the Earls of Clarendon. Educated at Wellington College and trained at the Royal Academy of Dramatic Art, he possessed a distinctive, resonant voice and an unmistakably upper-class demeanor. His refined delivery made him a natural choice to portray eccentric aristocrats, haughty military officers, and entrenched establishment figures across a prolific career that spanned theatre, television, and film. Throughout the 1960s and 1970s, he built a solid reputation in British cinema with notable appearances in films such as Repulsion (1965), The Smashing Bird I Used to Have (1969), and Asylum (1972). In 1981, Villiers joined the James Bond ensemble in For Your Eyes Only as Bill Tanner, the Chief of Staff to M. Following the death of actor Bernard Lee, who had played M since the franchise''s inception, the producers chose not to recast the head of MI6 for the film out of respect, instead having Tanner and the Minister of Defence deliver the mission briefing to Roger Moore''s 007. Villiers brought a dry, bureaucratic authority to the role, briefing Bond on the loss of the ATAC system and overseeing the logistical intelligence efforts from London. For Your Eyes Only stands as Villiers'' sole performance in the James Bond film series. After his role in the Bond franchise, Villiers remained a staple of British performing arts, appearing in films like Under the Volcano (1984) and King Ralph (1991), alongside numerous classic British television series including Doctor Who, The Upper Hand, and Inspector Morse. He also enjoyed a long, respected career on the West End stage, frequently working with prestigious theater companies until his passing in February 1998 at the age of sixty-four.',
       'British',
       '1933-09-29',
       '1998-01-18',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Moreno (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('fb113908-f5ca-45d8-9839-0e5e73335666'),
       'John Moreno',
       'Luigi Ferrara',
       'John Moreno was born in France in March 1939 to parents in the entertainment industry. Raised in a touring environment, he developed performance skills early in life, later completing military service in the French army before formally training at drama school in England. During the 1960s and 1970s, Moreno built a versatile career on the British stage as a founding member of the Actors Company and touring internationally with the London Shakespeare Group, while simultaneously appearing in screen productions such as Lost Command (1966) and Moonbase 3. In 1981, Moreno featured in the James Bond entry For Your Eyes Only as Luigi Ferrara, MI6''s contact in Cortina, Italy. Ferrara assists Roger Moore''s 007 by introducing him to local informants before being murdered in his car by the villainous Emile Leopold Locque. Ferrara''s death fuels Bond''s personal vengeance, leading directly to the iconic cliffside confrontation with Locque. For Your Eyes Only stands as Moreno''s single performance in the James Bond film series. Following his role in the Bond franchise, Moreno remained active across television, film, and theatre. His notable screen credits include roles in the television serials Kessler (1981), The Talisman (1980–1981), and the popular British sitcom Only Fools and Horses. In addition to his screen and stage performances, Moreno expanded his career into voice work, fight direction, and public speaking coaching.',
       'British',
       '1939-03-04',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Charles Dance (For your eyes only)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b2c3d4e5-f6a7-8b9c-0d1e-1f2a3b4c5d6e'),
       'Charles Dance',
       'Claus',
       'Charles Dance was born Walter Charles Dance in Redditch, Worcestershire, England, in 1946. Raised primarily by his mother after the early death of his father, he studied graphic design and photography before shifting his focus to acting in his mid-twenties. He joined the Royal Shakespeare Company in the mid-1970s, honing his craft on stage through classical roles that showcased his commanding vocal presence, sharp features, and imposing physical posture. By the late 1970s, he was beginning to transition toward screen work, making his professional television debut in 1974. In 1981, Dance made his feature film debut in the James Bond entry For Your Eyes Only playing Claus, a silent henchman aligned with the villainous Erich Kriegler and Aristotle Kristatos. His character serves as a menacing presence throughout the Italian Alps sequences, pursuing Roger Moore''s 007 during the ski chase and ice rink encounters before being killed with a thrown trident. For Your Eyes Only stands as Dance''s single performance in the James Bond film series. Following his big-screen debut in the Bond franchise, Dance quickly rose to international stardom, gaining widespread acclaim for his lead role in the landmark British television serial The Jewel in the Crown (1984). Over the subsequent decades, he built an extraordinary film and television career, starring in major Hollywood productions such as The Golden Child (1986), Alien 3 (1992), and Last Action Hero (1993), as well as acclaimed dramas like Gosford Park (2001) and The Imitation Game (2014). He achieved massive global recognition in the 2010s for his portrayal of the cold, calculating patriarch Tywin Lannister in HBO''s Game of Thrones, establishing himself as one of Britain''s most respected and recognizable screen actors.',
       'British',
       '1946-10-10',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Maud Adams (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('4c539789-9dd8-40fa-bd30-35154f502e16'),
       'Maud Adams',
       'Octopussy',
       'Maud Adams, born Maud Solveig Christina Wikström on February 12, 1945, in Luleå, Sweden, is a Swedish actress and former top fashion model who holds a unique distinction in cinematic history. Discovered by a photographer in a shop, she embarked on a highly successful international modeling career that led her to Paris and New York, where she worked with top agencies and graced the covers of major fashion magazines. Her striking elegance and fluent multilingual abilities eased her transition into acting during the early 1970s. In 1974, Adams achieved major film prominence when she was cast as Andrea Anders in The Man with the Golden Gun. Playing the doomed, mistreated mistress of assassin Francisco Scaramanga, Adams infused the character with a poignant blend of vulnerability and quiet desperation. Her character secretly mails golden bullets to British intelligence in a bid to set 007 against Scaramanga, making her essential to driving the film''s plot before meeting a tragic fate. Adams went on to earn a rare status within the James Bond franchise by making multiple appearances across different roles in the Roger Moore era. Beyond 007, she starred in cult films like Rollerball (1975) and Tattoo (1981), along with television appearances on hit shows such as Hawaii Five-O, Kojak, and Magnum, P.I. She later expanded her career into cosmetics and business ventures, remaining an enduring and elegant fan favorite at international cinema conventions.',
       'Swedish',
       '1945-02-12',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Louis Jourdan (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1f2a3b4c-5d6e-7f8a-9b0c-1d2e3f4a5b6c'),
       'Louis Jourdan',
       'Prince Kamal Khan',
       'Louis Jourdan was born Louis Robert Gendre in Marseille, France, in June 1921. Educated in France, Turkey, and England, he studied acting at the École Dramatique under René Simon before making his French screen debut in the late 1930s. During World War II, following the German occupation of France, Jourdan refused to participate in Nazi propaganda films and instead joined the French Resistance, using his position to print and distribute underground newspapers. After the war, he was scouted by Hollywood producer David O. Selznick, making his American film debut in Alfred Hitchcock''s The Paradine Case (1947). He quickly established himself as Hollywood''s quintessential suave French leading man, earning critical acclaim and a Golden Globe nomination for his starring role in the Academy Award-winning musical Gigi (1958). In 1983, Jourdan starred as the primary antagonist Prince Kamal Khan in the James Bond entry Octopussy. Portraying an exiled Afghan prince who conspires with a rogue Soviet general to detonate a nuclear warhead at an American airbase in West Germany, Jourdan brought a refined, aristocratic charm to the villainous role opposite Roger Moore''s 007. His memorable performance included tense encounters over high-stakes backgammon and an aerial climax involving a flying aircraft. Octopussy stands as Jourdan''s single performance in the James Bond film series. Following his turn in the Bond franchise, Jourdan continued to work selectively in film and television, appearing in Swamp Thing (1982) and its 1989 sequel, as well as the action thriller Year of the Comet (1992), which marked his final feature film before retiring from acting. For his contributions to cinema and his wartime service in the Resistance, he was appointed an Officer of the Legion of Honour in 2010. Jourdan passed away at his home in Beverly Hills, California, in February 2015 at the age of ninety-three.',
       'French',
       '1921-06-19',
       '2015-02-14',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Kristina Wayborn (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2a3b4c5d-6e7f-8a9b-0c1d-2e3f4a5b6c7d'),
       'Kristina Wayborn',
       'Magda',
       'Kristina Wayborn was born Britt-Inger Johansson in Nybro, Sweden, in September 1950. She rose to national prominence after winning the Miss Sweden title in 1970 and subsequently competing as a semi-finalist in the Miss Universe pageant that same year. Following her success in beauty pageants and modeling, she pursued an acting career in both the United Kingdom and the United States. Her breakthrough television performance came when she portrayed iconic screen legend Greta Garbo in the television film The Silent Lovers (1980), a role that brought her to the attention of the producers of the James Bond franchise. In 1983, Wayborn starred in the James Bond feature Octopussy as Magda, a glamorous and acrobatic member of Octopussy''s circus group and trusted ally to both Octopussy and the villainous Prince Kamal Khan. Her memorable role combined elegance with action, featuring a notable scene in which she seduced Roger Moore''s 007 to retrieve a Fabergé egg, as well as a martial arts sequence fighting off Kamal Khan''s guards at the film''s climax. Octopussy stands as Wayborn''s single performance in the James Bond film series. Following her appearance in the Bond franchise, Wayborn remained active in television and film throughout the 1980s and 1990s. She made guest appearances on popular American series such as The Love Boat, Airwolf, MacGyver, Dallas, General Hospital, and Baywatch. She also appeared in an episode of That ''70s Show alongside her Octopussy co-star Maud Adams and other Bond alumni.',
       'Swedish',
       '1950-09-24',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Kabir Bedi (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3b4c5d6e-7f8a-9b0c-1d2e-3f4a5b6c7d8e'),
       'Kabir Bedi',
       'Gobinda',
       'Kabir Bedi was born in Lahore, Punjab, British India, in January 1946. Raised in a distinguished family with a Punjabi Sikh father and a British mother who was a ordained Buddhist nun, he grew up in Delhi and earned a degree in history from St. Stephen''s College. Starting his career in Indian advertising and theater, he quickly transitioned to Hindi cinema, making his screen debut in the early 1970s. Bedi achieved widespread acclaim across Europe after starring as the titular pirate hero in the hit Italian television miniseries Sandokan (1976), which launched his career as a prominent international actor across Bollywood, Hollywood, and European film markets. In 1983, Bedi featured in the James Bond entry Octopussy as Gobinda, the towering and intensely loyal chief henchman to the villainous Prince Kamal Khan. Serving as a physical threat throughout the film, Gobinda engages Roger Moore''s 007 in several high-stakes confrontations, including a tense jungle hunt and an aerial duel atop an in-flight aircraft, where he ultimately falls to his death. Octopussy stands as Bedi''s single performance in the James Bond film series. Following his performance in the Bond franchise, Bedi maintained a prolific international career across four decades. He became a familiar face on American television with recurring and guest roles in popular series such as The Bold and the Beautiful, Dynasty, Knight Rider, Highlander, and Murder, She Wrote. In addition to his screen work, Bedi has remained a prominent figure in global cinema, continuing to star in major Bollywood productions, host news and cultural television programs, perform in international theater, and serve as an official ambassador for various international charitable organizations.',
       'Indian',
       '1946-01-16',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Steven Berkoff (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('4c5d6e7f-8a9b-0c1d-2e3f-4a5b6c7d8e9f'),
       'Steven Berkoff',
       'General Orlov',
       'Steven Berkoff was born Leslie Steven Berkoff in Stepney, London, in August 1937. Raised in the East End, he studied drama and mime at L''École Internationale de Théâtre Jacques Lecoq in Paris and trained at the Webber Douglas Academy of Dramatic Art. He began his professional career on the stage before founding the London Theatre Group, where he became renowned as an accomplished playwright, theatre director, and practitioner of physical theatre. Berkoff established a formidable screen presence during the 1970s, making early film appearances in Stanley Kubrick''s A Clockwork Orange (1971) and Barry Lyndon (1975). In 1983, Berkoff featured in the James Bond entry Octopussy as General Orlov, a fanatical and renegade Soviet officer who conspires with Prince Kamal Khan to detonate a nuclear bomb on a United States Air Force base in West Germany. Berkoff brought an intensely animated, theatrical intensity to the role, delivering memorable monologues advocating for Soviet military expansion before his character was gunned down by East German border guards. Octopussy stands as Berkoff''s single performance in the James Bond film series. Following his role in the Bond franchise, Berkoff solidified a career as one of international cinema''s premier villain actors. He went on to star as the antagonist Victor Maitland in Beverly Hills Cop (1984) and Lieutenant Colonel Podovsky in Rambo: First Blood Part II (1985), while continuing to appear in films like Revolution (1985), Absolute Beginners (1986), and David Fincher''s The Girl with the Dragon Tattoo (2011). Alongside his extensive film work, Berkoff maintained a prolific output in the theatre, publishing plays, directing international stage productions, and writing several volumes of autobiography.',
       'British',
       '1937-08-03',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  David Meyer (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('5d6e7f8a-9b0c-1d2e-3f4a-5b6c7d8e9f0a'),
       'David Meyer',
       'Mischka (Twin One)',
       'David Meyer was born in Watford, Hertfordshire, England, in July 1947. Early in his career, he developed a strong background in classical theatre, performing with the Royal Shakespeare Company in productions such as A Midsummer Night''s Dream. Throughout his screen career, Meyer often performed alongside his identical twin brother, Anthony Meyer, with the pair frequently leveraging their uncanny physical synergy in avant-garde and art-house cinema, including an experimental 1976 film adaptation of Hamlet and Peter Greenaway''s The Draughtsman''s Contract (1982). In 1983, Meyer featured in the James Bond film Octopussy as Mischka, credited on screen as "Twin One". Playing an expert knife-throwing circus performer and assassin working alongside his brother Grischka (played by Anthony Meyer), his character serves as a menacing henchman in Prince Kamal Khan''s operation. Mischka participates in several key set pieces, including the assassination of 009 in East Berlin and a tense pursuit aboard a moving train, where James Bond ultimately crushes him beneath a heavy luggage cart. Octopussy stands as Meyer''s single performance in the James Bond film series. Following his role in the Bond franchise, Meyer maintained a steady career across British stage, film, and television. He continued to work extensively in classical theatre, particularly with Shakespeare''s Globe in London, while appearing in films such as War Requiem (1989) and Bent (1997), as well as popular television series like Inspector Morse and The Bill.',
       'British',
       '1947-07-24',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Tony Meyer (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6e7f8a9b-0c1d-2e3f-4a5b-6c7d8e9f0a1b'),
       'Anthony Meyer',
       'Grischka (Twin Two)',
       'Anthony Meyer, known professionally as Tony Meyer, was born in Watford, Hertfordshire, England, in July 1947. Alongside his identical twin brother, David Meyer, he pursued classical theatre training and worked with prominent British institutions, including the Royal Shakespeare Company. Early in his screen career, the brothers frequently collaborated on film projects that drew upon their striking resemblance and shared physical precision, notably appearing in the experimental 1976 film adaptation of Hamlet and Peter Greenaway''s acclaimed period drama The Draughtsman''s Contract (1982). In 1983, Meyer featured in the James Bond film Octopussy as Grischka, credited on screen as "Twin Two". As a deadly knife-throwing performer in Octopussy''s traveling circus, Grischka operates as a ruthless assassin under the command of Prince Kamal Khan alongside his brother Mischka. Grischka participates in several crucial sequences, including the opening pursuit that leads to the death of agent 009 in East Berlin and a high-stakes duel aboard a moving train, where James Bond ultimately slays him with a throwing knife to avenge 009. Octopussy stands as Meyer''s single performance in the James Bond film series. Following his performance in the Bond franchise, Meyer continued to perform across British theatre, film, and television. He remained active in classical stage productions and appeared in various screen projects throughout the late twentieth century, including the feature film War Requiem (1989), maintaining a career closely tied to the British theatrical tradition alongside his regular artistic collaborations with his twin brother.',
       'British',
       '1947-07-24',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Michaela Clavell (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7f8a9b0c-1d2e-3f4a-5b6c-7d8e9f0a1b2c'),
       'Michaela Clavell',
       'Penelope Smallbone',
       'Michaela Clavell was born in England into a family with deep ties to the entertainment and literary worlds. She is the daughter of the celebrated novelist, screenwriter, and film director James Clavell, best known for his Asian Saga novels such as Shōgun and Tai-Pan. Growing up in an environment centered around high-profile creative projects, Clavell pursued a career in the dramatic arts, training as an actress and securing early professional roles in British television and film productions during the early 1980s. In 1983, Clavell featured in the James Bond entry Octopussy as Penelope Smallbone, the efficient and charming assistant to Moneypenny at MI6 headquarters. Introduced in a playful scene alongside Roger Moore''s 007 and Lois Maxwell''s Moneypenny, her character was originally envisioned as a potential successor or dynamic addition to the secretarial office at MI6, receiving a traditional double entendre welcome from Bond as she presents him with his travel documents. Octopussy stands as Clavell''s single performance in the James Bond film series. Following her appearance in the Bond franchise, Clavell continued to act in selected screen and stage projects, including a role in the 1986 film adaptation of her father''s novel Tai-Pan. In subsequent years, she shifted her professional focus away from full-time acting toward managing and preserving her late father''s literary and cinematic legacy, overseeing the adaptation and rights management of his extensive catalog of works for new generations of international audiences.',
       'British',
       null,
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Vijay Amritraj (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('8a9b0c1d-2e3f-4a5b-6c7d-8e9f0a1b2c3d'),
       'Vijay Amritraj',
       'Vijay',
       'Vijay Amritraj was born in Chennai, India, in December 1953. He rose to international prominence not on the screen, but on the tennis court, becoming one of Asia''s most successful professional athletes during the 1970s and 1980s. Alongside his brothers Anand and Ashok, he helped put Indian tennis on the global map, driving India to two Davis Cup finals and reaching the quarterfinals at both Wimbledon and the US Open multiple times. His charismatic personality and effortless poise made him a natural sports celebrity, smoothly paving the way for a transition into media, broadcasting, and acting. In 1983, Amritraj featured in the James Bond entry Octopussy as Vijay, an MI6 ally based in India who assists Roger Moore''s 007. Playing a fictionalized version of himself operating as a secret agent under the cover of a local auto-rickshaw driver and snake charmer, Amritraj brought warmth, humor, and physical agility to the role. He participates in a memorable chase through the streets of Udaipur armed with a modified tennis racket before meeting a tragic fate at the hands of Prince Kamal Khan''s assassins. Octopussy stands as Amritraj''s single performance in the James Bond film series. Following his performance in the Bond franchise, Amritraj pursued selected screen roles, including an appearance in Star Trek IV: The Voyage Home (1986) and a starring turn in the American television comedy series The Yakov Smirnoff Show. However, he devoted the majority of his post-athletic career to sports broadcasting, becoming the lead tennis commentator for major networks across Asia and North America. Beyond media, Amritraj was named a United Nations Messenger of Peace, established the Vijay Amritraj Foundation to support vulnerable communities in India, and served as President of the Tamil Nadu Tennis Association.',
       'Indian',
       '1953-12-14',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Albert Moses (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9b0c1d2e-3f4a-5b6c-7d8e-9f0a1b2c3d4e'),
       'Albert Moses',
       'Sadruddin',
       'Albert Moses was born in Gampola, Ceylon (now Sri Lanka), in August 1937. He began his performance career in the 1960s, initially working in the Indian film industry in Bombay and taking on roles in local television productions before relocating to Africa and eventually settling in the United Kingdom during the 1970s. To hone his trade in Britain, he studied drama and film production, quickly establishing himself as a reliable character actor and stunt performer. His distinct voice and natural comedic timing made him a frequent face across classic British television series, most notably as Ranjeet Singh in the hugely popular sitcom Mind Your Language. In 1983, Moses featured in the James Bond entry Octopussy as Sadruddin, the head of the MI6 station in Udaipur, India. Operating under the guise of a local hotel manager, Sadruddin acts as 007''s primary local contact, welcoming Roger Moore''s James Bond to India, briefing him on local threats, and coordinating logistics with fellow field agent Vijay. While Octopussy represents his major featured role in the franchise, Moses had previously made an uncredited appearance six years earlier in The Spy Who Loved Me (1977) as a Cairo barman who serves Bond and Anya Amasova. Following his work in the Bond franchise, Moses maintained a steady career across British television and film, appearing in high-profile productions such as The Jewel in the Crown, An American Werewolf in London, and The Little Drummer Girl. In addition to his screen acting, he was an accomplished playwright and author, publishing books of poetry and children''s stories, as well as serving on the board of governors for the actors'' union Equity. Moses passed away in September 2017 at his home in London at the age of eighty.',
       'Sri Lankan-British',
       '1937-12-19',
       '2017-09-15',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Douglas Wilmer (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0c1d2e3f-4a5b-6c7d-8e9f-0a1b2c3d4e5f'),
       'Douglas Wilmer',
       'Jim Fanning (Art Expert)',
       'Douglas Wilmer was born in Brentford, Middlesex, England, in January 1920. He developed a passion for the stage early in life and trained at the Royal Academy of Dramatic Art before his studies were interrupted by service in the Royal Artillery during World War II. Returning to acting after the war, Wilmer built an impressive stage career with the Royal Shakespeare Company and the Old Vic, earning a reputation for his authoritative screen presence, distinctive baritone voice, and sharp, analytical features. He achieved enduring international fame in 1965 when he portrayed Arthur Conan Doyle''s legendary sleuth in the BBC series Sherlock Holmes, a definitive performance that set the benchmark for future adaptations. In 1983, Wilmer featured in the James Bond entry Octopussy as Jim Fanning, an expert antiquarian and representative of Sotheby''s auction house. Accompanying Roger Moore''s 007 to an exclusive London auction, Fanning assists Bond in identifying a forged Fabergé egg and monitoring the bidding war driven by the villainous exiled Afghan prince, Kamal Khan. Wilmer brought a refined, scholarly dignity to the sequence, anchoring the high-stakes art sale with understated gravitas. Octopussy stands as Wilmer''s single performance in the James Bond film series. Following his performance in the Bond franchise, Wilmer continued to work steadily in film, television, and radio, while also writing memoirs and opening a wine bar in Suffolk. His late career was marked by warm tributes from mystery fans worldwide, culminating in a affectionate cameo appearance in the 2012 Sherlock episode "Reichenbach Fall" alongside Benedict Cumberbatch. Wilmer passed away in March 2016 at the age of ninety-six, leaving behind a distinguished legacy as one of Britain''s premier character actors.',
       'British',
       '1920-01-08',
       '2016-03-31',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Andy Bradford (Octopussy)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('19b02ba4-751d-41cf-8ca4-0a350cd609c1'),
       'Andy Bradford',
       'Agent 009',
       'Andy Bradford began his professional career in the British entertainment industry in the 1960s, initialing building his resume through supporting acting roles on film and television. His early credits featured appearances in classic productions such as Othello, The Family Way, and popular series like Z Cars. Due to his athletic abilities, he increasingly incorporated high-risk physical action into his roles, eventually transitioning into stunt work alongside his standard character acting. This dual expertise led to prominent involvement in major feature films, including Star Wars, The Eagle Has Landed, and Krull. In 1983, Bradford portrayed the ill-fated MI6 operative Agent 009 in the James Bond entry Octopussy. Featured in the film''s opening sequence, his character flees through East Berlin dressed as a circus clown while being relentlessly pursued by the knife-throwing assassins Mischka and Grischka. Though fatally wounded, 009 manages to reach the British Ambassador''s residence and collapse inside with a fake Fabergé egg, kicking off the core mystery that James Bond investigates throughout the rest of the film. Prior to this onscreen acting role, Bradford performed stunt work for the series in For Your Eyes Only (1981). Beyond his work in the James Bond series, Bradford established a long-running career in the film industry as both an actor and a prolific stunt performer. His extensive stunt credits include blockbusters such as Flash Gordon, Indiana Jones and the Last Crusade, Who Framed Roger Rabbit, and Patriot Games. Through dozens of screen roles across television and cinema, he remained a respected presence within the British stunt and acting community.',
       'British',
       '1944-09-07',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Robert Brown (Octopussy, A View To a Kill, The living daylights, License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d8046dca-f263-48b4-bb74-7806ee35685c'),
       'Robert Brown',
       'M.',
       'Robert Brown was born in Swanage, Dorset, England, in July 1921. He began his professional acting career in British theater and cinema during the late 1940s, making an early film appearance in Carol Reed’s classic noir thriller The Third Man (1949). Over the following decades, Brown built a prolific career as a dependable character actor, distinguished by his robust build, stern features, and commanding vocal delivery. His extensive screen work included supporting roles in landmark productions such as Ben-Hur (1959), Sink the Bismarck! (1960), Billy Budd (1962), and One Million Years B.C. (1966), alongside numerous guest appearances on television. In 1983, Brown officially took over the role of M, head of the Secret Intelligence Service (MI6), in the James Bond entry Octopussy. Following the passing of Bernard Lee—who had portrayed M in the previous eleven films—the production team chose Brown to step into the iconic role. Bringing a slightly more gruff, no-nonsense authority to the briefing room, Brown’s M holds Roger Moore’s 007 to strict professional standards during the investigation into the forged Fabergé egg and Soviet nuclear plot. Brown had previously debuted in the series six years earlier in The Spy Who Loved Me (1977) playing Vice Admiral Hargreaves, leading many fans and franchise scholars to speculate that Hargreaves was promoted to succeed Lee’s character as M. Following his debut as M in Octopussy, Brown remained a central figure in the franchise throughout the remainder of the 1980s. He reprised the role opposite Roger Moore in A View to a Kill (1985) and continued as M through Timothy Dalton''s tenure in The Living Daylights (1987) and Licence to Kill (1989). In Licence to Kill, Brown was given a particularly memorable narrative thread as he personally revokes Bond''s license to kill in Key West when 007 chooses personal revenge over MI6 orders. Brown retired from acting in the 1990s and passed away in November 2003 at the age of eighty-two.',
       'British',
       '1921-07-23',
       '2003-11-11',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Christopher Walken (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('341b928f-e96c-42e8-863a-9edde5e3f5e1'),
       'Christopher Walken',
       'Max Zorin',
       'Christopher Walken was born Ronald Walken in Astoria, Queens, New York, in March 1943. Trained as a dancer at the Professional Children''s School in Manhattan, he began his career as a child actor in television and theater before transitioning to feature films in the late 1960s. Known for his intense screen presence, idiosyncratic speech cadence, and versatility across genres, Walken achieved widespread critical acclaim for his performance in Michael Cimino''s The Deer Hunter (1978), earning the Academy Award for Best Supporting Actor. Throughout his career, he established himself as one of American cinema''s most compelling character actors, starring in iconic films such as Annie Hall, The Dogs of War, Pennies from Heaven, Pulp Fiction, and Catch Me If You Can. Although associated with the peak of the 1980s Roger Moore era, Walken did not appear in Octopussy (1983). Instead, he made his single entry into the James Bond franchise two years later in A View to a Kill (1985), portraying the central antagonist Max Zorin. As Zorin—a psychopathic, genetically engineered industrialist plotting to destroy California''s Silicon Valley to monopolize the microchip market—Walken delivered a chillingly eccentric performance that served as one of the standout elements of Moore''s final outing as 007. Following his turn in the Bond franchise, Walken continued to build an extraordinarily eclectic filmography, seamlessly moving between prestige dramas, cult thrillers, and broad comedies. His work in films like At Close Range, King of New York, Batman Returns, True Romance, Seven Psychopaths, and Dune: Part Two solidified his reputation as a unique cultural icon. Over a career spanning six decades, Walken has received nominations for the Academy Award, BAFTA, and Tony Award, while remaining one of the most distinctive and recognizable talents in modern cinema.',
       'American',
       '1943-03-31',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Tanya Roberts (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('ed8ec557-825a-43c0-b247-36006d50cd48'),
       'Tanya Roberts',
       'Stacey Sutton',
       'Tanya Roberts was born Victoria Leigh Blum in the Bronx, New York, in September 1955. After working as a teenage model and studying at the Actors Studio, she made her screen debut in the 1975 horror film Forced Entry. Roberts built her early career through appearances in television commercials and off-Broadway theatrical productions before earning wider recognition in high-profile genre cinema during the late 1970s and early 1980s. Her break into mainstream television arrived when she was cast as Julie Rogers in the final season of the hit series Charlie''s Angels, establishing her as a prominent pop culture figure. Throughout the early 1980s, she continued to star in fantasy and adventure features, including The Beastmaster and the title role in Sheena. Although associated with the James Bond series, Roberts did not appear in Octopussy (1983). Instead, she made her sole franchise performance two years later in A View to a Kill (1985), portraying state geologist Stacey Sutton. Opposite Roger Moore''s 007 and Christopher Walken''s villainous Max Zorin, Roberts played a key ally whose family oil business was targeted for takeover by Zorin. Sutton teams up with Bond to uncover and thwart Zorin''s conspiracy to detonate explosives along the San Andreas Fault to submerge Silicon Valley. Following her involvement in the Bond series, Roberts appeared in numerous television films, thrillers, and guest spots throughout the late 1980s and 1990s. She experienced a major career revitalization in 1998 when she was cast as Midge Pinciotti, the delightfully eccentric mother of Donna Pinciotti, on the hit sitcom That ''70s Show. She remained a main cast member for several seasons before stepping back from acting in the early 2000s to care for her family. Roberts passed away in Los Angeles in January 2021 at the age of sixty-five.',
       'American',
       '1955-10-15',
       '2021-01-04',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Grace Jones (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('5e18ca56-b696-4e90-b16a-8939be186cc7'),
       'Grace Jones',
       'May Day',
       'Grace Jones was born Beverly Grace Jones in Spanish Town, Jamaica, in May 1948. Raised by her grandparents before moving to New York in her teens, she began working as a fashion model, quickly becoming a fixture in the Paris and New York fashion scenes for her striking, androgenous look and commanding presence. In the late 1970s, she launched a highly successful music career, becoming a disco and new wave icon with avant-garde albums such as Warm Leatherette and Nightclubbing. Her blend of bold visuals, distinctive vocal delivery, and theatrical stage performances established her as a major pop culture figure, eventually leading to mainstream acting opportunities. Although associated with the 1980s Roger Moore era, Jones did not appear in Octopussy (1983). Instead, she made her sole James Bond appearance two years later in A View to a Kill (1985), portraying the secondary antagonist and chief assassin May Day. Serving as the enforcer and lover of villain Max Zorin, May Day possesses formidable physical strength and executes several high-profile assassinations throughout the film. After Zorin betrays her by triggering a flood inside a mine with her trapped inside, May Day switches sides and sacrifices her life to help James Bond haul a nuclear explosive out of the mine, preventing the destruction of Silicon Valley. Following her memorable turn in the Bond franchise, Jones continued her career as an international music artist, model, and actress. Her filmography includes roles in fantasy and action productions such as Conan the Destroyer, Vamp, and Boomerang. Renowned for her unique visual aesthetic and ongoing influence across music and fashion, Jones remains a celebrated figure in global entertainment.',
       'Jamaican',
       '1948-05-19',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Patrick Macnee (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('850f0ee0-d550-4ae0-864a-e9b24483b3ba'),
       'Patrick Macnee',
       'Sir Godfrey Tibbett',
       'Patrick Macnee was born Daniel Patrick Macnee in Paddington, London, in February 1922. Educated at Eton College, he pursued acting at the Webber Douglas Academy of Dramatic Art before serving in the Royal Navy during the Second World War as a lieutenant on Motor Torpedo Boats. After the war, Macnee established himself across theater, film, and television in both the United Kingdom and Canada, earning early credits in classic feature films like Laurence Olivier''s Hamlet (1948) and Alastair Sim''s Scrooge (1951). His ultimate international breakthrough came in 1961 when he was cast as the impeccably tailored, bowler-hatted secret agent John Steed in the hit British television series The Avengers, a definitive spy-genre role he played throughout the 1960s and reprised in The New Avengers during the late 1970s. In 1985, Macnee joined the James Bond franchise for his sole appearance in A View to a Kill, playing MI6 ally Sir Godfrey Tibbett. A horse racing authority, Tibbett poses as James Bond''s chauffeur and valet to help 007 covertly infiltrate the French estate of villainous industrialist Max Zorin and investigate his suspicious thoroughbred breeding practices. Macnee brought a warm, humorous dynamic to his scenes alongside real-life close friend Roger Moore, making Tibbett a beloved ally until the character met a tragic end at the hands of Zorin''s lethal henchwoman, May Day. Following his performance in the Bond franchise, Macnee maintained a busy career as a character actor, television guest star, and voice artist. His post-Bond credits included roles in The Howling, This Is Spinal Tap, Transformers, and guest spots on popular series like Frasier and Murder, She Wrote. Widely respected for his gentlemanly charm and enduring contributions to screen espionage history, Macnee spent his later years in Southern California before passing away in Rancho Mirage in June 2015 at the age of ninety-three.',
       'British-American',
       '1922-02-06',
       '2015-06-25',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Patrick Bauchau (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('adabf2ab-a654-40ac-906f-195b579cd543'),
       'Patrick Bauchau',
       'Scarpine',
       'Patrick Bauchau was born in Brussels, Belgium, in December 1938. Raised in a sophisticated international household as the son of a Belgian writer and a Russian painter, he grew up fluent in multiple languages and attended the University of Oxford. Bauchau initially entered the film industry through the French New Wave, working as an executive and manager before making his screen debut in Éric Rohmer''s La Collectionneuse (1967). After taking a hiatus from acting to pursue artistic and commercial ventures, he returned to the screen in the early 1980s, quickly establishing himself as an internationally sought-after character actor known for his suave demeanor, cultured voice, and imposing screen presence. In 1985, Bauchau joined the James Bond franchise in A View to a Kill, playing Scarpine, the cold and calculating head of security for psychopathic industrialist Max Zorin. Throughout the film, Scarpine acts as Zorin''s primary enforcer, managing security at the French estate, overseeing brutal liquidations, and guarding Zorin''s blimp during the climax in San Francisco. Bauchau brought a quiet, sophisticated menace to the role, serving as a sinister right-hand man until Scarpine meets his end in the explosive destruction of Zorin''s airship against the Golden Gate Bridge. Following his appearance in the Bond series, Bauchau built an extensive and acclaimed career across European and American cinema and television. He became widely known to global television audiences for his starring role as Sydney in the cult mystery series The Pretender and as Dr. Rowan Chase in House. His notable film credits include roles in The Music Teacher, Clear and Present Danger, Panic Room, and 2012. Bauchau has remained active in the industry for over five decades, earning respect as a versatile multilingual performer across independent art-house cinema and major Hollywood productions.',
       'Belgian',
       '1938-12-06',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  David Yip (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3779ddc8-f6a3-495a-8455-9d1c5b5d4f5a'),
       'David Yip',
       'Chuck Lee',
       'David Yip was born in Liverpool, England, in June 1951, to a Chinese father and an English mother. He trained as an actor at the East 15 Acting School in Essex during the early 1970s, making his early professional appearances in British regional theater and television. Yip achieved a major career breakthrough in 1981 when he was cast as Detective Sergeant John Ho in the BBC series The Chinese Detective. His starring role marked a historic moment in British television history, as it was the first drama series on British television to feature a East Asian lead actor, earning Yip widespread recognition and acclaim. In 1985, Yip joined the James Bond franchise in A View to a Kill, playing CIA operative Chuck Lee. Stationed in San Francisco, Lee serves as James Bond''s primary American contact, supplying 007 with vital intelligence regarding the background and microchip operations of industrialist Max Zorin. Yip portrayed Lee as an efficient, professional ally who helps steer Bond toward Zorin''s conspiracy in Silicon Valley. Tragically, the character meets an abrupt demise when he is strangled in his car by Zorin''s deadly enforcer, May Day, before he can deliver key research to Bond. Beyond his performance in the Bond series, Yip built an extensive career spanning film, television, radio, and stage both in the United Kingdom and internationally. He made memorable appearances in major feature films such as Steven Spielberg''s Indiana Jones and the Temple of Doom (1984), where he played Wu Han, as well as Entrapment (1999). On television, he appeared in high-profile series like Casualty, Holby City, Doctor Who, and 24: Live Another Day. Alongside his screen work, Yip has remained a passionate advocate for East Asian representation in the arts and an active performer in British theater.',
       'British',
       '1951-06-04',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Fiona Fullerton (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('ac8c1e6a-e1c6-400e-8bf3-dab6b4370b87'),
       'Fiona Fullerton',
       'Pola Ivanova',
       'Fiona Fullerton was born in Kaduna, Nigeria, in October 1956. She began her formal training in performance at an early age, attending the Elmhurst Ballet School as a boarder. Making her screen acting debut at age twelve in the feature film Run Wild, Run Free (1969), she quickly established herself as a prominent young talent. She gained widespread international recognition shortly thereafter when she starred as Alice in the 1972 film adaptation Alice''s Adventures in Wonderland and played Anastasia Romanov in Nicholas and Alexandra (1971). Throughout the 1970s and early 1980s, Fullerton maintained an active career across British television, film, and West End theater, notably playing Guinevere in the musical Camelot alongside Richard Harris. In 1985, Fullerton appeared in the James Bond franchise in A View to a Kill, playing KGB operative Pola Ivanova. Sent to San Francisco to spy on industrialist Max Zorin, Ivanova crosses paths with James Bond while both attempt to gather intelligence on Zorin''s operations. Sharing a history and romantic past with 007, she shares a relaxed moment with him in a hot tub, during which she covertly steals an audio recording Bond had recovered. However, Bond anticipates her scheme and secretly swaps the cassette before she leaves, leaving her with a tape of classical music instead of the vital secret intel. Following her performance in the Bond franchise, Fullerton continued acting in prominent television series and films, including Shaka Zulu, The Charmer, and A Taste for Death. By the late 1990s, she transitioned away from full-time acting to build a successful career as a real estate entrepreneur and property investor. She later authored columns on real estate, appeared as a contestant on the BBC''s Strictly Come Dancing in 2013, and established herself as a businesswoman in the United Kingdom.',
       'British',
       '1956-10-10',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Manning Redwood (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('8b9c0d1e-2f3a-4b5c-6d7e-8f9a0b1c2d3e'),
       'Manning Redwood',
       'Bob Conley',
       'Manning Redwood was born in New York City in February 1929. He began his acting career on television, notably starring as J. Robert Oppenheimer in the BBC miniseries Oppenheimer. Due to his gravelly voice and authoritative physical presence, he became a sought-after character actor in both British and American screen productions, frequently cast as military officers, law enforcement officials, and stern authority figures. His early feature film credits included Stanley Kubrick''s The Shining (1980), Outland (1981), and the non-Eon James Bond entry Never Say Never Again (1983). In 1985, Redwood joined the official James Bond franchise in A View to a Kill, playing Bob Conley, the chief mining engineer for industrialist Max Zorin. Conley oversees Zorin''s oil pumping operations and mining preparations aimed at triggering a massive earthquake along the San Andreas Fault. Though corrupt, Conley draws the line when he realizes Zorin intends to detonate the mine early and slaughter the miners trapped inside. When Conley confronts Zorin over the senseless loss of life, Zorin''s head of security, Scarpine, knocks him unconscious, leaving him to perish as the mine is flooded. Following his appearance in A View to a Kill, Redwood maintained a busy career across film and television in the United Kingdom and the United States. His subsequent screen credits included film roles in Death Wish 3 (1985) and Water (1985), as well as appearances in popular television series such as Minder and Jeeves and Wooster. Redwood passed away in July 2006 at the age of seventy-seven.',
       'American',
       '1929-02-16',
       '2006-07-09',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Alison Doody (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9c0d1e2f-3a4b-5c6d-7e8f-9a0b1c2d3e4f'),
       'Alison Doody',
       'Jenny Flex',
       'Alison Doody was born in Dublin, Ireland. Raised in a creative family, she originally pursued modeling after being approached by a fashion photographer. Her commercial modeling work quickly caught the eye of casting directors, leading directly to her feature film acting debut while she was still a teenager. In 1985, Doody joined the James Bond franchise in A View to a Kill, playing Jenny Flex. Aged just eighteen during production, she holds the distinction of being the youngest actress ever cast as a Bond girl. Her character serves as an henchwoman and equestrian assistant to villainous industrialist Max Zorin at his estate in France. Clad in riding gear, Flex helps oversee Zorin''s stables, monitor guests, and maintain order, acting as part of Zorin''s loyal inner security circle alongside May Day. Following her debut in the Bond series, Doody''s career accelerated rapidly. She starred in prominent late-1980s films such as A Prayer for the Dying (1987) and Taffin (1988) opposite Pierce Brosnan. She achieved global stardom in 1989 when Steven Spielberg cast her as Dr. Elsa Schneider in Indiana Jones and the Last Crusade alongside Harrison Ford and Sean Connery. After stepping away from acting in the late 1990s to focus on family life, Doody later returned to screen performance with roles in television series like Beaver Falls and major international feature films including the Indian blockbuster RRR (2022).',
       'Irish',
       '1966-11-11',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Willoughby Gray (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0d1e2f3a-4b5c-6d7e-8f9a-0b1c2d3e4f5a'),
       'Willoughby Gray',
       'Dr. Carl Mortner',
       'John Willoughby Gray was born in London, England, in November 1916. Before establishing his long career on stage and screen, he served with distinction during the Second World War as an officer in the GHQ Liaison Regiment, receiving the Member of the Order of the British Empire (MBE) for his military service in Europe. Following the war, Gray built an extensive career in British theater and early television. He achieved widespread popularity in the 1950s with multiple television roles, including prominent appearances in The Adventures of Robin Hood. Over the following decades, he became a dependable character actor, featuring in films such as Laurence Olivier''s Richard III (1955), The Mummy (1959), and Waterloo (1970). In 1985, Gray joined the James Bond franchise in A View to a Kill, playing Dr. Carl Mortner. Mortner is revealed to be Hans Glaub, a former Nazi scientist who created psychopathic industrialist Max Zorin through medical experimentation. Serving as Zorin''s mentor and advisor, Mortner assists in Zorin''s equestrian doping schemes using microchip-operated steroid implants. During the film''s climax, Mortner attempts to destroy Bond using dynamite aboard Zorin''s airship, only to perish when the explosives detonate prematurely against the Golden Gate Bridge. Following his performance in the Bond series, Gray achieved further film recognition playing the kindly King in Rob Reiner''s beloved fantasy film The Princess Bride (1987). He also maintained a recurring role as banker Sir John Stevens in the BBC drama series Howards'' Way during the late 1980s. Gray passed away in Salisbury, Wiltshire, in February 1993 at the age of seventy-six.',
       'British',
       '1916-11-05',
       '1993-02-13',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jean Rougerie (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('fad2c782-71fd-4f05-bb33-cdc4fc19c968'),
       'Jean Rougerie',
       'Achille Aubergine',
       'Jean Rougerie was born in Neuilly-sur-Seine, France, in March 1929. Over a prolific career spanning several decades, he became a distinguished character actor in French cinema, television, and theater, well-regarded for his expressive performances and natural gravitas. Working alongside eminent European directors such as Louis Malle and Luis Buñuel, Rougerie appeared in acclaimed French features including Lacombe, Lucien (1974), The Phantom of Liberty (1974), Get Out Your Handkerchiefs (1978), and Buffet froid (1979). In 1985, Rougerie made his mark in international cinema when he joined the James Bond franchise in A View to a Kill, playing French private detective Achille Aubergine. Hired by the French Jockey Club to investigate industrialist Max Zorin''s suspicious thoroughbred horse racing victories, Aubergine meets James Bond at the Eiffel Tower''s Jules Verne restaurant to share critical intelligence regarding Zorin''s operations. During their elegant dinner, Aubergine brings sophisticated humor and vital exposition to the scene before meeting a sudden, tragic demise when Zorin''s lethal enforcer, May Day, assassinates him with a poisoned butterfly dart hidden inside a stage prop. Rougerie continued to work steadily in French film and television productions throughout the late 1980s and 1990s, accumulating dozens of credits across multiple genres. He remained an active performer up until his death in Ivry-sur-Seine, France, in January 1998 at the age of sixty-eight.',
       'French',
       '1929-03-09',
       '1998-01-25',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Daniel Benzali (A View To a Kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('c3d4e5f6-a7b8-9c0d-1e2f-2a3b4c5d6e7f'),
       'Daniel Benzali',
       'W.G. Howe',
       'Daniel Benzali was born in Rio de Janeiro, Brazil, in January 1950, to Jewish parents who later relocated the family to the United States. Raised in New York, he developed a passion for acting early in life and trained extensively for the stage, eventually moving to the United Kingdom where he spent several years working with prestigious theater companies, including the Royal Shakespeare Company. Known for his distinctive bald head, deep baritone voice, and imposing physical presence, Benzali quickly established a reputation on both sides of the Atlantic for playing formidable, stern, and often intimidating authority figures. In 1985, Benzali made a memorable appearance in the James Bond series in A View to a Kill, playing W.G. Howe, the Chief City Engineer of San Francisco. Howe becomes an unwitting obstacle to villainous industrialist Max Zorin''s plans when he refuses to grant additional drilling permits in Silicon Valley due to seismic safety concerns. Sent to inspect City Hall, Bond and Stacey Sutton confront Howe, only for Zorin and May Day to arrive, murder Howe with his own gun, and set fire to the building in an attempt to frame Bond for the crime. Following his role in the Bond franchise, Benzali transitioned into a high-profile television career in Hollywood. He gained widespread acclaim and a Golden Globe nomination for his starring role as cold, brilliant defense attorney Ted Hoffman in the ground-breaking legal drama series Murder One (1995–1996). He went on to star in numerous feature films and series, including The Grey Zone, Californication, Nip/Tuck, and General Hospital. Outside of acting, Benzali is also an accomplished pianist and singer, having released a jazz album in the 2000s.',
       'American-Brazilian',
       '1950-01-20',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Nadim Sawalha (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('80452376-2f71-403b-9833-4f6b9a541980'),
       'Nadim Sawalha',
       'Tangier Chief of Police',
       'Nadim Sawalha was born in Madaba, Jordan, in 1935. He moved to the United Kingdom in the 1950s to study drama at the Drama Centre London, eventually settling in Britain and building a distinguished career as a character actor across theater, television, and international cinema. His natural charisma and ability to project authority made him a popular choice for playing diplomats, merchants, and traditional authority figures. Over a career spanning more than five decades, Sawalha accumulated an impressive list of credits in major Hollywood and British productions. His notable film appearances include The Return of the Pink Panther (1975), Young Sherlock Holmes (1985), Syriana (2005), and West Is West (2010). On television, he appeared in widely recognized series such as The Sweeney, Doctor Who, The Bill, and House of Cards. He also established a legacy through his family, as father to prominent British actresses Julia Sawalha and Nadia Sawalha. In 1977, Sawalha appeared in the James Bond film The Spy Who Loved Me as Fekkesh, an Egyptian contact who holds key information regarding the stolen submarine tracking system microfilm. In the film, Bond tracks Fekkesh to Cairo, following him through a bustling market and onto the rooftops near the Pyramids, where Fekkesh is ultimately murdered by the imposing henchman Jaws before he can reveal the location of the microfilm. Throughout his career, Sawalha remained an influential figure for Arab actors in British television and cinema, frequently advocating for broader and more nuanced representation of Middle Eastern characters in Western media. He continued performing across film, television, and radio well into his later years.',
       'Jordanian-British',
       '1935-09-09',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Maryam d'Abo (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7a95027a-f9ad-41da-8591-5ea343a6f90e'),
       'Maryam d''Abo',
       'Kara Milovy',
       'Maryam d''Abo was born in London, England, in December 1960, to a Georgian mother and a Dutch father. Raised in Paris and Geneva, she grew up trilingual and developed a deep interest in drama, eventually moving to London to study at the Drama Centre. She began her career in commercial modeling while pursuing screen acting, making her feature film debut in the low-budget British horror film Xtro (1982). Throughout the early 1980s, d''Abo built her acting resume with appearances in French cinema, British television dramas, and sci-fi productions such as Arthur the King (1985) and Until September (1984). In 1987, d''Abo achieved global fame when she was cast as the lead Bond girl, Kara Milovy, in The Living Daylights opposite Timothy Dalton. Playing a sweet-natured Czechoslovakian cellist unwitting used as a pawn by her lover, corrupt Soviet General Georgi Koskov, Milovy brought a grounded, vulnerable, and romantic dynamic to the franchise. Her chemistry with Dalton complemented the darker, more realistic tone of his debut as 007. d''Abo received widespread praise for her performance, bringing emotional depth and warmth to a role that required her to balance innocence with courageous action across Eastern Europe and North Africa. Following her breakout role in the Bond franchise, d''Abo maintained a diverse career across European and American film and television. She appeared in feature films such as Leon the Pig Farmer (1992) and Dorian Gray (2009), as well as prominent television miniseries like Helen of Troy (2003). Demonstrating a deep appreciation for her Bond legacy, she co-wrote the 2002 book Bond Girls Are Forever, which was accompanied by a acclaimed television documentary celebrating the actresses of the James Bond series. In her personal life, she married Oscar-winning director Hugh Hudson in 2003 and has remained a respected figure within the Bond fan community.',
       'British',
       '1960-12-27',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jeroen Krabbé (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('91c4b061-cd3e-45e3-80c0-c3669ed4190c'),
       'Jeroen Krabbé',
       'General Georgi Koskov',
       'Jeroen Aart Krabbé was born in Amsterdam, Netherlands, in December 1944, into an artistic family. Both his father and grandfather were painter-artists, inspiring his own lifelong passion for painting alongside performance. Krabbé studied at the Academy of Dramatic Arts in Amsterdam and quickly became a prominent figure in Dutch theater and television. He achieved international breakthrough during the late 1970s and early 1980s through his starring roles in classic films directed by fellow Dutchman Paul Verhoeven, most notably Soldier of Orange (1977), Spetters (1980), and The Fourth Man (1983). His charismatic screen presence, distinguished good looks, and fluent multilingual abilities soon caught the attention of Hollywood casting directors, leading to high-profile American projects such as Jumpin'' Jack Flash (1986) and No Mercy (1986). In 1987, Krabbé joined the James Bond series in The Living Daylights, playing the principal villain General Georgi Koskov. Koskov is a renegade Soviet general who feigns defecting to the West with 007''s help in Bratislava, only to orchestrate a elaborate scheme involving arms deals, opium smuggling, and playing the MI6 against the KGB for personal gain. Krabbé brought a distinct charm, nervous humor, and theatrical flair to the role, contrasting Koskov''s outgoing, friendly demeanor with his deeply deceitful and cold-blooded motives. His performance contributed significantly to the tense, grounded Cold War tone of Timothy Dalton''s debut as James Bond. Following his memorable turn in the Bond franchise, Krabbé solidified his reputation as a sought-after character actor on the international stage, often portraying refined, complex villains or authoritative figures. His notable film appearances include The Punisher (1989), Robin Hood (1991), The Prince of Tides (1991), The Fugitive (1993) as Dr. Charles Nichols, Immortal Beloved (1994), and Ever After (1998). In addition to acting, Krabbé expanded into film directing with acclaimed projects like Left Luggage (1998) and The Discovery of Heaven (2001). Throughout his career, he has remained a celebrated landscape painter in the Netherlands, regularly exhibiting his artwork in galleries across Europe.',
       'Dutch',
       '1944-12-05',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Joe Don Baker (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1b7ff4e7-06be-43d0-b110-051fbc3d84cb'),
       'Joe Don Baker',
       'Brad Whitaker',
       'Joe Don Baker was born in Groesbeck, Texas, in February 1936. Raised in Texas, he played college football at North Texas State University before serving in the United States Army. Following his military service, Baker pursued acting, studying at the Actors Studio in New York City and honing his craft on stage. He made early television guest appearances throughout the late 1960s on popular series such as Gunsmoke, Bonanza, and Mission: Impossible. His breakthrough feature film role arrived in the 1972 Western Junior Bonner, followed by his star-making performance as the real-life vigilante lawman Buford Pusser in the hit action drama Walking Tall (1973). Throughout the 1970s and 1980s, Baker became a staple of American cinema, recognized for his hulking physical build, booming voice, and ability to balance intense tough-guy roles with genial charisma in films like Charley Varrick (1973), The Natural (1984), and Fletch (1985). In 1987, Baker entered the James Bond franchise in The Living Daylights, portraying the primary American antagonist, Brad Whitaker. A megalomaniacal, military-obsessed arms dealer expelled from West Point, Whitaker surrounds himself with wax statues of historical conquerors and partners with rogue Soviet General Georgi Koskov to finance a massive opium shipment. Baker brought a larger-than-life, manic energy to the role, culminating in a climactic gun battle against Timothy Dalton''s 007 inside Whitaker''s Tangier estate, where the villain utilizes high-tech weaponry and body armor before being crushed by a falling bust of Arthur Wellesley, Duke of Wellington. Notably, Baker became one of the few actors in franchise history to return to the James Bond series in a completely different, friendly role. In 1995, he was cast as Jack Wade, the eccentric, Hawaiian-shirt-wearing CIA liaison who assists Pierce Brosnan''s Bond in GoldenEye. Baker returned as Wade once more in 1997''s Tomorrow Never Dies, providing comic relief and tactical assistance in the South China Sea. Outside the Bond series, Baker maintained a respected career in television and film, earning a BAFTA nomination for his performance in the acclaimed BBC miniseries Edge of Darkness (1985) and starring in major feature films such as Cape Fear (1991), Congo (1995), Mars Attacks! (1996), and Mud (2012).',
       'American',
       '1936-02-12',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Rhys-Davies (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('48c38efc-e520-4927-aca3-2a119823a7d6'),
       'John Rhys-Davies',
       'General Leonid Pushkin',
       'John Rhys-Davies was born in Salisbury, Wiltshire, England, in May 1944, to Welsh parents. Raised between England, Wales, and Tanganyika (now Tanzania), where his father served as a colonial officer, he developed an early appreciation for storytelling, history, and languages. He attended Truro School and later graduated from the University of East Anglia before earning a scholarship to the Royal Academy of Dramatic Art in London. Rhys-Davies established his reputation as a classical actor through extensive stage work with the Royal Shakespeare Company and roles in major British television series during the 1970s, including his breakout performance as Naevius Sutorius Macro in the acclaimed BBC miniseries I, Claudius (1976). His imposing stature, thunderous voice, and classical training quickly made him a sought-after character actor in Hollywood, leading to his iconic role as Sallah in Steven Spielberg''s Raiders of the Lost Ark (1981) and Indiana Jones and the Last Crusade (1989). In 1987, Rhys-Davies joined the James Bond franchise in The Living Daylights, playing General Leonid Pushkin, the newly appointed head of the KGB. Replacing General Anatoly Gogol as head of Soviet intelligence, Pushkin is a stern, pragmatic patriot who uncovers a rogue conspiracy within his own ranks led by General Georgi Koskov. After Koskov frames Pushkin by falsely accusing him of re-establishing "SMIERSH" (a Soviet directive to execute foreign spies), Bond tracks Pushkin to Tangier to assassinate him. Realizing Pushkin is innocent, 007 fakes Pushkin''s assassination in a public hotel room to lure Koskov into exposing himself. Rhys-Davies brought a formidable, dignified, and morally grounded authority to the role, serving as a vital counterweight to the movie''s main villains and reinforcing the nuanced political landscape of Timothy Dalton''s debut. Following his turn in the Bond series, Rhys-Davies built an extraordinarily prolific career spanning over two hundred screen credits. He achieved legendary status among modern moviegoers for his portrayal of the dwarf warrior Gimli—and the voice of the Ent Treebeard—in Peter Jackson''s record-breaking The Lord of the Rings trilogy (2001–2003). His expansive filmography also includes starring roles in television series such as Sliders and The Shannara Chronicles, voice work in animated series like Gargoyles and SpongeBob SquarePants, and a reprised performance as Sallah in Indiana Jones and the Dial of Destiny (2023).',
       'Welsh',
       '1944-05-05',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Art Malik (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1f76e538-3973-45ac-9933-49c959bf522c'),
       'Art Malik',
       'Kamran Shah',
       'Athar Ul-Haque Malik, known professionally as Art Malik, was born in Bahawalpur, West Punjab, Pakistan, in November 1952. Emigrating with his family to London at the age of three, he grew up in the United Kingdom and developed a deep interest in performance arts during his youth. He trained at the Drama Centre London, building a solid foundation in theater that led to work with the Royal Shakespeare Company and the Royal Court Theatre. Malik achieved his major international breakthrough in 1984 through his compelling portrayal of Hari Kumar in the award-winning ITV miniseries The Jewel in the Crown, followed shortly by his performance as Zubin Mehta in David Lean''s acclaimed feature film A Passage to India (1984). These early successes established him as one of the prominent British-Asian actors of his generation, recognized for his refined delivery, intensity, and regal screen presence. In 1987, Malik brought his dramatic talents to the James Bond franchise in The Living Daylights, playing Kamran Shah, a charismatic, Oxford-educated leader of the Afghan Mujahideen resistance. Posing as a wealthy local elder while imprisoned in a Soviet airbase, Shah is rescued by Timothy Dalton''s James Bond and Kara Milovy. Recognizing 007''s integrity and shared opposition to the rogue villain alliance of General Koskov and Brad Whitaker, Shah provides critical tactical support and leads his men in a dramatic horseback assault on the Soviet base, aiding Bond in destroying Koskov''s illicit opium shipment. Malik''s performance was widely praised for imbuing the freedom fighter role with unexpected sophistication, intellect, and dry humor rather than relying on action-movie tropes. Following his turn in the Bond series, Malik maintained a prolific international career spanning high-profile Hollywood blockbusters, British television, and acclaimed stage productions. He gained further global recognition for playing the villainous terrorist leader Salim Abu Aziz in James Cameron''s action blockbuster True Lies (1994) opposite Arnold Schwarzenegger. Over the subsequent decades, his varied credits have included feature films like Sex and the City 2 (2010) and The Wolfman (2010), as well as prominent roles in hit television series such as Borgia, Homeland, Indian Summers, Arthur & George, Doctor Who, and The Inbetweeners.',
       'British-Pakistani',
       '1952-11-13',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Andreas Wisniewski (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('85739ffa-4e23-4675-834d-a13212334dc1'),
       'Andreas Wisniewski',
       'Necros',
       'Andreas Wisniewski was born in West Berlin, West Germany, in July 1959. Growing up in post-war Berlin, he initially trained as a classical dancer, studying at the prestigious John Cranko Ballet School in Stuttgart. He pursued a professional career in dance with the Munich State Opera before transitioning into fashion modeling and acting in the early 1980s. Standing six feet three inches tall, with striking blond hair, sharp facial features, and an imposing athletic physique, Wisniewski quickly caught the attention of international casting directors looking for formidable physical performers. He made his feature film debut in the 1986 gothic horror film Gothic, directed by Ken Russell, playing the creature Byron''s vision. In 1987, Wisniewski landed his breakout role in the James Bond series in The Living Daylights, playing Necros, the ruthlessly efficient, walkman-wearing KGB assassin working for renegade General Georgi Koskov and arms dealer Brad Whitaker. Imbuing the character with icy precision and lethal grace, Wisniewski featured in several of the film''s most iconic action set-pieces, including a deadly infiltration of an MI6 safehouse disguised as a milkman and a perilous fight against Timothy Dalton''s 007 while hanging out the open cargo door of a flying C-130 Hercules transport plane. His performance created one of the most memorable henchmen of the late 1980s Bond era. Following his success in The Living Daylights, Wisniewski secured another memorable action cinema role as Tony, one of the primary German henchmen and brother to Karl, in the blockbuster action classic Die Hard (1988) opposite Bruce Willis. Over the following decades, he built a steady international career across film and television, with notable appearances in Mission: Impossible (1996) as one of Max''s henchmen, Mission: Impossible – Ghost Protocol (2011), Centurion (2010), and the German crime series Tatort. In addition to his screen acting, Wisniewski is a dedicated practitioner and instructor of Zen meditation and martial arts, particularly silat and tai chi, spending significant time teaching and guiding students in London and Europe.',
       'German',
       '1959-07-03',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Thomas Wheatley (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('de9c84a5-f28d-47e9-8095-8025f0af8fbb'),
       'Thomas Wheatley',
       'Saunders',
       'Thomas Wheatley was born in August 1951 in Chelmsford, Essex, England. Before pursuing a career in performance, he worked in the shipping industry for seven years across Europe and Australasia. Deciding to transition into acting in his late twenties, he completed formal dramatic training at the Drama Studio London in Ealing. He began his professional career on stage and television during the mid-1980s, gaining early screen visibility in projects such as Honest, Decent and True (1985) and the BBC serial The Singing Detective (1986). In 1987, Wheatley gained international recognition when he was cast in the James Bond film The Living Daylights, playing Saunders, the head of MI6 Section V in Vienna. Portrayed as a rigid, by-the-book bureaucrat who initially clashes with Timothy Dalton''s unconventional methods, Saunders oversees the logistics for General Koskov''s defection. Over the course of the narrative, Saunders earns Bond''s respect by uncovering vital financial leads in Austria, only to be assassinated by Necros in a cafe booby-trap explosion, an event that deeply motivates 007''s subsequent actions. Following his role in the Bond franchise, Wheatley built a steady career in British film, television, and theater. His screen appearances include roles in feature films such as Where Angels Fear to Tread (1991), Death at a Funeral (2007), The Duchess (2008), The Young Victoria (2009), and The Iron Lady (2011). On television, he has worked across numerous dramas and series, including Selling Hitler, Second Sight, Midsomer Murders, Casualty, The Bill, and Doctor Who, while also remaining active on stage with prestigious venues like the Royal National Theatre.',
       'British',
       '1951-08-20',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Terry (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d459c47b-fc90-416b-aed4-bbf311ef60f3'),
       'John Terry',
       'Felix Leiter',
       'John Terry was born in Vero Beach, Florida, in January 1950. Raised in Florida, he spent time working in his youth as a log-cabin builder before pursuing an interest in acting in his late twenties. He moved to the United Kingdom to hone his craft on stage, landing early film roles during the early 1980s. He made his feature film debut in the fantasy adventure Hawk the Slayer (1980) and subsequently appeared in Stanley Kubrick''s acclaimed Vietnam War drama Full Metal Jacket (1987) as Lieutenant Lockhart, a military journalist supervising the Stars and Stripes newspaper office. In 1987, Terry joined the official James Bond series in The Living Daylights, portraying CIA operative Felix Leiter. Taking over the part after Bernie Casey''s appearance four years earlier in Never Say Never Again, Terry became the sixth actor to depict 007''s primary American intelligence counterpart. Portrayed as a suave and reliable ally, his Leiter coordinates closely with Timothy Dalton''s James Bond in Tangier during the investigation into General Koskov''s fraudulent Soviet hit list, providing critical CIA intelligence and logistical support behind the scenes. Following his turn in the Bond franchise, Terry established a prolific career across American film and television. He starred as Slim in the film adaptation of Of Mice and Men (1992) alongside John Malkovich and Gary Sinise, and played Ben Pease in the western film Tombstone (1993). Terry achieved significant television prominence in the 2000s, most notably portraying Christian Shephard, the pivotal father of protagonist Jack Shephard, in the smash-hit mystery series Lost. His major television credits also include recurring and guest roles in ER, 24, Las Vegas, Brothers & Sisters, and Charlie''s Angels.',
       'American',
       '1950-01-25',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Virginia Hey (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6f68c8b4-8160-4805-921a-99b9ccf75fde'),
       'Virginia Hey',
       'Rubavitch, the mistress of General Koskov',
       'Virginia Hey was born in Sydney, New South Wales, Australia, in June 1952. Divided between Australia and the United Kingdom during her upbringing, she began her creative career as a high-fashion model, appearing on numerous magazine covers and in advertising campaigns across Europe and Australia. Her striking height, regal stature, and intense features naturally led her into acting during the early 1980s. She made a memorable feature film debut in George Miller''s apocalyptic classic Mad Max 2: The Road Warrior (1981), playing the fierce and tragic Warrior Woman, a performance that immediately established her screen presence in cult cinema. In 1987, Hey secured a role in the James Bond series in The Living Daylights, playing Rubavitch, the glamourous mistress of renegade KGB General Georgi Koskov. Introduced during the sequence set at General Pushkin''s Tangier villa, Rubavitch is caught off guard in her swimwear when Timothy Dalton''s 007 infiltrates the property to confront Pushkin. Although a small role within the film''s sprawling narrative, her appearance added a classic touch of Bondian glamour to the high-stakes Cold War plot. Following her appearance in the Bond franchise, Hey maintained an active career across film and television in both Australia and North America. She achieved major global popularity among science fiction fans for her starring role as Pa''u Zotoh Zhaan, a blue-skinned alien priestess, in the critically acclaimed sci-fi television series Farscape (1999–2002), a role that earned her a Saturn Award nomination for Best Supporting Actress. Over the years, her credits have also included guest appearances in Neighbours, E Street, Pacific Drive, and Mighty Morphin Power Rangers. Outside of acting, Hey has worked as a certified practitioner in natural therapies, a perfume designer, and a frequent guest at international fan conventions.',
       'Australian',
       '1952-06-19',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Bowe (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('120ea9f3-f9bd-461c-aebb-e2620049228f'),
       'John Bowe',
       'Colonel Feyador',
       'John Bowe was born in Greasby, Cheshire, England, in February 1950. Trained at the Bristol Old Vic Theatre School, the British actor began his career with minor television and stage roles before establishing himself as a prolific and highly recognizable character performer on screen. Through the late 1980s and beyond, his strong, authoritative presence made him a reliable fixture in various acclaimed dramas and popular television serials. In 1987, Bowe made his most prominent international feature film appearance in the James Bond franchise in The Living Daylights, portraying Colonel Feyador. As a corrupt Soviet military commander overseeing a remote airbase in occupied Afghanistan, Feyador is an old acquaintance and key collaborator of the duplicitous General Koskov. Feyador''s heavily guarded base serves as the site of a major opium transaction, as well as a temporary prison for Timothy Dalton''s James Bond and Kara Milovy. Bowe''s stern and imposing performance anchors the militaristic threat of the film''s third act, culminating in a chaotic battle where Feyador meets his demise during Kamran Shah''s horseback assault on the airbase. Beyond his role in the Bond series, Bowe became a well-known figure in the United Kingdom primarily through his extensive television work. He delivered a critically acclaimed performance as the primary suspect George Marlow in the first series of the landmark police drama Prime Suspect (1991) opposite Helen Mirren. Over the subsequent decades, he secured major recurring roles in beloved British soap operas, including playing Duggie Ferguson in Coronation Street from 1999 to 2002, and Lawrence White in Emmerdale from 2014 to 2018. His varied credits also include memorable appearances in hit shows such as Cranford, Tipping the Velvet, and a long-running recurring role on The Bill, cementing his reputation as a versatile and enduring talent in British television.',
       'British',
       '1950-02-01',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Julie T. Wallace (The Living Daylights)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('586bc1c9-eda3-4ba9-88d2-0708567f8145'),
       'Julie T. Wallace',
       'Rosika Miklos',
       'Julie T. Wallace was born in Wimbledon, London, England, in May 1961. Standing six feet tall and possessing a striking, unconventional appearance with sharp features, she initially trained in fine art and worked as a restorer before shifting her focus to the dramatic arts. She enrolled at the Central School of Speech and Drama in London, where she honed her acting skills. Wallace achieved her major breakthrough in 1986 when she landed the starring role of Ruth in the acclaimed, dark BBC television miniseries adaptation of Fay Weldon''s The Life and Loves of a She-Devil. Her powerful, intense portrayal of a spurned wife seeking elaborate revenge on her unfaithful husband made her an instant household name across the United Kingdom and established her reputation for playing eccentric, formidable characters. In 1987, following the massive success of She-Devil, Wallace brought her distinct screen presence to the James Bond franchise in The Living Daylights. She played Rosika Miklos, a Czechoslovakian contact who assists Timothy Dalton''s James Bond during his mission in Bratislava. Operating as a cellist in the orchestra where Kara Milovy plays, Miklos helps 007 track down General Georgi Koskov''s supposed defection route, though she is tragically killed by KGB sniper Pushkin''s agent later in the sequence. Despite the brevity of her screen time, Wallace contributed a memorably gritty and grounded texture to the film''s tense, espionage-heavy opening act set behind the Iron Curtain. Following her appearance in the Bond series, Wallace continued to build a diverse career across British television, film, and theater. Her notable later screen credits include feature films such as the fantasy comedy Splitting Heirs (1993) alongside Eric Idle and Rick Moranis, and the British comedy The Commissioner (1998). On television, she has made guest and recurring appearances in popular British series such as The Bill, Casualty, EastEnders, and Heartbeat. In addition to her acting work, she has remained active in the visual arts, returning to painting and sculpture.',
       'British',
       '1961-05-28',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Caroline Bliss (The Living Daylights, License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('31ddaaa6-7934-42aa-91e4-ce3efeb38f84'),
       'Caroline Bliss',
       'Miss Moneypenny',
       'Caroline Bliss was born in England in July 1961. The granddaughter of composer Sir Arthur Bliss, she trained at the prestigious Bristol Old Vic Theatre School before entering professional acting in the early 1980s. She made her television breakthrough starring as Lady Diana Spencer in the 1982 television film Charles & Diana: A Royal Love Story. Following her debut, she built an active career in British television, appearing in series such as Dempsey and Makepeace, My Brother Jonathan, and The Moneymen. In 1987, Bliss joined the official James Bond series in The Living Daylights, stepping into the iconic role of Miss Moneypenny. Taking over the part after Lois Maxwell''s twenty-three-year tenure, she became the second actress—and the youngest to date—to portray M''s loyal secretary in the Eon Productions franchise. Bliss opted to wear glasses on screen to create a distinct, contemporary personality for the character, bringing a softer, flirtatious charm that complemented Timothy Dalton''s fresh interpretation of 007. She reprised the role of Miss Moneypenny two years later in Licence to Kill (1989), assisting Bond behind the scenes during his rogue mission in North America. Following her time in the Bond franchise, Bliss continued working across British stage and television throughout the 1990s, with notable credits including The Paradise Club, Spender, and Ruth Rendell Mysteries. She eventually stepped away from professional screen acting in the late 1990s to focus on her personal life and family.',
       'British',
       '1961-07-08',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Timothy Dalton (The Living Daylights, License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('f720f4cd-3c45-425b-9f2a-7b5254128c14'),
       'Timothy Dalton',
       'James Bond',
       'Timothy Leonard Dalton Leggett was born in Colwyn Bay, Wales, in March 1946. Raised in Derbyshire, England, he discovered his passion for performance as a teenager after seeing a production of Macbeth. He enrolled at the Royal Academy of Dramatic Art in London, honed his craft with the National Youth Theatre, and quickly made a name for himself as a formidable classical stage actor with the Birmingham Repertory Theatre and the Royal Shakespeare Company. Dalton made an acclaimed feature film debut playing King Philip II of France in the historical drama The Lion in Winter (1968) alongside Peter O''Toole and Katharine Hepburn. His striking looks and intense dramatic presence led to starring roles in period classics like Wuthering Heights (1970) and Mary, Queen of Scots (1971), as well as playing Prince Barin in the cult sci-fi adventure Flash Gordon (1980). In 1986, following Roger Moore''s retirement from the series, Dalton was officially cast as the fourth actor to play James Bond in Eon Productions'' official franchise. He made his debut in 1987''s The Living Daylights, bringing a dramatic reset to the iconic spy. Departing from the lighthearted, theatrical tone of the previous decade, Dalton returned to Ian Fleming''s original literary source material, depicting Bond as a grounded, reluctant, and gritty professional operative burdened by the moral ambiguities of Cold War espionage. His portrayal won praise for its vulnerability, realism, and intense physical edge, anchoring a thrilling storyline that spanned Bratislava, Tangier, and Afghanistan. Dalton reprised the role in 1989''s Licence to Kill, delivering an even darker, vengeance-driven interpretation of the character. Though contractually slated for a third film, lengthy legal disputes over distribution rights delayed production for years, leading Dalton to officially step down from the role in 1994. In the decades since, he has built an exceptionally versatile career across film, stage, and television. His notable later screen credits include roles in The Rocketeer (1991), the action-comedy Hot Fuzz (2007), voicing Mr. Pricklepants in Pixar''s Toy Story franchise, and starring roles in television series such as Penny Dreadful, Doom Patrol, and 1923.',
       'Welsh',
       '1946-03-21',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Robert Davi (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b670ab66-0659-4c1f-8232-980db1bfeaac'),
       'Robert Davi',
       'Franz Sanchez',
       'Robert Davi is an accomplished American actor, writer, director, and singer, best known to global audiences for his chilling portrayal of the ruthless drug lord Franz Sanchez in the 1989 James Bond film Licence to Kill. Born on June 26, 1953, in Astoria, Queens, New York, Davi developed an early passion for the performing arts, studying voice and acting before breaking into television and film in the late 1970s. With his imposing stature and distinctively sharp features, he quickly carved out a successful Hollywood career specializing in playing complex villains and formidable law enforcement officers. Over a career spanning more than four decades, Davi has appeared in over a hundred films and numerous television series. Beyond his iconic turn as a Bond villain opposite Timothy Dalton, some of his most memorable big-screen roles include the opera-loving villain Jake Fratelli in The Goonies, the FBI agent Big Johnson in Die Hard, and a mob boss in Showgirls. In addition to his on-screen work, Davi is a talented jazz vocalist, paying tribute to Frank Sinatra with his acclaimed album Davi Sings Sinatra. He continues to remain active in the entertainment industry as a multifaceted performer and cultural commentator.',
       'American',
       '1951-06-26',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Carey Lowell (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('63e77142-0a9e-4faf-8109-01558fb0e8db'),
       'Carey Lowell',
       'Pam Bouvier',
       'Carey Lowell is an American actress and former model born on February 11, 1961, in Huntington, New York. Due to her geologist father''s career, she spent parts of her childhood living in multiple countries, including France, the Netherlands, and Libya, before her family eventually settled in Colorado. In her youth, she moved to New York City to pursue modeling, successfully working for prominent high-fashion clients such as Calvin Klein and Ralph Lauren. She later transitioned to acting, studying at Manhattan''s Neighborhood Playhouse School of the Theatre. Lowell broke into the film industry with roles in projects like Dangerously Close and Club Paradise before achieving international recognition in 1989. That year, she landed her most iconic film role as the independent and tough CIA pilot Pam Bouvier opposite Timothy Dalton in the James Bond movie Licence to Kill. Following her Bond girl appearance, she continued acting in various films and television shows, including Sleepless in Seattle and Leaving Las Vegas. She later earned widespread acclaim for her television work, starring as Assistant District Attorney Jamie Ross on the hit legal drama series Law & Order from 1996 to 2001.',
       'American',
       '1961-02-11',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Talisa Soto (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('01f083ef-6d74-4246-8224-f46ecc6a0ec0'),
       'Talisa Soto',
       'Lupe Lamora',
       'Talisa Soto is an American retired actress and former model who was born on March 27, 1967, in Brooklyn, New York, as the youngest of four children to parents who moved to New York from Puerto Rico. During her early childhood, her family relocated to Northampton, Massachusetts, where she was raised and educated. At the age of fifteen, she began her professional career by signing with Click Model Management. Quickly finding international success, she traveled to Europe to model, eventually gracing the covers of high-profile publications such as American and British Vogue, British Elle, Mademoiselle, and Glamour, as well as appearing in major advertising campaigns. Transitioning from modeling to acting, Soto made her feature film debut in the 1988 comedy Spike of Bensonhurst. International recognition followed shortly after in 1989 when she was cast as the Bond girl Lupe Lamora, the girlfriend of the ruthless drug lord Franz Sanchez, in the James Bond film Licence to Kill starring Timothy Dalton. Throughout the 1990s and early 2000s, Soto appeared in more than twenty films. Her most notable subsequent roles include Princess Kitana in the fantasy action film Mortal Kombat and its sequel Mortal Kombat Annihilation, as well as appearances in Don Juan DeMarco, The Mambo Kings, and Piñero. Alongside her film work, she was named one of People magazine''s 50 Most Beautiful People in the World in 1990 and was featured in the Sports Illustrated Swimsuit Issue in 1995. Soto later stepped back from acting following her marriage to actor Benjamin Bratt, with whom she shares two children.',
       'American',
       '1967-03-27',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Anthony Zerbe (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('edaf5db8-248d-4fc8-a594-259b4b938bad'),
       'Anthony Zerbe',
       'Milton Krest',
       'Anthony Zerbe is an accomplished American actor celebrated for his prolific career across film, television, and stage, known worldwide for his memorable role as the maritime tycoon and drug smuggler Milton Krest in the 1989 James Bond film Licence to Kill. Born on May 20, 1936, in Long Beach, California, Zerbe developed an interest in the dramatic arts and studied at Pomona College before launching his professional acting career. With his distinctive features, commanding deep voice, and intense screen presence, he quickly became one of Hollywood''s most sought-after character actors, frequently specializing in playing sophisticated villains, authoritative figures, and morally complex individuals. Throughout a career spanning decades, Zerbe has accumulated a vast body of work with appearances in numerous acclaimed motion pictures and television series. Some of his most notable big-screen credits include his roles in Cool Hand Luke, The Omega Man, Papillon, The Taking of Pelham One Two Three, and later portraying the Counselor in the science fiction sequels The Matrix Reloaded and The Matrix Revolutions. In addition to his extensive film resume, he has enjoyed a rich career on television, earning an Emmy Award nomination and making guest appearances on classic shows like Mission: Impossible, The Rockford Files, and Star Trek: Deep Space Nine. A dedicated stage actor as well, Zerbe has performed in numerous theatrical productions on Broadway and regional stages, cementing his legacy as a versatile and enduring talent in the entertainment industry.',
       'American',
       '1936-05-20',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Frank McRae (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9eac7811-584e-42b6-a2cd-754a35d30bd4'),
       'Frank McRae',
       'Sharkey',
       'Frank McRae was an American actor and professional football player born on March 18, 1941, in Memphis, Tennessee. Before entering the entertainment industry, he attended Tennessee State University where he played college football and pursued a double major in drama and history. His athletic talents led to a brief professional football career as a defensive tackle, playing six games for the Chicago Bears during the 1967 NFL season. Standing at an imposing height of six feet seven inches, McRae transitioned into acting in the early 1970s and leveraged his commanding physical presence to carve out a prolific career playing tough guys, law enforcement officers, and authority figures. Throughout a screen career spanning more than three decades, McRae appeared in over forty films, often leaving a strong impression in both action movies and comedies. James Bond fans best know him for his memorable role as Sharkey, a loyal friend and ally to James Bond who aids him against drug traffickers in the 1989 film Licence to Kill. Some of his other notable film credits include playing a shouting police captain in 48 Hrs., a security guard in National Lampoon''s Vacation, an empathetic mechanic in Batteries Not Included, and a police lieutenant in Last Action Hero. McRae retired from acting in the mid-2000s and passed away from a heart attack in Santa Monica, California, on April 29, 2021.',
       'American',
       '1941-03-18',
       '2021-04-29',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Everett McGill (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('629914c7-516e-43ee-8e5d-14d328656959'),
       'Everett McGill',
       'Ed Killifer',
       'Everett McGill is an American actor born on October 21, 1945, in Miami Beach, Florida. He established a diverse acting career spanning theatre, television, and film, initially training and performing on Broadway in prominent productions like Equus and Whose Life Is It, Anyway? With his striking presence and intense demeanor, McGill transitioned into motion pictures, gaining early widespread recognition for starring as a caveman in Jean-Jacques Annaud''s prehistoric adventure film Quest for Fire. He followed this with a succession of notable feature film roles throughout the 1980s, including playing Stilgar in David Lynch''s science-fiction epic Dune, a Reverend in Stephen King''s Silver Bullet, and Major Malcolm Powers in the Clint Eastwood military film Heartbreak Ridge. In 1989, McGill joined the James Bond franchise to portray the corrupt law enforcement official Ed Killifer in Licence to Kill, a role in which his character betrays Felix Leiter by accepting a bribe to help drug lord Franz Sanchez escape custody. Following his Bond appearance, he achieved further cult television fame starring as the eccentric Big Ed Hurley in David Lynch''s landmark series Twin Peaks, a role he later reprised for the 2017 revival. His extensive screen credits also include major genre features like Wes Craven''s The People Under the Stairs and the action sequel Under Siege 2: Dark Territory.',
       'American',
       '1945-10-21',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Wayne Newton (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('608be459-e5e2-4c0c-8bdf-4b116e31d53a'),
       'Wayne Newton',
       'Professor Joe Butcher',
       'Wayne Newton is an American singer, actor, and entertainer born on April 3, 1942, in Roanoke, Virginia. Often referred to as "Mr. Las Vegas" or "The Midnight Idol," he rose to national prominence as a teenager in the early 1960s with his signature soaring tenor vocals and charismatic stage presence, eventually becoming one of the most iconic and highest-earning headliners in the history of the Las Vegas Strip. Alongside his legendary music career, which includes worldwide hit singles like Danke Schoen, Newton built a versatile acting resume spanning television and film, frequently appearing as himself or playing memorable character roles that often parodied his own larger-than-life Vegas persona. In 1989, Newton expanded his acting credits by joining the James Bond franchise to play Professor Joe Butcher in Licence to Kill. In the film, Butcher is a charismatic, televangelist con artist who uses his religious broadcasting network, the Faithful Word Foundation, as a fraudulent front to launder drug money and promote the global cocaine empire of the primary villain, Franz Sanchez. Beyond his work in the Bond universe, Newton has made numerous guest appearances on popular television shows like Bonanza, Hawaii Five-O, and The Fresh Prince of Bel-Air, and has featured in notable movies such as The Adventures of Ford Fairlane and Vegas Vacation. He has remained an active cultural fixture and performing artist, maintaining his deep entertainment ties to Las Vegas for over six decades.',
       'American',
       '1942-04-03',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Benicio Del Toro (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('de44504e-3bb0-44eb-a9ef-bc8771e22759'),
       'Benicio Del Toro',
       'Dario',
       'Benicio Del Toro is an acclaimed Puerto Rican actor and producer born on February 19, 1967, in San Germán, Puerto Rico. Relocating to Pennsylvania during his youth, he initially pursued a degree in business at the University of California, San Diego, before discovering a passion for acting and studying under legendary teachers Stella Adler and Arthur Penn. He began landing minor television roles in the late 1980s before making a striking early feature film impression when he was cast at just 21 years old as Dario, the psychotic and sadistic henchman to drug lord Franz Sanchez in the 1989 James Bond film Licence to Kill, making him the youngest actor ever to play a primary Bond henchman. Following his breakout work in the Bond franchise, Del Toro earned widespread critical acclaim throughout the 1990s with memorable supporting performances in films like The Usual Suspects and Fear and Loathing in Las Vegas. He achieved major international stardom and won the Academy Award for Best Supporting Actor for his gripping portrayal of honest Mexican police officer Javier Rodriguez in Steven Soderbergh''s 2000 crime drama Traffic. His illustrious career spans diverse blockbuster and independent projects, including earning another Oscar nomination for 21 Grams, starring as Che Guevara in the biographical epic Che, and playing the Collector in the Marvel Cinematic Universe.',
       'Puerto Rican',
       '1967-02-19',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Anthony Starke (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1c1543c7-6d1c-4ef6-acad-15a1f6117e34'),
       'Anthony Starke',
       'Truman-Lodge',
       'Anthony Starke is an American actor born on August 6, 1963, in Glendale, California. He pursued his passion for performance by studying theatre at Moorhead State University before launching his professional acting career on stage, television, and film in the mid-1980s. Starke quickly established himself as a versatile performer capable of handling both comedic and dramatic roles, landing early guest spots on popular television series like The Facts of Life and Cheers. He gained wider mainstream recognition in 1989 when he was cast in two major feature films: playing the titular lead in the comedy sequel National Lampoon''s Christmas Vacation 2 (though his scenes were largely cut or reworked) and portraying the sleek, ambitious accountant Truman-Lodge in the James Bond film Licence to Kill. In Licence to Kill, Starke played Truman-Lodge, the smooth-talking financial advisor and corporate mastermind who manages the illegal drug money and legitimate business fronts for the primary villain, Franz Sanchez. Following his appearance in the Bond franchise, Starke maintained a prolific career in television, appearing in dozens of high-profile shows including Seinfeld, The Pretender, Boston Legal, Nip/Tuck, and Mad Men. He also secured recurring television roles, notably playing Craig Feldspar on the hit sitcom Malcolm in the Middle and Travis Marshall on the drama series The Closer, cementing a durable and respected career across both the small and big screens.',
       'American',
       '1963-08-06',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Pedro Armendáriz Jr. (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('abe80de5-1c4c-4111-9270-3df4fc91ac54'),
       'Pedro Armendáriz Jr.',
       'President Hector Lopez',
       'Pedro Armendáriz Jr. was a prominent Mexican actor born on April 6, 1940, in Mexico City, Mexico, as the son of renowned actor Pedro Armendáriz. Initially studying architecture, he transitioned into acting at the encouragement of director Arturo Ripstein and went on to build a prolific career spanning over two hundred film and television productions across both Mexican and American cinema. Well-regarded for his bilingualism and strong screen presence, he appeared in numerous international Hollywood features throughout his life, including The Mask of Zorro, Amistad, and Once Upon a Time in Mexico, alongside winning multiple prestigious Ariel Awards in Mexico for his stellar character work. In the 1989 James Bond film Licence to Kill, Armendáriz Jr. portrayed President Hector Lopez, the corrupt president of Isthmus who accepts bribes from the drug lord Franz Sanchez. His appearance in the franchise created a notable family legacy, as his father had famously played the British agent Kerim Bey in the 1963 James Bond film From Russia with Love. Armendáriz Jr. continued acting up until his final years before passing away on December 26, 2011, in New York City.',
       'Mexican',
       '1940-04-06',
       '2011-12-26',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Priscilla Barnes (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('689533c0-6a07-42a0-a10b-3031dd20e353'),
       'Priscilla Barnes',
       'Della Churchill',
       'Priscilla Barnes is an American actress born on December 7, 1955, in Fort Dix, New Jersey, the daughter of a military officer. Raised across various military bases, she began pursuing an entertainment career as a teenager, initially working as a dancer and model before transitioning into acting in the mid-1970s. After landing early television guest roles in popular series like The Rockford Files and Kojak, she achieved major mainstream recognition in 1981 when she was cast as Terri Alden on the hit sitcom Three''s Company, a role she played for two seasons. Throughout her decades-long career, she established herself as a versatile screen presence, starring in numerous film and television projects such as the thriller The Lords of Salem and the soap opera The Bay. In the 1989 James Bond film Licence to Kill, Barnes portrayed Della Churchill, the loving and vibrant fiancée of CIA agent Felix Leiter. Her character''s tragic fate on her wedding day serves as the primary catalyst and emotional driving force for James Bond''s rogue mission of personal vengeance against the drug lord Franz Sanchez. Barnes continued a steady acting career in film and television following her appearance in the franchise.',
       'American',
       '1954-12-07',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Don Stroud (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3111a692-e9d9-4dac-a221-d085dc25a763'),
       'Don Stroud',
       'Heller',
       'Don Stroud is an American actor and professional surfer born on February 4, 1943, in Honolulu, Hawaii. He grew up immersed in the surfing culture of Waikiki before breaking into the entertainment industry in the mid-1960s, quickly establishing a reputation for playing tough guys, villains, and law enforcement officers due to his imposing physique and rugged screen presence. He gained widespread recognition for his memorable film roles, including starring alongside Clint Eastwood in Coogan''s Bluff (1968), appearing in Bloody Mama (1970), and playing the ruthless bounty hunter Buddy in The Buddy Holly Story (1978), a performance that earned him critical acclaim. Over a prolific career spanning six decades, he has remained a familiar face in both film and television, with notable recurring roles in series like General Hospital and guest appearances across numerous classic action and crime shows. In the 1989 James Bond film Licence to Kill, Stroud played Milton Krest''s loyal and corrupt right-hand man, Heller, who works for the ruthless drug lord Franz Sanchez. His character serves as a formidable enforcer within the cartel operation before meeting a brutal end when James Bond manipulates the situation to turn Sanchez against him.',
       'American',
       '1943-09-01',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Grand L. Bush (License to kill)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('e74a9893-f7d0-4501-a516-a34e6e5d8449'),
       'Grand L. Bush',
       'Hawkins',
       'Grand L. Bush is an American actor born on December 24, 1955, in Los Angeles, California. He pursued his passion for the performing arts by studying acting and music before breaking into film and television in the late 1970s. He quickly established himself as a recognizable and versatile character actor, frequently bringing energy and distinct presence to a wide variety of supporting roles in major Hollywood blockbusters and television series throughout the 1980s and 1990s. Some of his most memorable big-screen appearances include playing Balrog in the action-comedy classic The Cannonball Run (1981), portraying Detective Jerry Pollard in William Friedkin''s thriller To Live and Die in L.A. (1985), and starring as Gordon in the sci-fi action hit Predator 2 (1990). In addition to his film work, he made numerous guest appearances on popular television shows such as The A-Team, Miami Vice, and Star Trek: The Next Generation. In the 1989 James Bond film Licence to Kill, Bush portrayed Hawkins, a Drug Enforcement Administration agent who works alongside Felix Leiter and James Bond during the dramatic operation to capture the drug lord Franz Sanchez. His character is present during the pivotal early mission to intercept Sanchez, establishing the law enforcement backdrop that sets the film''s intense plot in motion. Following his extensive career in film and television, Bush eventually stepped away from acting to focus on other personal pursuits and education.',
       'American',
       '1955-12-24',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Pierce Brosnan (Goldeneye, Tomorrow Never Dies, The World Is Not Enough, Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7a0961d5-7c93-4216-a7ff-3453cac62b60'),
       'Pierce Brosnan',
       'James Bond',
       'Pierce Brosnan is an Irish actor and film producer born on May 16, 1953, in Drogheda, County Louth, Ireland, before moving to London at a young age where he trained at the Drama Centre. He first achieved international superstardom and widespread television recognition in the early 1980s by starring as the charming private investigator in the hit romantic-comedy mystery series Remington Steele. Following that television success, he established himself as a versatile leading man in numerous Hollywood films, ranging from action blockbusters to romantic comedies and dramas, including his acclaimed performances in Mrs. Doubtfire (1993), The Thomas Crown Affair (1999), and The Matador (2005), as well as proving his musical talents as Sam Carmichael in the smash-hit movie musical Mamma Mia! (2008). In the James Bond franchise, Brosnan became the fifth actor to officially portray the iconic British secret agent, debuting in the critically and commercially triumphant 1995 film GoldenEye. He went on to star as 007 in three subsequent blockbusters: Tomorrow Never Dies (1997), The World Is Not Enough (1999), and Die Another Day (2002), successfully revitalizing the legendary spy series for a modern post-Cold War audience with his signature blend of effortless charm, suave sophistication, and gritty action prowess.',
       'Irish',
       '1953-05-16',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Sean Bean (Goldeneye)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('be516057-8d6e-4302-aa7d-81f4981ba0f6'),
       'Sean Bean',
       'Alec Trevelyan (Agent 006)',
       'Sean Bean is an English actor born on February 17, 1959, in Handsworth, Sheffield, England. He developed an interest in the arts after initially working in his father''s welding business before winning a scholarship to study at the prestigious Royal Academy of Dramatic Art (RADA) in London. He began his professional career on the stage before breaking into film and television in the mid-1980s, quickly establishing a reputation for playing intense, gritty, and often doomed characters due to his commanding screen presence and distinctive Yorkshire accent. He achieved widespread international acclaim for his iconic television and film roles, notably starring as the Napoleonic Wars hero Richard Sharpe in the long-running television series Sharpe, portraying Boromir in Peter Jackson''s epic fantasy trilogy The Lord of the Rings, and playing Eddard Stark in the first season of the HBO fantasy hit Game of Thrones. In the James Bond franchise, Bean famously portrayed the primary antagonist Alec Trevelyan, also known as Agent 006, in the 1995 film GoldenEye. His character is introduced as a fellow MI6 operative who fakes his own death and turns rogue to orchestrate a devastating satellite attack against the United Kingdom''s financial infrastructure, setting up a thrilling ideological and physical showdown against Pierce Brosnan''s James Bond.',
       'British',
       '1959-04-17',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Izabella Scorupco (Goldeneye)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('589821b2-fa86-4846-90e6-c773be836d13'),
       'Izabella Scorupco',
       'Natalya Simonova',
       'Izabella Scorupco is a Polish-Swedish actress, singer, and model born on June 4, 1970, in Białystok, Poland. When she was a young child, she moved with her mother to Stockholm, Sweden, where she grew up fluent in multiple languages and began a successful career as a high-fashion teenager model, appearing on the cover of European Vogue. She expanded into the entertainment industry in the late 1980s, gaining recognition in Sweden for her starring role in the television film Ingen kan älska som vi (1988) and later launching a brief yet successful pop music career that included a platinum-selling self-titled album and chart-topping singles. In the James Bond franchise, Scorupco achieved international stardom when she was cast as the brilliant, resilient computer programmer Natalya Simonova in the 1995 blockbuster GoldenEye. Her character serves as the emotional and intellectual anchor of the film, surviving the destruction of a Siberian tracking station and teaming up with Pierce Brosnan''s James Bond to stop a catastrophic satellite weapon from destroying London. Following her breakout role in GoldenEye, she continued to work in international cinema, most notably starring alongside Val Kilmer in the sci-fi adventure film Vertical Limit (2000) and appearing in the action-horror film Reign of Fire (2002) opposite Christian Bale and Matthew McConaughey.',
       'Polish-Swedish',
       '1970-06-04',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Famke Janssen (Goldeneye)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('f8b9f826-d66c-4c9a-8686-7aafbd559465'),
       'Famke Janssen',
       'Xenia Onatopp',
       'Famke Janssen is a Dutch actress, director, screenwriter, and former fashion model born on November 5, 1964, in Amstelveen, Netherlands. After moving to the United States in the mid-1980s, she initially achieved high-profile success as a top international fashion model working in New York City for elite brands like Yves Saint Laurent, Chanel, and Victoria''s Secret. Transitioning to acting, she studied at Columbia University and made her feature film debut opposite Jeff Goldblum in the crime drama Father Hood (1993). She established herself as a versatile and striking presence in Hollywood through a wide range of memorable film and television roles, most notably playing the powerful telepathic mutant Jean Grey in the original X-Men film trilogy, starring as Ava Moore in the critically acclaimed television series Nip/Tuck, and leading the action-thriller franchise Taken alongside Liam Neeson. In the James Bond franchise, Janssen achieved massive international recognition for her unforgettable portrayal of the sadistic and lethal assassin Xenia Onatopp in the 1995 blockbuster GoldenEye. Her character became one of the most iconic and distinct villains in cinematic history, famously combining brutal physical combat prowess with eccentric flair as she hunted down her targets, culminating in a fierce and dramatic confrontation with Pierce Brosnan''s James Bond.',
       'Dutch',
       '1964-11-05',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Tchéky Karyo (Goldeneye)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('1d8f8986-5bcb-4745-9da2-fc4d21fd8bbb'),
       'Tchéky Karyo',
       'Defence Minister Dimitri Mischkin',
       'Tchéky Karyo is a distinguished French actor and musician born as Bozorgmehr Karyo on October 4, 1953, in Istanbul, Turkey, to a Turkish-Jewish father and a Greek mother. Moving to Paris at a young age, he studied drama at the National Academy of Dramatic Arts and spent several years performing classical and contemporary theater with the National Theatre of Strasbourg. He transitioned into cinema in the early 1980s, rapidly establishing himself as one of France''s most reliable and intense character actors, frequently cast in gripping thrillers and crime dramas. His striking screen presence and brooding intensity earned him a César Award nomination for Most Promising Actor for his performance in The Return of Martin Guerre (1982). Over a prolific career spanning decades, he has transitioned effortlessly between French cinema and major Hollywood productions, accumulating memorable supporting credits in international blockbusters such as La Femme Nikita (1990), 1492: Conquest of Paradise (1992), Bad Boys (1995), The Patriot (2000), and critically acclaimed television work like the mystery-crime series The Missing. In the James Bond franchise, Karyo brought his signature gravitas to the 1995 blockbuster GoldenEye, playing the role of Defence Minister Dimitri Mischkin. As a high-ranking Russian government official, Mischkin finds himself caught in the complex web of political betrayal and military conspiracy orchestrated by the renegade Janus syndicate. His character acts as a key figure in the tense political drama surrounding the stolen GoldenEye satellite weapon system, ultimately meeting a tragic end when he is framed and eliminated by the film''s primary villains before he can expose the true conspirators.',
       'French',
       '1953-10-04',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Gottfried John (Goldeneye)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('66a356f9-e322-4df7-96aa-fc574d134612'),
       'Gottfried John',
       'General Arkady Ourumov',
       'Gottfried John was a prominent German stage, television, and film actor born on August 29, 1942, in Berlin, Germany. Growing up in post-war Berlin under difficult circumstances, he was largely self-taught and drifted through various odd jobs before discovering a passion for acting, eventually training and working extensively in theater. He rose to international prominence through his longstanding creative collaboration with acclaimed German film director Rainer Werner Fassbinder, delivering standout performances in landmark New German Cinema masterpieces such as Ali: Fear Eats the Soul (1974), Despair (1978), and the monumental television epic Berlin Alexanderplatz (1980). With his distinctively piercing eyes, commanding voice, and intense screen presence, John frequently excelled at playing complex, brooding, or menacing characters, making him a sought-after talent for both German productions and major international crossover projects throughout his long and prolific career. In the James Bond franchise, John delivered one of his most widely recognized international performances as General Arkady Ourumov in the 1995 blockbuster GoldenEye. As a corrupt and ambitious Russian military general, Ourumov conspires with the renegade agent Alec Trevelyan to hijack the secret Soviet GoldenEye satellite weapon system, showcasing a rigid and ruthless dedication to his nationalist goals. His character serves as a central and formidable antagonist for the first half of the film, culminating in a dramatic showdown in St. Petersburg before he is ultimately betrayed and eliminated by his own co-conspirators.',
       'German',
       '1942-08-29',
       '2014-09-01',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Alan Cumming (Goldeneye)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0fe903b2-3ea6-4640-8f35-7030d21c0edf'),
       'Alan Cumming',
       'Boris Grishenko',
       'Alan Cumming is a multifaceted Scottish-American actor, author, activist, and singer born on January 27, 1965, in Aberfeldy, Scotland. He trained at the Royal Scottish Academy of Music and Drama and quickly established himself as a phenomenal talent across British theater, television, and film. He achieved worldwide theatrical renown for his transformative, Tony Award-winning portrayal of the Master of Ceremonies in the Broadway revival of Cabaret (1998), a role he reprised to critical acclaim in 2014. Known for his flamboyant style, sharp wit, and incredible versatility, Cumming has enjoyed a prolific career spanning high-profile independent films, major blockbusters, and television hits, including starring as Eli Gold in the acclaimed political drama series The Good Wife, hosting the reality competition series The Traitors, and voicing various iconic animated characters. In the James Bond franchise, Cumming delivered a memorable and eccentric supporting performance as Boris Grishenko, a brilliant, hyperactive, and deeply arrogant Russian computer programmer in the 1995 blockbuster GoldenEye. Working out of the Severnaya facility, Boris''s unmatched hacking skills are exploited by the renegade Janus syndicate to help control the deadly satellite weapon system. His character is famously remembered for his obnoxious habit of clicking pens, shouting "I am invincible!" during moments of triumph, and meeting a memorably chilling end when he is encased in liquid nitrogen.',
       'Scottish-British',
       '1965-01-27',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Serena Gordon (Goldeneye)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0f486115-a8f0-434d-a547-19220b313a4e'),
       'Serena Gordon',
       'Caroline',
       'Serena Gordon is a talented English actress born on September 3, 1963, in London, England. She trained at the prestigious Central School of Speech and Drama and has built a diverse career spanning British television, film, and theater. Gordon is well-regarded for her elegance and versatility, making frequent guest and recurring appearances in popular British television series such as The Bill, Holby City, Midsomer Murders, and Judge John Deed, alongside her work in classical and contemporary stage productions. In the James Bond franchise, Gordon appeared in the opening pre-title sequence of the 1995 blockbuster GoldenEye as Caroline, an MI6 evaluation officer assessing James Bond during a covert infiltration of a Soviet chemical weapons facility in Arkhangelsk. Her brief yet memorable role provides a sharp comedic contrast as she attempts to maintain professional composure and psychological evaluation protocols while Bond engages in high-adrenaline espionage, famously pausing mid-mission to flirt with her.',
       'British',
       '1963-09-03',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Billy J. Mitchell (Goldeneye)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9a053236-f4c5-461f-90c7-d38b2e077ffe'),
       'Billy J. Mitchell',
       'Admiral Chuck Farrel',
       'Billy J. Mitchell was an American character actor born on June 16, 1942, who was primarily based in the United Kingdom throughout his career. Known for his versatile ability to portray distinct North American characters, he became a familiar face in numerous major British-based film productions, lending his talents to blockbusters and cult classics such as Superman, Top Secret!, Indiana Jones and the Last Crusade, and Return of the Jedi. He maintained a steady presence in cinema and television from the mid-1970s until his passing. In the James Bond franchise, Mitchell made his most notable series appearance in the 1995 film GoldenEye as Admiral Chuck Farrel, a Canadian naval officer who becomes an early victim of the lethal Janus Syndicate assassin Xenia Onatopp. (He had also previously appeared in the non-Eon Bond film Never Say Never Again in 1983 as Commander Peterson). In GoldenEye, his character is famously lured away from a Monte Carlo casino by Onatopp, leading to his demise and the subsequent theft of a restricted military identification card used to infiltrate a demonstration of the stealth helicopter.',
       'American',
       '1941-03-27',
       '2007-12-08',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Joe Don Baker (Goldeneye, Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('fbb22cbe-6e73-4a48-bcda-71254604a27d'),
       'Joe Don Baker',
       'Jack Wade',
       'Joe Don Baker was born in Groesbeck, Texas, in February 1936. Raised in Texas, he played college football at North Texas State University before serving in the United States Army. Following his military service, Baker pursued acting, studying at the Actors Studio in New York City and honing his craft on stage. He made early television guest appearances throughout the late 1960s on popular series such as Gunsmoke, Bonanza, and Mission: Impossible. His breakthrough feature film role arrived in the 1972 Western Junior Bonner, followed by his star-making performance as the real-life vigilante lawman Buford Pusser in the hit action drama Walking Tall (1973). Throughout the 1970s and 1980s, Baker became a staple of American cinema, recognized for his hulking physical build, booming voice, and ability to balance intense tough-guy roles with genial charisma in films like Charley Varrick (1973), The Natural (1984), and Fletch (1985). In 1987, Baker entered the James Bond franchise in The Living Daylights, portraying the primary American antagonist, Brad Whitaker. A megalomaniacal, military-obsessed arms dealer expelled from West Point, Whitaker surrounds himself with wax statues of historical conquerors and partners with rogue Soviet General Georgi Koskov to finance a massive opium shipment. Baker brought a larger-than-life, manic energy to the role, culminating in a climactic gun battle against Timothy Dalton''s 007 inside Whitaker''s Tangier estate, where the villain utilizes high-tech weaponry and body armor before being crushed by a falling bust of Arthur Wellesley, Duke of Wellington. Notably, Baker became one of the few actors in franchise history to return to the James Bond series in a completely different, friendly role. In 1995, he was cast as Jack Wade, the eccentric, Hawaiian-shirt-wearing CIA liaison who assists Pierce Brosnan''s Bond in GoldenEye. Baker returned as Wade once more in 1997''s Tomorrow Never Dies, providing comic relief and tactical assistance in the South China Sea. Outside the Bond series, Baker maintained a respected career in television and film, earning a BAFTA nomination for his performance in the acclaimed BBC miniseries Edge of Darkness (1985) and starring in major feature films such as Cape Fear (1991), Congo (1995), Mars Attacks! (1996), and Mud (2012).',
       'American',
       '1936-02-12',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Michael Kitchen (Goldeneye, The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b088a0d9-4996-424d-a561-1bd3288e8f0a'),
       'Michael Kitchen',
       'Bill Tanner',
       'Michael Kitchen is a distinguished English actor born on October 31, 1948, in Leicester, England. He trained at the prestigious Royal Academy of Dramatic Art (RADA) and quickly established a reputation as a consummate character actor with a commanding presence on both stage and screen. Kitchen has enjoyed a prolific career across British television, film, and theater, earning widespread critical acclaim for his subtle, intelligent performances and understated delivery. He is perhaps best known to international television audiences for his critically lauded starring role as Detective Chief Superintendent Christopher Foyle in the immensely popular wartime mystery series Foyle''s War, a role he played for over a decade. His extensive film credits include memorable appearances in major motion pictures such as Out of Africa, Enchanted April, and House of America, cementing his status as one of Britain''s most reliable and respected dramatic talents. In the James Bond franchise, Kitchen made his debut as Bill Tanner, M''s loyal and level-headed Chief of Staff, in the 1995 blockbuster GoldenEye. He reprised the character four years later in The World Is Not Enough, serving as a trusted administrative right-hand man within MI6 who offers crucial operational briefings, calm logistical support, and a steady bureaucratic foil to the high-stakes exploits of James Bond.',
       'British',
       '1948-10-31',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Robbie Coltrane (Goldeneye, The world is not enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('ed74a294-b036-4919-b274-59b747c1e4ef'),
       'Robbie Coltrane',
       'Valentin Zukovsky',
       'Robbie Coltrane was a beloved Scottish actor, comedian, and author born as Anthony Robert McMillan on March 30, 1950, in Rutherglen, Scotland. After studying art at Glasgow Art School, he turned to acting in his early twenties, adopting the stage name Coltrane as a tribute to the jazz saxophonist John Coltrane. He began his career in theater and stand-up comedy before transitioning successfully to television and film, where his towering physical stature, warm comedic timing, and remarkable dramatic depth made him a standout presence. He achieved widespread British acclaim starring as the forensic psychologist Dr. Edward "Fitz" Fitzgerald in the gritty television crime drama Cracker (1993–2006), a landmark role that earned him three consecutive BAFTA TV Awards for Best Actor. Internationally, he captured the hearts of millions of fans around the world for his iconic portrayal of the half-giant gamekeeper Rubeus Hagrid in all eight films of the blockbuster Harry Potter series, cementing his status as a legendary figure in modern cinematic history. In the James Bond franchise, Coltrane delivered a memorable and charismatic supporting performance as Valentin Zukovsky, a former KGB officer turned wealthy, cynical Russian mafia boss and nightclub owner, debuting in the 1995 blockbuster GoldenEye. Zukovsky famously bore a limp and a grudge stemming from an old encounter with Pierce Brosnan''s James Bond, yet the two characters formed an uneasy, begrudging alliance. Coltrane reprised the fan-favorite role in the 1999 film The World Is Not Enough, where Zukovsky aids Bond once more before heroically sacrificing his life to help rescue him from the villainous Elektra King.',
       'Scottish',
       '1950-03-30',
       '2022-10-14',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Samantha Bond (Goldeneye, Tomorrow Never Dies, The World Is Not Enough, Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0dbda1e7-4450-42d2-9b18-e75ba383c843'),
       'Samantha Bond',
       'Miss Moneypenny',
       'Samantha Bond is an accomplished English actress born on February 27, 1961, in London, England, into a theatrical family as the daughter of actor Philip Bond. She trained at the prestigious Bristol Old Vic Theatre School and has built a distinguished career spanning theater, television, and film, earning particular acclaim for her extensive work on the British stage with the Royal Shakespeare Company and the National Theatre. Alongside her classical theatrical roots, Bond has become a familiar and beloved face on British television through starring roles in popular drama series such as The Inspector Lynley Mysteries, Downton Abbey, Home Fires, and Outnumbered. Recognized for her poise, sharp comedic timing, and refined elegance, she has maintained a vibrant and enduring presence across diverse entertainment mediums for decades. In the James Bond franchise, Bond made her debut as the iconic secret service secretary Miss Moneypenny in the 1995 blockbuster GoldenEye, a role she reprised across all four films of the Pierce Brosnan era, concluding with Die Another Day in 2002. Her portrayal brought a modern, witty, and fiercely independent edge to the traditional character, establishing a playfully flirtatious and sharp-witted dynamic with James Bond that offered a refreshing counterpoint to the high-stakes espionage action.',
       'British',
       '1961-02-27',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Judi Dench (Goldeneye, Tomorrow Never Dies, The World Is Not Enough, Die Another Day, Casino Royale, Quantum Of Solace, Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2bddd2b9-b312-4095-b24d-4939b97d922d'),
       'Judi Dench',
       'M.',
       'Dame Judi Dench is an English actress widely celebrated as one of the most distinguished and accomplished performers in the history of British theatre and cinema, born on December 9, 1934, in Heworth, North Yorkshire. After initially training as a set designer, she shifted her focus to acting and graduated from the Royal Central School of Speech and Drama. She began her professional career on stage in 1957 with the Old Vic Company and spent decades establishing herself as a preeminent Shakespearean actress with the Royal Shakespeare Company, earning numerous accolades. While she enjoyed a stellar theatrical and British television career for many years—starring in acclaimed series like A Fine Romance and As Time Goes By—she achieved global film stardom later in life. Her remarkable major film credits include her Academy Award-winning supporting role in Shakespeare in Love (1998), as well as critically lauded performances in Mrs. Brown (1997), Iris (2001), Notes on a Scandal (2006), and Philomena (2013). In the James Bond franchise, Dench made history by becoming the first female actor to portray M, the head of MI6 and James Bond''s formidable superior, debuting in the 1995 blockbuster GoldenEye. Modeled partly on real-life intelligence figures, her sharp, witty, and uncompromising portrayal breathed fresh air into the long-running series, famously dressing down Pierce Brosnan''s Bond as a "sexist, misogynist dinosaur" in their first meeting. She became the rare fixture of the franchise to bridge the gap between different eras, maintaining her role across the remainder of Brosnan''s tenure and continuing seamlessly into Daniel Craig''s gritty reboot era, ultimately cementing her legacy across eight films before her character''s poignant departure.',
       'British',
       '1934-12-09',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jonathan Pryce (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('fc457670-13a5-48dd-8874-9dec60016dbf'),
       'Jonathan Pryce',
       'Elliot Carver',
       'Jonathan Pryce is an acclaimed Welsh actor and singer born on June 1, 1947, in Mostyn, Wales. He trained at the Royal Academy of Dramatic Art (RADA) and rose to prominence in the 1970s through groundbreaking theatrical work, winning his first Tony Award for Comedians in 1977 and another for his iconic portrayal of the Engineer in the original West End and Broadway runs of Miss Saigon. Celebrated for his extraordinary range and magnetic intensity, Pryce transitioned seamlessly into a prolific film and television career, delivering memorable performances in acclaimed projects such as Brazil, Glengarry Glen Ross, Pirates of the Caribbean, Game of Thrones, and receiving an Academy Award nomination for Best Actor for his portrayal of Pope Francis in The Two Popes. In the James Bond franchise, Pryce starred as the primary villain Elliot Carver in the 1997 film Tomorrow Never Dies. He played a megalomaniacal media mogul and ruthless publishing baron who attempts to orchestrate a global war between the United Kingdom and China using manipulated news broadcasts and a stealth ship in order to secure exclusive broadcasting rights in the Chinese market.',
       'Welsh',
       '1947-06-01',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Michelle Yeoh (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2033616f-2a05-4f0d-abce-796701847683'),
       'Michelle Yeoh',
       'Wai Lin',
       'Michelle Yeoh is a celebrated international actress born on August 6, 1962, in Ipoh, Malaysia. Trained in ballet from a young age at the Royal Academy of Dance in London, her early aspirations of a professional dance career were cut short by a back injury. After winning the Miss Malaysia beauty pageant in 1983, she transitioned into the film industry, rising to fame in the 1980s and 1990s as a trailblazing star of Hong Kong action and martial arts cinema. Renowned for performing her own dangerous stunts, she starred in numerous high-profile action features such as Yes, Madam!, Police Story 3: Super Cop, and Wing Chun. Over a career spanning more than four decades, she achieved widespread global acclaim and historic milestones, including winning the Academy Award for Best Actress for her critically lauded performance in Everything Everywhere All at Once. In the James Bond franchise, Yeoh achieved international mainstream recognition by starring in the 1997 film Tomorrow Never Dies. She played Wai Lin, a skilled and resourceful spy for the People''s Republic of China''s Ministry of State Security. Breaking away from traditional portrayals of passive Bond characters, her role as Wai Lin featured her as an equal counterpart to James Bond, combining sharp intellect, advanced combat skills, and high-octane action capabilities as they worked together to thwart a media mogul''s scheme to instigate global conflict.',
       'Malaysian',
       '1962-08-06',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Teri Hatcher (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('dfff0b4f-8088-4ca8-a01e-cfa9f4d184e0'),
       'Teri Hatcher',
       'Paris Carver',
       'Teri Hatcher is a prominent American actress born on December 8, 1964, in Palo Alto, California. Before embarking on her acting career, she studied mathematics and engineering at De Anza College and trained in ballet and dance. Hatcher rose to widespread prominence in the 1990s through her iconic television role as Lois Lane in the hit series Lois & Clark: The New Adventures of Superman, which established her as a major television star. She later achieved a massive career resurgence playing Susan Mayer in the critically acclaimed and globally popular comedy-drama series Desperate Housewives, a role that earned her a Golden Globe Award and a Screen Actors Guild Award, cementing her status as a beloved staple of American television. In the James Bond franchise, Hatcher starred in the 1997 film Tomorrow Never Dies as Paris Carver, a glamorous former fashion model and the estranged wife of media mogul Elliot Carver. Her character shares a complex past romance with James Bond before being thrust back into his orbit when she assists him in gaining access to her husband''s heavily guarded media empire, leading to a tragic end as a pawn in Carver''s murderous plot.',
       'American',
       '1964-12-08',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Ricky Jay (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('f6e11a08-bda8-4968-b579-6435b158ab65'),
       'Ricky Jay',
       'Henry Gupta',
       'Ricky Jay was an exceptionally gifted American stage magician, actor, and writer born on June 26, 1946, in Brooklyn, New York. Widely considered one of the greatest sleight-of-hand artists and card mechanics in history, he was legendary for his astonishing memory, encyclopedic knowledge of magic history, and incredible card-throwing abilities that earned him a spot in the Guinness Book of World Records. Alongside his celebrated theatrical and literary career, Jay cultivated a distinctive parallel career as a character actor, frequently collaborating with acclaimed auteur directors like David Mamet and Paul Thomas Anderson in prominent films such as House of Games, The Spanish Prisoner, Magnolia, and Boogie Nights, bringing a quiet, highly intellectual intensity to every screen appearance. In the James Bond franchise, Ricky Jay appeared in the 1997 film Tomorrow Never Dies as Henry Gupta. He played a brilliant, cold-blooded American technocrat, cyber-terrorist, and technical consultant who works closely alongside the primary villain Elliot Carver, utilizing his advanced computer skills to manipulate global markets, disrupt satellite communications, and engineer a war between Britain and China before meeting a swift and ruthless end at Carver''s own hands.',
       'American',
       '1946-06-26',
       '2018-11-24',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Götz Otto (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('8b373885-a994-4607-837d-84ca53b92cd3'),
       'Götz Otto',
       'Stamper',
       'Götz Otto is a prominent German actor born on October 15, 1967, in Offenbach am Main, Germany. He studied acting at the prestigious Westphalian Drama School in Bochum and later trained at the Ernst Busch Academy of Dramatic Arts in Berlin. Standing at an imposing height of nearly two meters, Otto quickly established himself internationally, leveraging his towering physical presence and striking features to carve out a successful career playing formidable villains, soldiers, and authority figures in both European and Hollywood cinema. Over a prolific career spanning decades, he has appeared in numerous high-profile international productions, including Steven Spielberg''s Schindler''s List, the satirical sci-fi cult classic Iron Sky, and various acclaimed German television dramas. In the James Bond franchise, Götz Otto gained widespread global recognition for his role as Richard Stamper in the 1997 film Tomorrow Never Dies. He portrayed the ruthless, imposing, and sadistic henchman and chief security enforcer to the primary villain Elliot Carver. Physically intimidating and intensely loyal to Carver, Stamper was notorious for his brutal efficiency, proficiency in hand-to-hand combat, and his chilling use of a specialized electroshock torture device before meeting his dramatic demise during the film''s climactic finale aboard Carver''s stealth ship.',
       'German',
       '1967-10-15',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Vincent Schiavelli (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('888806a4-7f20-442f-b96e-f33097252c9e'),
       'Vincent Schiavelli',
       'Dr. Kaufman',
       'Vincent Schiavelli was a distinctive and prolific American character actor born on November 11, 1948, in Brooklyn, New York. Recognized instantly by his towering height, melancholic eyes, and uniquely expressive facial features, he studied acting at New York University''s School of the Arts before building a legendary career playing eccentric, memorable, and often deeply nuanced supporting characters across film, television, and stage. Schiavelli appeared in over one hundred film and television projects, creating indelible impressions in timeless classics such as One Flew Over the Cuckoo''s Nest, Fast Times at Ridgemont High, Ghost, Amadeus, and Batman Returns, while also showcasing his diverse talents as a food writer and cookbook author later in life. In the James Bond franchise, Schiavelli appeared in the 1997 film Tomorrow Never Dies as Dr. Kaufman. He portrayed a chillingly calm, polite, and methodical professional assassin who specializes in interrogation and torture under the guise of an analytical forensic scientist. Tasked by media mogul Elliot Carver with staging the apparent murder-suicide of James Bond and Paris Carver, Dr. Kaufman famously described his work as a professional "labor of love" before meeting an abrupt and witty end at the hands of Bond himself.',
       'American',
       '1948-11-11',
       '2005-12-26',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Geoffrey Palmer (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('012aba22-f692-44ab-8dcb-215f9d72f8d9'),
       'Geoffrey Palmer',
       'Admiral Roebuck',
       'Geoffrey Palmer was a beloved and distinguished English actor born on June 4, 1927, in London, England. Known instantly for his unique, deadpan delivery, impeccably proper demeanor, and unmistakable gravelly voice, he became an icon of British television comedy and drama. After serving in the Royal Marines, Palmer trained for the stage and built a prolific career spanning over six decades. He achieved widespread fame for starring in classic British sitcoms such as The Fall and Rise of Reginald Perrin and As Time Goes By, alongside memorable dramatic roles in films like Mrs. Brown and The Madness of King George, cementing his legacy as a master of understated wit and quintessential British charm. In the James Bond franchise, Geoffrey Palmer appeared in the 1997 film Tomorrow Never Dies as Admiral Roebuck. He portrayed a stern, impatient, and traditional senior Royal Navy officer who frequently clashed with M during military briefings. Representing the hawkish military establishment, Roebuck was quick to jump to conclusions regarding geopolitical threats and eager to deploy naval firepower, providing a sharp and formidable administrative foil to M and James Bond as they worked against Elliot Carver''s machinations.',
       'British',
       '1927-06-04',
       '2020-11-05',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Julian Fellowes (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('c0ffae72-5dec-4e91-b7c9-f25104f94869'),
       'Julian Fellowes',
       'Minister of defence',
       'Julian Fellowes is an acclaimed English actor, novelist, director, and screenwriter born on August 17, 1949, in Cairo, Egypt. Educated at Magdalene College, Cambridge, and trained at the Webber Douglas Academy of Dramatic Art, he initially established himself as a versatile character actor in British film and television. However, he achieved monumental global renown as a master writer and creator of period dramas, winning an Academy Award for Best Original Screenplay for Gosford Park and creating the critically acclaimed, worldwide television phenomenon Downton Abbey, alongside his work on the historical series The Gilded Age. In the James Bond franchise, Julian Fellowes appeared in the 1997 film Tomorrow Never Dies as the British Minister of Defence. He portrayed a high-ranking government official who participates in tense strategic briefings alongside M and Admiral Roebuck, managing the escalating geopolitical crisis orchestrated by media mogul Elliot Carver and deciding on military responses before James Bond resolves the threat.',
       'British',
       '1949-08-17',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Terence Rigby (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7479b3dd-249a-447f-8f9a-b3276c96c66d'),
       'Terence Rigby',
       'General Bukharin',
       'Terence Rigby was a distinguished English actor born on January 2, 1937, in Erdington, Birmingham, England. Trained at the Royal Academy of Dramatic Art (RADA) after completing his national service in the Royal Air Force, he established a prolific and respected career spanning theatre, television, and film. Recognized for his versatility and strong screen presence, Rigby became a familiar face in British culture through memorable television roles—such as PC Snow in the long-running crime series Softly, Softly: Task Force and playing Dr. Watson opposite Tom Baker in a BBC adaptation of The Hound of the Baskervilles. He also built an impressive film resume with standout appearances in critically acclaimed features like Get Carter, Elizabeth, and Mona Lisa Smile. In the James Bond franchise, Terence Rigby appeared in the 1997 film Tomorrow Never Dies as General Bukharin. He portrayed a Russian military liaison officer present in the British Situation Room during the film''s opening sequence. As a Russian representative collaborating with M and Admiral Roebuck, General Bukharin reacts with alarm when a rogue terrorist aircraft is discovered carrying a dangerous Soviet nuclear payload, adding tension to the high-stakes geopolitical situation before James Bond intercepts the threat.',
       'British',
       '1937-01-02',
       '2008-08-10',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Cecilie Thomsen (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('c7a77002-8644-4e9f-9ce4-e6db95718fb8'),
       'Cecilie Thomsen',
       'Professor Inga Bergstrøm',
       'Cecilie Thomsen is a Danish actress and former model born on November 29, 1974, in Bodø, Norway. Raised primarily in Denmark, she began her career as a successful international fashion model, gracing runways and high-profile magazine covers before transitioning into acting in the mid-1990s. Her striking presence and international background allowed her to secure various roles in European and American film and television productions, including appearances in the Danish comedy Hannibal & Jerry and the comedy feature The Boys from County Clare. Outside of her acting and modeling career, she gained broader cultural recognition through her high-profile personal life, notably a multi-year relationship with rock star Bryan Adams during the 1990s. In the James Bond franchise, Cecilie Thomsen appeared in the 1997 film Tomorrow Never Dies as Professor Inga Bergstrøm. She portrayed a Danish linguistic and nuclear physics professor who is romantically involved with James Bond at the beginning of the film. Introduced in a remote Oxford cabin where 007 is ostensibly meant to be enjoying a quiet academic getaway, her character provides the setup for a humorous interruption when M contacts Bond via his special car to pull him away for his next mission.',
       'Danish',
       '1974-10-29',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Nina Young (Tomorrow Never Dies)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('8d09ff0f-2f2c-4a4a-ab70-9495c6b7bdc9'),
       'Nina Young',
       'Tamara Steel',
       'Nina Young is an accomplished Australian actress born on October 12, 1966, in the United States to Australian parents, though she grew up primarily in Sydney, Australia. She later moved to the United Kingdom to pursue formal training at the prestigious Central School of Speech and Drama. Since then, she has built a robust and versatile career spanning film, television, and theatre. Her notable screen credits include prominent roles in major feature films such as Johnny English, Harry Potter and the Philosopher''s Stone, and The Man Who Knew Too Little, alongside extensive television work in popular British dramas and comedies. In the James Bond franchise, Nina Young appeared in the 1997 film Tomorrow Never Dies as Tamara Steel. She portrayed a glamorous assistant to media mogul Elliot Carver, working at his Hamburg headquarters during the launch of the Carver Media Group Network. Her character interacts briefly with James Bond when he infiltrates the building under an alias, adding to the corporate espionage and intrigue of the film''s early acts before Carver''s sinister operations are fully exposed.',
       'Australian',
       '1966-04-12',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Colin Salmon (Tomorrow Never Dies, The World Is not Enough, Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('5e6de3cf-ac7a-4e1c-9894-0b7cd4928788'),
       'Colin Salmon',
       'Charles Robinson',
       'Colin Salmon is a distinguished British actor born on December 6, 1962, in Bethnal Green, London, England. Before embarking on his acting career, he spent time as a touring musician and percussionist. Standing at an imposing height and possessing a resonant, deeply commanding voice alongside an undeniable screen presence, Salmon transitioned into acting and quickly became a prominent fixture in British and international film and television. Over his extensive career, he has built a reputation for portraying authoritative, capable, and dignified characters, earning critical acclaim and fan devotion across major franchises and high-profile projects, including Resident Evil, Arrow, Doctor Who, EastEnders, and the acclaimed series Limitless. In the James Bond franchise, Colin Salmon is widely recognized for playing Charles Robinson, the steadfast Chief of Staff to M. He portrayed the role across three consecutive films in the Pierce Brosnan era: Tomorrow Never Dies in 1997, The World Is Not Enough in 1999, and Die Another Day in 2002. As Robinson, Salmon provided a calm, professional, and reliable military and administrative backbone for MI6 headquarters, frequently assisting M, Bond, and Tanner during crisis management, mission briefings, and field coordination.',
       'British',
       '1962-12-06',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Sophie Marceau (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9bc6394b-a3c1-4532-9c90-8964b1f05236'),
       'Sophie Marceau',
       'Elektra King',
       'Sophie Marceau is an acclaimed French actress, director, screenwriter, and author born on November 17, 1966, in Paris, France. She rose to superstardom as a teenager following her film debut in the massively successful French coming-of-age comedy La Boum (1980), for which she won the César Award for Most Promising Actress for its sequel. Quickly transitioning into a major European star, Marceau successfully expanded into international cinema with prominent roles in historical epics and dramas like Mel Gibson''s Braveheart (1995), Firelight (1997), and Anna Karenina (1997). Known for her striking beauty, versatility, and commanding screen presence, she has remained a dominant figure in French and global cinema for decades. In the James Bond franchise, Sophie Marceau starred in the 1999 film The World Is Not Enough as Elektra King. Breaking away from traditional Bond character tropes, she played a wealthy oil heiress who was initially introduced as a vulnerable kidnap victim that James Bond is assigned to protect. In a dramatic twist, her character is revealed to be the main mastermind and villain of the film, having formed a twisted alliance with her former captor Renard, making her one of the most complex and memorable antagonists in the series.',
       'French',
       '1966-11-17',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Robert Carlyle (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6950200c-b57a-44cb-ad10-f8ed8ebffc9e'),
       'Robert Carlyle',
       'Victor "Renard" Zokas',
       'Robert Carlyle is a celebrated Scottish actor born on April 14, 1961, in Glasgow, Scotland. Raised in a working-class background, he left school at a young age to work as a painter and decorator before discovering a passion for acting during his twenties. He trained at the Royal Scottish Academy of Music and Drama (RSAMD) and co-founded the Raindog theatre company in 1991. Carlyle achieved international renown and critical acclaim in the mid-1990s through a series of powerful, transformative performances in landmark British films such as Trainspotting, The Full Monty (for which he won a BAFTA Award for Best Actor in a Leading Role), and Riff-Raff. Known for his intense preparation, emotional depth, and ability to inhabit complex, volatile characters, he has maintained a prolific career spanning independent dramas, blockbusters, and acclaimed television series like Once Upon a Time and Stargate Universe. In the James Bond franchise, Robert Carlyle starred in the 1999 film The World Is Not Enough as Victor "Renard" Zokas, the film''s principal physical antagonist. He portrayed an ex-KGB agent turned anarchist terrorist who was shot in the head by MI6 years earlier, leaving a bullet lodged in his brain. This injury caused a unique neurological condition that rendered him completely impervious to physical pain while slowly destroying his sensory functions and leading to his eventual death. Driven by a fanatical obsession and a complex romantic manipulation by Elektra King, Renard plots to detonate a nuclear submarine in the waters of Istanbul, forcing James Bond into a deadly battle of attrition against an adversary who cannot feel the injuries inflicted upon him.',
       'Scottish',
       '1961-04-14',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Denise Richards (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('759cfef3-e8b6-4d80-af40-5415509323c6'),
       'Denise Richards',
       'Dr. Christmas Jones',
       'Denise Richards is an American actress and former fashion model born on February 17, 1971, in Downers Grove, Illinois. She grew up primarily in California and began her career in the entertainment industry as a model, appearing in numerous print ads and commercials before transitioning into television and film acting during the early 1990s. She achieved her breakthrough mainstream recognition with a prominent starring role as Carmen Ibanez in Paul Verhoeven''s sci-fi satire Starship Troopers (1997), followed by a critically acclaimed performance as the seductive and manipulative Kelly Van Ryan in the erotic thriller Wild Things (1998). Known for her striking appearance and pop-culture visibility, she has maintained a steady career across film and television, including reality TV appearances and diverse acting roles. In the James Bond franchise, Denise Richards starred in the 1999 film The World Is Not Enough as Dr. Christmas Jones, a nuclear physicist assigned to assist James Bond. She portrayed a brilliant and athletic specialist tasked with dismantling a stolen nuclear warhead in the oil pipelines of Azerbaijan. Despite her crucial role in helping neutralize the crisis orchestrated by Elektra King and Renard, her character became famous for a heavily scrutinized pun delivered by Bond during the film''s final moments, cementing her status as one of the most recognizable and debated Bond girls of the late 1990s era.',
       'American',
       '1971-02-17',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Cleese (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('562b23ec-ce34-4854-9b23-65e59c18b533'),
       'John Cleese',
       'R. (Q''s assistant',
       'John Cleese is an iconic English comedian, actor, writer, and producer born on October 27, 1939, in Weston-super-Mare, Somerset. He rose to international prominence during the 1960s as a founding member of the legendary comedy troupe Monty Python, co-writing and starring in the groundbreaking television sketch show Monty Python''s Flying Circus as well as cinematic masterpieces like Monty Python and the Holy Grail and Life of Brian. Following his time with Python, Cleese achieved massive commercial and critical success by writing and starring in the classic sitcom Fawlty Towers and penning the screenplay for the globally acclaimed comedy film A Fish Called Wanda, which earned him an Academy Award nomination for Best Original Screenplay. Renowned for his towering height, manic energy, and signature deadpan delivery, he has enjoyed a prolific multi-decade career spanning stage, television, and major blockbusters. In the James Bond franchise, John Cleese joined the cast in the 1999 film The World Is Not Enough as Q''s eccentric junior assistant. Introduced as a brilliant yet slightly pompous technical specialist, his character is cheekily dubbed "R" by James Bond—prompting a dry exchange about the agent''s wit. Cleese brought his trademark comedic timing and sharp verbal sparring to Q Branch, eventually taking over the mantle of the franchise''s chief quartermaster, "Q," in the subsequent 2002 film Die Another Day following the passing of longtime series veteran Desmond Llewelyn.',
       'British',
       '1939-10-27',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Maria Grazia Cucinotta (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('f0dd4223-569c-4fd6-b409-364a2722e929'),
       'Maria Grazia Cucinotta',
       'Cigar Girl (Giulietta da Vinci)',
       'Maria Grazia Cucinotta is an acclaimed Italian actress, model, producer, and director born on July 27, 1968, in Messina, Sicily. She began her career as a fashion model before transitioning into acting, gaining widespread national prominence in Italy with her breakout role in Massimo Troisi''s Oscar-winning masterpiece Il Postino (1994). Her performance in the film catapulted her to international recognition, establishing her as a prominent symbol of classic Mediterranean beauty and talent. Over a prolific career spanning European and international cinema, she has expanded her repertoire to include film and television production, starring in numerous Italian comedies, dramas, and American projects, while also serving as a cultural ambassador for Italian cinema worldwide. In the James Bond franchise, Maria Grazia Cucinotta appeared in the 1999 film The World Is Not Enough as the infamous "Cigar Girl." She portrayed an assassin who attempts to assassinate James Bond in Bilbao, Spain, using a booby-trapped briefcase filled with money during a ransom delivery. Following a thrilling high-speed boat chase along the River Thames in London, her character is cornered by Bond inside the MI6 headquarters and ultimately chooses to detonate her own hot-air balloon rather than be captured, setting the explosive and high-stakes tone for the beginning of the film.',
       'Italian',
       '1968-07-27',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Goldie (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d5fa1f7f-54b3-4033-876f-03897afd1687'),
       'Goldie',
       'Mr. Bullion (Bull)',
       'Goldie, whose birth name is Clifford Joseph Price, is a prominent British music producer, DJ, artist, and actor born on September 19, 1965, in Walsall, England. He rose to international prominence during the 1990s as a pioneering and highly influential figure in the electronic music scene, heavily associated with the development of jungle, drum and bass, and breakbeat genres through acclaimed releases on his record label Metalheadz. Beyond his massive footprint in the music industry, he has achieved recognition as a visual artist and a versatile actor, making notable appearances in British television and film, including Guy Ritchie''s crime comedy Snatch. In the James Bond franchise, Goldie appeared in the 1999 film The World Is Not Enough portraying the henchman known as Bull, also referred to as Mr. Bullion. He played the gold-toothed and gold-haired bodyguard and enforcer to the ex-KGB agent Valentin Zukovsky, though he was secretly a double agent working alongside the villains Renard and Elektra King. His character is memorably confronted and shot by Zukovsky at the climax of the film after his betrayal is uncovered.',
       'British',
       '1965-09-19',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  David Calder (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('22d8b471-2d34-4a9b-b3c0-de2a0d63b5db'),
       'David Calder',
       'Sir Robert King',
       'David Calder is a distinguished and prolific Scottish stage, television, and film actor born on August 1, 1948, in Portsmouth, Hampshire. He trained at the prestigious Bristol Old Vic Theatre School and built a formidable reputation on the British stage, starring in numerous acclaimed productions with the Royal Shakespeare Company and the National Theatre. Over a career spanning more than four decades, Calder has established himself as a master of intense, authoritative, and versatile character roles across British television and international cinema, delivering memorable performances in major projects such as The Mummy, The Lost City of Z, and various high-profile BBC drama series. In the James Bond franchise, David Calder appeared in the 1999 film The World Is Not Enough as Sir Robert King, a wealthy oil tycoon and a close personal friend of M. His character serves as the emotional catalyst for the film''s plot when he is brutally assassinated inside the MI6 headquarters by a disguised explosive device hidden within a suitcase of ransom money delivered by the Cigar Girl, plunging M and James Bond into a deeply personal investigation to protect his surviving daughter, Elektra King.',
       'British',
       '1946-08-01',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Serena Scott Thomas (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('6167c16d-68e8-49a7-a10d-5143adb1b850'),
       'Serena Scott Thomas',
       'Dr. Molly Warmflash',
       'Serena Scott Thomas is a talented English actress born on September 21, 1961, in Nether Wallop, Hampshire. She trained for the stage at the prestigious Bristol Old Vic Theatre School, following in the footsteps of a long line of performers, and is the sister of fellow acclaimed actress Kristin Scott Thomas. Throughout her career, she has built a diverse resume spanning British and American television series, miniseries, and feature films. She is widely recognized for her memorable portrayals of real-life historical figures and aristocrats, including her acclaimed performance as Diana, Princess of Wales, in the biographical television film Diana: Her True Story, alongside guest-starring roles in various popular American television dramas. In the James Bond franchise, Serena Scott Thomas appeared in the 1999 film The World Is Not Enough as Dr. Molly Warmflash, an MI6 medical officer and psychologist stationed at the agency. Her character has a brief romantic rendezvous with James Bond while evaluating his physical and psychological fitness for active field duty, ultimately passing him fit to return to service despite lingering injuries. However, it is later revealed that she has been compromised and manipulated by the film''s primary antagonist, Elektra King, unknowingly aiding the villains in their larger plot against MI6.',
       'British',
       '1961-09-19',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Ulrich Thomsen (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('797db764-0023-4d01-acb4-fd37155d7d47'),
       'Ulrich Thomsen',
       'Davidov',
       'Ulrich Thomsen is an acclaimed Danish actor born on December 6, 1963, in Odense, Denmark. He graduated from the Danish National School of Theatre in 1993 and quickly rose to prominence in Scandinavian cinema, earning international recognition for his breakthrough performance in Thomas Vinterberg’s critically acclaimed 1998 Dogme 95 film Festen (The Celebration). Known for his intense screen presence, versatility, and ability to portray complex, often morally ambiguous characters, Thomsen has maintained a prolific career spanning European art-house cinema, Hollywood blockbusters, and high-profile television series, including notable roles in The Thing, Banshee, and the Danish political drama Borgen. In the James Bond franchise, Ulrich Thomsen appeared in the 1999 film The World Is Not Enough as Davidov, the ruthless head of security and trusted henchman for the villain Renard. His character operates primarily in the oil pipeline regions of the Caucasus, overseeing operations and enforcing security for Elektra King''s empire, before being tracked down and killed by James Bond, who subsequently assumes his identity to infiltrate a high-security Russian nuclear ICBM base.',
       'Danish',
       '1963-12-06',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Seru (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('a94d0fdf-2a20-4f0b-acfd-5732f97768ac'),
       'John Seru',
       'Gabor',
       'John Seru is an accomplished actor, television personality, and former professional wrestler born on January 12, 1964. Standing at an imposing height with a powerful athletic background, he initially gained widespread fame and international recognition under the ring name Vulcan as a star competitor on both the Australian and British versions of the hit television series Gladiators. His dominant physical presence and background in professional wrestling—having trained at the renowned Malenko Wrestling Academy—paved the way for his transition into television and film, where he has taken on various supporting roles in projects spanning action and drama. In the James Bond franchise, John Seru appeared in the 1999 film The World Is Not Enough as Gabor, the fiercely loyal head bodyguard and henchman to the villainous Elektra King. His character utilizes his formidable physical stature to oversee security and protect Elektra at her oil installations and stronghold, remaining steadfastly by her side until he is ultimately eliminated during the film''s climactic confrontation at the maiden''s tower in Istanbul.',
       'Fijian-British',
       '1960-03-29',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Claude-Oliver Rudolph (The World Is Not Enough)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('d56958a1-c3fe-4b99-a33f-13c8560c08e4'),
       'Claude-Oliver Rudolph',
       'Colonel Akakievich',
       'Claude-Oliver Rudolph is a prominent German actor, screenwriter, director, and producer born on November 30, 1956, in Frankfurt am Main, West Germany. He grew up in Bochum, where he developed an early passion for film, starting to shoot amateur films as a teenager before being discovered as a stage actor by renowned director Peter Zadek. He further honed his craft by studying philosophy, psychology, and dramatics, and by attending the prestigious Actor’s Studio in New York. Over a prolific career spanning decades, Rudolph has established a strong reputation in European cinema and television, gaining international early recognition with a supporting role in Wolfgang Petersen''s legendary war masterpiece Das Boot and subsequently appearing in numerous German productions, crime dramas, and directing projects. In the James Bond franchise, Claude-Oliver Rudolph appeared in the 1999 film The World Is Not Enough as Colonel Akakievich. His character is a Russian military officer stationed at an ICBM silo site who interacts with James Bond during the narrative''s intense operations involving stolen nuclear material and international security threats.',
       'German',
       '1956-11-30',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  John Cleese (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7d0cd58d-12bd-493e-bc9d-c530944e7063'),
       'John Cleese',
       'Q.',
       'John Cleese is an iconic English comedian, actor, writer, and producer born on October 27, 1939, in Weston-super-Mare, Somerset. He rose to international prominence during the 1960s as a founding member of the legendary comedy troupe Monty Python, co-writing and starring in the groundbreaking television sketch show Monty Python''s Flying Circus as well as cinematic masterpieces like Monty Python and the Holy Grail and Life of Brian. Following his time with Python, Cleese achieved massive commercial and critical success by writing and starring in the classic sitcom Fawlty Towers and penning the screenplay for the globally acclaimed comedy film A Fish Called Wanda, which earned him an Academy Award nomination for Best Original Screenplay. Renowned for his towering height, manic energy, and signature deadpan delivery, he has enjoyed a prolific multi-decade career spanning stage, television, and major blockbusters. In the James Bond franchise, John Cleese joined the cast in the 1999 film The World Is Not Enough as Q''s eccentric junior assistant. Introduced as a brilliant yet slightly pompous technical specialist, his character is cheekily dubbed "R" by James Bond—prompting a dry exchange about the agent''s wit. Cleese brought his trademark comedic timing and sharp verbal sparring to Q Branch, eventually taking over the mantle of the franchise''s chief quartermaster, "Q," in the subsequent 2002 film Die Another Day following the passing of longtime series veteran Desmond Llewelyn.',
       'British',
       '1939-10-27',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Halle Berry (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('2227edca-e74c-49d2-8155-6fa072c966a1'),
           'Halle Berry',
           'Giacinta "Jinx" Johnson',
           'Halle Berry is an iconic American actress and former model born on August 14, 1966, in Cleveland, Ohio. Before launching her successful acting career, she achieved notable success in beauty pageants, finishing as the first runner-up in the 1986 Miss USA pageant and competing in Miss World. Transitioning to television and film, she quickly rose to prominence with breakout roles in Spike Lee''s Jungle Fever and the romantic comedy Boomerang. Over a stellar career, Berry made history by becoming the first and only African-American woman to win the Academy Award for Best Actress, which she earned for her powerful performance in the 2001 romantic drama Monster''s Ball. Alongside her Oscar-winning prestige, she has cemented her status as a versatile Hollywood superstar through high-profile blockbusters, including playing the mutant superhero Storm in the X-Men film series. In the James Bond franchise, Halle Berry starred in the 2002 milestone film Die Another Day as Giacinta "Jinx" Johnson, an elite and lethal NSA operative. Her character is a fiercely independent and capable secret agent who crosses paths with James Bond in Cuba while investigating a rogue North Korean colonel, famously recreating Ursula Andress''s iconic ocean-emerging scene from Dr. No and proving to be an equal match for 007 in both action and espionage.',
           'American',
           '1966-08-14',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Rosamund Pike (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('b74d1068-83ca-4bb6-a958-d9664deaa016'),
           'Rosamund Pike',
           'Miranda Frost',
           'Rosamund Pike is a critically acclaimed English actress born on January 27, 1979, in London, England. She studied English Literature at Wadham College, Oxford, while actively honing her craft through various stage productions with the National Youth Theatre. She achieved international recognition and critical acclaim early in her film career with her breakout role as the sophisticated yet deceitful MI6 double agent Miranda Frost in the James Bond franchise. Over the decades, Pike has established herself as a powerhouse actress capable of portraying chillingly complex, razor-sharp, and multi-dimensional characters across independent cinema and major Hollywood features, earning a nomination for the Academy Award for Best Actress for her mesmerizing and terrifying performance as Amy Dunne in David Fincher''s psychological thriller Gone Girl. In the James Bond franchise, Rosamund Pike appeared in the 2002 film Die Another Day as Miranda Frost, an undercover MI6 agent and fencing champion who is secretly working as a double agent for the villainous North Korean operative Gustav Graves. Her character initially appears to be an ally and romantic interest for James Bond during his mission in London and Iceland, but her true loyalties are ultimately exposed when she betrays 007, leading to a tense, high-stakes sword duel and final confrontation aboard Graves'' cargo plane.',
           'British',
           '1979-01-27',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Toby Stephens (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('31105519-ccd8-4de8-9ff2-db0a481ba1e4'),
           'Toby Stephens',
           'Gustav Graves',
           'Toby Stephens is a highly accomplished English stage, television, and film actor born on April 21, 1969, in London, England. Coming from a prestigious acting family as the son of legendary actress Dame Maggie Smith and actor Sir Robert Stephens, he trained at the prestigious London Academy of Music and Dramatic Art (LAMDA). Stephens quickly established himself as a formidable classical actor, becoming one of the youngest actors ever to play major leading roles with the Royal Shakespeare Company. Over a diverse and prolific career, he has earned immense respect for his commanding stage presence and versatility, starring in critically acclaimed period dramas, psychological thrillers, and television series such as Jane Eyre, Black Sails, and Lost in Space. In the James Bond franchise, Toby Stephens appeared in the 2002 film Die Another Day as Gustav Graves, the charismatic, eccentric, and ruthless British billionaire industrialist who is secretly the transformed persona of Colonel Tan-Sun Moon, a rogue North Korean officer. His character serves as the film''s primary antagonist, developing a revolutionary orbital weapon system named Icarus and using his public persona to conceal his terrorist ambitions, ultimately engaging James Bond in a high-tech armor suit and sword battle before his scheme is thwarted.',
           'British',
           '1969-04-21',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Rick Yune (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('2fa40fda-7dc7-4126-9398-20de242fd7de'),
           'Rick Yune',
           'Zao',
           'Rick Yune is an American actor, screenwriter, producer, and former model born on August 22, 1971, in Washington, D.C. Before transitioning to acting, he earned a degree in finance from the Wharton School of the University of Pennsylvania, worked on Wall Street as a hedge fund trader, and became a successful fashion model who worked with top global brands. Deeply trained in martial arts, holding Olympic-level credentials in Taekwondo and a black belt in Hapkido, Yune leveraged his athletic skills to break into Hollywood, making his impressive feature film debut as a charismatic gang leader in the critically acclaimed crime drama Snow Falling on Cedars. He quickly rose to mainstream international prominence by starring as the ruthless villain Johnny Tran in the blockbuster hit The Fast and the Furious before securing his iconic role in the James Bond franchise. In the James Bond franchise, Rick Yune appeared in the 2002 film Die Another Day as Zao, a brutal and enigmatic North Korean terrorist and mercenary. His character is recognizable by his striking appearance featuring diamonds embedded in his face from an explosion, serving as the primary henchman to Gustav Graves and tangling with 007 in intense action sequences spanning from North Korea to Iceland.',
           'American',
           '1971-08-22',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Michael Madsen (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('da98087a-5a62-45e7-901e-9dd31374d298'),
           'Michael Madsen',
           'Damian Falco',
           'Michael Madsen is a legendary American actor, poet, and photographer born on September 25, 1957, in Chicago, Illinois. He began his acting career in the Chicago theater scene, studying under legendary acting coach Joyce Piven before transitioning to film and television in the early 1980s. Madsen became internationally renowned for his striking screen presence, gravelly voice, and penchant for playing tough, enigmatic, and morally ambiguous antiheroes. He achieved legendary status in Hollywood through his memorable collaborations with director Quentin Tarantino, most notably delivering an iconic, chilling performance as the sadistic torturer Mr. Blonde in Reservoir Dogs, as well as starring roles in Kill Bill, The Hateful Eight, and Ridley Scott''s classic road film Thelma & Louise. In the James Bond franchise, Michael Madsen appeared in the 2002 film Die Another Day as Damian Falco, a high-ranking senior National Security Agency (NSA) official. His character represents the American intelligence apparatus, working alongside M and British authorities, and initially clashes with MI6 over jurisdiction and handling operations before playing a key role in the oversight of international security matters surrounding the rogue activities of Gustav Graves and Zao.',
           'American',
           '1957-09-25',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Will Yun Lee (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('27ea5dcf-c609-4722-948f-ed23c6b092c3'),
           'Will Yun Lee',
           'Colonel Tan-Sun Moon',
           'Will Yun Lee is a prominent American actor and martial artist born on March 22, 1971, in Arlington, Virginia. Raised in a family with deep martial arts roots by his taekwondo grandmaster father, Lee grew up training extensively in combat arts, which later paved the way for his athletic and dynamic screen presence. He attended the University of California, Berkeley, where he studied political science and ethnic studies before turning his focus entirely to acting. Lee quickly established himself as a recognizable face in television and film during the late 1990s and early 2000s, landing notable roles in series like Witchblade and blockbuster films before achieving major international recognition with his appearance in the James Bond franchise. Over his prolific career, he has continued to build a diverse resume with prominent roles in hit projects such as The Wolverine, San Andreas, Altered Carbon, and The Good Doctor. In the James Bond franchise, Will Yun Lee appeared in the 2002 film Die Another Day as Colonel Tan-Sun Moon, a ruthless and arrogant rogue North Korean military officer. His character serves as the primary instigator of the film''s opening sequence, smuggling weapons and clashing with 007 in a high-speed hovercraft chase before apparently perishing, only to secretly undergo gene therapy and resurface later in the narrative as the wealthy British industrialist Gustav Graves.',
           'American',
           '1971-03-22',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Kenneth Tsang (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('f2928cf3-fa5f-41b8-b77f-ecbf5bedf8d4'),
           'Kenneth Tsang',
           'General Moon',
           'Kenneth Tsang was a renowned and prolific Hong Kong actor whose career spanned nearly seven decades, featuring roles across Cantonese dramas, martial arts cinema, and major international blockbusters. Born in Shanghai, China, he studied architecture at the University of California, Berkeley, before returning to Hong Kong where his entry into the film industry was facilitated through connections in the entertainment world. Over the years, Tsang established himself as a prominent screen presence, gaining widespread international recognition for his memorable supporting roles in contemporary action and crime pictures directed by John Woo, as well as transitioning into Hollywood productions. In the James Bond franchise, Kenneth Tsang appeared in the 2002 film Die Another Day as General Moon. His character is a high-ranking military official in the North Korean army and the father of Colonel Tan-Sun Moon, serving as a more moderate military figure within the narrative before his son''s rogue actions and transformation into Gustav Graves set the film''s central plot in motion.',
           'Hong Kong',
           '1935-09-02',
           '2022-04-27',
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Emilio Echevarría (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('e3048a5e-775e-4ee0-9505-120ba6064a5a'),
           'Emilio Echevarría',
           'Raoul',
           'Emilio Echevarría was a veteran Mexican film and theatre actor who became widely known internationally for his powerful performances in cinema. Beginning his acting career in theatre in the late 1970s, he transitioned to film in the 1980s and achieved broad international recognition with his unforgettable role as the vagrant El Chivo in Alejandro González Iñárritu''s Oscar-nominated drama Amores Perros. Over a distinguished career, Echevarría established himself as a prominent fixture in Mexican and international cinema, taking on notable roles in acclaimed productions such as Alfonso Cuarón''s Y Tu Mamá También, Iñárritu''s Babel, and the historical western The Alamo. In the James Bond franchise, Emilio Echevarría appeared in the 2002 film Die Another Day as Raoul. His character is a cigar factory manager based in Havana, Cuba, who secretly operates as a British sleeper agent, assisting James Bond by providing crucial intelligence and access during 007''s investigation into Zao.',
           'Mexican',
           '1944-07-03',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Michael Gor (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('12ba1cef-7480-4689-ac8b-b7023c387d51'),
           'Michael Gor',
           'Vladimir "Vlad" Popov',
           'Michael Gor, credited professionally in English-language productions from his birth name Mikhail Vitalievich Gorevoy, is a Russian actor, director, and teacher born on May 19, 1965, in Moscow, Russia. He graduated with honors from the prestigious Moscow Art Theater School in 1987 and began his professional career on stage with the Sovremennik Theatre. Following his film debut in the late 1980s, he spent several years living in the United States during the 1990s, where he taught the Stanislavski method before returning to Russia to establish his own theater and expand a prolific screen career. Internationally, he has become widely recognized for his versatile supporting roles in major Hollywood and European productions, including Steven Spielberg''s historical drama Bridge of Spies and the action thriller Hunter Killer. In the James Bond franchise, Michael Gor appeared in the 2002 film Die Another Day as Vladimir "Vlad" Popov. His character serves as the chief scientist and head inventor working for the villainous billionaire Gustav Graves, operating out of the ice palace in Iceland and engineering advanced technology for the narrative''s central conflicts.',
           'Israeli',
           '1964-07-10',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Lawrence Makoare (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('6c5f92d4-9723-414f-89f3-99616c33894d'),
           'Lawrence Makoare',
           'Mr. Kil',
           'Lawrence Makoare is a prominent New Zealand actor born on March 20, 1968, in Bastion Point, Auckland, New Zealand. Before transitioning into acting and stunt work, he worked in road construction and drifted into the entertainment industry after accompanying a partner to a drama class, where a teacher noticed his striking physical presence. He quickly built a reputation for intense, highly physical screen roles, achieving massive international fame for portraying formidable antagonists under heavy prosthetic makeup in Peter Jackson''s blockbuster film trilogies, most notably playing the Uruk-hai leader Lurtz and the Witch-king of Angmar in The Lord of the Rings series, as well as Bolg in The Hobbit series. In the James Bond franchise, Lawrence Makoare appeared in the 2002 film Die Another Day as Mr. Kil. His character serves as a brutal and imposing henchman working for the villainous industrialist Gustav Graves, utilizing his intimidating physical stature during confrontations with James Bond before meeting his demise.',
           'New Zealander',
           '1968-03-20',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Rachel Grant (Die Another Day)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('0e82046c-10d4-4e2d-a8bd-8fb4d2b7ce40'),
           'Rachel Grant',
           'Peaceful Fountains of Desire',
           'Rachel Grant is a British actress, television presenter, and writer born on February 16, 1974, in the Philippines, with a heritage that includes Filipino royalty from her mother''s side. Raised primarily in the United Kingdom, she pursued training in performing arts before embarking on a diverse career that spans television, theatre, and travel journalism, earning recognition as a prominent host and explorer. Beyond her acting projects, she has gained global acclaim for her adventurous expeditions, holding a Guinness World Record for the deepest theatrical performance ever staged, which she conducted deep inside an underground cavern in 2013. In the James Bond franchise, Rachel Grant appeared in the 2002 film Die Another Day as Peaceful Fountains of Desire. Her character is a massage therapist and undercover MI6 agent operating out of a health club in Hong Kong, who briefly assists James Bond and provides him with a concealed communication device at the beginning of the film.',
           'British',
           '1975-09-15',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Eva Green (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('6cc55076-10e4-42b3-afa9-07634d7b0dc9'),
           'Eva Green',
           'Vesper Lynd',
           'Eva Green is a celebrated French actress and model born on July 6, 1980, in Paris, France, to actress Marlène Jobert and dentist Walter Green. Developing an early passion for acting after seeing a performance by Isabelle Adjani, she studied at the Cours Florent in Paris before continuing her training at the Webber Douglas Academy of Dramatic Art in London and the Tisch School of the Arts in New York. She made her celebrated theatrical debut on the Paris stage before catching the eye of acclaimed director Bernardo Bertolucci, who cast her in his erotic drama The Dreamers in 2003. Green quickly established a reputation for playing intense, enigmatic, and magnetically complex characters, transitioning seamlessly into major international film and television projects. Her striking screen presence and willingness to embrace dark, otherworldly, or fiercely independent roles have earned her a devoted global following and critical acclaim across diverse genres, ranging from fantasy and horror to historical drama. In the James Bond franchise, Eva Green starred in the 2006 film Casino Royale as Vesper Lynd. Her character is a subtle and sharp treasury agent assigned to oversee the government funds used by James Bond in a high-stakes poker tournament in Montenegro, serving as both a professional adversary and the profound romantic catalyst who permanently alters Bond''s emotional life and worldview.',
           'French',
           '1980-07-06',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Mads Mikkelsen (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('0751e4c4-c98b-47d2-a549-6ce0d288fc6f'),
           'Mads Mikkelsen',
           'Le Chiffre',
           'Mads Mikkelsen is an acclaimed Danish actor born on November 22, 1965, in Copenhagen, Denmark. Before establishing himself as one of Europe''s most distinctive and versatile screen actors, he spent nearly a decade working as a professional gymnast and dancer, studying ballet in Sweden before fully transitioning into acting by enrolling at the Århus Theatre School in his early thirties. He rose to prominence in Danish cinema through a string of gritty and memorable performances, including his breakout role in Nicolas Winding Refn''s crime thriller Pusher and acclaimed turns in local hits like The Green Butchers and Adam''s Apples. Mikkelsen quickly cultivated an international reputation for his intense screen presence, magnetic composure, and willingness to tackle complex characters, paving the way for a stellar global career that has encompassed major studio franchises, prestigious European dramas, and television acclaim—including winning the Best Actor Award at the Cannes Film Festival for The Hunt and leading the psychological thriller series Hannibal. In the James Bond franchise, Mads Mikkelsen starred in the 2006 film Casino Royale as Le Chiffre. His character is a ruthless and mathematically brilliant private banker who finances global terrorist organizations, memorably distinguished by a medical condition causing him to weep blood and serving as James Bond''s primary intellectual and psychological adversary during a high-stakes poker game in Montenegro.',
           'Danish',
           '1965-11-22',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Caterina Murino (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('ff32f01e-ce24-417b-82fd-8b00404b0ba3'),
           'Caterina Murino',
           'Solange Dimitrios',
           'Caterina Murino is a talented Italian actress born on September 15, 1977, in Cagliari, Sardinia, Italy. Initially pursuing a career in medicine, she shifted her focus toward modeling before finding her true calling in the dramatic arts, studying acting under the esteemed director Francesca de Sapio at the Film and Theatre Academy of Studio Cinema in Rome. She began her career on the Italian stage and in television before achieving international recognition with a standout performance in the César-winning French comedy The Corsican File in 2004. Murino has since cultivated a diverse global film and television career, celebrated for her striking elegance, multilingual fluency, and ability to bring depth to sophisticated dramatic characters across European and international productions. In the James Bond franchise, Caterina Murino appeared in the 2006 film Casino Royale as Solange Dimitrios. Her character is the unhappy and vulnerable wife of high-ranking terrorist associate Alex Dimitrios, who briefly crosses paths with James Bond in the Bahamas before tragically becoming a victim of Le Chiffre''s ruthless associates.',
           'Italian',
           '1977-09-15',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Simon Abkarian (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('cb594978-49c8-4ba6-a542-46a8b8bf70c5'),
           'Simon Abkarian',
           'Alex Dimitrios',
           'Simon Abkarian is a renowned French-Armenian actor born on March 5, 1962, in Gonesse, France, to Armenian parents who later relocated to Beirut, Lebanon. Fleeing the Lebanese Civil War during his youth, his family moved to Los Angeles, where he spent his teenage years and began exploring the theatrical arts before eventually returning to France in the mid-1980s. He trained extensively under renowned directors and established a formidable reputation in European theatre before breaking into international cinema, most notably through his acclaimed collaboration with director Robert Guédiguian in films like Marie-Jo and Her Two Lovers and The Army of Crime. Abkarian''s commanding screen presence, gravelly voice, and intense dramatic range have made him a sought-after presence in major international film and television productions spanning historical dramas, political thrillers, and action epics. In the James Bond franchise, Simon Abkarian appeared in the 2006 film Casino Royale as Alex Dimitrios. His character is a dangerous, high-ranking contractor and terrorist associate operating out of the Bahamas, known for his volatile temper, martial arts skills, and illicit dealings with international criminals before meeting his demise at the hands of James Bond.',
           'French',
           '1962-03-05',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Isaach De Bankolé (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('3614144b-6a18-48ab-baf0-0d53674e2605'),
           'Isaach De Bankolé',
           'Steven Obanno',
           'Isaach De Bankolé is a celebrated Ivoirian actor born on August 12, 1957, in Abidjan, Ivory Coast. He moved to France in his youth, where he pursued higher education and earned a master''s degree in mathematics and a degree in physics, while simultaneously studying acting at the Cours Simon and the École Nationale Supérieure des Arts et Techniques de le Théâtre in Paris. He quickly broke barriers in French cinema, winning the prestigious César Award for Most Promising Actor for his role in the 1986 comedy Black Mic Mac, becoming one of the first African actors to achieve major mainstream acclaim in Europe. Over a prolific and critically acclaimed career, De Bankolé has cultivated a reputation for his dignified, intense, and commanding screen presence, collaborating extensively with celebrated independent and auteur directors on acclaimed projects such as Chocolat, Manderlay, The Limits of Control, Black Panther, and Limbo. In the James Bond franchise, Isaach De Bankolé appeared in the 2006 film Casino Royale as Steven Obanno. His character is a high-ranking and formidable Lord''s Resistance Army leader who acts as a crucial client for Le Chiffre, traveling to Montenegro to entrust millions of dollars to the banker before discovering the funds have been lost in the poker tournament, leading to a brutal and violent confrontation with James Bond.',
           'Ivorian',
           '1957-08-12',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Ivana Milicevic (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('ab7eaf28-6a78-4459-bf7b-a1e2a312a7f0'),
           'Ivana Milicevic',
           'Valenka (Le Chiffres girlfriend)',
           'Ivana Miličević is a versatile actress and model born on April 26, 1974, in Sarajevo, Yugoslavia. She moved to the United States with her family at a young age, growing up in Detroit, Michigan, before relocating to Los Angeles following her high school graduation to pursue a professional performance career. Initially establishing success in modeling, she transitioned smoothly into acting, building an extensive resume across television and film. Over the decades, she has become widely recognized by audiences for her memorable work in major projects, including prominent television series like Banshee and The 100, alongside feature film appearances in comedies and thrillers. In the James Bond franchise, Ivana Miličević appeared in the 2006 film Casino Royale as Valenka. Her character is the quiet and loyal girlfriend and companion of the primary antagonist, Le Chiffre, accompanying him to the high-stakes poker tournament in Montenegro and observing the dangerous financial underworld surrounding the operation.',
           'American',
           '1974-04-26',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Tobias Menzies (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('227d99cb-a460-4378-96f0-0e378a981f29'),
           'Tobias Menzies',
           'Villiers',
           'Tobias Menzies is an English actor born on March 7, 1974, in Hammersmith, London. He attended the Royal Academy of Dramatic Art (RADA), graduating with a Bachelor of Arts degree in Acting in 1998. He has built a prolific and acclaimed career across theatre, television, and film, earning widespread international recognition for his versatile dramatic work. Some of his most prominent television roles include playing Marcus Junius Brutus in the historical drama series Rome, Edmure Tully in Game of Thrones, dual roles as Frank and Jonathan "Black Jack" Randall in Outlander, and Prince Philip, Duke of Edinburgh, in seasons three and four of The Crown, a performance for which he won a Primetime Emmy Award. In the James Bond franchise, Tobias Menzies appeared in the 2006 film Casino Royale as Villiers. His character serves as the capable, professional personal aide and assistant to M, supporting the head of MI6 and tracking intelligence details as James Bond navigates his early high-stakes missions.',
           'British',
           '1974-03-07',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Claudio Santamaria (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('dfff9127-54ef-41b3-bdf9-601aac1f3d6b'),
           'Claudio Santamaria',
           'Carlos',
           'Claudio Santamaria is an acclaimed Italian actor born on July 22, 1974, in Rome, Italy. He began his career in the entertainment industry as a voice actor and dubber before transitioning to stage and screen, quickly establishing himself as one of the most versatile and prominent performers of his generation in Italian cinema. Over a robust career spanning decades, he has worked with celebrated directors and earned numerous prestigious accolades, including a David di Donatello Award for Best Actor for his powerful performance in the crime drama They Call Me Jeeg. He is widely known for his ability to seamlessly shift between intense dramatic roles, dark thrillers, and commercial features. In the James Bond franchise, Claudio Santamaria appeared in the 2006 film Casino Royale as Carlos. His character is a dangerous terrorist bomber tasked with orchestrating a major attack at Miami International Airport, whose plot is ultimately intercepted and thwarted by James Bond during the film''s tense middle sequence.',
           'Italian',
           '1974-07-22',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Sebastien Foucan (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('4ecd3acf-1d7d-4084-8525-f30aace826e9'),
           'Sebastien Foucan',
           'Mollaka',
           'Sébastien Foucan is a French freerunner, actor, and the founder of freerunning, born on May 27, 1974, in Paris, France. Growing up in the Parisian suburbs, he developed an innovative approach to physical movement and urban exploration alongside childhood friends, helping to pioneer and shape the discipline of parkour before ultimately creating freerunning to incorporate greater self-expression, acrobatics, and individual creativity. He gained widespread international prominence through pioneering media projects, including prominent documentary features like Jump London, high-profile brand collaborations, and a featured role in music video and live tour performances with Madonna. In the James Bond franchise, Sébastien Foucan appeared in the 2006 film Casino Royale as Mollaka. His character is a nimble bomb maker and terrorist who is famously pursued by James Bond in an intense, gravity-defying parkour chase across a construction site and embassy in Madagascar during the film''s memorable opening sequence.',
           'French',
           '1974-05-27',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Malcolm Sinclair (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('7fe4ad3a-4b56-4cbf-b40d-342b2dea048d'),
           'Malcolm Sinclair',
           'Dryden',
           'Malcolm Sinclair is a distinguished English actor born on June 5, 1950, in London, England. A classically trained stage and screen veteran, he graduated from the prestigious Central School of Speech and Drama and went on to build a remarkably prolific career in British theatre, television, and film. He is particularly renowned for his extensive work with the Royal Shakespeare Company and the National Theatre, earning critical acclaim for his commanding stage presence, authoritative demeanor, and versatility in classic and contemporary drama. Beyond his theatrical achievements, he has maintained a steady presence in major television series and prestige feature films, portraying establishment figures, politicians, and high-ranking officials with distinct gravitas. In the James Bond franchise, Malcolm Sinclair appeared in the 2006 film Casino Royale as Dryden. His character is the corrupt MI6 section chief stationed in Prague, whose illegal activities and compromised loyalties force James Bond to execute him in a tense, stylish pre-credits sequence in order to secure his own promotion to 00 status.',
           'British',
           '1950-06-05',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Richard Sammel (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('b6e43235-ff3f-4c3c-b1c7-0c55232b9991'),
           'Richard Sammel',
           'Adolph Gettler',
           'Richard Sammel is a German actor born on October 13, 1960, in Heidelberg, West Germany. He pursued formal training in music and drama in Germany, acting and direction in France, and method acting in Italy. Fluent in multiple languages, he has built a prolific international career spanning over a hundred film and television productions, often renowned for portraying complex, authoritative, or menacing antagonists. Some of his most notable screen credits include Sergeant Werner Rachtman in Quentin Tarantino''s Inglourious Basterds, the vampire master Thomas Eichhorst in the television series The Strain, and roles in acclaimed features like Life Is Beautiful and Spencer. In the James Bond franchise, Richard Sammel appeared in the 2006 film Casino Royale as Adolph Gettler. His character is a ruthless, high-ranking operative and henchman associated with the organization''s financial network, who confronts James Bond and Vesper Lynd during the tense climax in Venice.',
           'German',
           '1960-10-13',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Ludger Pistor (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('aa31b80c-aca0-4c95-b45b-35e219693143'),
           'Ludger Pistor',
           'Mendel',
           'Ludger Pistor is a German actor born on March 16, 1959, in Recklinghausen, West Germany. Over a prolific career spanning decades, he has established a prominent presence across numerous German-language film and television productions, while also crossing over into major international and English-language feature films. Known for his versatile character work, some of his notable cinematic credits include Steven Spielberg''s Academy Award-winning Schindler''s List, Tom Tykwer''s acclaimed thriller Run Lola Run, Quentin Tarantino''s Inglourious Basterds, and X-Men: First Class. In the James Bond franchise, Ludger Pistor appeared in the 2006 film Casino Royale as Mendel. His character is the precise and professional Swiss banker who oversees the secure financial transfer of the massive poker tournament winnings won by James Bond.',
           'German',
           '1959-03-16',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Joseph Millson (Casino Royale)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('bd8fca5d-30eb-4643-9413-7295135eb5bc'),
           'Joseph Millson',
           'Carter',
           'Joseph Millson is an English actor born on April 27, 1970, in Berinsfield, Oxfordshire. He trained at the prestigious Mountview Academy of Theatre Arts and has since built a celebrated, prolific career spanning British theatre, television, and film. He is widely recognized for his extensive work with the Royal Shakespeare Company and the National Theatre, alongside starring roles in major television series such as Holby City, Peak Practice, Episodes, and The Last Kingdom. Known for his commanding stage presence and versatile dramatic range, he remains a prominent fixture across both classical theatrical productions and contemporary screen dramas. In the James Bond franchise, Joseph Millson appeared in the 2006 film Casino Royale as Carter. His character is an MI6 agent and field colleague who assists James Bond during the early, chaotic surveillance and infiltration operations in Madagascar before the mission escalates.',
           'British',
           '1970-04-27',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Daniel Craig (Casino Royale, Quantum Of Solace, Skyfall, Spectre, No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('28d5ae2d-85cb-4a9b-a09d-6ef1187a4258'),
       'Daniel Craig',
       'James Bond',
       'Daniel Craig is an acclaimed English actor born on March 2, 1968, in Chester, Cheshire, United Kingdom. Growing up with an early passion for the performing arts, he moved to Liverpool as a teenager and joined the Everyman Theatre before relocating to London to join the National Youth Theatre. He subsequently honed his craft at the prestigious Guildhall School of Music and Drama, graduating in 1991 alongside fellow notable actors. Craig began his professional career on the London stage and in television, steadily building a reputation for intense, character-driven performances. His major breakthrough arrived with the critically acclaimed 1996 BBC drama series Our Friends in the North, which showcased his formidable dramatic range and brought him widespread recognition across the United Kingdom. Throughout the late 1990s and early 2000s, Craig successfully transitioned into feature films, establishing himself as a versatile international screen presence. He took on diverse and challenging roles in independent dramas and major Hollywood studio projects alike, appearing in films such as Elizabeth, The Power of One, Lara Croft: Tomb Raider, and Sam Mendes''s period gangster drama Road to Perdition. His career gained significant momentum with his starring turn in the British crime thriller Layer Cake, which highlighted his ability to command the screen with a combination of cool intelligence and latent menace. This performance, alongside his compelling work in Steven Spielberg''s historical thriller Munich, caught the attention of producers looking for an actor capable of redefining one of cinema''s most legendary and enduring roles for a new generation. In 2005, Craig was announced as the sixth actor to officially portray Ian Fleming''s secret agent James Bond, a casting choice that initially sparked intense media debate before silencing critics entirely upon the release of his debut in the role. By bringing a gritty realism, emotional vulnerability, physical intensity, and psychological depth to the character, he successfully modernized the franchise and steered it in a bold new direction. His fifteen-year tenure as 007 became one of the most defining eras in the history of the long-running series, culminating in a historic sequence of five blockbuster films that achieved unprecedented critical acclaim and massive global box office success. Outside of his iconic work as the secret agent, Craig has continued to expand his cinematic legacy with celebrated performances, including playing the journalist Mikael Blomkvist in David Fincher''s The Girl with the Dragon Tattoo and starring as the eccentric master detective Benoit Blanc in Rian Johnson''s widely popular comedic mystery franchise Knives Out and its sequels. In the James Bond franchise, Daniel Craig established a continuous, serialized narrative arc across five successive films beginning with Casino Royale (2006). Directed by Martin Campbell, this film served as a gritty, character-driven reboot that depicted James Bond earning his 00 status and facing his first major trials, defined by a complex romance with treasury agent Vesper Lynd. He reprised the role in Quantum of Solace (2008), directed by Marc Forster, which followed a raw and vengeful Bond tracking down the secretive criminal organization responsible for Vesper''s tragic death. He returned in Sam Mendes''s Skyfall (2012), a critically and commercially historic film that explored Bond''s psychological resilience, his loyalty to M, and the hidden origins of his childhood home. He continued with Spectre (2015), which brought various threads of his previous missions together by revealing a global shadow syndicate orchestrated by his adoptive brother turned nemesis, Ernst Stavro Blofeld. Craig concluded his landmark tenure with No Time to Die (2021), directed by Cary Joji Fukunaga, a monumental and emotionally resonant blockbuster that pulled a retired Bond back into service to face a devastating global conspiracy, culminating in a definitive and historic conclusion to his defining era as the world''s most famous secret agent.',
       'British',
       '1968-03-02',
       NULL,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Jeffrey Wright (Casino Royale, Quantum Of Solace, No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('f1c740a6-a554-4b08-b850-0c42bffa45ff'),
           'Jeffrey Wright',
           'Felix Leiter',
           'Jeffrey Wright is a highly acclaimed American actor born on December 7, 1965, in Washington, D.C. He graduated from Amherst College, where he initially studied political science with the intention of pursuing a career in law before discovering a profound passion for acting and subsequently attending New York University''s Tisch School of the Arts. Wright established a stellar reputation on the stage, winning a Tony Award in 1994 for his brilliant portrayal of Belize in Tony Kushner''s landmark Broadway production Angels in America, a role he later reprised in the acclaimed HBO television adaptation. Over a distinguished career spanning film, television, and theatre, he has earned a reputation for transformative, intelligent, and deeply nuanced performances across an extraordinary range of genres, collaborating with visionary directors on projects like Basquiat, The Manchurian Candidate, The French Dispatch, The Batman, and earning an Academy Award nomination for his starring role in American Fiction. In the James Bond franchise, Jeffrey Wright made history by becoming the first actor to play CIA agent Felix Leiter across multiple consecutive films, beginning with his introduction in the 2006 reboot Casino Royale. His character is a dependable and savvy American intelligence officer who assists James Bond during his high-stakes mission at the poker tournament in Montenegro, a role Wright later reprised in Quantum of Solace (2008) and No Time to Die (2021), anchoring a loyal alliance between the CIA and MI6 throughout Craig''s tenure.',
           'American',
           '1965-12-07',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Jesper Christensen (Casino Royale, Quantum Of Solace, Spectre)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('924ca87d-ff54-4018-8e81-44fba83b8236'),
           'Jesper Christensen',
           'Mr. White',
           'Jesper Christensen is a highly respected Danish actor born on May 16, 1948, in Copenhagen, Denmark. A veteran of European cinema and stage, he spent decades performing in prominent theatrical productions before transitioning extensively into film. Over a prolific career spanning more than a hundred film credits, he has earned widespread critical acclaim in his home country, including multiple prestigious Bodil Awards for his powerful dramatic work in Danish cinema. He has also successfully transitioned into prominent English-language projects, establishing an international presence through his chillingly understated performances and distinct screen gravity. In the James Bond franchise, Jesper Christensen gained international recognition for playing the recurring, enigmatic villain Mr. White, starting with the 2006 film Casino Royale. His character serves as a shadowy liaison and high-ranking operative for a powerful criminal syndicate, elegantly orchestrating illicit financial arrangements and acting as a persistent, ominous thread that bridges multiple films across Daniel Craig''s tenure as 007.',
           'Danish',
           '1948-05-16',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Giancarlo Giannini (Casino Royale, Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('8222472f-0909-4221-b220-ed6918588210'),
           'Giancarlo Giannini',
           'Rene Mathis',
           'Giancarlo Giannini is a legendary Italian actor and director born on August 1, 1942, in La Spezia, Italy. He moved with his family to Naples as a child before studying electronics at a technical institute and eventually enrolling at the Academy of Dramatic Art in Rome. He began his career on the stage before launching a prolific cinematic journey, collaborating with renowned Italian auteurs such as Lina Wertmüller, Luchino Visconti, and Dario Argento. Giannini achieved global acclaim and a Best Actor Academy Award nomination for his brilliant, highly expressive performance in Wertmüller''s tragicomedy Seven Beauties in 1975, establishing himself as a master of intense, deeply charismatic, and emotionally volatile characters across both European cinema and major international productions. In the James Bond franchise, Giancarlo Giannini appeared in the 2006 film Casino Royale and its 2008 sequel Quantum of Solace as René Mathis. His character is a seasoned MI6 contact stationed in Montenegro who assists James Bond by acting as his local guide, intelligence provider, and trusted confidant during the high-stakes poker tournament, before later becoming a tragic casualty of the global conspiracy Bond is trying to dismantle.',
           'Italian',
           '1942-08-01',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Olga Kurylenko (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('2052bd2a-b055-4325-ba83-4e24d5188b9b'),
           'Olga Kurylenko',
           'Camille Montes',
           'Olga Kurylenko was born in Berdyansk, Ukrainian SSR, Soviet Union, in November 1979. Raised by a single mother and her grandmother in modest circumstances during the final years of the Soviet era, she moved to Moscow at the age of thirteen, where a modeling scout discovered her while she was visiting a museum. By age sixteen, she had relocated to Paris to sign with the Madison modeling agency, quickly rising to international prominence as a cover model for major fashion magazines such as Vogue and Elle. Transitioning from fashion to cinema in the early 2000s, she made her feature film debut in the French erotic drama L''Annulaire (2005) and soon gained recognition in action-oriented roles, most notably as Nika Boronina in the video game adaptation Hitman (2007). In 2008, Kurylenko achieved global stardom when she was cast as Camille Montes in the James Bond film Quantum of Solace. Portrayed as a fierce, resolute Bolivian secret agent, Camille joins forces with Daniel Craig''s James Bond not out of romance, but out of a shared, burning desire for personal vengeance against General Medrano, the brutal dictator who murdered her family. Kurylenko performed many of her own stunts and brought a quiet, brooding intensity to the character, making Camille a compelling modern inversion of the traditional Bond girl by matching 007 in lethal capability and emotional trauma rather than serving as a damsel in distress. Following her breakout performance in the Bond franchise, Kurylenko established herself as a versatile leading lady in major Hollywood blockbusters and international science fiction films. Her prominent feature film credits include starring alongside Tom Cruise in the dystopian sci-fi epic Oblivion (2013), playing the lead in Neil Marshall''s historical action film Centurion (2010), acting opposite Russell Crowe in The Water Diviner (2014), and starring in the thriller The Courier (2019) and the Marvel Cinematic Universe film Black Widow (2021) as the villainous Taskmaster.',
           'Ukrainian-French',
           '1979-11-14',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Mathieu Amalric (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('29152539-82e3-402a-9881-a6d5d66ef898'),
           'Mathieu Amalric',
           'Dominic Greene',
           'Mathieu Amalric was born in Neuilly-sur-Seine, France, in October 1965. The son of a journalist mother and a film critic father, he grew up immersed in the world of arts and cinema. He attended the prestigious École Normale Supérieure and initially pursued academic and literary paths before gravitating toward filmmaking and acting in the late 1980s. He made his feature film debut in Favorites of the Moon (1984) directed by Otar Iosseliani, but his major breakthrough came when he starred in Arnaud Desplechin''s critically acclaimed drama My Sex Life... or How I Got Into an Argument (1996), which earned him the César Award for Most Promising Actor. Over the following decades, Amalric established himself as one of France''s most celebrated and versatile contemporary actors and directors, earning widespread international acclaim for his tour-de-force performance as the paralyzed author Jean-Dominique Bauby in Julian Schnabel''s biographical drama The Diving Bell and the Butterfly (2007). In 2008, Amalric brought his intense screen presence to the James Bond franchise in Quantum of Solace, portraying the primary antagonist Dominic Greene. Unlike the towering, physically imposing villains of earlier eras, Amalric played Greene as a seemingly unassuming, cold, and calculating businessman who masks his ruthless greed behind an environmental philanthropic front called Green Planet. As a high-ranking operative of the villainous Quantum organization, Greene attempts to orchestrate a coup in Bolivia to secure a monopoly on the nation''s water supply. Amalric''s chillingly modern, corporate-minded performance presented a frighteningly plausible portrait of ecological exploitation, earning praise for redefining the classic Bond villain archetype. Following his role in the Bond franchise, Amalric continued to maintain a prolific international career bridging major blockbusters and independent European art-house cinema. He appeared in Steven Spielberg''s historical drama Munich (2005), Wes Anderson''s whimsical comedies The Grand Budapest Hotel (2014) and The French Dispatch (2021), and Roman Polanski''s Venus in Fur (2013). In addition to his extensive acting resume, Amalric is an accomplished film director, winning the Best Director award at the Cannes Film Festival for his acclaimed 2010 drama On Tour.',
           'French',
           '1965-10-25',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Gemma Arterton (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('4c0a44dd-8ba8-4438-ac9f-9e9d5ea0decb'),
           'Gemma Arterton',
           'Strawberry Fields',
           'Gemma Arterton was born in Gravesend, Kent, England, in February 1986. Raised in a working-class single-parent household by her mother, she developed an early interest in the performing arts and won a government grant to study at the prestigious Royal Academy of Dramatic Art (RADA) in London. While still completing her training at RADA, she secured her professional stage debut at Shakespeare''s Globe and made her feature film debut as Kelly Jones in the anarchic British comedy St Trinian''s (2007). In 2008, Arterton achieved international prominence when she was selected from over a thousand candidates to join the James Bond franchise in Quantum of Solace. She portrayed Strawberry Fields, an MI6 intelligence agent stationed at the British consulate in Bolivia who is dispatched to order Daniel Craig''s James Bond back to London. Yielding to 007''s charm, Fields instead aids his rogue mission before tragically meeting a fate reminiscent of classic Bond lore, being found drowned and covered entirely in crude oil. Her performance earned her widespread visibility and an Empire Award for Best Newcomer. Following her appearance in the Bond series, Arterton built a diverse and prolific international career spanning major blockbusters, gritty independent dramas, and acclaimed stage productions. Her prominent film credits include starring roles in fantasy and adventure epics like Clash of the Titans (2010) and Prince of Persia: The Sands of Time (2010), as well as acclaimed performances in smaller-scale British films such as The Disappearance of Alice Creed (2009), The Escape (2017), and The King''s Man (2021). On stage, she has earned high critical acclaim, including Laurence Olivier Award nominations for her work in the West End musicals and plays like Made in Dagenham and Nell Gwynn.',
           'British',
           '1986-02-12',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  David Harbour (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('d252acbb-6530-4b19-9448-ee1a22ea5566'),
           'David Harbour',
           'Gregg Beam',
           'David Harbour was born in White Plains, New York, in April 1975. He developed an early interest in acting and graduated from Dartmouth College in 1997, where he majored in drama and Italian. He began his professional acting career on stage, performing in Shakespearean productions and making his Broadway debut in 1999 in a revival of The Rainmaker. He earned a Tony Award nomination in 2005 for his performance in Who''s Afraid of Virginia Woolf? and built a solid reputation as a versatile character actor across theater, television, and film, with early screen appearances including Brokeback Mountain (2005) and Revolutionary Road (2008). In 2008, Harbour joined the James Bond franchise in Quantum of Solace, portraying Gregg Beam, the corrupt CIA Section Chief for South America. In the film, Beam acts as a cynical and pragmatic bureaucrat who cynically strikes a clandestine deal with the primary antagonist Dominic Greene, trading intelligence oversight of a violent coup in exchange for corporate interests, while attempting to undermine his more principled subordinate, Felix Leiter. Harbour''s performance captured the slick, self-serving corporate-political corruption underpinning the film''s espionage network. Following his appearance in the Bond series, Harbour expanded his resume with major film and television roles, including parts in End of Watch (2012), Black Mass (2015), and the historical drama The Equalizer (2014). He achieved global superstardom and critical acclaim for his starring role as Chief Jim Hopper in the Netflix science fiction series Stranger Things (2016–2025), which earned him multiple Primetime Emmy Award nominations. His subsequent blockbusters include starring as the title hero in Hellboy (2019) and playing Alexei Shostakov / Red Guardian in the Marvel Cinematic Universe films Black Widow (2021) and Thunderbolts* (2025).',
           'American',
           '1975-04-10',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Anatole Taubman (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('dc48ffa3-3488-44d7-b610-7327dd506625'),
           'Anatole Taubman',
           'Elvis',
           'Anatole Taubman was born in Zürich, Switzerland, in December 1970. Coming from a multicultural background, he trained at the prestigious Drama Studio London and immersed himself in international theater, film, and television. He built a reputation as a dynamic character actor capable of speaking multiple languages fluently, which allowed him to transition seamlessly between Swiss, German, British, and American productions. His early career included notable stage performances and supporting screen roles in European television dramas and independent cinema. In 2008, Taubman gained widespread international exposure when he joined the James Bond franchise in Quantum of Solace. He portrayed Elvis, the quirky, uniquely styled, and fiercely loyal henchman and chief assistant to the primary villain Dominic Greene. Recognizable by his distinct hairstyle, bespoke suits, and deadpan demeanor, Elvis serves as Greene''s right-hand man during high-stakes negotiations and operations until his life is abruptly ended by Bond during the dramatic climax at the Perla de las Dunas eco-hotel in the Bolivian desert. Following his role in the Bond series, Taubman maintained a prolific career across European and Hollywood film and television projects. His prominent feature film credits include appearing in the historical war drama Defiance (2008) alongside Daniel Craig, the action thriller Taken (2008), the thriller The Fifth Estate (2013), and the Captain America short film Marvel One-Shot: Agent Carter (2013). He has also remained a familiar face on European television, starring in numerous serials and crime dramas.',
           'Swiss',
           '1970-01-23',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Tim Pigott-Smith (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('1c2dd50e-e77a-4c55-9fc1-1e2caad7b38b'),
           'Tim Pigott-Smith',
           'British Foreign Secretary',
           'Tim Pigott-Smith was born in Rugby, Warwickshire, England, in May 1946. He developed an early passion for the theater and pursued formal training at the Bristol Old Vic Theatre School before embarking on a distinguished stage career. He became a familiar face with the Royal Shakespeare Company and the National Theatre, establishing a reputation as a commanding classical actor. He achieved international television stardom in 1984 with his critically acclaimed, BAFTA-winning starring role as the rigid Superintendent Ronald Merrick in the epic historical drama miniseries The Jewel in the Crown. Throughout his prolific career, he balanced highbrow theatrical work with prominent television and film roles. In 2008, Pigott-Smith joined the James Bond franchise in Quantum of Solace, portraying the British Foreign Secretary. In the film, he appears alongside Judi Dench''s M and Jeffrey Wright''s Felix Leiter during a tense diplomatic meeting in Salzburg, where government officials mistakenly attempt to appease Dominic Greene and the CIA, reflecting the film''s cynical geopolitical themes. Pigott-Smith''s dignified and authoritative screen presence lent a layer of stark political realism to the sequence. Following his appearance in the Bond series, Pigott-Smith continued to work extensively in film, television, and theater, earning high praise for his commanding stage performances, including a Laurence Olivier Award nomination for Best Actor for his role in King Charles III (2014). His notable later screen credits include the historical drama film Viceroy''s House (2017), the political thriller The Escape (2017), and appearances in popular television series such as Downton Abbey and Inspector Lewis, before his passing in April 2017.',
           'British',
           '1946-05-13',
           '2017-04-07',
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Joaquín Cosio (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('ff5217a6-93f6-46d2-85dc-2a5590faad77'),
           'Joaquín Cosio',
           'General Medrano',
           'Joaquín Cosío was born in Tepic, Nayarit, Mexico, in October 1962. Before pursuing a full-time career in acting, he worked for years as a poet, a cultural journalist, and a university professor in Ciudad Juárez. He transitioned to the stage in his thirties and quickly established himself as a powerful dramatic presence in Mexican theater before breaking into cinema. He achieved widespread recognition and critical acclaim across Latin America for his iconic breakthrough performance as the ruthless drug cartel enforcer Rubén "El Cochiloco" Reyes in Luis Estrada''s acclaimed satirical black comedy El infierno (2010) and Matando Cabos (2004), cementing his reputation as one of Mexico''s most versatile and commanding character actors. In 2008, Cosío brought his imposing screen presence to international audiences when he joined the James Bond franchise in Quantum of Solace. He portrayed General Medrano, the corrupt and brutal exiled Bolivian military officer attempting to orchestrate a violent political coup. Medrano serves as the primary physical antagonist and personal nemesis to Olga Kurylenko''s Camille, whose family he ruthlessly murdered years earlier, leading up to his fiery demise during the film''s explosive climax at the desert eco-hotel. Cosío''s fierce, gravelly-voiced performance provided a menacing and grounded anchor for the film''s geopolitical plot. Following his appearance in the Bond series, Cosío maintained a thriving international career, seamlessly alternating between prominent Mexican productions and major Hollywood blockbusters. His notable Hollywood and English-language credits include roles in Gore Verbinski''s Western action film The Lone Ranger (2013), the horror sequel The Strain (2014–2017), the DC superhero film The Suicide Squad (2021) as General Mateo Suárez, and voicing the character Ruben in the animated feature Spider-Man: Across the Spider-Verse (2023).',
           'Mexican',
           '1962-10-05',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Fernando Guillén Cuervo (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('205bbeb9-d065-4e50-b3e2-372a43bb02bb'),
           'Fernando Guillén Cuervo',
           'Colonel of Police (Carlos)',
           'Fernando Guillén Cuervo was born in Barcelona, Spain. Coming from a deeply established artistic family as the son of renowned actors Fernando Guillén and Gemma Cuervo, he naturally gravitated toward the performing arts. He built a diverse and successful career as a Spanish actor, film director, and scriptwriter, establishing a strong presence across Spanish cinema, television, and theater. Over the decades, he earned widespread recognition for his versatile acting capabilities, including a Goya Award nomination for Best Supporting Actor for his performance in the film Boca a boca (1995). In 2008, Guillén Cuervo brought his intense screen presence to international audiences when he joined the James Bond franchise in Quantum of Solace. He portrayed Colonel Carlos, the corrupt chief of the National Bolivian Police. In the film, Carlos acts as a duplicitous antagonist who covertly allies with General Medrano and the Quantum organization, orchestrating the betrayal and murder of René Mathis before ultimately meeting his demise when James Bond tracks him down during the explosive climax at the desert eco-hotel. Following his appearance in the Bond series, Guillén Cuervo continued to maintain a prolific career in Spanish television and film productions, while also expanding into interactive media projects, winning a Children''s and Family Emmy Award for Outstanding Interactive Media for Madrid Noir - Prologue in 2022.',
           'Spanish',
           '1963-03-11',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Jesús Ochoa (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('d077319f-08fc-41ff-9dad-232bb738f98b'),
           'Jesús Ochoa',
           'Lieutenant Orso',
           'Jesús Ochoa was born in Ures, Mexico, in December 1959. He began his performance career participating in local theater productions during his youth before relocating to Mexico City in 1979 to formally study acting at the Instituto de Arte Escénico. Establishing himself as a prominent figure in Mexican entertainment across film, theater, and television, he earned widespread acclaim and two Ariel Awards for Best Supporting Actor for his work in Mexican cinema. Over the decades, he built a versatile international resume spanning high-profile English-language films, including roles in Tony Scott''s crime drama Man on Fire (2004) and the comedy Beverly Hills Chihuahua (2008). In 2008, Ochoa brought his commanding screen presence to the James Bond franchise in Quantum of Solace. He portrayed Lieutenant Orso, a renegade Bolivian military officer who serves as the loyal bodyguard and right-hand man to the exiled General Medrano. Orso accompanies the General to key meetings with Dominic Greene in Haiti and Bolivia, until his character meets his demise during the explosive climax at the Perla de las Dunas eco-hotel when he is overcome by Camille Montes. Following his appearance in the Bond series, Ochoa continued a prolific career across television, film, and voice acting. His prominent subsequent credits include major Spanish-language film and television projects, as well as high-profile voice dubbing work, such as voicing Manny the Mammoth in the Spanish-language versions of the Ice Age animated franchise.',
           'Mexican',
           '1959-12-24',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Lucrezia Lante della Rovere (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('4a3d0d9b-e96a-4031-af09-c76fa6cf904d'),
           'Lucrezia Lante della Rovere',
           'Gemma',
           'Lucrezia Lante della Rovere was born in Rome, Italy, in July 1966. She began her professional life as a fashion model in her teens before transitioning into acting, making her cinematic debut in Mario Monicelli''s acclaimed comedy-drama Speriamo che sia femmina (1986). Over the following decades, she built a successful and versatile career spanning film, television, and theater, establishing herself as a prominent figure in Italian entertainment with memorable performances in projects such as Storia di ragazzi e di ragazze (1989) and Viola di mare (2009). In 2008, Lante della Rovere expanded her career to include international cinema when she appeared in the James Bond film Quantum of Solace. In the film, she portrayed Gemma, adding to the international flavor of the globetrotting production. Following her role in the Bond franchise, Lante della Rovere continued to work extensively across European film and television, taking on diverse character roles in popular television miniseries and maintaining an active presence on the Italian stage.',
           'Italian',
           '1966-07-19',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Glenn Foster (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('363e3e73-a806-4e54-83bc-0582eb347f6c'),
           'Glenn Foster',
           'Craig Mitchell',
           'Glenn Foster was born in Yorkshire, England, and developed a passionate interest in physical performance and action cinema from a young age, inspired by books and classic movies. After working as an outdoors and rock-climbing instructor, he transitioned into professional stunt work, undergoing years of rigorous training to join the British stunt registry. He established a successful career as an elite Hollywood stuntman and performer, lending his physical talents to major blockbuster productions including Batman Begins, The Dark Knight, Casino Royale, and The Bourne Ultimatum. In 2008, Foster brought his stunt expertise in front of the camera for the James Bond franchise when he appeared in Quantum of Solace. He portrayed Craig Mitchell, the treacherous MI6 agent and bodyguard to M who is revealed as a mole working for the Quantum organization. Mitchell triggers the film''s opening sequence by turning on his superiors and attempting to assassinate M, leading to an intense, high-octane foot chase across the rooftops and through an art gallery in Siena, Italy, before culminating in a physical struggle where he is shot by James Bond. Following his work on the Bond series, Foster continued a highly successful career in major international cinema, later serving as the primary stunt double for Robert Downey Jr. in high-profile projects such as Sherlock Holmes, Iron Man, The Avengers, and Captain America, earning critical recognition and Taurus World Stunt Award nominations for his high-level stunt performances.',
           'British',
           '1983-01-01',
           '2020-12-01',
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Paul Ritter (Quantum Of Solace)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('c4874543-4584-4496-a141-bc8c56ec4126'),
           'Paul Ritter',
           'Guy Haines',
           'Paul Ritter was born in Kent, England, in December 1966. He established a prolific and highly respected acting career across British stage, television, and film, earning a reputation for his immense versatility and compelling character portrayals. A familiar and celebrated face in classical theater, he notably performed with the Royal Shakespeare Company and the National Theatre, earning a Laurence Olivier Award nomination in 2009 for his standout performance in Coram Boy. In 2008, Ritter appeared in the James Bond franchise in Quantum of Solace, portraying Guy Haines, a high-ranking special advisor or envoy to the British Prime Minister. Beneath his respectable government exterior, Haines is secretly a senior member of the executive board of the villainous Quantum organization, attending the covert meeting during the performance of Tosca in Bregenz, Austria, and pulling strings behind the scenes regarding international political and corporate corruption. Following his role in the Bond film, Ritter continued to build an acclaimed screen career with memorable appearances in major film and television projects. His prominent later credits include playing Eldred Worple in Harry Potter and the Half-Blood Prince (2009), Anatoly Dyatlov in the critically acclaimed historical miniseries Chernobyl (2019), and starring as Martin Goodman in the long-running British sitcom Friday Night Dinner (2010–2020), before his passing in April 2021.',
           'British',
           '1966-03-05',
           '2021-04-05',
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Rory Kinnear (Quantum Of Solace, Skyfall, Spectre, No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('09311e3d-0f24-4fad-8931-74146d4bb223'),
           'Rory Kinnear',
           'Bill Tanner',
           'Rory Kinnear was born in Hammersmith, London, England, in February 1978. Coming into a rich theatrical heritage as the son of renowned actor Roy Kinnear and actress Carmel Cryan, he studied English literature at Balliol College, Oxford, before training at the London Academy of Music and Dramatic Art (LAMDA). He established himself as one of Britain''s most respected stage actors, working extensively with the Royal Shakespeare Company and the National Theatre, where his powerful classical performances earned him widespread critical acclaim and two Laurence Olivier Awards. In 2008, Kinnear joined the James Bond franchise in Quantum of Solace, taking over the recurring role of Bill Tanner, M''s trusted Chief of Staff at MI6. As Tanner, Kinnear brought a grounded, steady, and sharp-witted bureaucratic presence to the series, serving as a vital confidant and administrative anchor for Daniel Craig''s iteration of 007 and Judi Dench''s M. Kinnear would go on to reprise the role in subsequent Bond films, including Skyfall (2012), Spectre (2015), and No Time to Die (2021), making him a rare and enduring fixture of the modern Bond supporting cast. Alongside his multi-film tenure in the Bond series, Kinnear built a prolific and versatile career across television and film. His prominent screen credits include starring as the Creature in the gothic horror series Penny Dreadful (2014–2016), playing the fictional British Prime Minister Michael Callow in the dark anthology series Black Mirror (2011), and starring in the historical drama series Men (2022) and Our Flag Means Death (2022–2023).',
           'British',
           '1978-02-17',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Javier Bardem (Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('dfe12d1b-5424-44b4-a0f7-923d058e24af'),
           'Javier Bardem',
           'Raoul Silva',
           'Javier Bardem was born in Las Palmas, Canary Islands, Spain, in March 1969. Coming from a legendary Spanish family deeply rooted in the cinematic arts—including his mother, actress Pilar Bardem, and prominent acting grandparents—he grew up surrounded by the industry. Before fully committing to acting, he played for the Spanish national rugby union team and studied painting at the Escuela de Artes y Oficios. He transitioned into a powerhouse screen actor, achieving international breakthrough recognition with his gripping, intense performances in Spanish cinema, such as Jamón, jamón (1992) and Boca a boca (1995), before cementing his global superstardom with an Academy Award for Best Supporting Actor for his terrifying portrayal of Anton Chigurh in the Coen brothers'' No Country for Old Men (2007). In 2012, Bardem brought his magnetic and chilling screen presence to the James Bond franchise in Skyfall. He famously portrayed Raoul Silva, a brilliant, blond-haired former MI6 cyber-terrorist and disgraced agent seeking brutal vengeance against M for abandoning him to Chinese captivity years prior. Silva serves as one of the most psychological and iconic villains in the series, engineering cyber-attacks on MI6 and executing a direct assault on the inquiry committee and Skyfall estate. Bardem''s eccentric, layered, and deeply memorable performance earned widespread critical acclaim, revitalizing the franchise''s antagonist archetype. Following his iconic turn in the Bond series, Bardem continued to anchor major international and Hollywood blockbusters, earning further Academy Award nominations and starring in prominent films such as Dune (2021) and its sequel Dune: Part Two (2024) as Stilgar, Being the Ricardos (2021) as Desi Arnaz, and Disney''s live-action The Little Mermaid (2023) as King Triton, solidifying his legacy as one of the most versatile and respected actors of his generation.',
           'Spanish',
           '1969-03-01',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Bérénice Marlohe (Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('9fa1dd80-94d0-4f0c-ad79-b29f7f52ac35'),
           'Bérénice Marlohe',
           'Sévérine',
           'Bérénice Marlohe was born in Paris, France, in May 1979, to a French mother who worked as a teacher and a father of Cambodian and Chinese descent who was a doctor. Growing up in France, she initially pursued a different career path, studying at the prestigious École nationale supérieure des arts décoratifs in Paris with the goal of becoming a visual artist or designer. However, her passion for performance eventually led her to pivot toward acting, taking drama classes and appearing in various French television series, short films, and stage productions while actively breaking into the competitive European entertainment industry. In 2012, Marlohe achieved international breakthrough recognition when she joined the James Bond franchise in Skyfall. She portrayed Sévérine, a mysterious and tragic French-Vietnamese femme fatale who is held captive by the central villain Raoul Silva, serving as his associate and reluctant mistress. Despite her glamorous exterior, Sévérine lives in constant fear and desperation, ultimately crossing paths with James Bond in Macau and offering to help him reach Silva in exchange for protection, which tragically leads to her brutal execution during a game of roulette orchestrated by the villain. Following her memorable appearance in the Bond series, Marlohe expanded her career into American and international cinema and television. Her post-Bond credits include starring roles in the sci-fi action film Revolt (2017), the David Lynch-inspired mystery film Twin Peaks revival series, and various independent feature films, establishing a versatile international career as both an actress and a prominent fashion model.',
           'French',
           '1979-05-19',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Albert Finney (Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('8fa3dd77-e45a-4d80-a95b-751ddc1218f9'),
           'Albert Finney',
           'Kincaid',
           'Albert Finney was born in Salford, Lancashire, England, in May 1936, and grew up in a working-class household before discovering a passion for the dramatic arts. He trained at the prestigious Royal Academy of Dramatic Art, where he was a classmate of fellow future stars, and quickly rose to prominence as a titan of the British stage, starring with the Birmingham Repertory Theatre and the Royal Shakespeare Company. Finney became a leading figure of the British New Wave in cinema during the 1960s, earning international acclaim and the first of five Academy Award nominations for his star-making performance in Tom Jones (1963), followed by iconic roles in films such as Murder on the Orient Express (1974), The Dresser (1983), and Erin Brockovich (2000). In 2012, near the twilight of his legendary career, Finney joined the James Bond franchise in Skyfall. He portrayed Kincaid, the gruff, loyal, and fiercely protective Scottish gamekeeper of the ancestral Skyfall estate where James Bond was raised as an orphan. Kincaid plays a pivotal role in the film''s climactic third act, assisting Bond and M in fortifying the historic manor and using his intimate knowledge of the rugged Scottish terrain to help them fight off Raoul Silva''s heavily armed mercenaries. Finney''s appearance in Skyfall marked his final feature film performance before his passing in February 2019 at the age of 82. His memorable turn as Kincaid provided a warm, grounded, and deeply nostalgic touch to the franchise, cementing a fittingly triumphant final chapter for one of Britain''s most celebrated cinematic icons.',
           'British',
           '1936-05-09',
           '2019-02-07',
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Ola Rapace (Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('5b84735f-59a8-42d2-9945-440676de1df1'),
           'Ola Rapace',
           'Patrice',
           'Ola Rapace was born Pär Ola Norell in Tyresö, a suburb southeast of Stockholm, Sweden, in December 1971. Growing up primarily in the Stockholm area, he later studied philosophy at the University of Montpellier in France, where he discovered his passion for acting. He returned to Sweden to pursue formal theatre training, studying at the Theatre Academy at the University of Gothenburg from 1995 to 1999. Following his graduation and stage debut, he quickly transitioned to screen acting, making his feature film debut in Lukas Moodysson''s critically acclaimed comedy Together (2000) and establishing a prominent profile in Scandinavian television with starring roles in popular crime and drama series such as Tusenbröder and the initial season of Wallander. In 2012, Rapace achieved international prominence when he joined the cast of the James Bond film Skyfall, directed by Sam Mendes. He portrayed Patrice, a ruthless, cold, and calculating mercenary assassin. His character sets the intense tone for the film''s opening sequence by stealing a classified hard drive containing undercover NATO agents, triggering a thrilling pursuit across Istanbul that features a high-speed motorcycle and train-top chase with James Bond. Rapace performed many of his own stunts for the physically demanding role, which served as his major breakout into large-scale international cinema. Following his appearance in Skyfall, Rapace expanded his career further into international film and television projects, relocating to Paris for several years and appearing in productions such as the French science-fiction film Ares (2016), Luc Besson''s space opera Valerian and the City of a Thousand Planets (2017) as Major Gibson, and the historical drama series The Last Kingdom. He continues to work across European and global platforms, balancing television drama with feature film roles.',
           'Swedish',
           '1971-12-03',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Helen McCrory (Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('32492fe1-d93c-4e54-bba0-2ef5bb88faab'),
           'Helen McCrory',
           'Clair Dovar',
           'Helen McCrory was born in London, England, in August 1968, and built an illustrious, highly respected acting career across British theatre, television, and film. After completing her professional training at the Drama Centre London, she made her stage debut in 1990 and quickly rose to prominence as a powerhouse classical actress, performing leading roles with the Royal Shakespeare Company and London''s West End, including acclaimed turns as Lady Macbeth and Medea. She established an equally impressive screen profile, earning widespread acclaim for her portrayal of Cherie Blair in The Queen (2006) and The Special Relationship (2010), playing Narcissa Malfoy in the final installments of the Harry Potter film series, and starring as the formidable Polly Gray in the hit television series Peaky Blinders. In 2012, McCrory joined the James Bond franchise when she appeared in the Sam Mendes-directed film Skyfall. She portrayed Clair Dowar, a British Member of Parliament and senior political figure who heavily questions and scrutinizes M during a high-stakes parliamentary inquiry regarding MI6''s handling of a major security breach. Though a brief appearance, her role added a layer of institutional pressure and bureaucratic oversight to the tense political backdrop of the film. Following her work in Skyfall, McCrory continued to command the screen in major television and film productions until her passing in April 2021. Remembered universally for her immense talent, poise, and fierce dedication to her craft, she left an indelible legacy across the British entertainment industry.',
           'British',
           '1968-08-17',
           '2021-04-16',
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Nicholas Woodeson (Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('bf9f513b-9f4c-4277-b8df-85c37bc0a447'),
           'Nicholas Woodeson',
           'Dr. Hall',
           'Nicholas Woodeson was born in Port Sudan, Sudan, in November 1949, and spent parts of his early childhood in Israel before moving to England. He attended Marlborough College and read English at the University of Sussex before earning a scholarship to train at the Royal Academy of Dramatic Art (RADA). Beginning his professional career on stage in regional repertory theatre, Woodeson eventually joined the Royal Shakespeare Company, building a distinguished multi-decade career across West End, Broadway, and international theatrical productions, earning Olivier and Drama Desk Award nominations along the way. On screen, he established himself as a prolific character actor with diverse film and television roles, including prominent performances in feature films such as The Pelican Brief (1993), Topsy-Turvy (1999), and The Death of Stalin (2017), alongside recurring television roles in series such as Rome and Taboo. In 2012, Woodeson joined the James Bond franchise when he appeared in Skyfall, directed by Sam Mendes. He portrayed Dr. Hall, an MI6 psychological evaluator who conducts a word-association assessment on James Bond to determine if the agent is mentally and emotionally fit to return to active field duty following his near-fatal shooting and subsequent sabbatical. Woodeson''s scene provided a memorable glimpse into Bond''s psychological state and highlighted the rigid institutional scrutiny facing 007 upon his return to service. Following his performance in Skyfall, Woodeson maintained an active presence across major film, stage, and television productions. His subsequent credits include film appearances in Mr. Turner (2014), The Danish Girl (2015), and Disobedience (2017), as well as ongoing stage engagements in London and extensive work in British and international television dramas.',
           'British',
           '1949-11-30',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Bill Buckhurst (Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('e4e89c84-0ec4-431e-9ba0-462b841cc898'),
           'Bill Buckhurst',
           'Ronson',
           'Bill Buckhurst built a rich, multifaceted career in the British performing arts as a versatile stage actor, screen performer, and acclaimed theatre and film director. He completed his professional training as an actor before performing extensively across prominent British theatrical institutions, including the Royal Shakespeare Company, the Royal Court Theatre, London''s West End, and Shakespeare''s Globe. Alongside his stage work, he transitioned into screen acting with appearances across various British television series and feature films, while also developing a celebrated career as a director. His directorial work includes high-profile stage productions such as the internationally acclaimed revival of Sweeney Todd—which transferred from a London pie shop to the West End and Off-Broadway—as well as his feature film directorial debut, Pond Life (2018). In 2012, Buckhurst appeared in the James Bond franchise in Skyfall, directed by Sam Mendes. He portrayed Ronson, an injured British MI6 field operative stationed at an Istanbul safe house during the film''s tense pre-title sequence. Discovered mortally wounded by James Bond after a confidential drive containing the identities of undercover NATO agents is stolen, Ronson serves as the initial catalyst for the high-stakes motorcycle and train chase across Turkey, establishing the immediate urgency and peril driving the narrative. Following his appearance in Skyfall, Buckhurst shifted significant focus toward his thriving career as a director and creative practitioner. He directed numerous productions for Shakespeare''s Globe, served as an education consultant for the institution, and led major West End and touring musical productions, including Sister Act The Musical and 101 Dalmatians The Musical, continuing his influential presence across the UK and international theatre landscapes.',
           'British',
           '1970-01-01',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Elize du Toit (Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('4e96ee32-499f-4c68-9dcd-3040ca9c596a'),
           'Elize du Toit',
           'Vanessa',
           'Elize du Toit was born in Grahamstown, South Africa, in February 1980. She spent most of her early childhood in Pretoria before her family moved to Berkshire, England, in 1994. While attending Wellington College, she became an active member of Reading''s Progress Theatre and later went on to study history at the University of Edinburgh, where she performed with the Edinburgh University Theatre Company. Her major acting breakthrough arrived in 2000 when she won an open audition against tens of thousands of applicants to land the regular role of Izzy Davies in the popular British soap opera Hollyoaks. Following her multi-year run on the show, she built a steady television and film career, appearing in various UK series such as Doctor Who, Casualty, The Line of Beauty, Lewis, and Coronation Street. In 2012, du Toit joined the James Bond franchise in Skyfall, directed by Sam Mendes. She portrayed Vanessa, a staff member working as M''s assistant within the MI6 headquarters. Her character appears during the high-stakes opening sequence monitoring communications alongside Bill Tanner and M as field operatives attempt to recover a stolen NATO hard drive in Istanbul. Following her brief appearance in Skyfall, du Toit stepped back from acting to focus on other pursuits and family life. Her stint as M''s assistant remains her highest-profile feature film contribution, capping an active decade-long career in British television and film.',
           'British',
           '1980-02-21',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Ben Whishaw (Skyfall, Spectre, No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('8ab6120c-6124-4e2e-aa5e-c27cdaf3674a'),
           'Ben Whishaw',
           'Q.',
           'Ben Whishaw was born in Clifton, Bedfordshire, England, in October 1980, and developed an early interest in the performing arts through the Bancroft Players Youth Theatre before pursuing formal training at the Royal Academy of Dramatic Art (RADA), graduating in 2003. He quickly gained widespread critical acclaim in British theatre for a transformative, androgynous portrayal of Hamlet at the Old Vic in 2004, establishing himself as one of the most compelling dramatic actors of his generation. Whishaw successfully transitioned into a diverse and celebrated film and television career, earning international recognition for starring roles in films such as Perfume: The Story of a Murderer (2006) and Bright Star (2009), voicing the beloved title character in the Paddington film series, and winning a Primetime Emmy Award for his performance in the television miniseries A Very English Scandal (2018). In 2012, Whishaw joined the James Bond franchise in Skyfall, taking over the iconic role of Q, the brilliant quartermaster and head of MI6''s technical branch. Reinventing the character for a modern, digital age, Whishaw''s Q is introduced as a youthful, cardigan-wearing cybersecurity expert and computer genius rather than the traditional, gadget-focused older inventor of previous eras, sharing a memorable introductory scene with Daniel Craig''s Bond in the National Gallery where they debate the nature of modern espionage. Following his debut in Skyfall, Whishaw cemented his place in the modern era of the franchise by reprising his role as Q in subsequent films Spectre (2015) and No Time to Die (2021). Alongside his ongoing contributions to the Bond series, he has maintained a prolific career spanning prestige television, independent cinema, and acclaimed stage productions, continuing to be celebrated for his exceptional versatility and emotional depth.',
           'British',
           '1980-10-14',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Naomie Harris (Skyfall, Spectre, No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('c9262a11-7759-40ae-a0f4-59a0904963b1'),
           'Naomie Harris',
           'Eve Moneypenny',
           'Naomie Harris was born in London, England, where she was raised and showed an early interest in acting, appearing in television projects starting from childhood. She pursued higher education at Pembroke College, Cambridge, graduating with a degree in social and political sciences before completing her professional training at the Bristol Old Vic Theatre School. Harris established a diverse and critically acclaimed screen career, landing major breakout roles in Danny Boyle''s post-apocalyptic thriller 28 Days Later (2002) and portraying the voodoo witch Tia Dalma in the Pirates of the Caribbean franchise, alongside prominent dramatic work in television and film. In 2012, Harris joined the James Bond franchise when she co-starred in Skyfall. She portrayed Eve Moneypenny, a capable MI6 field agent who works closely alongside Daniel Craig''s James Bond. Her casting marked a historic milestone for the long-running series, as she became the first actress to portray the iconic character with an explicitly given first name, transitioning the role away from a traditional secretary position into a dynamic, active participant in the espionage world. Following her debut in Skyfall, Harris continued to build upon her cinematic success, earning widespread critical acclaim and an Academy Award nomination for Best Supporting Actress for her powerful performance in the drama film Moonlight (2016). She also reprised her role as Eve Moneypenny in subsequent James Bond films Spectre (2015) and No Time to Die (2021), cementing her legacy within modern cinematic history.',
           'British',
           '1976-09-06',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Ralph Fiennes (Skyfall)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('17ce05f5-1f39-4d6d-a57f-c6974afde0ef'),
           'Ralph Fiennes',
           'Gareth Mallory',
           'Ralph Fiennes was born in Ipswich, Suffolk, England, in December 1962, into a creative family with various artistic pursuits. He studied painting at the Chelsea College of Arts before transitioning to acting, completing his professional training at the prestigious Royal Academy of Dramatic Art (RADA). Fiennes quickly established himself as a master of classical theatre, working extensively with the Royal Shakespeare Company and the National Theatre before building a legendary, critically acclaimed career in international cinema, earning Academy Award nominations for his mesmerizing performances in Schindler''s List (1993) and The English Patient (1996), alongside iconic roles such as Lord Voldemort in the Harry Potter film series. In 2012, Fiennes entered the James Bond franchise when he co-starred in Skyfall, portraying Gareth Mallory, a former British Army lieutenant colonel and the Chairman of the Intelligence and Security Committee who oversees the parliamentary inquiry into M''s handling of an MI6 data breach. Following the tragic events of the film and the death of Judi Dench''s M, Mallory succeeds her to become the new head of MI6, officially taking on the legacy codename M and steering the agency through complex modern geopolitical and bureaucratic challenges. Following his introduction in Skyfall, Fiennes continued to anchor the modern era of the franchise, reprising his role as M in subsequent films Spectre (2015) and No Time to Die (2021). Alongside his ongoing contributions to the Bond series, he has continued to balance high-profile blockbuster appearances with celebrated roles in independent and dark comedic cinema, including his acclaimed performance as Chef Slowik in The Menu (2022).',
           'British',
           '1962-12-22',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Ralph Fiennes (Spectre, No Time To Die)
 */
