VALUES (
           UUID_TO_BIN('3da9300b-1cd7-4cf8-ab81-542f19bc865b'),
           'Ralph Fiennes',
           'M.',
           'Ralph Fiennes was born in Ipswich, Suffolk, England, in December 1962, into a creative family with various artistic pursuits. He studied painting at the Chelsea College of Arts before transitioning to acting, completing his professional training at the prestigious Royal Academy of Dramatic Art (RADA). Fiennes quickly established himself as a master of classical theatre, working extensively with the Royal Shakespeare Company and the National Theatre before building a legendary, critically acclaimed career in international cinema, earning Academy Award nominations for his mesmerizing performances in Schindler''s List (1993) and The English Patient (1996), alongside iconic roles such as Lord Voldemort in the Harry Potter film series. In 2012, Fiennes entered the James Bond franchise when he co-starred in Skyfall, portraying Gareth Mallory, a former British Army lieutenant colonel and the Chairman of the Intelligence and Security Committee who oversees the parliamentary inquiry into M''s handling of an MI6 data breach. Following the tragic events of the film and the death of Judi Dench''s M, Mallory succeeds her to become the new head of MI6, officially taking on the legacy codename M and steering the agency through complex modern geopolitical and bureaucratic challenges. Following his introduction in Skyfall, Fiennes continued to anchor the modern era of the franchise, reprising his role as M in subsequent films Spectre (2015) and No Time to Die (2021). Alongside his ongoing contributions to the Bond series, he has continued to balance high-profile blockbuster appearances with celebrated roles in independent and dark comedic cinema, including his acclaimed performance as Chef Slowik in The Menu (2022).',
           'British',
           '1962-12-22',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Monica Bellucci (Spectre)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('47ba0224-fa94-4226-aa22-ba1d91229645'),
           'Monica Bellucci',
           'Lucia Sciarra',
           'Monica Bellucci was born in Città di Castello, Umbria, Italy, in September 1964. She began her professional career as a fashion model while studying law at the University of Perugia, eventually moving to Milan to pursue modeling full-time and becoming a leading muse for major international fashion houses. She transitioned into acting in the early 1990s, making her feature film debut in Italian cinema before making her American screen debut in Francis Ford Coppola''s Bram Stoker''s Dracula (1992). Bellucci gained international critical acclaim for her leading role in Giuseppe Tornatore''s Malèna (2000) and went on to command high-profile roles across European art-house cinema and Hollywood blockbusters, notably portraying Persephone in The Matrix Reloaded (2003) and The Matrix Revolutions (2003), Mary Magdalene in Mel Gibson''s The Passion of the Christ (2004), and starring in Irréversible (2002) and The Brothers Grimm (2005). Bellucci joined the James Bond franchise when she was cast in Spectre (2015). She portrayed Lucia Sciarra, the widow of Marco Sciarra, an assassin eliminated by James Bond in the opening sequence in Mexico City. At fifty years old when she played the role, Bellucci made franchise history as the oldest actress to portray a Bond girl, bringing an understated elegance and danger to her brief yet pivotal scenes in Rome as she provides 007 with vital intelligence regarding the secret organization SPECTRE. Following her appearance in Spectre, Bellucci has continued her prolific international acting career across film, television, and stage. Her subsequent project credits include roles in David Lynch''s Twin Peaks: The Return (2017), The Whistleblower, Mafia Mamma (2023), and Tim Burton''s fantasy-comedy Beetlejuice Beetlejuice (2024), alongside touring internationally with her acclaimed theatrical solo performance in Maria Callas: Letters and Memoirs.',
           'Italian',
           '1964-09-30',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Dave Bautista (Spectre)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('ce782364-7d75-4262-b30e-43e02abd8dd7'),
           'Dave Bautista',
           'Mr. Hinx',
           'Dave Bautista was born in Washington, D.C., in January 1969. Before carving out a major Hollywood career, he achieved international fame as a professional wrestler under the ring name Batista, becoming a multi-time World Heavyweight Champion and one of the defining figures of World Wrestling Entertainment (WWE). Transitioning into acting in the late 2000s, Bautista steadily built his resume through guest television roles and action cinema before landing his cinematic breakout role as Drax the Destroyer in Marvel Studios'' Guardians of the Galaxy (2014). His charismatic, comedic, and physical performance instantly made him a household name and established him as a talented screen actor. Following his Marvel success, Bautista entered the James Bond franchise when he was cast in Spectre (2015), rather than Skyfall. He portrayed Mr. Hinx, a silent, imposing, and impeccably dressed assassin serving as the primary enforcer for the SPECTRE criminal syndicate. Harkening back to iconic physical henchmen like Jaws and Oddjob, Hinx introduced a formidable physical threat to Daniel Craig''s 007. Bautista''s character executed memorable action sequences throughout the film, including a high-speed car chase through the streets of Rome in a Jaguar C-X75 and a brutal, extended hand-to-hand fight aboard a moving train in North Africa. Since his appearance in Spectre, Bautista has developed a wide-ranging filmography across blockbusters and auteur-driven cinema. He earned high praise for his dramatic performance in Denis Villeneuve''s Blade Runner 2049 (2017) and went on to star in Army of the Dead (2021), Glass Onion: A Knives Out Mystery (2022), M. Night Shyamalan''s Knock at the Cabin (2023), and the Dune franchise (2021, 2024), alongside continuing his long-running role in the Marvel Cinematic Universe.',
           'American',
           '1969-01-18',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Andrew Scott (Spectre)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('88d30822-98c6-4596-bd34-940ca28d76ce'),
           'Andrew Scott',
           'Max Denbigh (C.)',
           'Andrew Scott was born in Dublin, Ireland, in October 1976. He began acting as a teenager, making his film debut in the Irish feature Korea (1995) before studying drama at Trinity College Dublin. He soon left to join Dublin''s Abbey Theatre, subsequently moving to London to build an extensive stage and screen career. Scott achieved widespread international acclaim for his iconic portrayal of the villainous Jim Moriarty in the BBC series Sherlock (2010–2017), a role that earned him a BAFTA Television Award for Best Supporting Actor. Across stage and screen, he accumulated notable credits, including acclaimed theater roles that earned him multiple Laurence Olivier Awards, alongside film appearances in Pride (2014) and Victor Frankenstein (2015). In 2015, Scott joined the James Bond franchise in Spectre, directed by Sam Mendes. He portrayed Max Denbigh, a bureaucracy-obsessed British government official head of the Joint Intelligence Service who goes by the codename "C". Denbigh champions a global surveillance network known as Nine Eyes, seeking to dismantle the traditional 00 section and replace field agents with automated intelligence gathering, before eventually being revealed as a covert operative working directly for the SPECTRE criminal organization. Following his performance in Spectre, Scott continued to amass high-profile roles across film, television, and theater. He gained immense popularity and critical praise as the Priest in the second season of Phoebe Waller-Bridge''s Fleabag (2019), appeared in Sam Mendes''s war epic 1917 (2019), starred in the romantic drama All of Us Strangers (2023), and took on the titular role in the Netflix psychological thriller series Ripley (2024).',
           'Irish',
           '1976-10-21',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Alessandro Cremona (Spectre)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('3d69a464-86bd-4363-96ca-14abb1d141e3'),
           'Alessandro Cremona',
           'Marco Sciarra',
           'Alessandro Cremona was born in Milan, Italy, in April 1968. He developed a passion for acting and physical performance at an early age, establishing himself in Italian entertainment through a blend of stunt work, action choreography, and character acting. Over the course of his multi-decade career in European film and television, he built a reputation as a versatile actor capable of bringing intense physical presence to screen roles. His Italian credits include guest appearances and supporting roles in popular television series such as Il commissario Montalbano, Squadra antimafia, Don Matteo, and Gomorrah, alongside feature film projects across Europe. In 2015, Cremona gained international visibility when he was cast in the 24th James Bond film, Spectre, directed by Sam Mendes. He portrayed Marco Sciarra, a high-ranking terrorist operative working for the criminal syndicate SPECTRE. Cremona plays a central role in the film''s celebrated, unbroken opening tracking sequence set during the Day of the Dead festival in Mexico City. After James Bond thwarts Sciarra''s plot to bomb a stadium, Cremona''s character engages in a thrilling, high-stakes fight sequence with 007 inside a spiraling helicopter above a crowded square, culminating in Bond throwing Sciarra from the aircraft and claiming his ring bearing the SPECTRE octopus insignia. Following his memorable role in Spectre, Cremona continued to work steadily in Italian and international screen productions. He returned to television and cinema, making appearances in action, drama, and crime series, while remaining an active performer and martial artist within the European entertainment industry.',
           'Italian',
           '1970-07-16',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Stephanie Sigman (Spectre)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('f2e0bd0e-e792-4cef-80af-4887b77d4f31'),
           'Stephanie Sigman',
           'Estrella',
           'Stephanie Sigman was born in Ciudad Obregón, Sonora, Mexico, in February 1987. Beginning her professional career as a fashion model, she quickly transitioned into acting on Mexican television before securing her breakthrough cinematic role in the acclaimed Mexican crime drama Miss Bala (2011). Her haunting performance as a beauty pageant contestant caught in the crossfire of drug cartel violence earned international critical acclaim and launched her global career. Over the following years, Sigman expanded her international profile by co-starring in the Canadian documentary Flight of the Butterflies (2012), the Norwegian underwater thriller Pioneer (2013), and securing a recurring television role in the FX crime series The Bridge (2013–2014). In 2015, she starred as real-life television journalist Valeria Vélez in the hit Netflix crime series Narcos. In 2015, Sigman entered the James Bond franchise when she was cast in Spectre, directed by Sam Mendes. She made franchise history as the first official Mexican Bond girl, portraying Estrella in the film''s celebrated pre-title sequence. Dressed in elaborate Day of the Dead attire, her character accompanies James Bond through a vibrant parade crowd in Mexico City to a hotel room, where Bond leaves her briefly to pursue a hitman, triggering a catastrophic explosion and high-stakes rooftop chase. Following her appearance in Spectre, Sigman built an extensive acting portfolio across American feature films and network television. She starred in the action comedy Going Under (2016), John Michael McDonagh''s dark comedy War on Everyone (2016), and the horror hit Annabelle: Creation (2017). On television, she joined the main cast of the CBS action drama series S.W.A.T. (2017–2019), playing Captain Jessica Cortez for its first two seasons alongside ongoing film and voice-acting roles.',
           'Mexican',
           '1987-02-28',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Domenico Fortunato (Spectre)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('458fbadb-0e01-411b-81fb-e3e2782798d4'),
           'Domenico Fortunato',
           'Gallo',
           'Domenico Fortunato was born in Potenza, Basilicata, Italy, in April 1964. Over a career spanning several decades in European television and film, he established himself as a versatile character actor and director. He built an extensive body of work in Italian television, appearing in popular series such as Rex (also known as Inspector Rex) and Nonno Felice, alongside numerous domestic television movies and dramas. In 2015, Fortunato gained international recognition when he was cast in the James Bond film Spectre, directed by Sam Mendes. He portrayed Gallo, a operative associated with Marco Sciarra and the SPECTRE criminal organization. Featured during the opening Day of the Dead sequence in Mexico City, his character meets with Sciarra to discuss a stadium bombing plot before spotting James Bond spying through a window. Bond shoots Gallo before he can draw his weapon, triggering the explosive confrontation that drives the film''s opening sequence. Following his role in Spectre, Fortunato expanded his work into directing while continuing to act in prominent international and Italian projects. He directed and starred in the feature film Bentornato papà (2021), appeared in the historical drama Munich: The Edge of War (2021), and took on a role in Michael Mann''s biographical drama Ferrari (2023).',
           'Italian',
           '1965-02-12',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Christoph Waltz (Spectre, No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('cc308703-e6b8-40a9-93b5-7e9272d36aa8'),
           'Christoph Waltz',
           'Franz Oberhauser (Ernst Stavro Blofeld)',
           'Christoph Waltz was born in Vienna, Austria, in October 1956 into a theatrical family, with both of his parents working as costume and set designers. He studied acting at the Max Reinhardt Seminar in Vienna and the Lee Strasberg Theatre and Film Institute in New York City. Waltz began his professional career on stage before becoming a prolific presence on Austrian and German television and cinema for over three decades. His international breakthrough arrived in 2009 when Quentin Tarantino cast him as the villainous SS officer Hans Landa in Inglourious Basterds, a performance that earned him widespread critical acclaim, including the Academy Award for Best Supporting Actor. He earned a second Academy Award three years later for his role as Dr. King Schultz in Tarantino''s Django Unchained (2012), establishing himself as one of Hollywood''s premier character actors. Waltz entered the James Bond franchise when he was cast as the iconic arch-nemesis Ernst Stavro Blofeld (initially introduced as Franz Oberhauser) in Spectre (2015), rather than Skyfall. As Blofeld, the shadowy mastermind behind the global syndicate SPECTRE, Waltz brought a sinister calm and psychological cruelty to the role, revealing a deeply personal history with James Bond that tied together the overarching narrative of the modern franchise. He later reprised the character from prison in No Time to Die (2021), delivering another chilling performance as Bond''s enduring adversary. Following his contributions to the 007 series, Waltz has continued to work extensively across major international film and television projects. His subsequent screen credits include starring roles in Alita: Battle Angel (2019), The French Dispatch (2021), and the thriller series The Consultant (2023), alongside ongoing voice work and acclaimed stage directorships in opera across Europe.',
           'Austrian-German',
           '1956-10-04',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Léa Seydoux (Spectre, No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('fd485a8b-d86a-4cec-a03d-4bfe3b12cab0'),
           'Léa Seydoux',
           'Dr. Madeleine Swann',
           'Léa Seydoux was born in Paris, France, in July 1985 into a family deeply connected to the French film industry. Though she initially studied music at the Conservatoire de Paris with aspirations of becoming an opera singer, she decided to pursue acting in her late teens, taking classes at Les Enfants Terribles and later studying at the Actors Studio in New York. She made her feature film debut in the teen comedy Girlfriends (2006) and earned critical acclaim for her breakthrough performance in The Beautiful Person (2008), which secured her first César Award nomination. Over the following years, Seydoux quickly balanced major European art-house cinema with prominent Hollywood supporting roles, appearing in Quentin Tarantino''s Inglourious Basterds (2009), Ridley Scott''s Robin Hood (2010), Woody Allen''s Midnight in Paris (2011), and as a ruthless assassin in Mission: Impossible – Ghost Protocol (2011). Her international standing soared in 2013 when she co-starred in Blue Is the Warmest Colour, becoming one of the few performers in history to be awarded an honorary Palme d''Or at the Cannes Film Festival alongside the director and her co-star. Seydoux joined the James Bond franchise when she was cast as Dr. Madeleine Swann in Spectre (2015), rather than Skyfall. A French psychiatrist and daughter of former SPECTRE member Mr. White, Madeleine becomes a central figure in James Bond''s personal journey, helping him track down the organization while forming a profound emotional connection with 007. Seydoux made history in the franchise when she reprised her role in No Time to Die (2021), becoming one of the very few female leads in Bond history to return for consecutive installments and serving as the emotional anchor of Daniel Craig''s final film as James Bond. Following her pivotal role in the 007 series, Seydoux has continued to build an extraordinarily versatile filmography across auteur cinema and global blockbusters. Her notable credits include frequent collaborations with Wes Anderson in The Grand Budapest Hotel (2014) and The French Dispatch (2021), Yorgos Lanthimos''s The Lobster (2015), David Cronenberg''s Crimes of the Future (2022), Mia Hansen-Løve''s One Fine Morning (2022), Bertrand Bonello''s The Beast (2023), and Denis Villeneuve''s Dune: Part Two (2024).',
           'French',
           '1985-07-01',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Ana de Armas (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('96a8d020-6b7c-4a3d-b951-763125fd6300'),
           'Ana de Armas',
           'Paloma',
           'Ana de Armas was born in Havana, Cuba, in April 1988 and raised in the coastal town of Santa Cruz del Norte. At age fourteen, she enrolled at the National Theatre School of Cuba to study drama before relocating to Spain at eighteen to launch her professional career. In Madrid, she quickly achieved widespread recognition starring as Carolina Leal Solís in the popular teen drama series El Internado (2007–2010). Seeking new challenges, de Armas moved to Los Angeles in 2014 and undertook intensive language courses to learn English, transitioning smoothly into Hollywood productions including Knock Knock (2015), War Dogs (2016), and Denis Villeneuve''s Blade Runner 2049 (2017). Her standout performance as Marta Cabrera in the murder mystery Knives Out (2019) catapulted her to international stardom and earned her a Golden Globe nomination. In 2021, de Armas joined the James Bond franchise in No Time to Die, directed by Cary Joji Fukunaga. She portrayed Paloma, a bubbly, effervescent, and unexpectedly lethal CIA operative stationed in Havana. Reunited on screen with her Knives Out co-star Daniel Craig, de Armas stole the film''s celebrated Cuba sequence, balancing lighthearted humor with high-caliber martial arts and gunplay while wearing an elegant evening gown alongside 007. Following her memorable turn in the Bond series, de Armas expanded her repertoire across dramatic lead roles and major action blockbusters. She delivered a critically acclaimed, transformative portrayal of Marilyn Monroe in Blonde (2022), becoming the first Cuban actress nominated for the Academy Award for Best Actress. Her subsequent projects include the action thrillers The Gray Man (2022) and Ghosted (2023), as well as taking on the lead role in the John Wick franchise spin-off feature Ballerina (2025).',
           'Cuban-Spanish',
           '1988-04-30',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Rami Malek (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('c55df0b2-2ef8-417a-8eaf-2a549ddfb0c4'),
           'Rami Malek',
           'Lyutsifer Safin',
           'Rami Said Malek was born in Torrance, California, in May 1981 to Egyptian immigrant parents. Raised in Los Angeles, he pursued drama from an early age and earned a Bachelor of Fine Arts from the University of Evansville in Indiana in 2003. After returning to California, Malek made his screen debut in a guest role on the television series Gilmore Girls (2004) before securing notable film and television parts, including Pharaoh Ahkmenrah in the comedy feature Night at the Museum (2006) and its sequels, as well as Corporal Merriell "Snafu" Shelton in the HBO World War II miniseries The Pacific (2010). His major career breakthrough came when he was cast as Elliot Alderson, a brilliantly unstable hacker, in the USA Network series Mr. Robot (2015–2019), a performance that earned him a Primetime Emmy Award. Malek achieved international stardom for his portrayal of Queen frontman Freddie Mercury in the biopic Bohemian Rhapsody (2018), winning the Academy Award, Golden Globe, and BAFTA Award for Best Actor. In 2021, Malek joined the James Bond franchise as the central antagonist in No Time to Die, directed by Cary Joji Fukunaga. He portrayed Lyutsifer Safin, a disfigured, soft-spoken terrorist leader and former assassin seeking vengeance against SPECTRE and the family of Dr. Madeleine Swann. Operating from an isolated poison garden island base built inside a World War II submarine facility, Safin repurposes a DNA-targeted nanobot bio-weapon known as Project Heracles. Malek infused the character with a quiet, menacing atmosphere, posing a catastrophic threat that ultimately drove Daniel Craig''s 007 into his heroic, final sacrifice. Following his performance in No Time to Die, Malek continued to take on major cinematic roles across studio blockbusters and auteur drama. He co-starred in David O. Russell''s period ensemble Amsterdam (2022) and portrayed real-life nuclear physicist David L. Hill in Christopher Nolan''s Oscar-winning historical epic Oppenheimer (2023). He subsequently produced and starred as a grieving CIA cryptographer seeking justice in the action thriller The Amateur (2025), alongside leading the festival-acclaimed drama The Man I Love (2026).',
           'American',
           '1981-05-12',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Lashana Lynch (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('b4464a3d-a4c9-4829-ab54-aa07bb99d55d'),
           'Lashana Lynch',
           'Nomi',
           'Lashana Lynch was born in Hammersmith, London, in November 1987. She studied acting at the Arts Educational Schools in London before making her feature film debut in the athletics drama Fast Girls (2012). She established herself across British television with roles in Silent Witness, Crims, and Bulletproof, as well as starring in the American period drama series Still Star-Crossed (2017). Lynch achieved major international recognition in 2019 when she was cast as Air Force pilot Maria Rambeau in Marvel Studios'' Captain Marvel, a breakout role that established her as a formidable talent in major franchise cinema. In 2021, Lynch made history in the James Bond series when she starred in No Time to Die, directed by Cary Joji Fukunaga. She portrayed Nomi, a sharp, highly skilled MI6 secret agent who is assigned the 007 designation following James Bond''s retirement from active service. Portraying a new generation of field operative, Lynch brought a confident, competitive edge to the role as Nomi clashes and eventually collaborates with Daniel Craig''s Bond during their joint mission to thwart Lyutsifer Safin''s biological threat. Following her turn in the Bond franchise, Lynch won the BAFTA Rising Star Award in 2022 and continued to build an impressive, high-profile body of work. She delivered acclaimed performances as the fierce Agojie warrior Izogie in the historical epic The Woman King (2022) and as Miss Honey in the musical feature Matilda the Musical (2022). She expanded her portfolio across major projects, starring as Rita Marley in the biographical film Bob Marley: One Love (2024), reprising her Marvel persona across multiple productions, and co-starring as Bianca Pullman in the spy thriller series The Day of the Jackal (2024).',
           'British',
           '1987-11-27',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Billy Magnussen (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('cb7c62f9-a7de-4e4a-b10d-a7c6995a768b'),
           'Billy Magnussen',
           'Logan Ash',
           'William Gregory Magnussen was born in Woodhaven, Queens, New York, in April 1985. Raised in Georgia, he studied drama at the University of North Carolina School of the Arts before pursuing a professional career across theater, television, and film. Magnussen made his Broadway debut in 2007 and earned a Tony Award nomination for his supporting role in Vanya and Sonia and Masha and Spike (2013). He soon gained widespread cinematic recognition playing Rapunzel''s Prince in the musical film Into the Woods (2014) and built a strong reputation as a versatile, scene-stealing character actor. His notable pre-Bond credits include feature roles in Bridge of Spies (2015), Ingrid Goes West (2017), Game Night (2018), and Guy Ritchie''s live-action Aladdin (2019), alongside acclaimed turns in television series such as The People v. O. J. Simpson: American Crime Story (2016) and Maniac (2018). In 2021, Magnussen joined the James Bond franchise in No Time to Die, directed by Cary Joji Fukunaga. He portrayed Logan Ash, a jovial CIA operative assigned alongside Felix Leiter to recruit James Bond in Jamaica. Ash is subsequently revealed to be a ruthless double agent working covertly for terrorist leader Lyutsifer Safin and SPECTRE. Magnussen brought an unsettling, frat-boy enthusiasm to the antagonist, executing a devastating betrayal that results in the death of Felix Leiter and triggers a high-stakes hunt in Norway, where 007 eventually kills Ash under a rolled vehicle. Following his performance in No Time to Die, Magnussen continued to build an energetic and diverse screen repertoire. He starred in the dark sci-fi comedy series Made for Love (2021–2022), appeared in The Many Saints of Newark (2021), and took on key roles in action features including Lift (2024) and the Road House remake (2024). He subsequently expanded into high-profile comedy and family entertainment, co-starring in Sam Mendes''s comedy series The Franchise (2024), starring as Pleakley in the live-action Lilo & Stitch (2025), and appearing in drama features such as A Big Bold Beautiful Journey (2025).',
           'American',
           '1985-04-20',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  David Dencik (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('fe2f8dbd-4c36-4213-937c-fb087a2fa6e9'),
           'David Dencik',
           'Dr. Valdo Obruchev',
           'Karl David Sebastian Dencik was born in Stockholm, Sweden, in October 1974. Raised in Denmark, he pursued formal theater training at the Swedish National Academy of Mime and Acting in Stockholm, graduating in 2003 before starting a stage career at prestigious venues like the Royal Dramatic Theatre in Stockholm. He achieved his screen breakthrough in Scandinavian television and cinema with compelling, complex dramatic performances, winning critical acclaim for his roles in the Danish feature A Soap (2006) and the Swedish true-crime miniseries Lasermannen (2005). Building a prolific international career across Nordic noir, British drama, and Hollywood blockbusters, Dencik delivered standout performances in Tinker Tailor Soldier Spy (2011), David Fincher''s The Girl with the Dragon Tattoo (2011), Steven Spielberg''s War Horse (2011), the crime series McMafia (2018), and as Soviet leader Mikhail Gorbachev in HBO''s Chernobyl (2019). In 2021, Dencik joined the James Bond franchise in No Time to Die, directed by Cary Joji Fukunaga. He portrayed Valdo Obruchev, a eccentric, arrogant Russian rogue scientist working at an MI6 bioweapons facility who is kidnapped to re-engineer Project Heracles, a DNA-targeted nanobot weapon. Functioning as a mercenary scientist under the control of SPECTRE and later Lyutsifer Safin, Obruchev brings an unpredictable, darkly comedic energy to the narrative before meeting his demise at the hands of Nomi in Safin''s island fortress. Following his appearance in No Time to Die, Dencik continued to command prominent roles across international film and television. He won a Robert Award for his role in the Netflix Danish crime series The Chestnut Man (2021) and co-starred in projects such as the thriller series Prisoner (2023), Thomas Vinterberg''s dystopian series Families Like Ours (2024), and the action series The Assassin (2025), alongside feature film appearances in Denmark and internationally.',
           'Swedish-Danish',
           '1974-10-31',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Dali Benssalah (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('70682a0c-6d2d-4aa7-b280-ceb8317a78dd'),
           'Dali Benssalah',
           'Primo',
           'Dali Benssalah was born in Rennes, France, in January 1992. Before pursuing an acting career, he spent his youth training as a competitive martial artist, winning a French national championship in Thai boxing. He studied economics at the University of Rennes before shifting his focus to the dramatic arts, enrolling at the prestigious Cours Florent acting school in Paris. Benssalah built an impressive foundation in French theater, television, and short films before earning widespread attention for starring in the high-energy, viral 2017 music video for The Blaze''s hit track "Territory." He subsequently transitioned into feature cinema, making appearances in notable French films such as Louis Garrel''s A Faithful Man (2018) and the drama series Savages (2019). In 2021, Benssalah reached a global audience when he was cast in the 25th James Bond film, No Time to Die, directed by Cary Joji Fukunaga. He portrayed Primo, a ruthless, bionic-eyed mercenary and assassin affiliated with SPECTRE who later serves Lyutsifer Safin. Nicknamed "Cyclops" due to his advanced cybernetic optic implant, Primo acts as a recurring physical adversary to Daniel Craig''s 007 throughout the narrative, culminating in high-octane action sequences in Matera, Italy, and a final brutal confrontation on Safin''s island fortress where Bond utilizes a weaponized gadget watch to defeat him. Following his role in the Bond franchise, Benssalah established himself as a dynamic leading actor across international cinema and prestige television. He earned widespread critical acclaim for his starring role as Abdel in Romain Gavras''s explosive Netflix tragedy Athena (2022), which premiered at the Venice International Film Festival. His subsequent credits include the historical drama The Last Queen (2022), the ensemble drama All Your Faces (2023), the FX spy thriller series The Veil (2024), and high-profile feature projects such as Les Orphelins (2025) and Le Lièvre (2026).',
           'French-Algerian',
           '1992-01-08',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Lisa-Dorah Sonnet (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('a105e45e-2230-4301-a1d3-e972092d88e0'),
           'Lisa-Dorah Sonnet',
           'Mathilde (Daughter of James and Madeleine)',
           'Lisa-Dorah Sonnet is a young child actress who gained wide international attention upon making her professional feature film debut in the James Bond franchise. Selected at a young age to join the production of No Time to Die (2021), directed by Cary Joji Fukunaga, she was cast in a pivotal role that added significant emotional depth to the historic final chapter of Daniel Craig''s tenure as 007. In No Time to Die, Sonnet portrayed Mathilde, the five-year-old daughter of Dr. Madeleine Swann and James Bond. When Bond reunites with Madeleine at her secluded childhood home in Norway, he meets Mathilde, though Madeleine initially insists the young girl is not his child. Mathilde becomes central to the narrative when she and her mother are abducted by terrorist leader Lyutsifer Safin and taken to his island fortress. Her presence deepens the emotional stakes of the mission, driving Bond''s protective instincts as he works alongside Nomi to secure her safe rescue before the final confrontation. Following her appearance in No Time to Die, Sonnet entered franchise history as the first actress to portray a child of James Bond in an official Eon Productions film. Her subtle, natural performance added a sense of domestic vulnerability and personal stakes to the climax of the multi-film storyline.',
           'French',
           '2015-01-01',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Coline Defaud (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('b60a4dbd-b0f8-4d96-a994-50cdb7fd666e'),
           'Coline Defaud',
           'Young Madeleine',
           'Coline Defaud is a French child actress who earned international visibility upon being cast in the landmark 25th entry of the James Bond film franchise. Her casting provided a crucial performance that anchored the atmospheric, chilling cold open of Daniel Craig''s final outing as 007. In No Time to Die (2021), directed by Cary Joji Fukunaga, Defaud portrayed the young version of Dr. Madeleine Swann. Set in a snowy, isolated cabin in Norway, her scenes depict a traumatic childhood event that shapes the character''s entire arc: the arrival of a masked assassin, Lyutsifer Safin, seeking vengeance against her father, Mr. White. Defaud delivered a haunting performance as the young girl who shoots the intruder in self-defense, flees across an ice-covered lake, falls through, and is unexpectedly saved from drowning by Safin. Her work in this sequence established the foundational psychological backstory for Léa Seydoux''s adult Madeleine and set up the overarching dynamic of the movie''s main villain. Defaud''s performance in No Time to Die stands as her principal cinematic landmark, cementing her place in James Bond history by depicting the pivotal moment that tied Madeleine Swann''s past directly to the central conflict of the film.',
           'French',
           '2010-03-10',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Mathilde Bourbin (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('941ec712-fb54-4f10-942b-92d3a36237d2'),
           'Mathilde Bourbin',
           'Madeleines Mother',
           'Mathilde Bourbin was born in Paris, France. She developed a passion for the dramatic arts at a young age, pursuing extensive acting training and masterclasses in Paris, including classical theater studies and work with the "Modèle du Libre Acteur". Bourbin established herself as a versatile creative across French theater, short films, and web productions, working as an actress, writer, and producer. She earned widespread recognition in the French digital entertainment scene for her starring role in the award-winning web series Frapuccino (2016–2021), which garnered international festival acclaim and earned her multiple best actress nominations. Her pre-Bond credits also include appearances in stage productions such as Molière''s Dom Juan and Victor Hugo''s Ruy Blas, along with feature film roles in Louise (2015) and French television series such as Scènes de ménages. In 2021, Bourbin achieved broad international visibility when she was cast in the 25th James Bond film, No Time to Die, directed by Cary Joji Fukunaga. She portrayed Madeleine Swann''s mother in the haunting, atmospheric cold open set at an isolated Norwegian lake house. Playing the tragic, estranged wife of SPECTRE assassin Mr. White, Bourbin delivered a high-stakes performance opposite Coline Defaud (as young Madeleine) and Rami Malek (as Lyutsifer Safin). Her character''s brutal murder at the hands of Safin establishes the foundational trauma of Madeleine''s past and drives the central villain''s motivation throughout the movie. Following her performance in No Time to Die, Bourbin continued to expand her presence across French cinema, prestige television, and stage. She featured in films such as Comme une actrice (2021) and Mercato (2024), while joining major television productions including Vise le cœur (2023) and Netflix''s Lupin (2025). In addition to her screen work, she remained deeply involved in the French theater circuit, co-directing and performing in stage plays such as Building at the Avignon Festival.',
           'French',
           '1978-01-01',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );

/**
  Hugh Dennis (No Time To Die)
 */
INSERT INTO actors (id, name, character_role, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
           UUID_TO_BIN('b52f3479-ce34-4cc4-bb90-3188b8cf1210'),
           'Hugh Dennis',
           'Dr. Hardy',
           'Peter Hugh Dennis was born in Kettering, Northamptonshire, in February 1962. Raised in London, he attended St John''s College, Cambridge, where he studied Geography and joined the famed Footlights comedy troupe. After working in corporate marketing for several years, Dennis transitioned full-time into entertainment, achieving his major comedic breakthrough in the late 1980s and early 1990s as part of the satirical radio and television series Punt and Dennis alongside Steve Punt, as well as appearing on The Mary Whitehouse Experience. He established himself as a fixture of British television, winning widespread acclaim for his starring role as the long-suffering father Pete Brockman in the award-winning BBC sitcom Outnumbered (2007–2016), as well as serving as a long-running panelist on Mock the Week and appearing in series like Fleabag and Not Going Out. In 2021, Dennis made a surprise cameo appearance in the James Bond franchise in No Time to Die, directed by Cary Joji Fukunaga. He portrayed Dr. Hardy, a senior British Secret Intelligence Service scientist working in a secure London laboratory dedicated to the development of Project Heracles, a DNA-targeted nanoweapon. His scene occurs early in the film during the high-stakes breach of the MI6 facility, where Dr. Hardy is forced by mercenaries to surrender the dangerous bioweapon before being shot by the assassin Primo. Following his cameo in No Time to Die, Dennis continued his career as a prominent television presenter, actor, and comedian in the United Kingdom. He hosted the archaeology and history series The Great British Dig (2020–2023) and Huge Homes with Hugh Dennis (2022), while taking on acting roles in series such as Murder, They Hope (2023) and appearing regularly across radio, stage, and factual television projects.',
           'British',
           '1962-02-13',
           NULL,
           CURRENT_TIMESTAMP(6),
           CURRENT_TIMESTAMP(6)
       );